    {
        return DETAILS_OVERLAY.equals(key) || METHOD_OVERLAY.equals(key);
    }
    static boolean acknowledgesFirstUse(String key)
    {
        return STRATEGY_MODE.equals(key) || SESSION_INTENT.equals(key)
                || ACTIVE_GOAL.equals(key);
    }
}

