            {VarbitID.SLAYER_BLOCKED_KRYSTILIA_1, VarbitID.SLAYER_BLOCKED_KRYSTILIA_2, VarbitID.SLAYER_BLOCKED_KRYSTILIA_3, VarbitID.SLAYER_BLOCKED_KRYSTILIA_4, VarbitID.SLAYER_BLOCKED_KRYSTILIA_5, VarbitID.SLAYER_BLOCKED_KRYSTILIA_6, VarbitID.SLAYER_BLOCKED_KRYSTILIA_DIARY},
            {VarbitID.SLAYER_BLOCKED_KONAR_1, VarbitID.SLAYER_BLOCKED_KONAR_2, VarbitID.SLAYER_BLOCKED_KONAR_3, VarbitID.SLAYER_BLOCKED_KONAR_4, VarbitID.SLAYER_BLOCKED_KONAR_5, VarbitID.SLAYER_BLOCKED_KONAR_6, VarbitID.SLAYER_BLOCKED_KONAR_DIARY},
            {VarbitID.SLAYER_BLOCKED_TURAEL_1, VarbitID.SLAYER_BLOCKED_TURAEL_2, VarbitID.SLAYER_BLOCKED_TURAEL_3, VarbitID.SLAYER_BLOCKED_TURAEL_4, VarbitID.SLAYER_BLOCKED_TURAEL_5, VarbitID.SLAYER_BLOCKED_TURAEL_6, VarbitID.SLAYER_BLOCKED_TURAEL_DIARY},
            {VarbitID.SLAYER_BLOCKED_MORTIMER_1, VarbitID.SLAYER_BLOCKED_MORTIMER_2}
    };

    private final Client client;
    private int cachedTick = -1;
    private SlayerSnapshot cached;

    public SlayerSnapshot read()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            cachedTick = -1;
            cached = null;
            return null;
        }

        var tick = client.getTickCount();
        if (cached != null && cachedTick == tick)
        {
            return cached;
        }

        var amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
        var points = max(0, client.getVarbitValue(VarbitID.SLAYER_POINTS));
        var masterId = client.getVarbitValue(VarbitID.SLAYER_MASTER);
        List<SlayerTaskOffer> offers = amount <= 0
                ? readMortimerOffers() : emptyList();
        if (!offers.isEmpty()) masterId = MORTIMER_MASTER_ID;
        var masterName = masterName(masterId);
        var rewards = readRewards();
        var streak = streak(masterId);
        var questPoints = max(0, client.getVarpValue(VarPlayerID.QP));
        boolean lumbridgeElite = client.getVarbitValue(
                VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) > 0;
        int blockCapacity = masterId == MORTIMER_MASTER_ID ? 2
                : SlayerPointEconomy.blockCapacity(questPoints, lumbridgeElite);
        var occupiedBlockSlots = occupiedBlockSlots(masterId, blockCapacity);
        boolean mortimerIntroduced = client.getVarbitValue(
                VarbitID.MORTIMER_INTRODUCTION) > 0;
        if (amount <= 0)
        {
            cached = new SlayerSnapshot(
                    null, 0, masterName, null, points, streak, questPoints,
                    blockCapacity, occupiedBlockSlots, rewards, offers,
                    mortimerIntroduced,
                    Confidence.VERIFIED);
            cachedTick = tick;
            return cached;
        }

        try
        {
            String taskName = taskName(
                    client.getVarpValue(VarPlayerID.SLAYER_TARGET),
                    client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
            if (taskName == null) return unresolved(amount, masterName,
                    points, streak, questPoints, blockCapacity, rewards,
                    mortimerIntroduced, tick);

            String taskLocation = null;
            var areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
            if (areaId > 0)
            {
                var rows = client.getDBRowsByValue(
                        DBTableID.SlayerArea.ID,
                        DBTableID.SlayerArea.COL_AREA_ID,
                        0,
                        areaId);
                if (!rows.isEmpty())
                {
                    taskLocation = (String) client.getDBTableField(
                            rows.get(0),
                            DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER,
                            0)[0];
                }
            }

            cached = new SlayerSnapshot(
                    taskName,
                    amount,
                    masterName,
                    taskLocation,
                    points,
                    streak,
                    questPoints,
                    blockCapacity,
                    occupiedBlockSlots,
                    rewards,
                    emptyList(),
                    mortimerIntroduced,
                    Confidence.VERIFIED);
            cachedTick = tick;
            return cached;
        }
        catch (RuntimeException ex)
        {
            return unresolved(amount, masterName, points, streak, questPoints,
                    blockCapacity, rewards, mortimerIntroduced, tick);
        }
    }

    public void clear()
    {
        cachedTick = -1;
        cached = null;
    }

    private SlayerSnapshot unresolved(int amount, String masterName,
            int points, Integer streak, int questPoints, int blockCapacity,
            SlayerRewardSnapshot rewards, boolean mortimerIntroduced, int tick)
    {
        cached = new SlayerSnapshot(
                null,
                amount,
                masterName,
                null,
                points,
                streak,
                questPoints,
                blockCapacity,
                null,
                rewards,
                emptyList(),
                mortimerIntroduced,
                Confidence.CHECK_NEEDED);
        cachedTick = tick;
        return cached;
    }

    private Integer streak(int masterId)
    {
        if (masterId == MORTIMER_MASTER_ID)
        {
            // RuneLite exposes Mortimer's live choices/modifiers but no public
            // separate completed-task counter. Never substitute normal streak.
            return null;
        }
        return max(0, client.getVarbitValue(
                masterId == KRYSTILIA_MASTER_ID
                        ? VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED
                        : VarbitID.SLAYER_TASKS_COMPLETED));
    }

    private List<SlayerTaskOffer> readMortimerOffers()
    {
        List<SlayerTaskOffer> offers = new ArrayList<>();
        addOffer(offers, VarbitID.SLAYER_CHOOSE_TASK_1,
                VarbitID.SLAYER_CHOOSE_TASK_1_BOSS_ID,
                VarbitID.SLAYER_CHOOSE_TASK_1_MODIFIER_ID,
                VarbitID.SLAYER_CHOOSE_TASK_1_MODIFIER_VALUE,
                VarbitID.SLAYER_CHOOSE_TASK_1_MODIFIER_NEGATIVE);
        addOffer(offers, VarbitID.SLAYER_CHOOSE_TASK_2,
                VarbitID.SLAYER_CHOOSE_TASK_2_BOSS_ID,
                VarbitID.SLAYER_CHOOSE_TASK_2_MODIFIER_ID,
                VarbitID.SLAYER_CHOOSE_TASK_2_MODIFIER_VALUE,
                VarbitID.SLAYER_CHOOSE_TASK_2_MODIFIER_NEGATIVE);
        addOffer(offers, VarbitID.SLAYER_CHOOSE_TASK_3,
                VarbitID.SLAYER_CHOOSE_TASK_3_BOSS_ID,
                VarbitID.SLAYER_CHOOSE_TASK_3_MODIFIER_ID,
                VarbitID.SLAYER_CHOOSE_TASK_3_MODIFIER_VALUE,
                VarbitID.SLAYER_CHOOSE_TASK_3_MODIFIER_NEGATIVE);
        return offers;
    }

    private void addOffer(List<SlayerTaskOffer> offers, int taskVarbit,
            int bossVarbit, int modifierVarbit, int valueVarbit,
            int negativeVarbit)
    {
        var taskId = client.getVarbitValue(taskVarbit);
        if (taskId <= 0) return;
        String task = null;
        String modifier = null;
        var value = client.getVarbitValue(valueVarbit);
        var negative = client.getVarbitValue(negativeVarbit) > 0;
        try
        {
            task = taskName(taskId, client.getVarbitValue(bossVarbit));
            modifier = modifierName(
                    client.getVarbitValue(modifierVarbit));
        }
        catch (RuntimeException ignored)
        {
            // Preserve the option as unresolved. Omitting it could make a
            // decoded alternative look best when the hidden option is better.
        }
        offers.add(new SlayerTaskOffer(task, modifier, value, negative));
    }

    private String taskName(int taskId, int bossId)
    {
        int taskRow;
        if (taskId == BOSS_TASK_ID)
        {
            var rows = client.getDBRowsByValue(
                    DBTableID.SlayerTaskSublist.ID,
                    DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
                    0, bossId);
            if (rows.isEmpty()) return null;
            taskRow = (Integer) client.getDBTableField(rows.get(0),
                    DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
        }
        else
        {
            var rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID,
                    DBTableID.SlayerTask.COL_ID, 0, taskId);
            if (rows.isEmpty()) return null;
            taskRow = rows.get(0);
        }
        Object[] values = client.getDBTableField(taskRow,
                DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
        return values == null || values.length == 0
                ? null : (String) values[0];
    }

    private String modifierName(int modifierId)
    {
        var rows = client.getDBRowsByValue(DBTableID.SlayerModifiers.ID,
                DBTableID.SlayerModifiers.COL_ID, 0, modifierId);
        if (rows.isEmpty()) return null;
        Object[] values = client.getDBTableField(rows.get(0),
                DBTableID.SlayerModifiers.COL_NAME, 0);
        return values == null || values.length == 0
                ? null : (String) values[0];
    }

    private SlayerRewardSnapshot readRewards()
    {
        Map<SlayerReward, Capability> states =
                new EnumMap<>(SlayerReward.class);
        for (SlayerReward reward : SlayerReward.values())
            states.put(reward, client.getVarbitValue(reward.getVarbitId()) > 0
                    ? Capability.VERIFIED : Capability.BLOCKED);
        return new SlayerRewardSnapshot(states);
    }

    static String masterName(int masterId)
    {
        return masterId > 0 && masterId < MASTER_NAMES.length
                ? MASTER_NAMES[masterId] : null;
    }

    private Integer occupiedBlockSlots(int masterId, int capacity)
    {
        var slots = blockVarbits(masterId);
        if (slots == null) return null;
        var occupied = 0;
        var visible = min(capacity, slots.length);
        for (int i = 0; i < visible; i++)
            if (client.getVarbitValue(slots[i]) > 0) occupied++;
        return occupied;
    }

    private static int[] blockVarbits(int masterId)
    {
        return masterId > 0 && masterId < BLOCKS.length
                ? BLOCKS[masterId] : null;
    }
}

package compass;
import lombok.*;

import java.util.*;


/**
 * Connects a curated Compass method to a deterministic RuneLite skill action.
 *
 * <p>The method catalog decides <em>which route</em> is strategically sensible.
 * This profile describes the repeatable unit inside that route so Compass can
 * convert exact XP remaining into laps, catches, logs, casts, furniture builds,
 * items processed, etc. Methods with variable XP per completion deliberately do
 * not get a profile until a trustworthy model exists.</p>
 */
@Getter
public final class MethodProfile
{
    public enum ProgressEstimateMode
    {
        /** Every successful action represented by the chosen row awards one XP value. */
        EXACT_ACTIONS,
        /** One repeated interaction can yield several differently valued outputs. */
        VARIABLE_OUTPUT_RANGE,
        /** Only XP remaining is safe to show. */
        XP_ONLY
    }

    public enum InputMode
    {
        NONE,
        ACTION_ITEM,
        RAW_ACTION_ITEM,
        LOG_FOR_BOW,
        BAR_FOR_SMITHED_ITEM,
        UNCUT_GEM,
        SAPLING_FOR_TREE,
        DART_TIP_FOR_DART,
        UNFINISHED_BOLT,
        FIXED
    }

    String methodId;
    List<String> actionTerms;
    String unitSingular;
    String unitPlural;
    double xpMultiplier;
    List<MethodInputRule> inputs;
    String note;
    ProgressEstimateMode progressEstimateMode;

    public String unit(int count)
    {
        return count == 1 ? unitSingular : unitPlural;
    }
}

package compass;
import lombok.*;

import java.util.*;
import javax.inject.*;
import net.runelite.api.Skill;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class MilestoneTracker
{
    private final ProgressionObjectiveCatalog progressionObjectives;

    public MilestoneCompletion detectCompletion(
            TrackedMilestone tracked,
            AccountSnapshot account)
    {
        if (tracked == null || account == null) return null;
        var skill = tracked.getSkill();
        if (skill == null) return null;
        var currentLevel = account.level(skill);
        if (currentLevel < tracked.targetLevel) return null;
        return new MilestoneCompletion(
                tracked.activityId, tracked.title, skill,
                tracked.getStartedAtLevel(), tracked.targetLevel
        );
    }

    public TrackedMilestone fromRecommendations(
            List<Recommendation> recommendations)
    {
        return fromRecommendations(recommendations, null);
    }

    public TrackedMilestone fromRecommendations(
            List<Recommendation> recommendations,
            CollectionLogSnapshot collectionLog)
    {
        if (recommendations == null || recommendations.isEmpty()) return null;
        var best = recommendations.get(0);
        var skill = skillFor(best);
        if (skill == null
                || best.currentLevel <= 0
                || best.targetLevel <= best.currentLevel)
        {
            return null;
        }

        var plan = best.plan();
        boolean progressionProtected = plan != null && plan.method() != null
                && protect(plan.method(), collectionLog);

        return new TrackedMilestone(
                best.id, best.title, skill.name(),
                best.currentLevel, best.targetLevel,
                progressionProtected
        );
    }

    boolean protect(TrainingMethod method,
            CollectionLogSnapshot collectionLog)
    {
        ProgressionObjectiveDefinition objective = progressionObjectives == null
                ? null : progressionObjectives.forMethod(method.id);
        return objective == null ? method.progressionProtected
                : collectionLog == null
                        || !collectionLog.isObjectiveComplete(objective.id);
    }

    public boolean sameCheckpoint(TrackedMilestone first, TrackedMilestone second)
    {
        if (first == null || second == null) return first == second;
        return safeEquals(first.activityId, second.activityId)
                && first.targetLevel == second.targetLevel
                && first.progressionProtected == second.progressionProtected;
    }

    public static Skill skillFor(Recommendation recommendation)
    {
        if (recommendation == null || recommendation.id == null) return null;
        var prefix = "skill:";
        if (!recommendation.id.startsWith(prefix)) return null;
        String name = recommendation.id.substring(prefix.length())
                .toUpperCase(Locale.ROOT);
        try
        {
            return Skill.valueOf(name);
        }
        catch (IllegalArgumentException ex)
        {
            return null;
        }
    }

    private static boolean safeEquals(String first, String second)
    {
        return first == null ? second == null : first.equals(second);
    }
}

package compass;

import javax.inject.Singleton;

/**
 * In-memory home for account observations that arrive at different times.
 *
 * <p>RuneLite does not expose every piece of account state continuously. A
 * bank snapshot may be seen when the bank is open, a clue may be detected from
 * another plugin/event, and a POH capability may be confirmed by the player.
 * This store lets those observations survive normal panel refreshes while still
 * being cleared when the active character changes.</p>
 *
 * <p>No setter invents data. Callers are responsible for only storing values
 * they actually observed or the player explicitly confirmed.</p>
 */
@Singleton
public class ObservedStateStore
{
    private QuestSnapshot quests;
    private DiarySnapshot diaries;
    private ClueSnapshot clue;
    private CombatAchievementSnapshot combatAchievements;
    private CollectionLogSnapshot collectionLog;
    private AccountEconomySnapshot economy;
    private StorageSnapshot storage;
    private TransportSnapshot transport;
    private PohSnapshot poh;
    private ItemsState groupStorage;
    private SlayerSnapshot slayer;
    private FarmingSnapshot farming;
    private SailingSnapshot sailing;
    private MinigameSnapshot minigames;
    private PvmSnapshot pvm;
    private RecurringOpportunitySnapshot recurringOpportunities;

    public synchronized void clearForAccountChange()
    {
        quests = null;
        diaries = null;
        clue = null;
        combatAchievements = null;
        collectionLog = null;
        economy = null;
        storage = null;
        transport = null;
        poh = null;
        groupStorage = null;
        slayer = null;
        farming = null;
        sailing = null;
        minigames = null;
        pvm = null;
        recurringOpportunities = null;
    }

    public synchronized QuestSnapshot quests() { return quests; }
    public synchronized void setQuests(QuestSnapshot value) { quests = value; }
    public synchronized DiarySnapshot diaries() { return diaries; }
    public synchronized void setDiaries(DiarySnapshot value) { diaries = value; }
    public synchronized ClueSnapshot clue() { return clue; }
    public synchronized void setClue(ClueSnapshot value) { clue = value; }
    public synchronized CombatAchievementSnapshot combatAchievements() { return combatAchievements; }
    public synchronized void setCombatAchievements(CombatAchievementSnapshot value) { combatAchievements = value; }
    public synchronized CollectionLogSnapshot collectionLog() { return collectionLog; }
    public synchronized void setCollectionLog(CollectionLogSnapshot value) { collectionLog = value; }
    public synchronized AccountEconomySnapshot economy() { return economy; }
    public synchronized void setEconomy(AccountEconomySnapshot value) { economy = value; }
    public synchronized StorageSnapshot storage() { return storage; }
    public synchronized void setStorage(StorageSnapshot value) { storage = value; }
    public synchronized TransportSnapshot transport() { return transport; }
    public synchronized void setTransport(TransportSnapshot value) { transport = value; }
    public synchronized PohSnapshot poh() { return poh; }
    public synchronized void setPoh(PohSnapshot value) { poh = value; }
    public synchronized ItemsState groupStorage() { return groupStorage; }
    public synchronized void setGroupStorage(ItemsState value) { groupStorage = value; }
    public synchronized SlayerSnapshot slayer() { return slayer; }
    public synchronized void setSlayer(SlayerSnapshot value) { slayer = value; }
    public synchronized FarmingSnapshot farming() { return farming; }
    public synchronized void setFarming(FarmingSnapshot value) { farming = value; }
    public synchronized SailingSnapshot sailing() { return sailing; }
    public synchronized void setSailing(SailingSnapshot value) { sailing = value; }
    public synchronized MinigameSnapshot minigames() { return minigames; }
    public synchronized void setMinigames(MinigameSnapshot value) { minigames = value; }
    public synchronized PvmSnapshot pvm() { return pvm; }
    public synchronized void setPvm(PvmSnapshot value) { pvm = value; }
    public synchronized RecurringOpportunitySnapshot recurringOpportunities() { return recurringOpportunities; }
    public synchronized void setRecurringOpportunities(RecurringOpportunitySnapshot value) { recurringOpportunities = value; }
}

