    /**
     * Force Swing to lay the text out at the real card width before BoxLayout
     * asks for dimensions. This keeps complete words inside the sidebar rather
     * than relying on JLabel HTML width hints.
     */
    private static void setWrappedText(JTextArea area, String text, int width)
    {
        if (area == null) return;
        var value = text == null ? "" : text;
        area.setText(value);
        // setPreferredSize makes Swing cache the previous measurement. Clear
        // all three explicit bounds before measuring new copy, otherwise an
        // area initialized empty remains one line tall even after a resolved
        // multi-line recommendation replaces it.
        area.setPreferredSize(null);
        area.setMinimumSize(null);
        area.setMaximumSize(null);
        area.setSize(new Dimension(width, 10_000));
        var preferred = area.getPreferredSize();
        var lineHeight = area.getFontMetrics(area.getFont()).getHeight();
        var height = value.isEmpty() ? 1 : max(lineHeight, preferred.height);
        var size = new Dimension(width, height);
        area.setPreferredSize(size);
        area.setMinimumSize(size);
        area.setMaximumSize(size);
    }

    private static JLabel eyebrow(String text)
    {
        var label = mutedLabel(text);
        label.setForeground(StrategistTheme.GOLD_SOFT);
        label.setFont(label.getFont().deriveFont(Font.BOLD, EYEBROW_FONT_SIZE));
        return label;
    }

    private static JLabel label(String text)
    {
        var label = new JLabel(html(text));
        label.setForeground(StrategistTheme.TEXT);
        label.setFont(label.getFont().deriveFont(BODY_FONT_SIZE));
        label.setAlignmentX(LEFT_ALIGNMENT);
        return label;
    }

    private static JLabel mutedLabel(String text)
    {
        var label = label(text);
        label.setForeground(StrategistTheme.MUTED_TEXT);
        label.setFont(label.getFont().deriveFont(MUTED_FONT_SIZE));
        return label;
    }

    private static JLabel inlineMutedLabel(String text)
    {
        var label = new JLabel(text);
        label.setForeground(StrategistTheme.MUTED_TEXT);
        label.setFont(label.getFont().deriveFont(MUTED_FONT_SIZE));
        label.setAlignmentX(LEFT_ALIGNMENT);
        return label;
    }

    private static String opportunityText(Opportunity opportunity)
    {
        boolean actionable = opportunity.isReady()
                && (opportunity.isSetupVerified()
                || opportunity.preparation.isEmpty());
        String state;
        if (actionable)
            state = "Ready";
        else if (!opportunity.preparation.isEmpty())
            state = "Prep: " + opportunity.preparation.get(0);
        else
            state = "Wait";
        return "• " + safe(opportunity.title) + "\n" + state;
    }

    private static String feedbackStatusText(FeedbackAction action, String title)
    {
        var activity = safe(title == null ? "Recommendation" : title);
        switch (action)
        {
            case LATER:
                return activity + get(1904);
            case NOT_TODAY:
                return activity + get(1905);
            case DISLIKE:
                return activity + get(1249);
            default:
                return "Feedback saved";
        }
    }

    private static String prettyName(String text)
    {
        if (text == null || text.isEmpty()) return "Unknown";
        var lower = text.toLowerCase().replace('_', ' ');
        return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
    }

    private static String safe(String value)
    {
        return value == null ? "" : value;
    }

    private static String escape(String value)
    {
        if (value == null) return "";
        return value
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#39;");
    }

    private static String html(String text)
    {
        return get(1250) + INNER_WIDTH + "px;'>"
                + (text == null ? "" : text)
                + "</div></html>";
    }
}

package compass;
import static java.util.Collections.*;

import static compass.Text.get;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.*;
import net.runelite.client.plugins.*;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.ui.*;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.*;

@PluginDescriptor(
        name = "Gielinor Compass",
        description = "Decides your next safe, useful move from observed account state",
        tags = {"strategy", "progression", "goals", "ironman", "uim", "gim", "clues", "slayer"}
)
@PluginDependency(ClueScrollPlugin.class)
public class OsrsStrategistPlugin extends Plugin
{
    private static final double COMPLETION_VARIETY_PENALTY = -10.0;
    private static final long COMPLETION_VARIETY_DURATION_MILLIS = 30L * 60L * 1000L;
    private static final long PROGRESS_CHECKPOINT_INTERVAL_MILLIS = 60_000L;
    /** Bursty varp/container events must not rebuild the full strategy each tick. */
    static final long STRATEGY_REFRESH_INTERVAL_MILLIS = 2_000L;

    @Inject private OsrsStrategistConfig config;
    @Inject private ConfigManager configManager;
    @Inject private ClientToolbar clientToolbar;
    @Inject private OverlayManager overlayManager;
    @Inject private StrategyDataAssembler strategyDataAssembler;
    @Inject private LiveItemStateReader liveItemStateReader;
    @Inject private StrategyEngine strategyEngine;
    @Inject private MethodGuidanceService methodGuidanceService;
    @Inject private AccountProfileStore accountProfileStore;
    @Inject private MilestoneTracker milestoneTracker;
    @Inject private SkillIconLoader skillIconLoader;
    @Inject private TrainingFatigueTracker trainingFatigueTracker;
    @Inject private MilestoneRewardOverlay milestoneRewardOverlay;
    @Inject private MethodGuidanceOverlay methodGuidanceOverlay;
    @Inject private RecommendationDetailsOverlay recommendationDetailsOverlay;
    @Inject private ProgressAnalyticsService progressAnalyticsService;
    @Inject private PlanContinuityService planContinuityService;

    private final PreferenceProfile preferenceProfile = new PreferenceProfile();
    private final RecommendationHistory recommendationHistory = new RecommendationHistory();
    private String loadedProfileKey;
    private String loadedProgressProfileKey;
    private boolean savingProfileConfiguration;
    private PlayerStrategyProfile strategyProfile;
    private TrackedMilestone trackedMilestone;
    private GameData latestData;
    private List<Recommendation> latestRecommendations = emptyList();
    private StrategicPlan latestPlan;
    private ProgressHistory progressHistory = new ProgressHistory();
    private final AccountProgressMilestoneDetector progressMilestoneDetector =
            new AccountProgressMilestoneDetector();
    private NavigationButton navButton;
    private OsrsStrategistPanel panel;
    private final UiGenerationGuard uiGeneration = new UiGenerationGuard();
    private final AtomicBoolean progressUiUpdatePending =
            new AtomicBoolean();
    private boolean varbitRefreshPending;
    private boolean accountRefreshPending;
    private boolean pohRefreshPending;
    private boolean diaryRefreshPending;
    private boolean progressCheckpointPending;
    private long lastProgressCheckpointAtMillis;
    private long lastStrategyRefreshAtMillis = Long.MIN_VALUE;
    private long lastPohObservationAtMillis = Long.MIN_VALUE;
    private long lastFarmingObservationAtMillis = Long.MIN_VALUE;
    private final OverlayLifecycleGuard overlayLifecycle =
            new OverlayLifecycleGuard();
    private final RecommendationStabilizer recommendationStabilizer =
            new RecommendationStabilizer();

    @Provides
    OsrsStrategistConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(OsrsStrategistConfig.class);
    }

    @Override
    protected void startUp()
    {
        panel = new OsrsStrategistPanel(
                this::applyRecommendationFeedback,
                skillIconLoader,
                this::updateRecommendationDetails,
                this::updateAccountPanel,
                this::acknowledgeFirstUse,
                SupportLinks.SUPPORT_URL,
                LinkBrowser::browse);
        panel.setDetailsOverlayEnabled(
                OverlayDisplayState.from(config).showsDetails());
        panel.setFirstUseHintVisible(!config.firstUseComplete());
        SidebarAccessibility.apply(panel, config.sidebarTextSize());
        navButton = NavigationButton.builder()
                .tooltip("Gielinor Compass")
                .icon(loadPluginIcon())
                .priority(5)
                .panel(panel)
                .build();
        clientToolbar.addNavigation(navButton);
        registerOverlays();
        trainingFatigueTracker.clear();
        pohRefreshPending = true;
        syncProfileState();
        updateAccountPanel();
    }

    @Override
    protected void shutDown()
    {
        uiGeneration.invalidate();
        if (navButton != null) clientToolbar.removeNavigation(navButton);
        unregisterOverlays();
        milestoneRewardOverlay.clear();
        methodGuidanceOverlay.clear();
        recommendationDetailsOverlay.clear();
        preferenceProfile.clear();
        recommendationHistory.clear();
        archiveProgressSession();
        progressHistory.clear();
        progressAnalyticsService.reset();
        progressMilestoneDetector.clear();
        trainingFatigueTracker.clear();
        strategyDataAssembler.clearForAccountChange();
        loadedProfileKey = null;
        loadedProgressProfileKey = null;
        savingProfileConfiguration = false;
        strategyProfile = null;
        trackedMilestone = null;
        latestData = null;
        latestRecommendations = emptyList();
        latestPlan = null;
        varbitRefreshPending = false;
        accountRefreshPending = false;
        lastStrategyRefreshAtMillis = Long.MIN_VALUE;
        lastPohObservationAtMillis = Long.MIN_VALUE;
        lastFarmingObservationAtMillis = Long.MIN_VALUE;
        pohRefreshPending = false;
        diaryRefreshPending = false;
        panel = null;
        navButton = null;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event == null) return;
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            // Login emits profile, inventory, equipment, varbit, quest and
            // object bursts close together. Let the next game tick assemble
            // one complete snapshot instead of synchronously evaluating here
            // and then reranking the same state again two seconds later.
            accountRefreshPending = true;
            pohRefreshPending = true;
            return;
        }
        if (progressAnalyticsService != null)
            progressAnalyticsService.pause(System.currentTimeMillis());
        pohRefreshPending = true;
        // Publish the waiting state once when leaving an active character;
        // intermediate loading-state events should not repeat full reads.
        if (latestData != null) updateAccountPanel();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        var now = System.currentTimeMillis();
        var accessChanged = strategyDataAssembler.observeAccess();
        boolean farmChanged = consumeFarmingObservation(now)
                && strategyDataAssembler.observeFarmingPatches();
        boolean pohChanged = consumePohRefreshPending(now)
                && strategyDataAssembler.observePoh();
        boolean diaryChanged = consumeDiaryRefreshPending()
                && strategyDataAssembler.observeOpenDiary();
        checkpointProgressSession();
        if (accessChanged || farmChanged || pohChanged || diaryChanged)
            accountRefreshPending = true;
        if (consumeStrategyRefreshPending(now))
            updateAccountPanel();
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event != null && event.getGroupId() == InterfaceID.JOURNALSCROLL)
            diaryRefreshPending = true;
    }

    /**
     * Quest, diary, Slayer, and several unlock states are varbit-backed. Coalesce
     * their often-bursty changes into one read on the following game tick.
     */
    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        varbitRefreshPending = true;
        // Entering build mode and furniture state transitions are varbit/object
        // backed. Coalesce them into one ownership-gated scene scan.
        pohRefreshPending = true;
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        pohRefreshPending = true;
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        pohRefreshPending = true;
    }

    boolean consumePohRefreshPending(long nowMillis)
    {
        if (!pohRefreshPending) return false;
        if (!intervalElapsed(nowMillis, lastPohObservationAtMillis))
            return false;
        pohRefreshPending = false;
        lastPohObservationAtMillis = nowMillis;
        return true;
    }

    boolean consumeDiaryRefreshPending()
    {
        var pending = diaryRefreshPending;
        diaryRefreshPending = false;
        return pending;
    }

    /**
     * Coalesces unrelated varbit bursts and repeated inventory mutations while
     * retaining the pending refresh. Delaying a rerank by at most two seconds
     * avoids client-thread catalog scans on every 600 ms game tick.
     */
    boolean consumeStrategyRefreshPending(long nowMillis)
    {
        if (!varbitRefreshPending && !accountRefreshPending) return false;
        if (!intervalElapsed(nowMillis, lastStrategyRefreshAtMillis))
            return false;
        varbitRefreshPending = false;
        accountRefreshPending = false;
        lastStrategyRefreshAtMillis = nowMillis;
        return true;
    }

    boolean consumeFarmingObservation(long nowMillis)
    {
        if (!intervalElapsed(nowMillis, lastFarmingObservationAtMillis))
            return false;
        lastFarmingObservationAtMillis = nowMillis;
        return true;
    }

    private static boolean intervalElapsed(long nowMillis, long previousMillis)
    {
        return previousMillis == Long.MIN_VALUE
                || nowMillis < previousMillis
                || nowMillis - previousMillis >= STRATEGY_REFRESH_INTERVAL_MILLIS;
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        var progressChanged = progressAnalyticsService.record(event);
        if (progressChanged)
        {
            progressCheckpointPending = true;
            updateProgressPanel();
        }
        var profile = effectiveStrategyProfile();
        TrainingFatigueTracker.FatigueSignal fatigue = trainingFatigueTracker.record(
                event.getSkill(), event.getXp(), profile.mode());
        if (fatigue.isPresent())
        {
            preferenceProfile.addTemporaryScoreAdjustment(
                    fatigue.activityId,
                    fatigue.getScoreDelta(),
                    fatigue.getDurationMillis());
        }
        if (fatigue.isPresent() || latestData == null
                || latestData.account() == null
                || latestData.account().level(event.getSkill())
                        != event.getLevel())
        {
            accountRefreshPending = true;
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event == null || !isStrategicContainer(event.getContainerId())) return;
        if (event.getContainerId()
                        == InventoryID.INV_GROUP_TEMP
                && liveItemStateReader != null)
        {
            liveItemStateReader.observeGroupStorage(event.getItemContainer());
        }
        accountRefreshPending = true;
    }

    static boolean isStrategicContainer(int containerId)
    {
        return containerId == InventoryID.INV
                || containerId == InventoryID.WORN
                || containerId == InventoryID.BANK
                || containerId
                        == InventoryID.INV_GROUP_TEMP;
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        if (savingProfileConfiguration) return;
        // Fail closed before reading the new profile. No queued Swing callback,
        // cached bundle, preference weight, or strategy choice from the prior
        // character may survive even for a single refresh generation.
        uiGeneration.invalidate();
        loadedProfileKey = null;
        if (Objects.equals(loadedProgressProfileKey,
                accountProfileStore.activeProfileKey()))
            archiveProgressSession();
        loadedProgressProfileKey = null;
        progressCheckpointPending = false;
        lastProgressCheckpointAtMillis = 0L;
        lastStrategyRefreshAtMillis = Long.MIN_VALUE;
        lastPohObservationAtMillis = Long.MIN_VALUE;
        lastFarmingObservationAtMillis = Long.MIN_VALUE;
        latestRecommendations = emptyList();
        latestPlan = null;
        latestData = null;
        preferenceProfile.clear();
        strategyProfile = null;
        trackedMilestone = null;
        recommendationHistory.clear();
        progressHistory = new ProgressHistory();
        progressAnalyticsService.reset();
        progressMilestoneDetector.clear();
        trainingFatigueTracker.clear();
        strategyDataAssembler.clearForAccountChange();
        varbitRefreshPending = false;
        accountRefreshPending = false;
        methodGuidanceOverlay.clear();
        recommendationDetailsOverlay.clear();
        syncProfileState();
        // RuneScapeProfileChanged and LOGGED_IN commonly arrive in the same
        // burst. State above is already cleared fail-closed; defer the one
        // expensive account assembly/rank to the coalesced game-tick path.
        accountRefreshPending = true;
        pohRefreshPending = true;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!OsrsStrategistConfig.GROUP.equals(event.getGroup())) return;
        var key = event.getKey();
        if (CompassConfigKeys.SIDEBAR_TEXT_SIZE.equals(key))
        {
            if (panel != null)
            {
                SidebarAccessibility.apply(panel, config.sidebarTextSize());
                updateAccountPanel();
            }
            return;
        }
        if (CompassConfigKeys.acknowledgesFirstUse(key)) acknowledgeFirstUse();
        if (CompassConfigKeys.isOverlay(key))
        {
            updateOverlaySettings();
            return;
        }
        if (CompassConfigKeys.FIRST_USE_COMPLETE.equals(key))
        {
            if (panel != null)
                panel.setFirstUseHintVisible(!config.firstUseComplete());
            return;
        }
        if (CompassConfigKeys.RESET_LEARNED_FEEDBACK.equals(key))
        {
            if (!config.resetLearnedFeedback()) return;
            try
            {
                // RuneLite shows ConfigItem.warning before setting this
                // one-shot action to true.
                resetLearnedFeedbackForActiveCharacter();
            }
            finally
            {
                configManager.setConfiguration(
                        OsrsStrategistConfig.GROUP,
                        CompassConfigKeys.RESET_LEARNED_FEEDBACK,
                        false);
            }
            return;
        }
        if (!CompassConfigKeys.changesPlanning(key)) return;

        if (CompassConfigKeys.changesStrategyProfile(key))
        {
            strategyProfile = PlayerStrategyProfile.fromConfig(config);
            saveStrategyProfile();
        }
        // A deliberate strategy-setting change is allowed to replace the plan
        // immediately; stability is for incidental game events only.
        latestRecommendations = emptyList();
        latestPlan = null;
        if (panel != null) panel.closeDetails();
        recommendationDetailsOverlay.clear();
        updateAccountPanel();
    }

    /** Clear only recommendation learning for the active RuneScape profile. */
    boolean resetLearnedFeedbackForActiveCharacter()
    {
        syncProfileState();
        var activeKey = accountProfileStore.activeProfileKey();
        if (activeKey == null) return false;

        persist(accountProfileStore::clearPreferences);
        preferenceProfile.clear();
        loadedProfileKey = activeKey;

        // Bypass hysteresis for this deliberate recovery action. Completion
        // history, goal/settings, milestone state, and observed account data
        // are intentionally left untouched.
        latestRecommendations = emptyList();
        accountRefreshPending = true;
        pohRefreshPending = true;
        if (recommendationDetailsOverlay != null)
            recommendationDetailsOverlay.clear();
        refreshStrategyImmediately();
        return true;
    }

    void applyRecommendationFeedback(String activityId, FeedbackAction action)
    {
        if (activityId == null || action == null) return;
        syncProfileState();
        Recommendation current = null;
        for (Recommendation recommendation : latestRecommendations)
            if (activityId.equals(recommendation.id))
            {
                current = recommendation;
                break;
            }
        if (current == null)
            preferenceProfile.apply(activityId, action);
        else
            preferenceProfile.applySemantic(
                    new RecommendationDeduplicator().semanticKey(current),
                    action);

        var historyAction = historyAction(action);
        if (historyAction != null)
        {
            recommendationHistory.add(activityId, null, historyAction);
            saveRecommendationHistory();
        }

        refreshStrategyImmediately();
        savePreferenceProfile();
    }

    private void updateRecommendationDetails(Recommendation recommendation)
    {
        if (recommendation == null
                || !OverlayDisplayState.from(config).showsDetails())
        {
            recommendationDetailsOverlay.clear();
            refreshMethodGuidanceOverlay();
        }
        else
        {
            AccountSnapshot account = latestData == null
                    ? null : latestData.account();
            recommendationDetailsOverlay.showRecommendation(recommendation,
                    GoalRecommendationContext.assess(
                            effectiveStrategyProfile().goal(),
                            recommendation,
                            account == null ? Membership.UNKNOWN
                                    : account.membership()));
            methodGuidanceOverlay.clear();
        }
    }

    private void refreshStrategyImmediately()
    {
        if (panel == null || latestData == null) return;
        lastStrategyRefreshAtMillis = System.currentTimeMillis();
        final long generation = uiGeneration.next();
        var profile = effectiveStrategyProfile();
        var result = evaluateAndStabilize(latestData, profile);
        latestRecommendations = new ArrayList<>(
                result.recommendations);
        updateTrackedMilestone(
                result.recommendations,
                latestData.collectionLog());
        updateGuidance(result, latestData);
        updateProgressTarget(result);

        Runnable update = () ->
        {
            if (!uiGeneration.isCurrent(generation) || panel == null) return;
            panel.updateRecommendations(result.recommendations);
            panel.updateOpportunities(result.getOpportunities());
            panel.updateProgress(progressAnalyticsService.snapshot(),
                    result.getPlan(), progressHistory);
            panel.revalidate();
            panel.repaint();
        };
        if (SwingUtilities.isEventDispatchThread()) update.run();
        else SwingUtilities.invokeLater(update);
    }

    private StrategyResult evaluate(GameData data, PlayerStrategyProfile profile)
    {
        return strategyEngine.evaluate(
                data,
                profile.mode(),
                profile.intent(),
                profile.questTolerance,
                profile.goal(),
                profile.usesGroupStorage(),
                profile.collectionist(),
                profile.allowsWilderness(),
                preferenceProfile);
    }

    private StrategyResult evaluateAndStabilize(
            GameData data, PlayerStrategyProfile profile)
    {
        StrategyResult fresh = recommendationStabilizer.stabilize(
                latestRecommendations, evaluate(data, profile));
        StrategyContext context = new StrategyContext(data,
                profile.mode(), profile.intent(),
                profile.questTolerance, profile.goal(),
                profile.usesGroupStorage(), profile.collectionist(),
                profile.allowsWilderness(), preferenceProfile);
        var previousPlan = latestPlan;
        latestPlan = planContinuityService.reconcile(previousPlan,
                fresh.getPlan(), context, fresh.recommendations);
        if (previousPlan != null && previousPlan.matchesContext(context)
                && previousPlan.getCurrentStep().isComplete(data)
                && latestPlan != null
                && !previousPlan.getCurrentStep().id.equals(
                        latestPlan.getCurrentStep().id))
            progressCheckpointPending |= progressAnalyticsService
                    .recordMilestone(new ProgressMilestone(
                            "plan-step:"
                                    + previousPlan.getCurrentStep().id,
                            ProgressMilestoneType.PLAN_STEP,
                            previousPlan.getCurrentStep().getObjective()
                                    + " complete",
                            get(410),
                            profile.goal().name(),
                            System.currentTimeMillis()));
        return fresh.withPlan(latestPlan);
    }

    private void updateProgressTarget(StrategyResult result)
    {
        if (result == null || result.recommendations.isEmpty())
        {
            progressAnalyticsService.clearTarget();
            return;
        }
        var top = result.recommendations.get(0);
        var plan = top.plan();
        if (plan == null || plan.method() == null
                || plan.method().getSkill() == null
                || top.getCurrentExecutionTargetLevel() < 2)
        {
            progressAnalyticsService.clearTarget();
            return;
        }
        progressAnalyticsService.setTarget(new ProgressTarget(top.id,
                plan.method().id, plan.method().getSkill(),
                top.getCurrentExecutionTargetLevel()));
    }

    private void updateProgressPanel()
    {
        if (panel == null || !progressUiUpdatePending.compareAndSet(false, true))
            return;
        Runnable update = () ->
        {
            progressUiUpdatePending.set(false);
            if (panel != null)
                panel.updateProgress(progressAnalyticsService.snapshot(),
                        latestPlan, progressHistory);
        };
        if (SwingUtilities.isEventDispatchThread()) update.run();
        else SwingUtilities.invokeLater(update);
    }

    private void updateGuidance(StrategyResult result, GameData data)
    {
        if (!OverlayDisplayState.from(config).showsMethodGuidance(
                    recommendationDetailsOverlay.hasRecommendation())
                || result == null
                || result.recommendations.isEmpty())
        {
            methodGuidanceOverlay.clear();
            return;
        }
        GuidanceChecklist checklist = methodGuidanceService.build(
                result.recommendations.get(0), data);
        methodGuidanceOverlay.update(checklist);
    }

    private void refreshMethodGuidanceOverlay()
    {
        if (!OverlayDisplayState.from(config).showsMethodGuidance(
                    recommendationDetailsOverlay.hasRecommendation())
                || latestRecommendations.isEmpty() || latestData == null)
        {
            methodGuidanceOverlay.clear();
            return;
        }
        methodGuidanceOverlay.update(methodGuidanceService.build(
                latestRecommendations.get(0), latestData));
    }

    private void syncProfileState()
    {
        var activeKey = accountProfileStore.activeProfileKey();
        if (Objects.equals(loadedProfileKey, activeKey)) return;
        preferenceProfile.clear();
        recommendationHistory.clear();
        if (activeKey == null)
        {
            loadedProfileKey = null;
            strategyProfile = PlayerStrategyProfile.fromConfig(config);
            trackedMilestone = null;
            return;
        }
        accountProfileStore.loadPreferences(preferenceProfile);
        strategyProfile = accountProfileStore.loadStrategy(
                PlayerStrategyProfile.fromConfig(config));
        trackedMilestone = accountProfileStore.loadMilestone();
        accountProfileStore.loadRecommendations(recommendationHistory);
        loadedProfileKey = activeKey;
    }

    private void syncProgressHistory(AccountSnapshot account)
    {
        var activeKey = accountProfileStore.activeProfileKey();
        if (Objects.equals(loadedProgressProfileKey, activeKey)
                && activeKey != null) return;
        progressHistory = activeKey == null
                ? new ProgressHistory() : accountProfileStore.loadProgress();
        progressAnalyticsService.beginSession(account);
        loadedProgressProfileKey = activeKey;
        progressCheckpointPending = false;
        lastProgressCheckpointAtMillis = System.currentTimeMillis();
    }

    private void archiveProgressSession()
    {
        if (loadedProgressProfileKey == null
                || !Objects.equals(loadedProgressProfileKey,
                        accountProfileStore.activeProfileKey()))
            return;
        progressHistory.archive(progressAnalyticsService.snapshot());
        persist(() -> accountProfileStore.saveProgress(progressHistory));
        progressAnalyticsService.reset();
        progressCheckpointPending = false;
    }

    /**
     * Persists a replaceable preview of the active session at most once per
     * minute. A crash or late profile-change signal can therefore lose only
     * the newest interval without writing configuration for every XP drop.
     */
    private void checkpointProgressSession()
    {
        if (!progressCheckpointPending || loadedProgressProfileKey == null
                || !Objects.equals(loadedProgressProfileKey,
                        accountProfileStore.activeProfileKey()))
            return;
        var now = System.currentTimeMillis();
        if (now - lastProgressCheckpointAtMillis
                < PROGRESS_CHECKPOINT_INTERVAL_MILLIS) return;
        persist(() -> accountProfileStore.saveProgress(
                progressHistory.checkpoint(progressAnalyticsService.snapshot(now))));
        progressCheckpointPending = false;
        lastProgressCheckpointAtMillis = now;
    }

    private PlayerStrategyProfile effectiveStrategyProfile()
    {
        if (strategyProfile == null) strategyProfile = PlayerStrategyProfile.fromConfig(config);
        return strategyProfile;
    }

    private void updateAccountPanel()
    {
        if (panel == null) return;
        lastStrategyRefreshAtMillis = System.currentTimeMillis();
        final long generation = uiGeneration.next();
        var data = strategyDataAssembler.read();
        if (data == null || data.account() == null)
        {
            latestData = null;
            latestRecommendations = emptyList();
            methodGuidanceOverlay.clear();
            recommendationDetailsOverlay.clear();
            var profile = effectiveStrategyProfile();
            SwingUtilities.invokeLater(() ->
            {
                if (!uiGeneration.isCurrent(generation) || panel == null) return;
                panel.updateAccount("Waiting for login...", "Unknown", 0);
                panel.updateGoal(profile.goal());
                panel.updateStrategy(profile.mode(),
                        profile.intent(), profile.questTolerance);
            panel.updateRecommendations(emptyList());
            panel.updateOpportunities(emptyList());
            panel.updateProgress(null, null, null);
            });
            return;
        }

        latestData = data;
        syncProfileState();
        syncProgressHistory(data.account());
        for (ProgressMilestone milestone : progressMilestoneDetector.observe(
                data, effectiveStrategyProfile().goal(),
                System.currentTimeMillis()))
            progressCheckpointPending |= progressAnalyticsService
                    .recordMilestone(milestone);

        var completedCheckpoint = trackedMilestone;
        MilestoneCompletion completion = milestoneTracker.detectCompletion(
                completedCheckpoint, data.account());
        if (completion != null)
        {
            if (completedCheckpoint == null
                    || !completedCheckpoint.progressionProtected)
            {
                preferenceProfile.addTemporaryScoreAdjustment(
                        completion.activityId, COMPLETION_VARIETY_PENALTY,
                        COMPLETION_VARIETY_DURATION_MILLIS);
                savePreferenceProfile();
            }

            recommendationHistory.add(
                    completion.activityId,
                    completion.title,
                    RecommendationHistoryAction.COMPLETED);
            saveRecommendationHistory();

            trackedMilestone = null;
            saveTrackedMilestone();
            milestoneRewardOverlay.show(completion);
            progressCheckpointPending |= progressAnalyticsService
                    .recordMilestone(new ProgressMilestone(
                            "skill-checkpoint:" + completion.activityId
                                    + ":" + completion.getSkill().name()
                                    .toLowerCase(Locale.ROOT) + ":"
                                    + completion.targetLevel,
                            ProgressMilestoneType.SKILL_LEVEL,
                            completion.title,
                            get(411),
                            effectiveStrategyProfile().goal().name(),
                            System.currentTimeMillis()));
        }

        var profile = effectiveStrategyProfile();
        var result = evaluateAndStabilize(data, profile);
        latestRecommendations = new ArrayList<>(
                result.recommendations);
        updateTrackedMilestone(
                result.recommendations,
                data.collectionLog());
        updateGuidance(result, data);
        updateProgressTarget(result);
        var account = data.account();

        SwingUtilities.invokeLater(() ->
        {
            if (!uiGeneration.isCurrent(generation) || panel == null) return;
            panel.updateAccount(
                    account.playerName,
                    account.getAccountTypeName(),
                    account.membership(),
                    account.getTotalLevel());
            panel.updateGoal(profile.goal());
            panel.updateStrategy(
                    profile.mode(),
                    profile.intent(),
                    profile.questTolerance);
            panel.updateRecommendations(result.recommendations);
            panel.updateOpportunities(result.getOpportunities());
            panel.updateProgress(progressAnalyticsService.snapshot(),
                    result.getPlan(), progressHistory);
        });
    }

    private void updateTrackedMilestone(
            List<Recommendation> recommendations,
            CollectionLogSnapshot collectionLog)
    {
        TrackedMilestone candidate = milestoneTracker.fromRecommendations(
                recommendations,
                collectionLog);
        if (milestoneTracker.sameCheckpoint(trackedMilestone, candidate)) return;
        trackedMilestone = candidate;
        saveTrackedMilestone();
    }

    private void savePreferenceProfile()
    {
        persist(() -> accountProfileStore.savePreferences(preferenceProfile));
        loadedProfileKey = accountProfileStore.activeProfileKey();
    }

    private void acknowledgeFirstUse()
    {
        if (config.firstUseComplete()) return;
        configManager.setConfiguration(OsrsStrategistConfig.GROUP,
                CompassConfigKeys.FIRST_USE_COMPLETE, true);
        if (panel != null) panel.setFirstUseHintVisible(false);
    }

    private void saveStrategyProfile()
    {
        if (accountProfileStore.activeProfileKey() == null) return;
        persist(() -> accountProfileStore.saveStrategy(strategyProfile));
        loadedProfileKey = accountProfileStore.activeProfileKey();
    }

    private void updateOverlaySettings()
    {
        var state = OverlayDisplayState.from(config);
        if (panel != null)
            panel.setDetailsOverlayEnabled(state.showsDetails());
        if (!state.showsDetails()) recommendationDetailsOverlay.clear();
        if (!state.showsMethodGuidance(
                recommendationDetailsOverlay.hasRecommendation()))
        {
            methodGuidanceOverlay.clear();
            return;
        }
        if (latestData != null && !latestRecommendations.isEmpty())
            methodGuidanceOverlay.update(methodGuidanceService.build(
                    latestRecommendations.get(0), latestData));
    }

    private void registerOverlays()
    {
        if (!overlayLifecycle.beginRegistration()) return;
        overlayManager.add(milestoneRewardOverlay);
        overlayManager.add(methodGuidanceOverlay);
        overlayManager.add(recommendationDetailsOverlay);
    }

    private void unregisterOverlays()
    {
        if (!overlayLifecycle.beginRemoval()) return;
        overlayManager.remove(milestoneRewardOverlay);
        overlayManager.remove(methodGuidanceOverlay);
        overlayManager.remove(recommendationDetailsOverlay);
    }

    private void saveRecommendationHistory()
    {
        persist(() -> accountProfileStore.saveRecommendations(
                recommendationHistory));
        loadedProfileKey = accountProfileStore.activeProfileKey();
    }

    private void saveTrackedMilestone()
    {
        persist(() -> accountProfileStore.saveMilestone(trackedMilestone));
        loadedProfileKey = accountProfileStore.activeProfileKey();
    }

    private void persist(Runnable write)
    {
        savingProfileConfiguration = true;
        try { write.run(); }
        finally { savingProfileConfiguration = false; }
    }

    private static RecommendationHistoryAction historyAction(FeedbackAction action)
    {
        switch (action)
        {
            case LATER:
                return RecommendationHistoryAction.LATER;
            case NOT_TODAY:
                return RecommendationHistoryAction.NOT_TODAY;
            case DISLIKE:
                return RecommendationHistoryAction.DISLIKE;
            default:
                return null;
        }
    }

    private BufferedImage loadPluginIcon()
    {
        return loadPluginIcon(getClass(), "/gielinor-compass-icon.png");
    }

    static BufferedImage loadPluginIcon(Class<?> owner, String resource)
    {
        try
        {
            var icon = ImageUtil.loadImageResource(owner, resource);
            if (icon != null) return icon;
        }
        catch (RuntimeException ignored)
        {
            // A packaging mistake must not prevent RuneLite from starting.
        }
        return new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
    }
}

package compass;
import static java.util.Collections.*;

import java.awt.Color;
import java.awt.FontMetrics;
import java.util.*;
import net.runelite.client.ui.overlay.components.LineComponent;

/** Shared measured text and line rendering for Compass overlays. */
final class OverlayUi
{
    private OverlayUi() { }

    static LineComponent line(String text, Color color)
    {
        return LineComponent.builder().left(text).leftColor(color).build();
    }

    static List<String> wrap(String text, FontMetrics metrics, int width)
    {
        List<String> lines = new ArrayList<>();
        if (text == null || text.trim().isEmpty()) return singletonList("");
        var current = new StringBuilder();
        for (String word : text.trim().split("\\s+"))
        {
            if (current.length() > 0
                    && metrics.stringWidth(current + " " + word) > width)
            {
                lines.add(current.toString());
                current.setLength(0);
            }
            if (metrics.stringWidth(word) <= width)
            {
                if (current.length() > 0) current.append(' ');
                current.append(word);
                continue;
            }
            for (int start = 0; start < word.length();)
            {
                int end = start + 1;
                while (end <= word.length()
                        && metrics.stringWidth(word.substring(start, end)) <= width) end++;
                end = Math.max(start + 1, end - 1);
                if (current.length() > 0)
                {
                    lines.add(current.toString());
                    current.setLength(0);
                }
                if (end < word.length()) lines.add(word.substring(start, end));
                else current.append(word, start, end);
                start = end;
            }
        }
        if (current.length() > 0) lines.add(current.toString());
        return lines.isEmpty() ? singletonList(text) : lines;
    }
}

package compass;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.*;

/** Movable on-game checklist complementing the Compass sidebar. */
class MethodGuidanceOverlay extends OverlayPanel
{
    private static final int OVERLAY_WIDTH = 320;
    private static final int STEP_TEXT_WIDTH = 285;

    private GuidanceChecklist checklist;

    @Inject
    public MethodGuidanceOverlay(OsrsStrategistPlugin plugin)
    {
        super(plugin);
        setPosition(OverlayPosition.TOP_LEFT);
        setMovable(true);
        panelComponent.setPreferredSize(new Dimension(OVERLAY_WIDTH, 0));
    }

    public synchronized void update(GuidanceChecklist checklist)
    {
        this.checklist = checklist;
    }

    public synchronized void clear()
    {
        checklist = null;
    }

    @Override
    public synchronized Dimension render(Graphics2D graphics)
    {
        if (checklist == null) return null;
        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Method Guidance")
                .color(StrategistTheme.GOLD)
                .build());
        var metrics = graphics.getFontMetrics();
        addSection("METHOD", checklist.title, metrics);
        addSection("BRING", checklist.getBring(), metrics);
        addSection("WHERE", checklist.getWhere(), metrics);
        addSection("DO", fallbackAction(checklist), metrics);
        addSection("PROGRESS", checklist.getProgress(), metrics);
        addSection("IMPORTANT", checklist.getImportant(), metrics);
        return super.render(graphics);
    }

    private void addSection(String heading, String value, FontMetrics metrics)
    {
        if (value == null || value.trim().isEmpty()) return;
        panelComponent.getChildren().add(LineComponent.builder()
                .left(heading)
                .leftColor("IMPORTANT".equals(heading)
                        ? StrategistTheme.WARNING : StrategistTheme.GOLD_SOFT)
                .build());
        for (String line : wrap(value, metrics, STEP_TEXT_WIDTH))
            panelComponent.getChildren().add(OverlayUi.line(line,
                    "IMPORTANT".equals(heading)
                            ? StrategistTheme.WARNING : StrategistTheme.TEXT));
    }

    private static String fallbackAction(GuidanceChecklist checklist)
    {
        if (checklist.getAction() != null
                && !checklist.getAction().trim().isEmpty())
            return checklist.getAction();
        var pending = checklist.firstPending();
        return pending == null ? checklist.getSubtitle() : pending.getLabel();
    }

    static java.util.List<String> wrap(String text, FontMetrics metrics, int maxWidth)
    {
        return OverlayUi.wrap(text, metrics, maxWidth);
    }

}

/** Short-lived CLOG-style reward surface for any Compass completion. */
class MilestoneRewardOverlay extends OverlayPanel
{
    private static final long DISPLAY_MILLIS = 6500L;

    private StrategistRewardNotification activeReward;
    private long hideAtMillis;

    @Inject
    public MilestoneRewardOverlay(OsrsStrategistPlugin plugin)
    {
        super(plugin);
        setPosition(OverlayPosition.TOP_CENTER);
        setMovable(false);
    }

    public synchronized void show(MilestoneCompletion completion)
    {
        show(StrategistRewardNotification.fromMilestone(completion));
    }

    public synchronized void show(StrategistRewardNotification reward)
    {
        activeReward = reward;
        hideAtMillis = reward == null
                ? 0L
                : System.currentTimeMillis() + DISPLAY_MILLIS;
    }

    public synchronized void clear()
    {
        activeReward = null;
        hideAtMillis = 0L;
    }

    @Override
    public synchronized Dimension render(Graphics2D graphics)
    {
        if (activeReward == null
                || System.currentTimeMillis() >= hideAtMillis)
        {
            clear();
            return null;
        }

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text(activeReward.getHeader())
                        .color(StrategistTheme.GOLD)
                        .build()
        );
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left(activeReward.getLeft())
                        .right(activeReward.getRight())
                        .build()
        );
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left(activeReward.getFooterLeft())
                        .right(activeReward.getFooterRight())
                        .build()
        );

        return super.render(graphics);
    }
}

/**
 * Movable on-game decision summary.
 *
 * <p>The full planner graph remains internal; players see only the selected
 * goal relationship, reason, blocker, current step, and next unlock when it is
 * useful.</p>
 */
class RecommendationDetailsOverlay extends OverlayPanel
{
    private static final int PANEL_WIDTH = 340;
    private static final int TEXT_WIDTH = 310;
    private Recommendation recommendation;
    private GoalRecommendationContext goalContext;

    @Inject
    public RecommendationDetailsOverlay(OsrsStrategistPlugin plugin)
    {
        super(plugin);
        setPosition(OverlayPosition.TOP_RIGHT);
        setMovable(true);
        panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));
    }

    public synchronized void showRecommendation(Recommendation recommendation)
    {
        showRecommendation(recommendation, null);
    }

    public synchronized void showRecommendation(Recommendation recommendation,
            GoalRecommendationContext goalContext)
    {
        this.recommendation = recommendation;
        this.goalContext = goalContext;
    }

    public synchronized void clear()
    {
        recommendation = null;
        goalContext = null;
    }

    public synchronized boolean hasRecommendation()
    {
        return recommendation != null;
    }

    @Override
    public synchronized Dimension render(Graphics2D graphics)
    {
        if (recommendation == null) return null;

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Compass Details")
                .color(StrategistTheme.GOLD)
                .build());

        var metrics = graphics.getFontMetrics();
        for (Presentation.Section section
                : Presentation.detailsSections(
                        recommendation, goalContext))
        {
            addLine(section.heading, StrategistTheme.GOLD_SOFT);
            for (String wrapped : wrap(section.getValue(), metrics, TEXT_WIDTH))
                addLine(wrapped, stateColor(section.getValue()));
        }
        return super.render(graphics);
    }

    private void addLine(String text, Color color)
    {
        panelComponent.getChildren().add(OverlayUi.line(text, color));
    }

    private static Color stateColor(String line)
    {
        if (line.startsWith("✓")) return StrategistTheme.SUCCESS;
        if (line.startsWith("✕") || line.startsWith("Blocked")) return StrategistTheme.DANGER;
        if (line.startsWith("?")) return StrategistTheme.WARNING;
        return StrategistTheme.TEXT;
    }

    static List<String> wrap(String text, FontMetrics metrics, int maxWidth)
    {
        if (metrics == null || maxWidth <= 0)
            return Collections.singletonList(text == null ? "" : text);
        return OverlayUi.wrap(text, metrics, maxWidth);
    }

}

package compass;
import lombok.*;
import static net.runelite.api.gameval.ItemID.*;
import static net.runelite.api.Skill.*;
import static java.lang.Math.*;
import static java.util.Collections.*;

import java.util.*;
import javax.inject.*;
import net.runelite.api.*;
import static compass.Text.get;

/**
 * Shared account-aware material planner for deterministic recommendations.
 *
 * <p>This is the single place that decides whether an observed item can satisfy
 * a milestone plan. Main, Iron, GIM, and UIM guidance therefore use the same
 * shortfall math instead of each skill reimplementing bank semantics.</p>
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class AccountResourcePlanner
{
    private final MarketPriceService marketPriceService;
    private final ResourceSourceCatalog resourceSourceCatalog;

    public SupplyPlan plan(
            GameData data,
            List<MethodInput> rawNeeds,
            boolean useGroupStorage)
    {
        var account = data == null ? null : data.account();
        AccountMode mode = account == null
                ? AccountMode.UNKNOWN
                : AccountMode.fromTypeCode(account.modeCode());
        var observed = new ItemIndex(data, useGroupStorage);
        var primaryObserved = observed.usableOwnershipObserved();
        var groupIncluded = useGroupStorage && mode.isGroupIronman();
        var groupObserved = observed.groupStorageObserved();

        var needs = merge(rawNeeds);
        List<String> required = new ArrayList<>();
        List<String> verified = new ArrayList<>();
        List<String> missing = new ArrayList<>();
        List<String> reusable = new ArrayList<>();
        List<String> restrictedItems = new ArrayList<>();
        List<MethodInput> missingInputs = new ArrayList<>();
        for (MethodInput need : needs)
        {
            var reusableSource = reusableSourceFor(observed, need.getName());
            var owned = observed.quantity(need.getName());
            var restricted = observed.restrictedQuantity(need.getName());
            int shortfall = reusableSource == null
                    ? max(0, need.quantity - owned)
                    : 0;
            required.add(format(need.quantity) + " " + need.getName());
            if (reusableSource == null)
                verified.add(format(owned) + " " + need.getName());
            else
                reusable.add(need.getName() + " supplied by " + reusableSource);
            if (shortfall > 0)
            {
                missing.add(format(shortfall) + " " + need.getName());
                missingInputs.add(new MethodInput(
                        need.getName(), need.itemId, shortfall));
            }
            if (restricted > 0)
                restrictedItems.add(format(restricted) + " " + need.getName());
        }

        String guidance = buildGuidance(
                data,
                mode,
                primaryObserved,
                groupIncluded,
                groupObserved,
                required, verified, missing, reusable, restrictedItems,
                missingInputs);
        return new SupplyPlan(
                mode,
                primaryObserved,
                groupIncluded,
                groupObserved,
                missingInputs,
                guidance);
    }

    private String buildGuidance(
            GameData data,
            AccountMode mode,
            boolean primaryObserved,
            boolean groupIncluded,
            boolean groupObserved, List<String> required,
            List<String> verified, List<String> missing,
            List<String> reusable, List<String> restricted,
            List<MethodInput> missingInputs)
    {
        if (required.isEmpty())
        {
            return get(69);
        }

        var text = new StringBuilder();
        text.append("Need ").append(join(required)).append(". ");
        if (!reusable.isEmpty())
        {
            text.append(get(1588)).append(join(reusable)).append(". ");
        }

        // An unobserved ownership surface is unknown, never empty. UIM uses
        // inventory/equipment evidence instead of the conventional bank.
        if (!primaryObserved)
        {
            if (mode == AccountMode.ULTIMATE_IRONMAN)
                text.append(get(80));
            else
                text.append(get(1376))
                        .append(get(81));
            if (groupIncluded && !groupObserved)
            {
                text.append(get(82));
            }
            return text.toString();
        }

        if (!verified.isEmpty())
        {
            text.append(get(1589))
                    .append(join(verified)).append(". ");
        }

        if (missing.isEmpty())
        {
            text.append(get(83));
            if (groupIncluded && groupObserved)
            {
                text.append(get(84));
            }
            appendRestrictedUimNote(text, restricted);
            return text.toString();
        }

        var shortfall = join(missing);
        if (mode.usesGrandExchange())
        {
            appendMainOpportunityGuidance(text, data, shortfall,
                    missingInputs);
        }
        else if (mode == AccountMode.ULTIMATE_IRONMAN)
        {
            List<String> routes = sourceRoutes(missingInputs, mode,
                    data == null || data.account() == null
                            ? Membership.UNKNOWN
                            : data.account().membership(), true);
            text.append(get(1377)).append(shortfall)
                    .append(get(85));
            if (!routes.isEmpty())
                text.append(" Route: ").append(routes.get(0));
            text.append(get(86));
        }
        else if (mode.isGroupIronman())
        {
            text.append("Self-source ").append(shortfall)
                    .append(get(1378));
            if (groupIncluded && groupObserved)
            {
                text.append(get(87));
            }
            else if (groupIncluded)
            {
                text.append(get(70));
            }
        }
        else if (mode.isIronLike())
        {
            List<String> routes = sourceRoutes(missingInputs, mode,
                    data == null || data.account() == null
                            ? Membership.UNKNOWN
                            : data.account().membership(), false);
            text.append("Self-source ").append(shortfall)
                    .append(get(1378));
            if (!routes.isEmpty())
                text.append(" Route: ").append(routes.get(0));
        }
        else
        {
            text.append("Source ").append(shortfall)
                    .append(get(71));
        }

        appendRestrictedUimNote(text, restricted);
        return text.toString();
    }

    private void appendMainOpportunityGuidance(StringBuilder text,
            GameData data, String shortfall,
            List<MethodInput> missingInputs)
    {
        Long cost = exactCost(missingInputs);
        List<String> routes = mainRoutes(missingInputs,
                data == null || data.account() == null
                        ? Membership.UNKNOWN
                        : data.account().membership());
        AccountEconomySnapshot economy = data == null ? null : data.economy();
        long coins = economy == null ? 0 : max(0, economy.coins);
        boolean priced = cost != null && cost > 0 && economy != null
                && economy.confidence == Confidence.VERIFIED;
        boolean affordable = priced && coins >= cost;
        boolean buy = affordable && (cost <= 1_000L && coins >= 5_000L
                || cost <= coins / 10L && coins - cost >= 10_000L);
        if (buy)
        {
            text.append("Buy ").append(shortfall)
                    .append(get(1379))
                    .append(get(1380))
                    .append(format(cost))
                    .append(get(72))
                    .append(format(coins))
                    .append(get(1381));
            return;
        }
        if (affordable && !routes.isEmpty())
        {
            text.append("Self-source ").append(shortfall).append(". ")
                    .append(get(1382))
                    .append(format(cost))
                    .append(" of ")
                    .append(format(coins))
                    .append(get(73))
                    .append(routes.get(0));
            return;
        }
        if (priced && !affordable)
        {
            text.append(get(74))
                    .append(format(cost))
                    .append(get(1590))
                    .append(format(coins))
                    .append(get(1383));
            if (!routes.isEmpty())
                text.append(get(75))
                        .append(routes.get(0));
            return;
        }

        text.append(get(76))
                .append(get(77));
        if (!routes.isEmpty())
            text.append(get(1384)).append(routes.get(0));
    }

    private Long exactCost(List<MethodInput> missing)
    {
        if (marketPriceService == null || missing == null || missing.isEmpty())
            return null;
        long total = 0;
        for (MethodInput input : missing)
        {
            if (input == null || input.quantity <= 0) continue;
            MarketPriceQuote quote = marketPriceService.quote(input.getName());
            if (quote == null || !quote.hasPrice()) return null;
            if (quote.getUnitPrice() > Long.MAX_VALUE / input.quantity
                    || total > Long.MAX_VALUE
                            - quote.getUnitPrice() * input.quantity)
                return Long.MAX_VALUE;
            total += quote.getUnitPrice() * input.quantity;
        }
        return total > 0 ? total : null;
    }

    private List<String> mainRoutes(List<MethodInput> missingInputs,
            Membership membership)
    {
        if (resourceSourceCatalog == null || missingInputs == null)
            return emptyList();
        List<String> routes = new ArrayList<>();
        for (MethodInput input : missingInputs)
        {
            for (String route : resourceSourceCatalog.suggestions(
                    input.getName(), AccountMode.MAIN, membership, false))
            {
                if (!routes.contains(route)) routes.add(route);
            }
        }
        return routes;
    }

    private List<String> sourceRoutes(List<MethodInput> missingInputs,
            AccountMode mode, Membership membership,
            boolean justInTime)
    {
        if (resourceSourceCatalog == null || missingInputs == null)
            return emptyList();
        List<String> routes = new ArrayList<>();
        for (MethodInput input : missingInputs)
            for (String route : resourceSourceCatalog.suggestions(
                    input.getName(), mode, membership, justInTime))
                if (!routes.contains(route)) routes.add(route);
        return routes;
    }

    private static void appendRestrictedUimNote(
            StringBuilder text,
            List<String> restricted)
    {
        if (restricted == null || restricted.isEmpty()) return;
        text.append(get(78))
                .append(join(restricted))
                .append(get(79));
    }

    /**
     * Only currently equipped reusable rune sources waive rune consumption.
     * Owning a staff in a bank is not enough because build requirements and the
     * recommendation's intended equipment setup may make it unusable.
     */
    private static String reusableSourceFor(
            ItemIndex observed,
            String itemName)
    {
        if (observed == null || itemName == null) return null;
        var rune = Names.lower(itemName);
        if ("fire rune".equals(rune))
        {
            return firstEquipped(observed,
                    "Staff of fire", get(1591), get(1592),
                    get(1593), get(1594),
                    get(1595), get(1385),
                    get(1596), get(1386),
                    "Tome of fire");
        }
        if ("water rune".equals(rune))
        {
            return firstEquipped(observed,
                    "Staff of water", get(1597), get(1387),
                    "Mud battlestaff", get(1598),
                    get(1595), get(1385),
                    get(1599), get(1600));
        }
        if ("earth rune".equals(rune))
        {
            return firstEquipped(observed,
                    "Staff of earth", get(1601), get(1388),
                    get(1593), get(1594),
                    "Mud battlestaff", get(1598),
                    get(1602), get(1603));
        }
        if ("air rune".equals(rune))
        {
            return firstEquipped(observed,
                    "Staff of air", "Air battlestaff", get(1604),
                    get(1596), get(1386),
                    get(1599), get(1600),
                    get(1602), get(1603));
        }
        return null;
    }

    private static String firstEquipped(
            ItemIndex observed,
            String... candidates)
    {
        for (String candidate : candidates)
        {
            if (observed.equipped(candidate)) return candidate;
        }
        return null;
    }

    /** Merge duplicate recipe rows before comparing them with storage. */
    private static List<MethodInput> merge(
            List<MethodInput> rawNeeds)
    {
        if (rawNeeds == null || rawNeeds.isEmpty()) return new ArrayList<>();
        Map<String, MutableNeed> merged = new LinkedHashMap<>();
        for (MethodInput input : rawNeeds)
        {
            if (input == null || input.getName() == null
                    || input.getName().trim().isEmpty()
                    || input.quantity <= 0)
            {
                continue;
            }
            var key = Names.lower(input.getName());
            var existing = merged.get(key);
            if (existing == null)
            {
                merged.put(key, new MutableNeed(
                        input.getName().trim(),
                        input.itemId,
                        input.quantity));
            }
            else
            {
                existing.quantity = safeAdd(
                        existing.quantity, input.quantity);
            }
        }

        List<MethodInput> result = new ArrayList<>();
        for (MutableNeed need : merged.values())
        {
            result.add(new MethodInput(
                    need.name, need.itemId, need.quantity));
        }
        return result;
    }

    private static int safeAdd(int a, int b)
    {
        if (a >= Integer.MAX_VALUE - b) return Integer.MAX_VALUE;
        return a + b;
    }

    private static String join(List<String> parts)
    {
        if (parts == null || parts.isEmpty()) return "nothing";
        if (parts.size() == 1) return parts.get(0);
        if (parts.size() == 2) return parts.get(0) + " and " + parts.get(1);
        var text = new StringBuilder();
        for (int i = 0; i < parts.size(); i++)
        {
            if (i > 0) text.append(i == parts.size() - 1 ? ", and " : ", ");
            text.append(parts.get(i));
        }
        return text.toString();
    }

    private static String format(long value)
    {
        return String.format(Locale.ROOT, "%,d", max(0, value));
    }


    private static final class MutableNeed
    {
        private final String name;
        private final int itemId;
        private int quantity;

        private MutableNeed(String name, int itemId, int quantity)
        {
            this.name = name;
            this.itemId = itemId;
            this.quantity = max(0, quantity);
        }
    }
}

/**
 * Resolves the best Agility course from level, membership, quest state, and
 * direct region observations. Direct observation is the strongest evidence.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class AgilityAccessEvaluator
{
    private final AgilityCourseCatalog catalog;

    public AgilityCourseDefinition bestStandardCourse(GameData data)
    {
        AgilityCourseDefinition best = null;
        for (AgilityCourseDefinition course : catalog.all())
        {
            if (course.wilderness || !isVerifiedAvailable(data, course))
            {
                continue;
            }
            if (best == null
                    || course.getRequiredLevel() > best.getRequiredLevel())
            {
                best = course;
            }
        }
        return best;
    }

    public EvidenceCheck courseCheck(
            GameData data,
            AgilityCourseDefinition course)
    {
        if (course == null)
        {
            return new EvidenceCheck(
                    "agility:course",
                    get(1390),
                    RequirementState.CHECK_NEEDED,
                    get(0)
            );
        }

        var account = data == null ? null : data.account();
        if (account == null)
        {
            return unknown(course, get(1391));
        }

        var level = account.level(Skill.AGILITY);
        if (level < course.getRequiredLevel())
        {
            return new EvidenceCheck(
                    "agility:" + course.id,
                    course.getDisplayName(),
                    RequirementState.BLOCKED,
                    "Requires " + course.getRequiredLevel()
                            + get(1392) + level + "."
            );
        }

        if (account.membership() != Membership.P2P)
        {
            return new EvidenceCheck(
                    "agility:" + course.id,
                    course.getDisplayName(),
                    RequirementState.BLOCKED,
                    get(1)
            );
        }

        var memory = data.accessMemory();
        if (memory != null && memory.hasObserved(course.observationKey()))
        {
            return verified(
                    course,
                    get(2)
            );
        }

        var quest = course.requiredQuest;
        if (quest != null)
        {
            var quests = data.quests();
            QuestStatus status = quests == null
                    ? QuestStatus.UNKNOWN
                    : quests.statusOf(quest);

            if (status == QuestStatus.COMPLETE)
            {
                return verified(
                        course,
                        quest + get(3)
                );
            }
            if (status == QuestStatus.NOT_STARTED
                    || status == QuestStatus.IN_PROGRESS)
            {
                return new EvidenceCheck(
                        "agility:" + course.id,
                        course.getDisplayName(),
                        RequirementState.BLOCKED,
                        quest + get(1690)
                );
            }
            return unknown(
                    course,
                    get(1691) + quest + get(1393)
            );
        }

        return verified(
                course,
                get(4)
        );
    }

    public EvidenceCheck wildernessCourseCheck(GameData data)
    {
        return courseCheck(data, catalog.wildernessCourse());
    }

    private boolean isVerifiedAvailable(
            GameData data,
            AgilityCourseDefinition course)
    {
        return courseCheck(data, course).getState() == RequirementState.VERIFIED;
    }

    private EvidenceCheck verified(
            AgilityCourseDefinition course,
            String evidence)
    {
        return new EvidenceCheck(
                "agility:" + course.id,
                course.getDisplayName(),
                RequirementState.VERIFIED,
                evidence
        );
    }

    private EvidenceCheck unknown(
            AgilityCourseDefinition course,
            String evidence)
    {
        return new EvidenceCheck(
                "agility:" + course.id,
                course.getDisplayName(),
                RequirementState.CHECK_NEEDED,
                evidence
        );
    }
}

/**
 * Resolves Farming access from the strongest evidence available.
 *
 * <p>Direct observation wins. Otherwise, open-world patches are inferred for a
 * member account and quest-gated patches are inferred only when the required
 * quest is confirmed complete. This is the pattern other content systems can
 * follow later: live state first, remembered proof second, safe inference third.</p>
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class FarmingAccessEvaluator
{
    private final FarmingAccessCatalog catalog;

    public FarmingSnapshot evaluate(
            AccountSnapshot account,
            QuestSnapshot quests,
            AccessMemorySnapshot memory,
            FarmingSnapshot existing)
    {
        Set<String> reachable = new HashSet<>();
        Map<String, Capability> tools = new HashMap<>();
        Map<String, Long> readyAt = new HashMap<>();

        if (existing != null)
        {
            reachable.addAll(existing.getReachablePatchIds());
            tools.putAll(existing.getLeprechaunTools());
            readyAt.putAll(existing.getPatchReadyAtMillis());
        }

        if (account == null
                || account.membership() != Membership.P2P)
        {
            return new FarmingSnapshot(reachable, tools, readyAt);
        }

        AccessMemorySnapshot safeMemory = memory == null
                ? AccessMemorySnapshot.empty()
                : memory;

        for (FarmingAccessDefinition definition : catalog.all())
        {
            if (safeMemory.hasObserved(definition.observationKey()))
            {
                reachable.add(definition.id);
                continue;
            }

            var requiredQuest = definition.requiredQuest;
            if (requiredQuest == null)
            {
                reachable.add(definition.id);
                continue;
            }

            if (quests != null
                    && quests.statusOf(requiredQuest) == QuestStatus.COMPLETE)
            {
                reachable.add(definition.id);
            }
        }

        return new FarmingSnapshot(reachable, tools, readyAt);
    }

    public String firstReachablePatchName(FarmingSnapshot farming)
    {
        if (farming == null)
        {
            return null;
        }

        for (FarmingAccessDefinition definition : catalog.all())
        {
            if (farming.isPatchReachable(definition.id))
            {
                return definition.getDisplayName();
            }
        }
        return null;
    }

    public String firstReachableHerbPatchName(FarmingSnapshot farming)
    {
        if (farming == null)
        {
            return null;
        }

        for (FarmingAccessDefinition definition : catalog.all())
        {
            if (definition.isHerbPatch()
                    && farming.isPatchReachable(definition.id))
            {
                return definition.getDisplayName();
            }
        }
        return null;
    }
}

/** Builds the current herb/tree checklist from verified access and resources. */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class FarmingRunPlanner
{
    private final FarmingRunCatalog catalog;
    private final FarmingSupplyCatalog supplyCatalog;

    public GuidanceChecklist build(GameData data, String activityId)
    {
        List<GuidanceStep> steps = new ArrayList<>();
        if (data == null || data.account() == null)
        {
            return new GuidanceChecklist(activityId, "Farming run",
                    get(1463), steps);
        }

        var account = data.account();
        var farmingLevel = account.level(Skill.FARMING);
        if (account.membership() != Membership.P2P)
        {
            return new GuidanceChecklist(activityId, "Farming run",
                    get(1464), steps);
        }

        appendPrep(steps, data, farmingLevel);
        FarmingRunSnapshot snapshot = data.farmingRuns() == null
                ? FarmingRunSnapshot.empty() : data.farmingRuns();

        for (FarmingRunPatchDefinition patch : catalog.all())
        {
            if (farmingLevel < patch.getMinimumLevel()
                    || !isConfirmedReachable(data, patch)) continue;
            steps.add(stepFor(patch, snapshot.stateOf(patch.id)));
        }

        return new GuidanceChecklist(
                activityId, "Farming run",
                get(244), steps);
    }

    private void appendPrep(
            List<GuidanceStep> steps,
            GameData data,
            int farmingLevel)
    {
        var farming = data.farming();
        appendResource(steps, resource(
                data, supplyCatalog.rake(), toolState(farming, "rake"),
                get(245)));
        appendResource(steps, resource(
                data, supplyCatalog.dibber(), toolState(farming, "dibber"),
                get(246)));
        appendResource(steps, resource(
                data, supplyCatalog.spade(), toolState(farming, "spade"),
                get(247)));

        if (farmingLevel >= 9)
        {
            appendResource(steps, resource(
                    data, supplyCatalog.herbSeedsForLevel(farmingLevel)));
        }
        if (farmingLevel >= 15)
        {
            appendResource(steps, resource(
                    data, supplyCatalog.treeSaplingsForLevel(farmingLevel)));
        }
    }

    private static EvidenceCheck resource(GameData data,
            ResourceRequirement need)
    {
        return new ItemIndex(data, false).check(need);
    }

    private static EvidenceCheck resource(GameData data,
            ResourceRequirement need, Capability alternate, String evidence)
    {
        if (alternate == Capability.VERIFIED)
            return new EvidenceCheck(need.id, need.getLabel(),
                    RequirementState.VERIFIED, evidence);
        return resource(data, need);
    }

    private Capability toolState(FarmingSnapshot farming, String id)
    {
        return farming == null
                ? Capability.UNKNOWN
                : farming.leprechaunToolState(id);
    }

    private void appendResource(
            List<GuidanceStep> steps,
            EvidenceCheck check)
    {
        GuidanceStepState state = check.getState() == RequirementState.VERIFIED
                ? GuidanceStepState.COMPLETE
                : GuidanceStepState.CHECK_NEEDED;
        steps.add(new GuidanceStep(
                check.id, "Prep • " + check.getLabel(),
                check.evidence, state));
    }

    private boolean isConfirmedReachable(
            GameData data,
            FarmingRunPatchDefinition patch)
    {
        var memory = data.accessMemory();
        if (memory != null)
        {
            for (Integer region : patch.getRegionIds())
            {
                if (memory.hasObserved("region." + region)) return true;
            }
        }
        var quest = patch.requiredQuest;
        if (quest == null) return true;
        var quests = data.quests();
        return quests != null && quests.statusOf(quest) == QuestStatus.COMPLETE;
    }

    private GuidanceStep stepFor(
            FarmingRunPatchDefinition patch,
            ObservedFarmingPatchState observed)
    {
        String prefix = patch.getKind() == FarmingPatchKind.HERB
                ? "Herb • " : "Tree • ";
        if (observed == null)
        {
            return new GuidanceStep(patch.id, prefix + patch.getDisplayName(),
                    get(248),
                    GuidanceStepState.CHECK_NEEDED);
        }
        switch (observed.getState())
        {
            case GROWING:
                return new GuidanceStep(patch.id, prefix + patch.getDisplayName(),
                        "Planted", GuidanceStepState.COMPLETE);
            case READY:
                return new GuidanceStep(patch.id, prefix + patch.getDisplayName(),
                        patch.getKind() == FarmingPatchKind.TREE
                                ? get(1465) : get(1466),
                        GuidanceStepState.ACTION);
            case EMPTY:
                return new GuidanceStep(patch.id, prefix + patch.getDisplayName(),
                        get(1695), GuidanceStepState.ACTION);
            case DISEASED:
                return new GuidanceStep(patch.id, prefix + patch.getDisplayName(),
                        "Cure the crop", GuidanceStepState.WARNING);
            case DEAD:
                return new GuidanceStep(patch.id, prefix + patch.getDisplayName(),
                        get(1696), GuidanceStepState.WARNING);
            case UNKNOWN:
            default:
                return new GuidanceStep(patch.id, prefix + patch.getDisplayName(),
                        get(1697), GuidanceStepState.CHECK_NEEDED);
        }
    }
}

/** Evaluates ALL/ANY item alternatives without treating unobserved storage as empty. */
final class ItemRequirementEvaluator
{
    public ItemRequirementResult evaluate(ItemRule expression,
            GameData data, boolean useGroupStorage)
    {
        if (expression == null)
            return new ItemRequirementResult(RequirementState.VERIFIED, "");
        var items = new ItemIndex(data, useGroupStorage);
        return evaluate(expression, data, items, useGroupStorage);
    }

    private ItemRequirementResult evaluate(ItemRule expression,
            GameData data, ItemIndex items,
            boolean useGroupStorage)
    {
        if (expression.getKind() == ItemRule.Kind.ITEM)
            return item(expression, data, items, useGroupStorage);
        if (expression.getKind() == ItemRule.Kind.ITEM_CLASS)
            return itemClass(expression, data, items, useGroupStorage);
        if (expression.getKind() == ItemRule.Kind.CHECK_NEEDED)
            return new ItemRequirementResult(RequirementState.CHECK_NEEDED,
                    expression.getCheckAction());

        List<ItemRequirementResult> results = new ArrayList<>();
        for (ItemRule child : expression.getChildren())
            results.add(evaluate(child, data, items, useGroupStorage));

        if (expression.getKind() == ItemRule.Kind.ANY_OF)
        {
            for (ItemRequirementResult result : results)
                if (result.isSatisfied()) return result;

            boolean needsVerification = results.stream().anyMatch(result ->
                    result.getState() == RequirementState.CHECK_NEEDED);
            RequirementState state = needsVerification
                    ? RequirementState.CHECK_NEEDED : RequirementState.BLOCKED;
            // If an alternative may still exist in unobserved storage, there is
            // no proven shortfall to source. Once every branch is proven absent,
            // carry the smallest concrete branch into acquisition guidance.
            List<MethodInput> inputs = needsVerification
                    ? emptyList() : bestAlternativeInputs(results);
            return new ItemRequirementResult(state,
                    (needsVerification
                            ? get(1320) : "Get one of: ")
                            + expression.label(), inputs);
        }

        List<String> actions = new ArrayList<>();
        List<MethodInput> inputs = new ArrayList<>();
        var state = RequirementState.VERIFIED;
        for (ItemRequirementResult result : results)
        {
            if (!result.isSatisfied() && !result.getAction().isEmpty())
                actions.add(result.getAction());
            inputs.addAll(result.missingInputs);
            if (result.getState() == RequirementState.BLOCKED)
                state = RequirementState.BLOCKED;
            else if (result.getState() == RequirementState.CHECK_NEEDED
                    && state != RequirementState.BLOCKED)
                state = RequirementState.CHECK_NEEDED;
        }
        return new ItemRequirementResult(state, String.join("; ", actions), inputs);
    }

    private ItemRequirementResult item(ItemRule expression,
            GameData data, ItemIndex items,
            boolean useGroupStorage)
    {
        var names = expression.getItemNames().toArray(new String[0]);
        int owned;
        boolean observed;
        switch (expression.getScope())
        {
            case EQUIPPED:
                owned = items.equippedQuantity(names);
                observed = data != null && data.equipment() != null;
                break;
            case CARRIED:
                owned = items.inventoryQuantity(names);
                observed = data != null && data.inventory() != null;
                break;
            case CARRIED_OR_EQUIPPED:
                owned = items.inventoryQuantity(names) + items.equippedQuantity(names);
                observed = data != null && data.inventory() != null
                        && data.equipment() != null;
                break;
            case OWNED_OR_RETRIEVABLE:
                owned = items.quantity(names) + items.restrictedQuantity(names);
                observed = ownershipObserved(data, items, useGroupStorage)
                        && !isUim(data);
                break;
            case IMMEDIATELY_USABLE:
            default:
                owned = items.quantity(names);
                observed = ownershipObserved(data, items, useGroupStorage);
                break;
        }
        if (owned >= expression.quantity)
            return new ItemRequirementResult(RequirementState.VERIFIED, "");

        var shortfall = max(0, expression.quantity - owned);
        var target = String.join(" or ", expression.getItemNames());
        if (expression.getItemNames().size() > 1) target = "(" + target + ")";
        String action = (observed ? "Get " : get(1321))
                + shortfall + " × " + target;

        List<MethodInput> inputs = emptyList();
        if (observed && expression.getItemNames().size() == 1)
        {
            inputs = singletonList(new MethodInput(
                    expression.getItemNames().get(0), -1, shortfall));
        }
        return new ItemRequirementResult(observed
                ? RequirementState.BLOCKED : RequirementState.CHECK_NEEDED,
                action, inputs);
    }

    private ItemRequirementResult itemClass(ItemRule expression,
            GameData data, ItemIndex items,
            boolean useGroupStorage)
    {
        var itemClass = expression.getItemClass();
        if (itemClass == null)
            return new ItemRequirementResult(RequirementState.CHECK_NEEDED,
                    get(1322));
        if (itemClass == ItemRequirementClass.EMPTY_INVENTORY_SPACE)
            return freeInventorySlots(expression, data);
        if (!itemClass.isNameObservable())
            return new ItemRequirementResult(RequirementState.CHECK_NEEDED,
                    get(1692) + expression.label());

        int owned;
        boolean observed;
        switch (expression.getScope())
        {
            case EQUIPPED:
                owned = items.equippedQuantityMatching(itemClass,
                        expression.getExcludedItemNames());
                observed = data != null && data.equipment() != null;
                break;
            case CARRIED:
                owned = items.inventoryQuantityMatching(itemClass,
                        expression.getExcludedItemNames());
                observed = data != null && data.inventory() != null;
                break;
            case CARRIED_OR_EQUIPPED:
                owned = items.inventoryQuantityMatching(itemClass,
                        expression.getExcludedItemNames())
                        + items.equippedQuantityMatching(itemClass,
                                expression.getExcludedItemNames());
                observed = data != null && data.inventory() != null
                        && data.equipment() != null;
                break;
            case OWNED_OR_RETRIEVABLE:
                owned = items.quantityMatching(itemClass,
                        expression.getExcludedItemNames())
                        + items.restrictedQuantityMatching(itemClass,
                                expression.getExcludedItemNames());
                observed = ownershipObserved(data, items, useGroupStorage)
                        && !isUim(data);
                break;
            case IMMEDIATELY_USABLE:
            default:
                owned = items.quantityMatching(itemClass,
                        expression.getExcludedItemNames());
                observed = ownershipObserved(data, items, useGroupStorage);
                break;
        }
        if (owned >= expression.quantity)
            return new ItemRequirementResult(RequirementState.VERIFIED, "");
        var shortfall = max(0, expression.quantity - owned);
        var target = itemClass.getLabel();
        if (!expression.getExcludedItemNames().isEmpty())
            target += " (excluding " + String.join(" or ",
                    expression.getExcludedItemNames()) + ")";
        return new ItemRequirementResult(observed
                ? RequirementState.BLOCKED : RequirementState.CHECK_NEEDED,
                (observed ? "Get " : get(1321)) + shortfall
                        + " × " + target);
    }

    private static ItemRequirementResult freeInventorySlots(
            ItemRule expression, GameData data)
    {
        var inventory = data == null ? null : data.inventory();
        if (inventory == null || !inventory.hasCompleteSlotObservation())
            return new ItemRequirementResult(RequirementState.CHECK_NEEDED,
                    get(332));
        var required = max(1, expression.quantity);
        int free = max(0, 28
                - UimSetupCostService.occupiedInventorySlots(inventory));
        if (free >= required)
            return new ItemRequirementResult(RequirementState.VERIFIED, "");
        return new ItemRequirementResult(RequirementState.BLOCKED,
                get(1323) + required
                        + get(1324) + free
                        + get(333));
    }

    private static List<MethodInput> bestAlternativeInputs(
            List<ItemRequirementResult> results)
    {
        List<MethodInput> best = emptyList();
        var bestCost = Long.MAX_VALUE;
        for (ItemRequirementResult result : results)
        {
            if (result.missingInputs.isEmpty()) continue;
            var cost = 0L;
            for (MethodInput input : result.missingInputs)
                cost += max(1, input.quantity);
            if (cost < bestCost)
            {
                bestCost = cost;
                best = result.missingInputs;
            }
        }
        return best;
    }

    private static boolean ownershipObserved(GameData data,
            ItemIndex items, boolean useGroupStorage)
    {
        if (data == null || data.account() == null) return false;
        return items.usableOwnershipObserved();
    }

    private static boolean isUim(GameData data)
    {
        return data != null && data.account() != null
                && AccountMode.fromTypeCode(data.account().modeCode())
                        == AccountMode.ULTIMATE_IRONMAN;
    }

}

/**
 * One engine for recurring and interrupt-driven opportunities.
 *
 * <p>Nothing appears merely because content exists in OSRS. A recurring entry
 * is surfaced only after a reader has observed a ready/cooldown timestamp for
 * that character. Membership is also enforced here so stale observations from
 * a previously-member account cannot leak members-only opportunities into an
 * F2P session.</p>
 */
@Singleton
class OpportunityEngine
{
    private static final Set<String> BIRDHOUSE_SEEDS = new HashSet<>(Arrays.asList(
            "barley seed", get(1883), "asgarnian seed", "jute seed",
            "yanillian seed", "krandorian seed", "wildblood seed", "guam seed",
            "marrentill seed", "tarromin seed", get(1884), "ranarr seed",
            "toadflax seed", "irit seed", "avantoe seed", "kwuarm seed",
            "snapdragon seed", "cadantine seed", "lantadyme seed",
            "dwarf weed seed", "torstol seed"));
    private final FarmingAccessCatalog farmingAccessCatalog =
            new FarmingAccessCatalog();
    private final FarmingSupplyCatalog farmingSupplyCatalog =
            new FarmingSupplyCatalog();

    public List<Opportunity> evaluate(AccountSnapshot snapshot)
    {
        if (snapshot == null) return emptyList();
        return evaluate(GameData.builder(snapshot).build());
    }

    public List<Opportunity> evaluate(GameData data)
    {
        List<Opportunity> opportunities = new ArrayList<>();
        if (data == null || data.account() == null) return opportunities;

        var membership = data.account().membership();
        var recurring = data.recurringOpportunities();
        var now = System.currentTimeMillis();

        // Every currently-modelled recurring activity below is members content.
        // Keep the entire family out of an F2P plan even if its timer was
        // observed while this character previously had membership.
        if (ContentAccessRules.hasVerifiedMembership(membership))
        {
            addBirdhouseOpportunity(opportunities, data, recurring, now);

            addHerbRunOpportunity(opportunities, data, recurring, now,
                    farmingAccessCatalog, farmingSupplyCatalog);

            addPreparedTimedOpportunity(opportunities, recurring, now,
                    get(1885), OpportunityType.TREE_RUN,
                    "Tree run", emptyList());
            addPreparedTimedOpportunity(opportunities, recurring, now,
                    get(1886), OpportunityType.FARMING_CONTRACT,
                    get(1887), emptyList());
            addPreparedTimedOpportunity(opportunities, recurring, now,
                    get(1888), OpportunityType.TEARS_OF_GUTHIX,
                    "Tears of Guthix", emptyList());
            addPreparedTimedOpportunity(opportunities, recurring, now,
                    get(1889), OpportunityType.KINGDOM,
                    "Kingdom", emptyList());
            addPreparedTimedOpportunity(opportunities, recurring, now,
                    get(1890), OpportunityType.KINGDOM_APPROVAL,
                    get(1891), emptyList());
            addPreparedTimedOpportunity(opportunities, recurring, now,
                    get(1892), OpportunityType.BATTLESTAVES,
                    get(1522), emptyList());
            addPreparedTimedOpportunity(opportunities, recurring, now,
                    get(1893), OpportunityType.DYNAMITE,
                    "Daily dynamite", emptyList());
            addPreparedTimedOpportunity(opportunities, recurring, now,
                    get(1894), OpportunityType.DAILY_DIARY_REWARD,
                    get(1523), emptyList());
        }

        var clue = data.clue();
        if (clue != null && clue.cluePresent)
        {
            var tier = ClueTier.fromText(clue.clueType);
            if (tier.isAvailableFor(membership))
            {
                var step = clue.getCurrentStep();
                List<String> preparation = new ArrayList<>();
                if (step == null)
                    preparation.add(get(392));
                else
                {
                    preparation.addAll(step.itemRequirements);
                    if (step.isRequiresSpade()) preparation.add("Spade");
                    if (step.isRequiresLight()) preparation.add("Light source");
                    if (step.hasEnemy()) preparation.add(
                            get(1524) + step.getEnemy());
                    if (step.wilderness) preparation.add(
                            get(1525));
                    if (step.hasStashUnit()) preparation.add(
                            "Observe the " + step.getStashUnit()
                                    + get(1526));
                }
                boolean ready = step != null
                        && tier == ClueTier.BEGINNER
                        && !step.requiresPreparation();
                opportunities.add(new Opportunity(
                        get(1895),
                        OpportunityType.CLUE,
                        clue.clueType == null ? "Pending clue"
                                : clue.clueType + " clue"
                                + (step == null ? "" : ": " + step.getKind()),
                        ready,
                        ready ? Confidence.VERIFIED
                                : Confidence.CHECK_NEEDED,
                        preparation,
                        false,
                        step != null && step.hasEnemy()
                                ? Safety.potentiallyIrreversible(
                                        tier == ClueTier.BEGINNER)
                                : Safety.harmless(
                                        tier == ClueTier.BEGINNER)
                ));
            }
        }

        return opportunities;
    }

    private static void addPreparedTimedOpportunity(
            List<Opportunity> result,
            RecurringOpportunitySnapshot recurring,
            long now,
            String id,
            OpportunityType type,
            String title,
            List<String> preparation)
    {
        if (recurring == null || recurring.readyAt(id) == null) return;
        var ready = recurring.isReadyNow(id, now);
        result.add(new Opportunity(
                id, type, title, ready,
                Confidence.VERIFIED, preparation, false, Safety.unknown()));
    }

    private static void addHerbRunOpportunity(List<Opportunity> result,
            GameData data, RecurringOpportunitySnapshot recurring,
            long now, FarmingAccessCatalog accessCatalog,
            FarmingSupplyCatalog supplyCatalog)
    {
        var id = get(1896);
        if (recurring == null || recurring.readyAt(id) == null) return;

        List<String> missing = new ArrayList<>();
        var inventory = data.inventory();
        if (quantity(inventory, "spade") == 0) missing.add("Carry a spade");
        if (quantity(inventory, "seed dibber") == 0) missing.add(get(1527));
        var farmingLevel = data.account().level(FARMING);
        ResourceRequirement herbSeeds = supplyCatalog.herbSeedsForLevel(
                farmingLevel);
        if (inventory == null || inventory.quantityOf(herbSeeds.getItemIds()) == 0)
            missing.add(get(1528));
        if (farmingLevel < 9)
            missing.add(get(393));
        var farming = data.farming();
        if (!hasReachableHerbPatch(farming, accessCatalog))
            missing.add(get(394));

        var ready = recurring.isReadyNow(id, now);
        var setupVerified = ready && missing.isEmpty();
        result.add(new Opportunity(id, OpportunityType.HERB_RUN, "Herb run",
                ready, Confidence.VERIFIED, missing,
                setupVerified, Safety.skill(false,
                FARMING)));
    }

    private static void addBirdhouseOpportunity(List<Opportunity> result,
            GameData data, RecurringOpportunitySnapshot recurring,
            long now)
    {
        var id = get(1897);
        if (recurring == null || recurring.readyAt(id) == null) return;
        List<String> missing = new ArrayList<>();
        var quests = data.quests();
        if (quests == null || quests.statusOf("Bone Voyage") != QuestStatus.COMPLETE)
            missing.add(get(395));
        var inventory = data.inventory();
        if (quantity(inventory, "hammer") == 0) missing.add("Carry a hammer");
        if (quantity(inventory, "chisel") == 0) missing.add("Carry a chisel");
        if (quantity(inventory, "clockwork") < 4)
            missing.add(get(1529));
        if (inventory == null || inventory.quantityWhere(name ->
                name.endsWith(" log") || name.endsWith(" logs")
                        || name.equals("logs")) < 4)
            missing.add(get(1530));
        if (birdhouseSeedQuantity(inventory) < 40)
            missing.add(get(1531));
        if (data.account().level(HUNTER) < 5)
            missing.add(get(1532));
        if (data.account().level(CRAFTING) < 5)
            missing.add(get(1533));
        var ready = recurring.isReadyNow(id, now);
        var setupVerified = ready && missing.isEmpty();
        result.add(new Opportunity(id, OpportunityType.BIRDHOUSE_RUN,
                "Birdhouse run", ready, Confidence.VERIFIED,
                missing, setupVerified,
                Safety.skill(false,
                        HUNTER)));
    }

    private static int quantity(ItemsState inventory, String name)
    {
        return inventory == null ? 0 : inventory.quantityNamed(name);
    }

    private static int birdhouseSeedQuantity(ItemsState inventory)
    {
        return inventory == null ? 0
                : inventory.quantityWhere(BIRDHOUSE_SEEDS::contains);
    }

    private static boolean hasReachableHerbPatch(FarmingSnapshot farming,
            FarmingAccessCatalog catalog)
    {
        if (farming == null) return false;
        for (FarmingAccessDefinition patch : catalog.all())
            if (patch.isHerbPatch() && farming.isPatchReachable(patch.id))
                return true;
        return false;
    }
}

/** Resolves only evidence represented by the current local snapshots. */
@Singleton
class QuestRequirementResolver
{
    private static final String IMPORTED_ITEM_PREFIX = "Required items:";
    private final ImportedQuestItemRequirementCatalog importedItems;
    private final ResourceSourceCatalog resourceSources;
    private final ResourceDependencyResolver resourcePlanner;

    @Inject
    public QuestRequirementResolver(ResourceSourceCatalog resourceSources,
            ResourceDependencyResolver resourcePlanner)
    {
        this.importedItems = new ImportedQuestItemRequirementCatalog();
        this.resourceSources = resourceSources == null
                ? new ResourceSourceCatalog() : resourceSources;
        this.resourcePlanner = resourcePlanner == null
                ? new ResourceDependencyResolver(this.resourceSources,
                        new ResourceDependencyCatalog())
                : resourcePlanner;
    }

    public QuestResolution resolve(QuestDefinition definition, StrategyContext context)
    {
        if (definition == null || context == null || context.data() == null
                || context.data().account() == null) return null;

        var data = context.data();
        var account = data.account();
        var quests = data.quests();
        List<Preparation> missing = new ArrayList<>();

        for (String prerequisite : definition.prerequisites)
        {
            QuestStatus status = quests == null ? QuestStatus.UNKNOWN
                    : quests.statusOf(prerequisite);
            if (status != QuestStatus.COMPLETE)
                missing.add(new Preparation(status == QuestStatus.UNKNOWN
                        ? get(560) + prerequisite
                        : get(1349) + prerequisite,
                        RestrictedQuestPolicy.isSafe(account, prerequisite)
                                ? Safety.verifiedSafe(
                                definition.freeToPlay)
                                : Safety.potentiallyIrreversible(
                                definition.freeToPlay)));
        }

        for (Map.Entry<Skill, Integer> requirement
                : definition.skillRequirements.entrySet())
        {
            var current = account.level(requirement.getKey());
            if (current < requirement.getValue())
                missing.add(new Preparation("Train "
                        + requirement.getKey().getName() + " from " + current
                        + " to " + requirement.getValue(),
                        Safety.skill(definition.freeToPlay,
                                requirement.getKey())));
        }

        ItemIndex items = new ItemIndex(data,
                context.usesGroupStorage());
        // An inventory observation does not prove that an unobserved bank is empty.
        var ownershipObserved = items.usableOwnershipObserved();
        for (QuestDefinition.QuestItemRequirement requirement
                : definition.itemRequirements)
        {
            var owned = items.quantity(requirement.getName());
            if (owned < requirement.quantity)
                missing.add(new Preparation((ownershipObserved ? "Obtain " : get(1350))
                        + max(0, requirement.quantity - owned) + " × "
                        + requirement.getName(), Safety.harmless(
                        definition.freeToPlay)));
        }

        ImportedQuestItemRequirementCatalog.Result imported = hasImportedItemEvidence(definition)
                ? importedItems.resultFor(definition.getName()) : null;
        var expression = definition.getItemRequirementExpression();
        if (expression == null && imported != null)
            expression = imported.getExpression();
        ItemRequirementResult expressionResult = new ItemRequirementEvaluator()
                .evaluate(expression, data, context.usesGroupStorage());
        if (!expressionResult.isSatisfied()
                && !expressionResult.getAction().isEmpty())
        {
            missing.add(itemPreparation(expressionResult, definition, context));
        }

        if (definition.getQuestPointsRequired() > 0)
            missing.add(new Preparation(get(1924)
                    + definition.getQuestPointsRequired() + " quest points",
                    Safety.harmless(definition.freeToPlay)));
        for (String check : definition.getAccessChecks())
        {
            if (check != null && check.startsWith(IMPORTED_ITEM_PREFIX))
            {
                if (imported == null)
                {
                    missing.add(new Preparation(check,
                            Safety.harmless(
                                    definition.freeToPlay)));
                }
                else
                {
                    for (String unresolved : imported.getUnresolved())
                        missing.add(new Preparation(
                                get(1351) + unresolved,
                                Safety.harmless(
                                        definition.freeToPlay)));
                }
                continue;
            }
            missing.add(new Preparation(check,
                    Safety.harmless(definition.freeToPlay)));
        }

        String unlocks = definition.getUnlocks().isEmpty() ? ""
                : String.join(", ", definition.getUnlocks());
        if (missing.isEmpty())
        {
            return new QuestResolution(Confidence.VERIFIED,
                    new Guidance(
                            "Start " + definition.getName() + ".",
                            get(561),
                            definition.getStartLocation(),
                            unlocks.isEmpty() ? get(562)
                                    : get(1352) + unlocks + "."),
                    get(1353),
                    Safety.verifiedSafe(
                            definition.freeToPlay));
        }

        List<String> missingText = new ArrayList<>();
        for (Preparation preparation : missing) missingText.add(preparation.detail);
        return new QuestResolution(Confidence.CHECK_NEEDED,
                new Guidance(missing.get(0).text + ".",
                        String.join("; ", missingText), definition.getStartLocation(),
                        unlocks.isEmpty()
                                ? get(563)
                                : get(1354) + unlocks + "."),
                get(1355) + missing.get(0).text,
                missing.get(0).safetyEvidence);
    }

    private Preparation itemPreparation(ItemRequirementResult result,
            QuestDefinition definition, StrategyContext context)
    {
        Safety safety = Safety.harmless(
                definition.freeToPlay);
        if (result.missingInputs.isEmpty())
            return new Preparation(result.getAction(), safety);

        var first = result.missingInputs.get(0);
        var dependency = dependencyResolution(context, first);
        var next = dependency == null ? null : dependency.nextAction();
        if (next != null
                && next.confidence != Confidence.VERIFIED
                && next.getAction() != null
                && !next.getAction().trim().isEmpty())
        {
            var action = withoutTerminalPeriod(next.getAction().trim());
            var detail = new StringBuilder(result.getAction());
            detail.append(get(1356))
                    .append(formatInputs(result.missingInputs)).append(".");
            detail.append(get(1357))
                    .append(quantity(first)).append(": ")
                    .append(next.getAction().trim());
            if (result.missingInputs.size() > 1)
                detail.append(get(564));
            return new Preparation(action, detail.toString(), safety);
        }

        var mode = context.accountMode();
        String action;
        if (mode == AccountMode.ULTIMATE_IRONMAN)
            action = "Acquire " + quantity(first) + " just in time";
        else if (mode.isIronLike())
            action = "Self-source " + quantity(first);
        else if (mode == AccountMode.UNKNOWN)
            action = "Source " + quantity(first) + get(1358);
        else
            action = "Acquire " + quantity(first);

        var routes = sourceRoutes(context, first.getName());
        if (!routes.isEmpty()) action += ": " + routes.get(0);

        var detail = new StringBuilder(result.getAction());
        detail.append(get(1356))
                .append(formatInputs(result.missingInputs)).append(".");
        if (!routes.isEmpty())
            detail.append(get(1359)).append(routes.get(0));
        if (result.missingInputs.size() > 1)
            detail.append(get(565));
        return new Preparation(action, detail.toString(), safety);
    }

    private DependencyResolution dependencyResolution(
            StrategyContext context, MethodInput input)
    {
        if (context == null || input == null || context.data() == null
                || context.data().account() == null)
            return null;
        return resourcePlanner.resolveKnownShortfall(
                context, input.getName(), input.quantity);
    }

    private List<String> sourceRoutes(StrategyContext context, String itemName)
    {
        if (context == null || context.data() == null
                || context.data().account() == null)
            return emptyList();
        return resourceSources.suggestions(itemName, context.accountMode(),
                context.data().account().membership(),
                context.allowsWilderness());
    }

    private static String quantity(MethodInput input)
    {
        return max(1, input.quantity) + " × " + input.getName();
    }

    private static String formatInputs(List<MethodInput> inputs)
    {
        List<String> values = new ArrayList<>();
        for (MethodInput input : inputs) values.add(quantity(input));
        return String.join(", ", values);
    }

    private static String withoutTerminalPeriod(String value)
    {
        if (value == null) return "";
        var result = value.trim();
        while (result.endsWith("."))
            result = result.substring(0, result.length() - 1).trim();
        return result;
    }

    private static boolean hasImportedItemEvidence(QuestDefinition definition)
    {
        for (String check : definition.getAccessChecks())
            if (check != null && check.startsWith(IMPORTED_ITEM_PREFIX)) return true;
        return false;
    }

    private static final class Preparation
    {
        private final String text;
        private final String detail;
        private final Safety safetyEvidence;

        private Preparation(String text,
                Safety safetyEvidence)
        {
            this(text, text, safetyEvidence);
        }

        private Preparation(String text, String detail,
                Safety safetyEvidence)
        {
            this.text = text;
            this.detail = detail == null ? text : detail;
            this.safetyEvidence = safetyEvidence;
        }
    }
}

@Singleton
class RecommendationEngine
{
    private final TrainingMethodSelector trainingMethodSelector;
    private final RecommendationGuidanceService guidanceService;
    private final CombatGuidanceService combatGuidanceService;
    private final SailingGuidanceService sailingGuidanceService;
    private final SkillBreakpointService breakpointService;
    private final AdaptiveActionSelector actionResolver;
    private final SlayerStrategist slayerStrategist;

    @Inject
    public RecommendationEngine(
            TrainingMethodSelector trainingMethodSelector,
            RecommendationGuidanceService guidanceService,
            CombatGuidanceService combatGuidanceService,
            SailingGuidanceService sailingGuidanceService,
            SkillBreakpointService breakpointService,
            AdaptiveActionSelector actionResolver,
            SlayerStrategist slayerStrategist)
    {
        this.trainingMethodSelector = trainingMethodSelector;
        this.guidanceService = guidanceService;
        this.combatGuidanceService = combatGuidanceService;
        this.sailingGuidanceService = sailingGuidanceService;
        this.breakpointService = breakpointService == null
                ? new SkillBreakpointService() : breakpointService;
        this.actionResolver = actionResolver == null
                ? new AdaptiveActionSelector() : actionResolver;
        this.slayerStrategist = slayerStrategist == null
                ? new SlayerStrategist() : slayerStrategist;
    }

    /** Full skill candidate pool for the global strategy queue. Do not trim here. */
    public List<Recommendation> recommendAll(
            GameData data,
            StrategyMode strategyMode,
            SessionIntent sessionIntent,
            boolean useGroupStorage,
            boolean allowWildernessMethods,
            GoalType activeGoal,
            PreferenceProfile preferenceProfile)
    {
        return recommendAllInternal(data, strategyMode, sessionIntent,
                useGroupStorage, allowWildernessMethods, activeGoal,
                preferenceProfile);
    }

    private List<Recommendation> recommendAllInternal(
            GameData data,
            StrategyMode strategyMode,
            SessionIntent sessionIntent,
            boolean useGroupStorage,
            boolean allowWildernessMethods,
            GoalType activeGoal,
            PreferenceProfile preferenceProfile)
    {
        List<Recommendation> recommendations = new ArrayList<>();
        if (trainingMethodSelector == null || data == null
                || data.account() == null) return recommendations;
        var snapshot = data.account();
        PreferenceProfile safePreferences = preferenceProfile == null
                ? new PreferenceProfile() : preferenceProfile;
        StrategyContext context = new StrategyContext(data, strategyMode,
                sessionIntent, QuestTolerance.NORMAL, activeGoal,
                useGroupStorage, false, allowWildernessMethods,
                safePreferences);

        for (Skill skill : Skill.values())
        {
            var level = snapshot.level(skill);
            if (level >= 99 || skill == HITPOINTS) continue;
            if (!ContentAccessRules.isSkillAvailable(skill,
                    snapshot.membership())) continue;
            if (!AccountBuildPolicy.allowsSkill(snapshot, skill)) continue;

            var activityId = "skill:" + skill.name().toLowerCase();
            if (safePreferences.isOnCooldown(activityId)) continue;

            SkillBreakpoint breakpoint = breakpointService.next(
                    skill, level, context);
            var target = breakpoint.getLevel();
            TrainingPlan trainingPlan = null;
            Guidance guidance = null;
            TrainingPlan highestRankedPlan = null;
            for (TrainingPlan candidate : trainingMethodSelector.rankedCandidates(
                    data, skill, level, strategyMode, sessionIntent,
                    allowWildernessMethods, useGroupStorage))
            {
                if (highestRankedPlan == null) highestRankedPlan = candidate;
                Guidance candidateGuidance = buildGuidance(
                        context, skill, level,
                        actionResolver.resolve(candidate, level, target),
                        candidate);
                if (candidateGuidance != null
                        && candidate.getStrategyProfile() != null)
                {
                    candidateGuidance = candidateGuidance.withBankingBehavior(
                            candidate.getStrategyProfile()
                                    .bankingBehavior);
                }
                // Some activities can only be rendered truthfully once live
                // resources or state identify a concrete execution loop. A
                // higher-scoring but unrenderable route must not consume the
                // skill's only candidate and hide a ready lower-ranked route.
                if (candidateGuidance == null) continue;
                trainingPlan = candidate.withCurrentStageTargetLevel(
                        actionResolver.resolve(candidate, level, target));
                guidance = candidateGuidance;
                break;
            }
            // Keep the historical diagnostic candidate when this engine was
            // constructed without a renderer capable of any method in the
            // skill. The final actionability boundary still prevents it from
            // leading DO NEXT; this also preserves focused selector callers.
            if (trainingPlan == null) trainingPlan = highestRankedPlan;
            if (trainingPlan == null || trainingPlan.method() == null) continue;

            var score = baseScore(level, breakpoint);
            score += safePreferences.weightFor(activityId) * 10.0;
            score += safePreferences.timedScoreAdjustmentFor(activityId);
            score += milestoneMomentum(level, target);

            var primaryReason = trainingPlan.getWhyThisMethod();
            if (primaryReason == null || primaryReason.trim().isEmpty())
                primaryReason = breakpoint.getLabel() + ".";
            Recommendation recommendation = new Recommendation(
                    activityId,
                    "Train " + skill.getName() + " to " + target,
                    primaryReason,
                    score,
                    trainingPlan,
                    trainingPlan.confidence,
                    level,
                    target,
                    guidance,
                    Safety.skill(
                            ContentAccessRules.isMethodAvailable(
                                    trainingPlan.method(), Membership.F2P),
                            skill));
            recommendation = recommendation.withStrategicValue(
                    StrategicValue.builder()
                            .unlockValue(breakpoint.strategicValue())
                            .evidence(breakpoint.getEvidenceId())
                            .build().merge(guidance == null
                                    ? StrategicValue.neutral()
                                    : guidance.getStrategicValue()));
            recommendations.add(recommendation);
        }

        recommendations.sort(Comparator.comparingDouble(
                Recommendation::getScore).reversed());
        return recommendations;
    }

    private Guidance buildGuidance(
            StrategyContext context,
            Skill skill,
            int level,
            int target,
            TrainingPlan trainingPlan)
    {
        var data = context.data();
        Guidance guidance = combatGuidanceService == null
                ? null : combatGuidanceService.build(
                        data, skill, level, target, trainingPlan,
                        context.intent(), context.usesGroupStorage());

        if (guidance == null && skill == SLAYER)
        {
            var decision = slayerStrategist.assess(context);
            guidance = decision == null ? null : decision.guidance;
        }

        if (guidance == null && skill == SAILING
                && sailingGuidanceService != null)
        {
            guidance = sailingGuidanceService.build(
                    data, level, target, trainingPlan);
        }

        if (guidance == null && guidanceService != null)
        {
            guidance = guidanceService.build(
                    data, skill, level, target, trainingPlan,
                    context.usesGroupStorage());
        }
        return guidance;
    }

    private double baseScore(int level, SkillBreakpoint breakpoint)
    {
        var distance = max(1, breakpoint.getLevel() - level);
        double proximity = distance <= 1 ? 12.0
                : distance <= 3 ? 7.0 : distance <= 7 ? 3.0 : 0.0;
        return 24.0 + proximity + breakpoint.strategicValue() * 20.0;
    }

    private double milestoneMomentum(int level, int target)
    {
        var remaining = target - level;
        if (remaining <= 1) return 8.0;
        if (remaining <= 3) return 4.0;
        return 0.0;
    }

}

/** Resolves method requirements from live access, account and item evidence. */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class RequirementEvidenceEngine
{
    private final FarmingAccessEvaluator farmingAccess;
    private final AgilityAccessEvaluator agilityAccess;
    private final FarmingSupplyCatalog farmingSupplies;
    private final RunecraftSupplyCatalog runecraftSupplies;
   public List<EvidenceCheck> evaluate(GameData data, TrainingMethod method)
    {
        return evaluate(data, method, false);
    }

    public List<EvidenceCheck> evaluate(GameData data, TrainingMethod method,
            boolean group)
    {
        if (method == null) return new ArrayList<>();
        var id = method.id;
        var skill = method.getSkill();
        var items = new ItemIndex(data, group);
        if (skill == Skill.FARMING) return farming(data, method, items);
        if (skill == Skill.AGILITY && agilityAccess != null)
            return agility(data, id);
        if (skill == SAILING) return sailing(data, id, items);
        if (skill == Skill.RUNECRAFT && runecraftSupplies.supports(id))
            return runecraft(id, items);
        if (skill == Skill.MAGIC && (id.equals(get(1625))
                || id.equals(get(1626))
                || id.equals(get(1627))
                || id.equals(get(1628))
                || id.equals("magic_f2p_curse"))) return magic(data, id, items);
        if (skill == Skill.COOKING && id.equals(get(1735)))
            return cookedFish(data, items);
        if (skill == Skill.COOKING && (id.equals(get(1577))
                || id.equals("cooking_wines"))) return cooking(data, id, items);
        if (skill == Skill.FISHING)
        {
            var result = fishing(data, id, items);
            if (result != null) return result;
        }
        if (skill == Skill.HUNTER)
        {
            var result = hunter(data, id, items);
            if (result != null) return result;
        }
        if (id.equals("runecraft_gotr"))
        {
            List<EvidenceCheck> result = quest(data, get(1736),
                    get(1737));
            result.add(tool(items, ItemRequirementClass.PICKAXE,
                    get(1738), "Usable pickaxe"));
            result.add(item(items, get(1739), "Chisel", 1,
                    CHISEL));
            return result;
        }
        if (id.equals("runecraft_zmi")) return list(item(items,
                get(1740), "Pure essence", 1,
                BLANKRUNE_HIGH));
        if (id.equals(get(1629)))
            return construction(data, items, false);
        if (id.equals(get(1630)))
            return construction(data, items, true);
        if (skill == Skill.MINING || skill == Skill.WOODCUTTING)
        {
            ItemRequirementClass type = skill == Skill.MINING
                    ? ItemRequirementClass.PICKAXE : ItemRequirementClass.AXE;
            List<EvidenceCheck> result = list(tool(items, type,
                    skill == Skill.MINING ? get(1741)
                            : get(1742),
                    skill == Skill.MINING ? "Usable pickaxe" : "Usable axe"));
            addGeneric(result, method);
            return result;
        }
        List<EvidenceCheck> result = new ArrayList<>();
        addGeneric(result, method);
        return result;
    }

    private static List<EvidenceCheck> magic(GameData data, String id,
            ItemIndex items)
    {
        var combat = data == null ? null : data.combatEvidence();
        var observed = combat != null;
        List<EvidenceCheck> result = list(new EvidenceCheck(
                get(1743), get(1534), observed
                        ? combat.getSpellbookSelector() == 0
                        ? RequirementState.VERIFIED : RequirementState.BLOCKED
                        : RequirementState.CHECK_NEEDED,
                !observed ? get(613) : combat.getSpellbookSelector() == 0
                        ? get(1535) : get(624)));
        if (id.equals("magic_f2p_curse"))
        {
            result.add(item(items, get(1744), "Body rune", 1,
                    BODYRUNE));
            result.add(item(items, get(1745), "Earth runes", 3,
                    EARTHRUNE));
            result.add(item(items, get(1746), "Water runes", 2,
                    WATERRUNE));
            result.add(splashing(data));
            return result;
        }
        var splash = id.equals(get(1628));
        int air = id.equals(get(1627)) ? 4
                : id.equals(get(1626)) ? 3 : splash ? 2 : 1;
        result.add(item(items, get(1747), get(1536),
                air, AIRRUNE));
        if (splash)
        {
            result.add(item(items, get(1748), "Fire runes", 3,
                    FIRERUNE));
            result.add(item(items, get(1749), "Mind rune", 1,
                    MINDRUNE));
            result.add(splashing(data));
        }
        else if (id.equals(get(1626))
                || id.equals(get(1627)))
        {
            var blast = id.endsWith("blast");
            result.add(item(items, get(1750), get(1537),
                    blast ? 5 : 4, FIRERUNE));
            result.add(item(items, get(1751),
                    get(1538), 1, blast ? DEATHRUNE : CHAOSRUNE));
        }
        else result.add(item(items, get(1752), "Mind rune",
                1, MINDRUNE));
        return result;
    }

    private static EvidenceCheck splashing(GameData data)
    {
        var equipment = data == null ? null : data.equipment();
        boolean helm = false, body = false, legs = false, shield = false,
                boots = false, staff = false;
        if (equipment != null) for (ItemState item : equipment.getEquippedItems())
        {
            if (item == null || item.getName() == null || item.quantity <= 0)
                continue;
            var name = item.getName().toLowerCase(Locale.ROOT);
            helm |= metal(name, "full helm");
            body |= metal(name, "platebody");
            legs |= metal(name, "platelegs") || metal(name, "plateskirt");
            shield |= metal(name, "kiteshield");
            boots |= name.equals("fancy boots") || name.equals("fighting boots")
                    || name.equals(get(1753));
            staff |= name.equals(get(1542));
        }
        var ready = helm && body && legs && shield && boots && staff;
        return new EvidenceCheck(get(1754), get(661),
                ready ? RequirementState.VERIFIED : RequirementState.CHECK_NEEDED,
                get(ready ? 614 : 615));
    }

    private static boolean metal(String name, String piece)
    {
        if (!name.endsWith(piece)) return false;
        for (String metal : new String[]{"bronze ", "iron ", "steel ", "black ",
                "mithril ", "adamant ", "rune ", "gilded "})
            if (name.startsWith(metal)) return true;
        return false;
    }

    private static List<EvidenceCheck> sailing(GameData data, String id,
            ItemIndex items)
    {
        List<EvidenceCheck> result = quest(data, "Pandemonium",
                get(1755));
        if (id.equals("sailing_courier"))
        {
            var sailing = data == null ? null : data.sailing();
            boolean route = sailing != null
                    && sailing.hasPort(SailingSnapshot.PORT_SARIM)
                    && sailing.hasPort(SailingSnapshot.PORT_PANDEMONIUM)
                    && sailing.hasActivity(SailingSnapshot.ACTIVITY_COURIER);
            result.add(state(get(1756), get(1539), route,
                    get(635), get(646)));
            result.add(item(items, get(1757), "Captain's log", 1,
                    SAILING_LOG_INITIAL, SAILING_LOG));
        }
        else if (id.equals(get(1758))) result.add(new EvidenceCheck(
                get(1759), get(1540),
                RequirementState.CHECK_NEEDED, get(657)));
        else if (id.startsWith(get(1760)))
        {
            if (id.contains("jubbly")) result.addAll(quest(data, get(1541),
                    get(1761)));
            if (id.contains("gwenith")) result.addAll(quest(data, "Regicide",
                    "quest:regicide"));
            result.add(new EvidenceCheck(get(1762),
                    get(1763), RequirementState.CHECK_NEEDED,
                    get(658)));
        }
        else result.add(new EvidenceCheck(get(1764), get(659),
                    RequirementState.CHECK_NEEDED, get(660)));
        return result;
    }

    private static List<EvidenceCheck> cookedFish(GameData data,
            ItemIndex items)
    {
        int level = data == null || data.account() == null ? 1
                : data.account().level(Skill.COOKING);
        int[] ids = {RAW_SHRIMP, RAW_SARDINE, RAW_HERRING,
                RAW_TROUT, RAW_PIKE, RAW_SALMON,
                RAW_TUNA, RAW_LOBSTER, RAW_SWORDFISH};
        int[] levels = {1, 1, 5, 15, 20, 25, 30, 40, 45};
        var count = 0;
        for (int required : levels) if (level >= required) count++;
        return list(item(items, get(1765), get(1543), 1,
                Arrays.copyOf(ids, count)));
    }

