    final List<String> blockedFamilies;

    UimRecurringPressureAssessment(int distinctObservedLayouts,
            List<String> blockedFamilies)
    {
        this.distinctObservedLayouts = max(0, distinctObservedLayouts);
        this.blockedFamilies = unmodifiableList(new ArrayList<>(
                blockedFamilies == null ? emptyList()
                        : blockedFamilies));
    }

    public boolean isRepeated()
    {
        return distinctObservedLayouts >= 2 && blockedFamilies.size() >= 2;
    }
}

/** Result of checking one proposed UIM storage route. */
@Getter
final class UimStorageDecision
{
    final StorageKind capability;
    final boolean allowed;
    final Confidence confidence;
    final RiskLevel riskLevel;
    final String explanation;

    public UimStorageDecision(
            StorageKind capability,
            boolean allowed,
            Confidence confidence,
            RiskLevel riskLevel,
            String explanation)
    {
        this.capability = capability;
        this.allowed = allowed;
        this.confidence = confidence;
        this.riskLevel = riskLevel == null ? RiskLevel.NONE : riskLevel;
        this.explanation = explanation;
    }

}

package compass;

import lombok.RequiredArgsConstructor;

/**
 * Goals that are complete enough to expose in RuneLite configuration.
 *
 * <p>Internal planning goals remain in {@link GoalType}; keeping this list
 * separate prevents experimental enum values from silently becoming public
 * controls.</p>
 */
@RequiredArgsConstructor
public enum PlayerGoal
{
    AUTOMATIC(GoalType.AUTOMATIC, "Automatic"),
    BARROWS_GLOVES(GoalType.BARROWS_GLOVES, "Barrows gloves"),
    FIRE_CAPE(GoalType.FIRE_CAPE, "Fire cape"),
    QUEST_CAPE(GoalType.QUEST_CAPE, "Quest cape"),
    PRIFDDINAS(GoalType.PRIFDDINAS, "Prifddinas"),
    BOWFA(GoalType.BOWFA, "Bowfa"),
    INFERNAL_CAPE(GoalType.INFERNAL_CAPE, "Infernal cape"),
    MAX(GoalType.MAX, "Max cape");

    final GoalType planningGoal;
    final String displayName;
    public GoalType toPlanningGoal()
    {
        return planningGoal;
    }

    public static boolean isPlayerFacing(GoalType goal)
    {
        if (goal == null) return false;
        for (PlayerGoal candidate : values())
            if (candidate.planningGoal == goal) return true;
        return false;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package compass;
import lombok.*;
import static java.lang.Math.*;

import java.util.*;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import static compass.Text.get;

/**
 * Hard guardrails for player-imposed account builds.
 *
 * <p>This layer answers a different question from Ironman/Main/UIM policy. A
 * Hardcore Ironman can also be a 1 Defence pure, a Main can be a level-3
 * skiller, and a GIM can be a Defence pure. Both policy layers must agree before
 * Compass recommends an action.</p>
 */
final class AccountBuildPolicy
{
    private AccountBuildPolicy() {}

    public static RestrictedBuildSuggestion detect(AccountSnapshot account)
    {
        if (account == null)
            return build(BuildType.STANDARD,
                    Confidence.CHECK_NEEDED, get(1206));

        var attack = account.level(Skill.ATTACK);
        var strength = account.level(Skill.STRENGTH);
        var defence = account.level(Skill.DEFENCE);
        var ranged = account.level(Skill.RANGED);
        var prayer = account.level(Skill.PRAYER);
        var magic = account.level(Skill.MAGIC);
        var hp = account.level(Skill.HITPOINTS);
        var highNonCombat = nonCombatExtreme(account, true);
        var lowNonCombat = nonCombatExtreme(account, false);
        int offence = max(max(attack, strength),
                max(ranged, magic));
        var combat = max(max(offence, defence), prayer);
        boolean baselineOffence = attack <= 1 && strength <= 1
                && ranged <= 1 && magic <= 1;

        if (baselineOffence && defence <= 1 && prayer <= 1 && hp <= 10
                && highNonCombat >= 20)
            return verified(account.membership() != Membership.P2P
                    ? BuildType.F2P_SKILLER
                    : BuildType.SKILLER, get(583));
        if (baselineOffence && defence <= 1 && hp <= 10 && prayer >= 15
                && highNonCombat >= 20)
            return verified(BuildType.PRAYER_SKILLER, get(590));
        if (lowNonCombat <= 1 && highNonCombat <= 1 && combat >= 40)
            return verified(BuildType.COMBAT_ONLY, get(591));
        if (baselineOffence && defence >= 20)
            return verified(BuildType.DEFENCE_PURE, get(592));
        if (hp <= 10 && (ranged >= 20 || magic >= 20 || prayer >= 20
                || highNonCombat >= 50))
            return verified(BuildType.TEN_HITPOINTS, get(593));
        if (attack <= 1 && defence <= 1 && strength >= 50)
            return verified(BuildType.OBSIDIAN_MAULER, get(594));
        if (defence <= 1 && offence >= 40)
            return verified(BuildType.ONE_DEFENCE_PURE, get(595));

        if (offence >= 50)
        {
            if (defence >= 2 && defence <= 13)
                return verified(BuildType.LOW_DEFENCE_PURE,
                        get(596));
            if (defence <= 20)
                return verified(BuildType.INITIATE_PURE, get(597));
            if (defence >= 39 && defence <= 40)
                return verified(BuildType.RUNE_PURE, get(584));
            if (defence <= 42 && defence >= 41)
                return verified(BuildType.VOID_PURE, get(585));
            if (defence >= 43 && defence <= 45 && attack >= 50 && strength >= 50)
                return verified(BuildType.ZERKER, get(586));
        }
        if (defence >= 70 && ranged >= 80 && magic >= 70
                && attack <= 60 && strength <= 70)
            return build(BuildType.RANGE_TANK,
                    Confidence.CHECK_NEEDED, get(587));
        if (lowNonCombat <= 1 && highNonCombat <= 5 && combat >= 30)
            return build(BuildType.COMBAT_ONLY,
                    Confidence.CHECK_NEEDED, get(588));
        return verified(BuildType.STANDARD, get(589));
    }

    private static RestrictedBuildSuggestion verified(
            BuildType type, String evidence)
    {
        return build(type, Confidence.VERIFIED, evidence);
    }

    private static RestrictedBuildSuggestion build(BuildType type,
            Confidence confidence, String evidence)
    {
        return new RestrictedBuildSuggestion(type, confidence, evidence);
    }

    private static int nonCombatExtreme(AccountSnapshot account,
            boolean highest)
    {
        var value = highest ? 1 : Integer.MAX_VALUE;
        for (Skill skill : Skill.values())
            if (!isCombatProgressionSkill(skill))
                value = highest ? max(value, account.level(skill))
                        : min(value, account.level(skill));
        return value == Integer.MAX_VALUE ? 1 : value;
    }

    /**
     * Returns the build that is safe to enforce automatically. Ambiguous
     * CHECK_NEEDED suggestions remain STANDARD until the player confirms them in
     * a future explicit build setting.
     */
    public static BuildType effectiveBuild(AccountSnapshot account)
    {
        var suggestion = detect(account);
        if (suggestion.confidence != Confidence.VERIFIED)
        {
            return BuildType.STANDARD;
        }
        return suggestion.getType();
    }

    public static boolean allowsSkill(AccountSnapshot account, Skill skill)
    {
        if (account == null || skill == null) return true;
        var build = effectiveBuild(account);

        switch (build)
        {
            case SKILLER:
            case F2P_SKILLER:
                return !isCombatProgressionSkill(skill);

            case PRAYER_SKILLER:
                return skill == Skill.PRAYER || !isCombatProgressionSkill(skill);

            case ONE_DEFENCE_PURE:
                return skill != Skill.DEFENCE;

            case LOW_DEFENCE_PURE:
                return skill != Skill.DEFENCE
                        || account.level(Skill.DEFENCE) < 13;

            case INITIATE_PURE:
                return skill != Skill.DEFENCE
                        || account.level(Skill.DEFENCE) < 20;

            case RUNE_PURE:
                return skill != Skill.DEFENCE
                        || account.level(Skill.DEFENCE) < 40;

            case VOID_PURE:
                return skill != Skill.DEFENCE
                        || account.level(Skill.DEFENCE) < 42;

            case ZERKER:
                return skill != Skill.DEFENCE
                        || account.level(Skill.DEFENCE) < 45;

            case OBSIDIAN_MAULER:
                return skill != Skill.ATTACK && skill != Skill.DEFENCE;

            case DEFENCE_PURE:
                // Defence-pure combat progression is deliberately limited to
                // Defence and Prayer. Hitpoints rises incidentally from legal
                // Defence training and is never a direct recommendation anyway.
                return skill != Skill.ATTACK
                        && skill != Skill.STRENGTH
                        && skill != Skill.RANGED
                        && skill != Skill.MAGIC
                        && skill != Skill.SLAYER;

            case TEN_HITPOINTS:
                // Attack/Strength/Defence/Ranged training normally creates HP
                // experience. Magic can remain legal through splashing,
                // alching, teleports, curses, enchanting, etc., so method-level
                // policy decides which Magic methods are safe.
                return skill != Skill.ATTACK
                        && skill != Skill.STRENGTH
                        && skill != Skill.DEFENCE
                        && skill != Skill.RANGED
                        && skill != Skill.HITPOINTS
                        && skill != Skill.SLAYER;

            case COMBAT_ONLY:
                return isCombatProgressionSkill(skill);

            case RANGE_TANK:
            case MED_BUILD:
            case STANDARD:
            default:
                return true;
        }
    }

    public static boolean allowsMethod(
            AccountSnapshot account,
            TrainingMethod method)
    {
        if (account == null || method == null) return true;
        if (!allowsSkill(account, method.getSkill())) return false;

        var build = effectiveBuild(account);
        var id = method.id == null ? "" : method.id.toLowerCase();

        if (build == BuildType.TEN_HITPOINTS)
        {
            if (method.getSkill() == Skill.MAGIC)
            {
                // Only known non-damaging/zero-HP Magic routes are allowed by
                // default. Combat, Slayer, bursting, and barraging are blocked.
                return id.contains("alch")
                        || id.contains("curse")
                        || id.contains("teleport")
                        || id.contains("enchant")
                        || id.contains("utility");
            }
            return !isHpGeneratingCombatSkill(method.getSkill());
        }

        if ((build == BuildType.SKILLER
                || build == BuildType.F2P_SKILLER
                || build == BuildType.PRAYER_SKILLER)
                && isHpGeneratingCombatSkill(method.getSkill()))
        {
            return false;
        }

        return true;
    }

    /**
     * Prevents broad gear ladders from suggesting armour that violates a known
     * Defence cap. Exact item-level requirement data can later replace these
     * conservative tier checks.
     */
    public static boolean allowsGearEntry(
            AccountSnapshot account,
            GearProgressionEntry entry)
    {
        if (account == null || entry == null) return true;
        var build = effectiveBuild(account);
        var id = entry.id == null ? "" : entry.id.toLowerCase();

        switch (build)
        {
            case SKILLER:
            case F2P_SKILLER:
            case PRAYER_SKILLER:
            case TEN_HITPOINTS:
            case COMBAT_ONLY:
                // Combat-only can use gear normally. The fall-through is split
                // below to keep the restricted non-aggressor builds explicit.
                return build == BuildType.COMBAT_ONLY;

            case ONE_DEFENCE_PURE:
            case OBSIDIAN_MAULER:
                return id.contains("1def") || id.contains("pure");

            case LOW_DEFENCE_PURE:
                return id.contains("low-def") || id.contains("pure");

            case INITIATE_PURE:
                return id.contains("20def") || id.contains("pure");

            case RUNE_PURE:
                return id.contains("40def") || id.contains("rune-pure")
                        || id.contains("pure");

            case VOID_PURE:
                return id.contains("42def") || id.contains("void-pure")
                        || id.contains("pure");

            case ZERKER:
                return id.contains("45def") || id.contains("zerker")
                        || id.contains("pure");

            case DEFENCE_PURE:
                return id.contains("defence-pure") || id.contains("tank");

            case RANGE_TANK:
                return entry.style == CombatStyle.RANGED
                        || entry.style == CombatStyle.MAGIC
                        || id.contains("tank");

            case MED_BUILD:
            case STANDARD:
            default:
                return true;
        }
    }

    public static String label(AccountSnapshot account)
    {
        return pretty(effectiveBuild(account));
    }

    private static boolean isCombatProgressionSkill(Skill skill)
    {
        switch (skill)
        {
            case ATTACK:
            case STRENGTH:
            case DEFENCE:
            case HITPOINTS:
            case RANGED:
            case PRAYER:
            case MAGIC:
            case SLAYER:
                return true;
            default:
                return false;
        }
    }

    private static boolean isHpGeneratingCombatSkill(Skill skill)
    {
        return skill == Skill.ATTACK
                || skill == Skill.STRENGTH
                || skill == Skill.DEFENCE
                || skill == Skill.RANGED
                || skill == Skill.MAGIC
                || skill == Skill.SLAYER;
    }

    private static String pretty(BuildType type)
    {
        var text = type.name().toLowerCase().replace('_', ' ');
        return Character.toUpperCase(text.charAt(0)) + text.substring(1);
    }
}

/**
 * Central account-mode rules used by planners before they recommend a route.
 *
 * <p>Keeping these rules in one place prevents accidental GE suggestions on
 * irons, inappropriate group-storage assumptions, or UIM storage advice that
 * ignores the account's restrictions.</p>
 */
final class AccountModePolicy
{
    private AccountModePolicy()
    {
    }

    public static boolean requiresSelfSourcing(AccountMode mode)
    {
        return mode != null && mode.isIronLike();
    }

    public static boolean isRiskSensitive(AccountMode mode)
    {
        return mode == AccountMode.HARDCORE_IRONMAN
                || mode == AccountMode.HARDCORE_GROUP_IRONMAN
                || mode == AccountMode.ULTIMATE_IRONMAN;
    }
}

/**
 * Hard gate for the primary DO NEXT slot and quality gate for alternatives.
 *
 * <p>The primary card must always contain an executable next action. A fully
 * verified route can lead immediately. A route with only ordinary preparation
 * outstanding may also lead when its guidance explains that preparation. True
 * unknown access, quest, build, or unlock requirements can never lead.</p>
 */
@Singleton
class ActionabilityPolicy
{
    private final RecommendationQualityPolicy qualityPolicy =
            new RecommendationQualityPolicy();

    public boolean canLeadQueue(Recommendation recommendation)
    {
        if (recommendation == null
                || recommendation.confidence == Confidence.BLOCKED)
        {
            return false;
        }

        var plan = recommendation.plan();
        var guidance = recommendation.guidance;
        if (!qualityPolicy.isPresentable(recommendation)) return false;

        if (plan == null)
        {
            // Non-skill candidates must be fully verified and structured before
            // they can displace a concrete training action. The one exception
            // is an explicitly typed preparation/verification action whose
            // remaining work is fully described by the quality contract.
            return (recommendation.confidence
                        == Confidence.VERIFIED
                    || (recommendation.confidence
                        == Confidence.CHECK_NEEDED
                        && isExplicitPreparation(recommendation)))
                    && guidance != null && hasText(guidance.getAction());
        }

        if (plan.method() == null || guidance == null
                || !hasText(guidance.getAction()))
        {
            return false;
        }

        if (recommendation.confidence == Confidence.VERIFIED)
        {
            return !RequirementActionability.hasHardUnresolvedRequirement(plan);
        }

        // CHECK_NEEDED is allowed only when every unresolved check is ordinary
        // preparation and the guidance explicitly covers supplies/setup.
        return RequirementActionability.isActionablePreparation(plan, guidance);
    }

    public boolean mayAppearAsAlternative(Recommendation recommendation)
    {
        if (recommendation == null
                || recommendation.confidence == Confidence.BLOCKED)
        {
            return false;
        }
        if (canLeadQueue(recommendation)) return true;

        if (!qualityPolicy.isPresentable(recommendation)) return false;

        var guidance = recommendation.guidance;
        var plan = recommendation.plan();

        // A secondary card still needs to tell the player something useful.
        // Bare "Needs Info" quest/upgrade placeholders are hidden until their
        // provider can produce a concrete next verification/preparation step.
        if (plan == null)
        {
            return guidance != null && hasText(guidance.getAction())
                    && (recommendation.confidence
                            == Confidence.VERIFIED
                        || isExplicitPreparation(recommendation));
        }

        return plan.method() != null
                && guidance != null
                && hasText(guidance.getAction())
                && !RequirementActionability.hasHardUnresolvedRequirement(plan);
    }

    private static boolean hasText(String value)
    {
        return value != null && !value.trim().isEmpty();
    }

    private static boolean isExplicitPreparation(Recommendation recommendation)
    {
        String id = recommendation == null || recommendation.id == null
                ? "" : recommendation.id.toLowerCase(
                        Locale.ROOT);
        return id.startsWith("prepare:")
                || id.startsWith("preparation:")
                || id.startsWith("verify:");
    }
}

/** Final access/build boundary shared by every recommendation family. */
@Singleton
class CandidateSafetyPolicy
{
    public boolean isAllowed(Recommendation recommendation, StrategyContext context)
    {
        if (recommendation == null || !hasValidExecution(recommendation, context)
                || !hasSafeStorageGuidance(recommendation.guidance))
            return false;
        if (recommendation == null || context == null || context.data() == null
                || context.data().account() == null)
        {
            return true;
        }

        var account = context.data().account();
        if (AccountMode.fromTypeCode(account.modeCode())
                    == AccountMode.ULTIMATE_IRONMAN
                && (recommendation.safetyEvidence
                        .isConventionalBankRequired()
                    || recommendation.plan() != null
                        && recommendation.plan().getStrategyProfile() != null
                        && recommendation.plan().getStrategyProfile()
                            .bankingBehavior
                            == BankingMode.CONVENTIONAL_BANK_LOOP
                    || recommendation.guidance != null
                        && recommendation.guidance.bankingBehavior
                            == BankingMode.CONVENTIONAL_BANK_LOOP))
            return false;
        return isAllowed(recommendation.safetyEvidence, account);
    }

    public boolean isAllowed(Safety evidence,
            StrategyContext context)
    {
        if (evidence == null || context == null || context.data() == null
                || context.data().account() == null) return false;
        return isAllowed(evidence, context.data().account());
    }

    private static boolean isAllowed(Safety evidence,
            AccountSnapshot account)
    {

        // Unannotated content is never assumed F2P-safe. This is the final
        // protection against a new provider forgetting its early access filter.
        if (account.membership() != Membership.P2P
                && evidence.getAccess() != Safety.Access.F2P_SAFE)
        {
            return false;
        }

        var mode = AccountMode.fromTypeCode(account.modeCode());
        if ((mode == AccountMode.HARDCORE_IRONMAN
                || mode == AccountMode.HARDCORE_GROUP_IRONMAN)
                && (evidence.getBuildEffect()
                == Safety.BuildEffect.POTENTIALLY_IRREVERSIBLE
                || evidence.getBuildEffect()
                == Safety.BuildEffect.UNKNOWN))
        {
            // When the candidate cannot prove its risk/build effects, preserving
            // a Hardcore life takes precedence over provider score.
            return false;
        }

        var suggestion = AccountBuildPolicy.detect(account);
        if (suggestion.confidence == Confidence.VERIFIED
                && suggestion.getType() == BuildType.STANDARD)
        {
            return true;
        }

        switch (evidence.getBuildEffect())
        {
            case HARMLESS:
            case VERIFIED_SAFE:
                return true;
            case SKILL_XP:
                return evidence.getAffectedSkill() != null
                        && AccountBuildPolicy.allowsSkill(account,
                        evidence.getAffectedSkill());
            case POTENTIALLY_IRREVERSIBLE:
            case UNKNOWN:
            default:
                // Ambiguous and verified restricted signatures both fail closed
                // unless the provider supplied a harmless or verified-safe proof.
                return false;
        }
    }

    private static boolean hasValidExecution(Recommendation recommendation,
            StrategyContext context)
    {
        var plan = recommendation.plan();
        if (plan == null) return true;
        var method = plan.method();
        int current = recommendation.currentLevel;
        int stageTarget = recommendation.getCurrentExecutionTargetLevel();
        return method != null && hasText(method.getName()) && current > 0
                && method.supportsLevel(current) && stageTarget > current
                && (recommendation.targetLevel <= 0
                    || stageTarget <= recommendation.targetLevel)
                && (context == null || context.data() == null
                    || context.data().account() == null
                    || ContentAccessRules.isMethodAvailable(method,
                        context.data().account().membership()))
                && recommendation.guidance != null
                && hasText(recommendation.guidance.getAction())
                && hasText(recommendation.guidance.location);
    }

    private static boolean hasSafeStorageGuidance(Guidance guidance)
    {
        if (guidance == null || guidance.getStorageCapability() == null)
            return true;
        var capability = guidance.getStorageCapability();
        var decision = guidance.getStorageDecision();
        return decision != null && decision.isAllowed()
                && decision.confidence == Confidence.VERIFIED
                && !UimStorageMechanics.isTooGenericToRecommend(capability)
                && (!UimStorageMechanics.isDangerous(capability)
                    || guidance.getRiskDisclosure() != null
                    && guidance.getRiskDisclosure()
                        .isAcknowledgementRequired());
    }

    private static boolean hasText(String value)
    {
        return value != null && !value.trim().isEmpty();
    }

}

/**
 * Hard membership boundary for quest recommendations.
 *
 * <p>RuneLite exposes the complete quest list even while the character is on a
 * free-to-play account/world. The Compass must therefore filter by content
 * entitlement before scoring quests. This list tracks the current F2P quest set
 * and intentionally fails closed for unknown names on F2P.</p>
 */
final class QuestMembershipPolicy
{
    private static final Set<String> FREE_TO_PLAY_QUESTS =
            PolicyLists.normalizedSet(PolicyLists.DATA.free_to_play_quests);

    private QuestMembershipPolicy()
    {
    }

    public static boolean isAvailable(String questName, Membership membership)
    {
        if (questName == null || questName.trim().isEmpty()) return false;
        if (membership == Membership.P2P) return true;
        return FREE_TO_PLAY_QUESTS.contains(normalize(questName));
    }

    private static String normalize(String value)
    {
        return PolicyLists.normalize(value);
    }
}

/** Rejects known placeholder-shaped copy before it can reach player cards. */
final class RecommendationQualityPolicy
{
    private static final List<String> GENERIC_TITLES =
            PolicyLists.list(PolicyLists.DATA.generic_titles);
    private static final List<String> GENERIC_ACTIONS =
            PolicyLists.list(PolicyLists.DATA.generic_actions);
    private static final List<String> GENERIC_LOCATIONS =
            PolicyLists.list(PolicyLists.DATA.generic_locations);
    private static final List<String> UNRESOLVED_SUPPLIES =
            PolicyLists.list(PolicyLists.DATA.unresolved_supplies);

    boolean isPresentable(Recommendation recommendation)
    {
        if (recommendation == null || !hasText(recommendation.title)) return false;
        if (isGenericTitle(recommendation.title))
            return false;
        var guidance = recommendation.guidance;
        if (guidance == null || !hasText(guidance.getAction())) return false;
        if (containsAny(guidance.getAction(), GENERIC_ACTIONS)) return false;
        if (containsAny(guidance.location, GENERIC_ACTIONS)) return false;
        if (containsAny(guidance.location, GENERIC_LOCATIONS)) return false;
        if (containsAny(guidance.supplies, UNRESOLVED_SUPPLIES)) return false;

        var plan = recommendation.plan();
        if (plan != null)
        {
            if (plan.method() == null
                    || !hasText(plan.method().getName())
                    || !hasText(guidance.location)) return false;
            if (containsAny(plan.method().getName(), GENERIC_ACTIONS))
            {
                return false;
            }
        }
        return coherentRuneRoute(plan, guidance);
    }

    private static boolean coherentRuneRoute(
            TrainingPlan plan, Guidance guidance)
    {
        if (plan == null || plan.method() == null
                || plan.method().getSkill() != Skill.RUNECRAFT)
        {
            return true;
        }
        var method = Names.text(plan.method().getName());
        var action = Names.text(guidance.getAction());
        String[] runes = {"air", "mind", "water", "earth", "fire", "body"};
        for (String rune : runes)
        {
            if (method.contains(rune + " rune"))
                return action.contains(rune + " rune");
        }
        return true;
    }

    private static boolean containsAny(String value, List<String> needles)
    {
        var normalized = Names.text(value);
        if (normalized.isEmpty()) return false;
        for (String needle : needles)
            if (normalized.contains(needle)) return true;
        return false;
    }

    private static boolean isGenericTitle(String value)
    {
        var normalized = Names.text(value);
        if (GENERIC_TITLES.contains(normalized)) return true;
        for (Skill skill : Skill.values())
        {
            if (normalized.equals("train " + Names.text(skill.getName())))
                return true;
        }
        return false;
    }

    private static boolean hasText(String value)
    {
        return value != null && !value.trim().isEmpty();
    }

}

/** Fail-closed quest safety for irreversible restricted-build XP. */
final class RestrictedQuestPolicy
{
    private static final Set<String> ONE_DEFENCE = PolicyLists.normalizedSet(
            PolicyLists.DATA.one_defence_safe);
    private static final Set<String> LEVEL_THREE = PolicyLists.normalizedSet(
            PolicyLists.DATA.level_three_safe);
    private static final Set<String> PRAYER_EXTRA = PolicyLists.normalizedSet(
            PolicyLists.DATA.prayer_skiller_extra);

    private RestrictedQuestPolicy() {}

    public static boolean isSafe(AccountSnapshot account, String questName)
    {
        if (account == null || questName == null) return false;
        var build = AccountBuildPolicy.effectiveBuild(account);
        switch (build)
        {
            case STANDARD:
            case RANGE_TANK:
            case MED_BUILD:
            case COMBAT_ONLY:
                return true;
            case SKILLER:
            case F2P_SKILLER:
                return LEVEL_THREE.contains(PolicyLists.normalize(questName));
            case PRAYER_SKILLER:
            case DEFENCE_PURE:
            case TEN_HITPOINTS:
                return safeForPrayerOnly(questName);
            case ONE_DEFENCE_PURE:
            case LOW_DEFENCE_PURE:
            case INITIATE_PURE:
            case RUNE_PURE:
            case VOID_PURE:
            case ZERKER:
            case OBSIDIAN_MAULER:
                return ONE_DEFENCE.contains(PolicyLists.normalize(questName));
            default:
                return false;
        }
    }

    private static boolean safeForPrayerOnly(String quest)
    {
        var key = PolicyLists.normalize(quest);
        return LEVEL_THREE.contains(key) || PRAYER_EXTRA.contains(key);
    }
}

/** Account-mode, restricted-build, and play-style guardrails for training methods. */
@Singleton
class TrainingMethodPolicy
{
    public boolean isAllowed(
            GameData data,
            TrainingMethod method,
            TrainingMethodMetadata metadata,
            boolean allowWildernessMethods)
    {
        if (method == null || metadata == null) return false;
        var account = data == null ? null : data.account();
        AccountMode mode = account == null
                ? AccountMode.UNKNOWN
                : AccountMode.fromTypeCode(account.modeCode());
        Membership membership = account == null
                ? Membership.UNKNOWN
                : account.membership();

        if (!AccountBuildPolicy.allowsMethod(account, method)) return false;

        // UNKNOWN membership is intentionally treated like F2P here. The route
        // can widen as soon as membership is verified, but it can never leak a
        // members-only method into an F2P account during a transient read.
        if (membership != Membership.P2P
                && !metadata.isFreeToPlayAllowed())
        {
            return false;
        }

        if (method.wilderness && !allowWildernessMethods) return false;

        if (mode == AccountMode.HARDCORE_IRONMAN
                || mode == AccountMode.HARDCORE_GROUP_IRONMAN)
        {
            if (method.wilderness
                    || !metadata.isHardcoreSafe()
                    || metadata.riskLevel == RiskLevel.HIGH
                    || metadata.riskLevel == RiskLevel.IRREVERSIBLE)
            {
                return false;
            }
        }

        if (mode == AccountMode.ULTIMATE_IRONMAN
                && !metadata.uimFriendly)
        {
            return false;
        }

        if (AccountModePolicy.isRiskSensitive(mode)
                && metadata.riskLevel == RiskLevel.IRREVERSIBLE)
        {
            return false;
        }

        return true;
    }

    public double scoreAdjustment(
            GameData data,
            TrainingMethodMetadata metadata,
            StrategyMode strategyMode,
            SessionIntent sessionIntent)
    {
        if (metadata == null) return 0.0;
        var account = data == null ? null : data.account();
        AccountMode mode = account == null
                ? AccountMode.UNKNOWN
                : AccountMode.fromTypeCode(account.modeCode());
        double score = intensityAdjustment(
                metadata.getIntensity(), strategyMode, sessionIntent);

        // Account-specific method value now comes from sourced strategy
        // profiles and live readiness in TrainingMethodSelector. Keep this
        // policy focused on play-style fit and real risk instead of layering
        // arbitrary Iron/UIM/method-cost bonuses over the knowledge model.
        if (AccountModePolicy.isRiskSensitive(mode))
        {
            if (metadata.riskLevel == RiskLevel.MEDIUM) score -= 5.0;
            if (metadata.riskLevel == RiskLevel.HIGH) score -= 10.0;
        }
        return score;
    }

    private static double intensityAdjustment(
            TrainingIntensity intensity,
            StrategyMode mode,
            SessionIntent intent)
    {
        var score = 0.0;
        var safeMode = mode == null ? StrategyMode.BALANCED : mode;
        var safeIntent = intent == null ? SessionIntent.PICK_FOR_ME : intent;

        switch (safeMode)
        {
            case EFFICIENT:
                if (intensity == TrainingIntensity.SWEATY) score += 5.0;
                if (intensity == TrainingIntensity.EFFICIENT) score += 7.0;
                if (intensity == TrainingIntensity.RELAXED) score -= 2.0;
                if (intensity == TrainingIntensity.AFK) score -= 3.0;
                break;
            case RELAXED:
                if (intensity == TrainingIntensity.AFK) score += 8.0;
                if (intensity == TrainingIntensity.RELAXED) score += 7.0;
                if (intensity == TrainingIntensity.BALANCED) score += 2.0;
                if (intensity == TrainingIntensity.SWEATY) score -= 9.0;
                break;
            case BALANCED:
            default:
                if (intensity == TrainingIntensity.BALANCED) score += 6.0;
                if (intensity == TrainingIntensity.EFFICIENT) score += 3.0;
                if (intensity == TrainingIntensity.RELAXED) score += 3.0;
                if (intensity == TrainingIntensity.SWEATY) score -= 1.0;
                break;
        }

        if (safeIntent == SessionIntent.AFK)
        {
            if (intensity == TrainingIntensity.AFK) score += 9.0;
            if (intensity == TrainingIntensity.RELAXED) score += 4.0;
            if (intensity == TrainingIntensity.BALANCED) score -= 2.0;
            if (intensity == TrainingIntensity.EFFICIENT) score -= 5.0;
            if (intensity == TrainingIntensity.SWEATY) score -= 12.0;
        }
        return score;
    }
}

package compass;
import static java.lang.Math.*;
import static java.util.Collections.*;

import java.util.*;

/**
 * A deliberately slow-moving preference model.
 *
 * <p>Three concepts stay separate:</p>
 * <ul>
 *     <li>Long-term preference: what the player generally likes/dislikes.</li>
 *     <li>Cooldowns: activities temporarily hidden by explicit feedback.</li>
 *     <li>Timed score adjustments: soft nudges such as post-milestone variety.</li>
 * </ul>
 *
 * <p>Keeping them separate prevents "Not Today" or a recently completed skill
 * from accidentally becoming a permanent dislike.</p>
 */
public final class PreferenceProfile
{
    private static final String SEMANTIC_PREFIX = "semantic:";
    private static final long ONE_HOUR_MILLIS = 60L * 60L * 1000L;
    private static final long SIX_HOURS_MILLIS = 6L * ONE_HOUR_MILLIS;
    private static final long ONE_DAY_MILLIS = 24L * ONE_HOUR_MILLIS;

    private final Map<String, Double> weights = new HashMap<>();
    private final Map<String, Long> cooldowns = new HashMap<>();
    private final Map<String, TimedScoreAdjustment> timedAdjustments =
            new HashMap<>();

    public double weightFor(String activityId)
    {
        return weights.getOrDefault(activityId, 0.0);
    }

    public double timedScoreAdjustmentFor(String activityId)
    {
        var adjustment = timedAdjustments.get(activityId);

        if (adjustment == null)
        {
            return 0.0;
        }

        var now = System.currentTimeMillis();
        if (adjustment.isExpired(now))
        {
            timedAdjustments.remove(activityId);
            return 0.0;
        }

        return adjustment.getScoreDelta();
    }

    public boolean isOnCooldown(String activityId)
    {
        var cooldownUntil = cooldowns.get(activityId);

        if (cooldownUntil == null)
        {
            return false;
        }

        if (cooldownUntil <= System.currentTimeMillis())
        {
            cooldowns.remove(activityId);
            return false;
        }

        return true;
    }

    /**
     * Adds a soft temporary ranking adjustment rather than hiding an activity.
     * This is ideal for milestone completion: we encourage a fresh suggestion,
     * but a strategically important continuation can still win the ranking.
     */
    public void addTemporaryScoreAdjustment(
            String activityId,
            double scoreDelta,
            long durationMillis)
    {
        if (activityId == null || durationMillis <= 0L)
        {
            return;
        }

        timedAdjustments.put(
                activityId,
                new TimedScoreAdjustment(
                        scoreDelta,
                        System.currentTimeMillis() + durationMillis
                )
        );
    }

    public void apply(String activityId, FeedbackAction action)
    {
        var now = System.currentTimeMillis();
        var delta = 0.0;

        switch (action)
        {
            case LATER:
                // "Later" is temporary, not a dislike.
                cooldowns.put(
                        activityId,
                        now + ONE_HOUR_MILLIS
                );
                break;

            case NOT_TODAY:
                // Hide it for a full day without damaging its long-term score.
                cooldowns.put(
                        activityId,
                        now + ONE_DAY_MILLIS
                );
                break;

            case DISLIKE:
                // A dislike should affect future ranking, but important
                // progression can still overcome the negative weight later.
                delta = -0.25;
                cooldowns.put(
                        activityId,
                        now + SIX_HOURS_MILLIS
                );
                break;

            default:
                break;
        }

        if (delta != 0.0)
        {
            double next = max(
                    -1.5,
                    min(
                            1.5,
                            weightFor(activityId) + delta
                    )
            );

            weights.put(activityId, next);
        }
    }

    /** Apply feedback to a deduplicated action so provider aliases cannot rebound. */
    public void applySemantic(String semanticKey, FeedbackAction action)
    {
        if (semanticKey == null || semanticKey.trim().isEmpty()
                || action == null) return;
        apply(SEMANTIC_PREFIX + semanticKey, action);
    }

    public boolean isSemanticOnCooldown(String semanticKey)
    {
        return semanticKey != null
                && isOnCooldown(SEMANTIC_PREFIX + semanticKey);
    }

    public double semanticWeightFor(String semanticKey)
    {
        return semanticKey == null ? 0.0
                : weightFor(SEMANTIC_PREFIX + semanticKey);
    }

    public double semanticTimedScoreAdjustmentFor(String semanticKey)
    {
        return semanticKey == null ? 0.0
                : timedScoreAdjustmentFor(SEMANTIC_PREFIX + semanticKey);
    }

    public void clear()
    {
        weights.clear();
        cooldowns.clear();
        timedAdjustments.clear();
    }

    public void replaceAll(Map<String, Double> storedWeights)
    {
        weights.clear();

        if (storedWeights == null)
        {
            return;
        }

        for (Map.Entry<String, Double> entry : storedWeights.entrySet())
        {
            var activityId = entry.getKey();
            var weight = entry.getValue();

            if (activityId == null || weight == null)
            {
                continue;
            }

            double clamped = max(
                    -1.5,
                    min(1.5, weight)
            );

            weights.put(activityId, clamped);
        }
    }

    public void replaceCooldowns(Map<String, Long> storedCooldowns)
    {
        cooldowns.clear();

        if (storedCooldowns == null)
        {
            return;
        }

        var now = System.currentTimeMillis();

        for (Map.Entry<String, Long> entry : storedCooldowns.entrySet())
        {
            var activityId = entry.getKey();
            var cooldownUntil = entry.getValue();

            if (activityId == null
                    || cooldownUntil == null
                    || cooldownUntil <= now)
            {
                continue;
            }

            cooldowns.put(
                    activityId,
                    cooldownUntil
            );
        }
    }

    public void replaceTimedAdjustments(
            Map<String, TimedScoreAdjustment> storedAdjustments)
    {
        timedAdjustments.clear();

        if (storedAdjustments == null)
        {
            return;
        }

        var now = System.currentTimeMillis();
        for (Map.Entry<String, TimedScoreAdjustment> entry
                : storedAdjustments.entrySet())
        {
            var activityId = entry.getKey();
            var adjustment = entry.getValue();

            if (activityId == null
                    || adjustment == null
                    || adjustment.isExpired(now))
            {
                continue;
            }

            timedAdjustments.put(activityId, adjustment);
        }
    }

    public Map<String, Double> snapshot()
    {
        return unmodifiableMap(
                new HashMap<>(weights)
        );
    }

    public Map<String, Long> cooldownSnapshot()
    {
        return unmodifiableMap(
                new HashMap<>(cooldowns)
        );
    }

    public Map<String, TimedScoreAdjustment> timedAdjustmentSnapshot()
    {
        // Purge expired entries before serializing the profile.
        for (String activityId : new HashMap<>(timedAdjustments).keySet())
        {
            timedScoreAdjustmentFor(activityId);
        }

        return unmodifiableMap(
                new HashMap<>(timedAdjustments)
        );
    }
}

package compass;
import static java.util.Collections.*;
import lombok.Getter;
import static java.lang.Math.*;
import static compass.Text.get;

import java.util.*;

/** Converts a recommendation into concise sidebar copy and full detail copy. */
public final class Presentation
{
    private static final int COMPACT_ACTION_CHARS = 150;
    private static final int COMPACT_SUPPLIES_CHARS = 120;
    private static final int COMPACT_LOCATION_CHARS = 130;

    private Presentation() {}

    public static String compactHtml(Recommendation recommendation)
    {
        return compactHtml(recommendation, null);
    }

    public static String compactHtml(Recommendation recommendation,
            GoalRecommendationContext goalContext)
    {
        if (recommendation == null) return "";
        var text = new StringBuilder();
        var plan = recommendation.plan();

        appendGoalStatus(text, goalContext);
        appendRiskDisclosure(text, recommendation.guidance);

        if (plan == null || plan.method() == null)
        {
            appendNonSkillCompact(text, recommendation);
            return text.toString();
        }

        var method = plan.method();
        appendMethodHeader(text, recommendation, method);

        var guidance = recommendation.guidance;
        if (guidance != null)
        {
            appendCompactGuidance(text, guidance);
        }

        var unresolved = hardUnresolved(plan);
        if (!unresolved.isEmpty())
        {
            appendBreak(text, 2);
            text.append(get(1911));
            var shown = min(2, unresolved.size());
            for (int i = 0; i < shown; i++)
            {
                if (i > 0) text.append("<br>");
                var check = unresolved.get(i);
                text.append(check.getState() == RequirementState.BLOCKED
                                ? "• Blocked: " : "• ")
                        .append(escape(check.getLabel()));
            }
            if (unresolved.size() > shown)
            {
                text.append("<br>• +")
                        .append(unresolved.size() - shown)
                        .append(get(1912));
            }
        }
        return text.toString();
    }

    public static String detailedHtml(Recommendation recommendation)
    {
        return detailedHtml(recommendation, null);
    }

    public static String detailedHtml(Recommendation recommendation,
            GoalRecommendationContext goalContext)
    {
        var text = new StringBuilder();
        for (Section section : detailsSections(recommendation, goalContext))
        {
            if (text.length() > 0) appendBreak(text, 2);
            text.append("<b>").append(escape(section.heading))
                    .append("</b><br>").append(escape(section.getValue()));
        }
        return text.toString();
    }

    public static String compactText(Recommendation recommendation)
    {
        return toPlainText(compactHtml(recommendation));
    }

    public static String compactText(Recommendation recommendation,
            GoalRecommendationContext goalContext)
    {
        return toPlainText(compactHtml(recommendation, goalContext));
    }

    public static String detailedText(Recommendation recommendation)
    {
        return toPlainText(detailedHtml(recommendation));
    }

    public static String detailedText(Recommendation recommendation,
            GoalRecommendationContext goalContext)
    {
        return toPlainText(detailedHtml(recommendation, goalContext));
    }

    /** Four compact sections retain the useful decision without graph dumps. */
    public static List<Section> detailsSections(Recommendation recommendation,
            GoalRecommendationContext goalContext)
    {
        if (recommendation == null) return emptyList();
        List<Section> sections = new ArrayList<>();
        var guidance = recommendation.guidance;
        if (guidance != null && guidance.getRiskDisclosure() != null)
            sections.add(new Section(
                    guidance.getRiskDisclosure().heading,
                    guidance.getRiskDisclosure().getMessage()));
        if (goalContext != null && goalContext.hasProvenRelationship()
                && hasText(goalContext.status))
            sections.add(new Section("GOAL",
                    compactSentence(goalContext.status, 160)));

        var why = playerWhy(recommendation);
        if (hasText(why))
            sections.add(new Section("WHY", compactSentence(why, 140)));

        var needed = firstNeeded(recommendation);
        if (hasText(needed))
            sections.add(new Section(
                    recommendation.confidence == Confidence.BLOCKED
                            ? "BLOCKED BY" : "NEEDED",
                    compactSentence(needed, 140)));

        // Reserve the fourth compact slot for the executable current step.
        if (sections.size() < 3 && guidance != null
                && hasText(guidance.location))
            sections.add(new Section("WHERE",
                    compactSentence(guidance.location, 140)));

        String current = guidance != null
                ? guidance.getAction() : recommendation.title;
        if (hasText(current))
            sections.add(new Section("CURRENT STEP",
                    compactSentence(current, 150)));

        if (sections.size() < 4 && hasText(recommendation.reason)
                && recommendation.goalProvenance == null
                && !sameSentence(why, recommendation.reason))
            sections.add(new Section("NEXT",
                    compactSentence(recommendation.reason, 130)));
        return unmodifiableList(sections.subList(0,
                min(4, sections.size())));
    }

    private static String playerWhy(Recommendation recommendation)
    {
        if (recommendation != null
                && recommendation.goalProvenance != null)
            return recommendation.goalProvenance.playerReason();
        return recommendation == null ? null : recommendation.reason;
    }

    private static void appendNonSkillCompact(
            StringBuilder text,
            Recommendation recommendation)
    {
        var guidance = recommendation.guidance;
        if (recommendation.confidence == Confidence.BLOCKED)
        {
            text.append(get(1913))
                    .append(get(692));
            return;
        }
        text.append(get(1914))
                .append(escape(compactSentence(recommendation.title, 110)));
        if (recommendation.confidence != Confidence.VERIFIED)
        {
            if (guidance != null && hasText(guidance.getAction()))
                appendCompactGuidance(text, guidance);
            else
            {
                appendBreak(text, 2);
                text.append("<b>DO</b><br>");
                text.append(get(693));
            }
            return;
        }

        if (guidance != null)
        {
            appendCompactGuidance(text, guidance);
        }
        else if (hasText(recommendation.reason))
        {
            appendBreak(text, 2);
            text.append(get(694));
        }
    }

    private static void appendRiskDisclosure(StringBuilder text,
            Guidance guidance)
    {
        if (guidance == null || guidance.getRiskDisclosure() == null) return;
        var disclosure = guidance.getRiskDisclosure();
        text.append("<b>").append(escape(disclosure.heading))
                .append("</b><br>")
                .append(escape(compactSentence(disclosure.getMessage(), 180)));
        if (disclosure.isAcknowledgementRequired())
            text.append(get(695));
        appendBreak(text, 2);
    }

    /** The primary card must contain the executable loop, not only its inputs. */
    private static void appendCompactGuidance(
            StringBuilder text, Guidance guidance)
    {
        if (guidance == null) return;
        if (meaningfulSupplies(guidance.supplies))
        {
            appendBreak(text, 2);
            text.append(get(1915))
                    .append(escape(compactSentence(guidance.supplies,
                            COMPACT_SUPPLIES_CHARS)));
        }
        if (hasText(guidance.location))
        {
            appendBreak(text, 2);
            text.append(get(1916))
                    .append(escape(compactSentence(guidance.location,
                            COMPACT_LOCATION_CHARS)));
        }
        if (hasText(guidance.getAction()))
        {
            appendBreak(text, 2);
            text.append("<b>DO</b><br>")
                    .append(escape(compactSentence(guidance.getAction(),
                            COMPACT_ACTION_CHARS)));
        }
    }

    private static boolean meaningfulSupplies(String supplies)
    {
        if (!hasText(supplies)) return false;
        var normalized = supplies.trim().toLowerCase();
        return !normalized.equals("none")
                && !normalized.startsWith(get(1234))
                && !normalized.startsWith(get(1235))
                && !normalized.startsWith(get(1236));
    }

    /**
     * Keep the sidebar useful without letting a detailed planner paragraph turn
     * into a wall of text. When guidance contains multiple sentences, the first
     * complete useful sentence wins even if the full paragraph technically fits
     * the character ceiling. Details retains the complete original string.
     */
    static String compactSentence(String value, int maxChars)
    {
        if (!hasText(value)) return "";
        var normalized = value.trim().replaceAll("\\s+", " ");

        var sentence = normalized.indexOf(". ");
        if (sentence > 20 && sentence + 1 <= maxChars)
        {
            return normalized.substring(0, sentence + 1);
        }
        if (normalized.length() <= maxChars) return normalized;

        var cut = min(maxChars, normalized.length());
        var word = normalized.lastIndexOf(' ', cut);
        if (word >= max(20, maxChars / 2)) cut = word;
        return normalized.substring(0, cut).trim() + "…";
    }

    private static boolean hasText(String value)
    {
        return value != null && !value.trim().isEmpty();
    }

    private static void appendGoalStatus(StringBuilder text,
            GoalRecommendationContext context)
    {
        if (context == null || !context.hasProvenRelationship()
                || !hasText(context.status)) return;
        text.append("<b>GOAL</b><br>")
                .append(escape(compactSentence(context.status, 125)));
        appendBreak(text, 2);
    }

    private static String firstNeeded(Recommendation recommendation)
    {
        var plan = recommendation.plan();
        if (plan != null)
            for (EvidenceCheck check : hardUnresolved(plan))
                if (check != null && hasText(check.getLabel()))
                    return check.getLabel();
        var guidance = recommendation.guidance;
        if (recommendation.confidence
                    == Confidence.CHECK_NEEDED
                && guidance != null && hasText(guidance.supplies))
            return guidance.supplies;
        if (recommendation.confidence == Confidence.CHECK_NEEDED)
            return get(696);
        if (recommendation.confidence == Confidence.BLOCKED)
            return get(697);
        return "";
    }

    private static boolean sameSentence(String left, String right)
    {
        if (!hasText(left) || !hasText(right)) return false;
        return compactSentence(left, 140).equals(compactSentence(right, 140));
    }

    private static List<EvidenceCheck> hardUnresolved(TrainingPlan plan)
    {
        List<EvidenceCheck> unresolved = new ArrayList<>();
        if (plan == null || plan.requirementChecks == null) return unresolved;
        for (EvidenceCheck check : plan.requirementChecks)
        {
            if (check == null || check.getState() == RequirementState.VERIFIED) continue;
            if (RequirementActionability.isPreparationRequirement(check)) continue;
            unresolved.add(check);
        }
        return unresolved;
    }

    private static void appendMethodHeader(
            StringBuilder text,
            Recommendation recommendation,
            TrainingMethod method)
    {
        text.append(get(1917))
                .append(escape(method.getName()));
    }

    private static void appendBreak(StringBuilder text, int count)
    {
        for (int i = 0; i < count; i++) text.append("<br>");
    }

    static String toPlainText(String html)
    {
        if (html == null || html.isEmpty()) return "";
        return html
                .replaceAll("(?i)<br\\s*/?>", "\n")
                .replaceAll(get(1918), "")
                .replaceAll("<[^>]+>", "")
                .replace("&amp;", "&")
                .replace("&lt;", "<")
                .replace("&gt;", ">")
                .replace("&quot;", "\"")
                .replace("&#39;", "'")
                .replaceAll("[ \\t]+\\n", "\n")
                .replaceAll("\\n{3,}", "\n\n")
                .trim();
    }

    private static String escape(String value)
    {
        if (value == null) return "";
        return value
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#39;");
    }

    @Getter
    public static final class Section
    {
        final String heading;
        private final String value;

        Section(String heading, String value)
        {
            this.heading = heading == null ? "" : heading;
            this.value = value == null ? "" : value;
        }

    }
}

package compass;
import static java.util.Collections.*;

import static compass.Text.get;

import com.google.gson.*;
import java.util.*;

/** Explicit profile JSON decoding without plugin-side reflection or TypeToken. */
final class ProfileJsonCodec
{
    private ProfileJsonCodec() { }

    static Map<String, Double> doubles(Gson gson, String json)
    {
        var object = object(gson, json);
        if (object == null) return emptyMap();
        Map<String, Double> result = new LinkedHashMap<>();
        for (Map.Entry<String, JsonElement> entry : object.entrySet())
            if (number(entry.getValue()))
            {
                var value = entry.getValue().getAsDouble();
                if (Double.isFinite(value)) result.put(entry.getKey(), value);
            }
        return result;
    }

    static Map<String, Long> longs(Gson gson, String json)
    {
        var object = object(gson, json);
        if (object == null) return emptyMap();
        Map<String, Long> result = new LinkedHashMap<>();
        for (Map.Entry<String, JsonElement> entry : object.entrySet())
            if (number(entry.getValue()))
                result.put(entry.getKey(), entry.getValue().getAsLong());
        return result;
    }

    static Map<String, TimedScoreAdjustment> timedAdjustments(
            Gson gson, String json)
    {
        var object = object(gson, json);
        if (object == null) return emptyMap();
        Map<String, TimedScoreAdjustment> result = new LinkedHashMap<>();
        for (Map.Entry<String, JsonElement> entry : object.entrySet())
        {
            var value = asObject(entry.getValue());
            if (value == null || !number(value.get("scoreDelta"))
                    || !number(value.get("expiresAtMillis"))) continue;
            var score = value.get("scoreDelta").getAsDouble();
            if (!Double.isFinite(score)) continue;
            result.put(entry.getKey(), new TimedScoreAdjustment(score,
                    value.get("expiresAtMillis").getAsLong()));
        }
        return result;
    }

    static Map<String, ObservedFarmingPatchState> farmingStates(
            Gson gson, String json)
    {
        var object = object(gson, json);
        if (object == null) return emptyMap();
        Map<String, ObservedFarmingPatchState> result = new LinkedHashMap<>();
        for (Map.Entry<String, JsonElement> entry : object.entrySet())
        {
            var value = asObject(entry.getValue());
            if (value == null || value.get("state") == null
                    || !number(value.get(get(1909)))) continue;
            try
            {
                PatchState state = PatchState.valueOf(
                        value.get("state").getAsString());
                if (state != PatchState.UNKNOWN)
                    result.put(entry.getKey(), new ObservedFarmingPatchState(
                            state, value.get(get(1909)).getAsLong()));
            }
            catch (IllegalArgumentException ignored)
            {
                // A removed or corrupt enum value is unknown, never evidence.
            }
        }
        return result;
    }

    private static JsonObject object(Gson gson, String json)
    {
        try
        {
            return gson == null || json == null ? null
                    : gson.fromJson(json, JsonObject.class);
        }
        catch (RuntimeException ignored)
        {
            return null;
        }
    }

    private static JsonObject asObject(JsonElement value)
    {
        return value != null && value.isJsonObject()
                ? value.getAsJsonObject() : null;
    }

    private static boolean number(JsonElement value)
    {
        return value != null && value.isJsonPrimitive()
                && value.getAsJsonPrimitive().isNumber();
    }
}

package compass;
import static java.lang.Math.*;
import static java.util.Collections.*;

import static compass.Text.get;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.swing.JPanel;

/** Lightweight, dependency-free XP-over-time chart for RuneLite's sidebar. */
public final class ProgressChartPanel extends JPanel
{
    private static final int DEFAULT_HEIGHT = 112;
    List<ProgressTimeBucket> buckets = emptyList();

    public ProgressChartPanel()
    {
        setOpaque(true);
        setBackground(StrategistTheme.CARD);
        setForeground(StrategistTheme.GOLD);
        setPreferredSize(new Dimension(180, DEFAULT_HEIGHT));
        setMinimumSize(new Dimension(80, DEFAULT_HEIGHT));
    }

    public void setBuckets(List<ProgressTimeBucket> values)
    {
        buckets = values == null ? emptyList()
                : unmodifiableList(new ArrayList<>(values));
        repaint();
    }

    @Override
    protected void paintComponent(Graphics graphics)
    {
        super.paintComponent(graphics);
        var g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON);
            var width = getWidth();
            var height = getHeight();
            var left = 7;
            var right = max(left + 1, width - 7);
            var top = 8;
            var bottom = max(top + 1, height - 18);

            if (buckets.isEmpty() || totalXp(buckets) <= 0L)
            {
                var message = get(1155);
                var metrics = g.getFontMetrics();
                var x = max(5, (width - metrics.stringWidth(message)) / 2);
                g.setColor(StrategistTheme.MUTED_TEXT);
                g.drawString(message, x, max(metrics.getAscent() + 3,
                        height / 2));
                return;
            }

            g.setColor(StrategistTheme.DIVIDER);
            g.setStroke(new BasicStroke(1f));
            g.drawLine(left, bottom, right, bottom);

            var available = max(1, right - left);
            var displayed = min(buckets.size(), available);
            var start = buckets.size() - displayed;
            var max = 1;
            for (int i = start; i < buckets.size(); i++)
                max = max(max, buckets.get(i).getTotalXp());

            var step = available / (double) displayed;
            var barWidth = max(1, (int) floor(step * 0.72));
            var chartHeight = max(1, bottom - top);
            g.setColor(StrategistTheme.GOLD);
            for (int index = 0; index < displayed; index++)
            {
                var xp = buckets.get(start + index).getTotalXp();
                int barHeight = max(1,
                        (int) round(chartHeight * (xp / (double) max)));
                var x = left + (int) floor(index * step);
                g.fillRect(x, bottom - barHeight, barWidth, barHeight);
            }

            g.setColor(StrategistTheme.MUTED_TEXT);
            g.drawString("XP / 5 min", left, height - 4);
        }
        finally
        {
            g.dispose();
        }
    }

    private static long totalXp(List<ProgressTimeBucket> values)
    {
        var result = 0L;
        for (ProgressTimeBucket value : values) result += value.getTotalXp();
        return result;
    }
}

package compass;
import static java.lang.Math.*;
import static java.util.Collections.*;

import java.util.*;
import net.runelite.api.Skill;

/** Character-local, strictly bounded progress archive. */
public final class ProgressHistory
{
    static final int MAX_SESSIONS = 30;
    static final int MAX_MILESTONES = 100;
    static final int MAX_BUCKETS = 288;

    final List<ProgressSessionSummary> sessions = new ArrayList<>();
    final List<ProgressMilestone> milestones = new ArrayList<>();
    final List<ProgressTimeBucket> buckets = new ArrayList<>();

    public void archive(ProgressSessionSnapshot snapshot)
    {
        if (snapshot == null) return;
        if (snapshot.getTotalXpGained() > 0 || snapshot.getLevelsGained() > 0
                || !snapshot.milestones.isEmpty())
            sessions.add(new ProgressSessionSummary(snapshot));
        milestones.addAll(snapshot.milestones);
        buckets.addAll(snapshot.getBuckets());
        normalizeAndTrim();
    }

    /** Returns a checkpoint document without closing the in-memory session. */
    public ProgressHistory checkpoint(ProgressSessionSnapshot snapshot)
    {
        var copy = new ProgressHistory();
        copy.replaceAll(sessions, milestones, buckets);
        copy.archive(snapshot);
        return copy;
    }

    void replaceAll(
            List<ProgressSessionSummary> nextSessions,
            List<ProgressMilestone> nextMilestones,
            List<ProgressTimeBucket> nextBuckets)
    {
        sessions.clear();
        milestones.clear();
        buckets.clear();
        if (nextSessions != null) sessions.addAll(nextSessions);
        if (nextMilestones != null) milestones.addAll(nextMilestones);
        if (nextBuckets != null) buckets.addAll(nextBuckets);
        normalizeAndTrim();
    }

    public List<ProgressSessionSummary> getSessions()
    {
        return unmodifiableList(new ArrayList<>(sessions));
    }

    public List<ProgressMilestone> getMilestones()
    {
        return unmodifiableList(new ArrayList<>(milestones));
    }

    public List<ProgressTimeBucket> getBuckets()
    {
        return unmodifiableList(new ArrayList<>(buckets));
    }

    public void clear()
    {
        sessions.clear();
        milestones.clear();
        buckets.clear();
    }

    void normalizeAndTrim()
    {
        sessions.sort(Comparator.comparingLong(
                ProgressSessionSummary::getStartedAtMillis).thenComparingLong(
                ProgressSessionSummary::getEndedAtMillis));
        Map<String, ProgressSessionSummary> uniqueSessions =
                new LinkedHashMap<>();
        for (ProgressSessionSummary session : sessions)
            uniqueSessions.putIfAbsent(sessionKey(session), session);
        sessions.clear();
        sessions.addAll(uniqueSessions.values());

        milestones.sort(Comparator.comparingLong(
                ProgressMilestone::getOccurredAtMillis));
        Map<String, ProgressMilestone> uniqueMilestones = new LinkedHashMap<>();
        for (ProgressMilestone milestone : milestones)
            uniqueMilestones.putIfAbsent(milestone.id, milestone);
        milestones.clear();
        milestones.addAll(uniqueMilestones.values());

        TreeMap<Long, EnumMap<Skill, Integer>> mergedBuckets = new TreeMap<>();
        for (ProgressTimeBucket bucket : buckets)
        {
            EnumMap<Skill, Integer> merged = mergedBuckets.computeIfAbsent(
                    bucket.startedAtMillis, ignored ->
                            new EnumMap<>(Skill.class));
            for (Map.Entry<Skill, Integer> entry
                    : bucket.getXpBySkill().entrySet())
                merged.merge(entry.getKey(), max(0, entry.getValue()),
                        ProgressHistory::saturatingAdd);
        }
        buckets.clear();
        for (Map.Entry<Long, EnumMap<Skill, Integer>> entry
                : mergedBuckets.entrySet())
            buckets.add(new ProgressTimeBucket(entry.getKey(), entry.getValue()));

        trimOldest(sessions, MAX_SESSIONS);
        trimOldest(milestones, MAX_MILESTONES);
        trimOldest(buckets, MAX_BUCKETS);
    }

    static String sessionKey(ProgressSessionSummary value)
    {
        return value.startedAtMillis + ":" + value.getEndedAtMillis()
                + ":" + value.activeDurationMillis + ":"
                + value.getTotalXpGained() + ":" + value.getLevelsGained()
                + ":" + value.getXpBySkill() + ":" + milestoneIds(value);
    }

    static String milestoneIds(ProgressSessionSummary value)
    {
        var result = new StringBuilder();
        for (ProgressMilestone milestone : value.milestones)
            result.append(milestone.id).append('|');
        return result.toString();
    }

    static int saturatingAdd(int first, int second)
    {
        var result = (long) first + second;
        return (int) min(Integer.MAX_VALUE, max(0L, result));
    }

    static void trimOldest(List<?> values, int limit)
    {
        while (values.size() > limit) values.remove(0);
    }
}

package compass;

import static compass.Text.get;

import com.google.gson.*;
import java.util.*;
import net.runelite.api.Skill;

/** Versioned fail-closed persistence codec for bounded local progress data. */
final class ProgressHistoryCodec
{
    private static final int SCHEMA_VERSION = 2;
    private static final long MAX_ACCOUNT_XP = 5_000_000_000L;
    private static final int MAX_SESSION_LEVELS = 3_000;

    private ProgressHistoryCodec() { }

    static String encode(Gson gson, ProgressHistory history)
    {
        var root = new JsonObject();
        root.addProperty("schemaVersion", SCHEMA_VERSION);
        var sessions = new JsonArray();
        for (ProgressSessionSummary value : history.getSessions())
        {
            var object = new JsonObject();
            object.addProperty("startedAtMillis", value.startedAtMillis);
            object.addProperty("endedAtMillis", value.getEndedAtMillis());
            object.addProperty(get(1906),
                    value.activeDurationMillis);
            object.addProperty("totalXpGained", value.getTotalXpGained());
            object.addProperty("levelsGained", value.getLevelsGained());
            object.add("xpBySkill", skills(value.getXpBySkill()));
            object.add("milestones", milestones(value.milestones));
            sessions.add(object);
        }
        root.add("sessions", sessions);

        root.add("milestones", milestones(history.milestones));

        var buckets = new JsonArray();
        for (ProgressTimeBucket value : history.getBuckets())
        {
            var object = new JsonObject();
            object.addProperty("startedAtMillis", value.startedAtMillis);
            object.add("xpBySkill", skills(value.getXpBySkill()));
            buckets.add(object);
        }
        root.add("buckets", buckets);
        return gson.toJson(root);
    }

    static ProgressHistory decode(Gson gson, String json)
    {
        var history = new ProgressHistory();
        var root = object(gson, json);
        int schema = root == null ? -1
                : integer(root.get("schemaVersion"), -1);
        if (schema != 1 && schema != SCHEMA_VERSION)
            return history;
        try
        {
            history.replaceAll(readSessions(root.get("sessions")),
                    readMilestones(root.get("milestones")),
                    readBuckets(root.get("buckets")));
        }
        catch (RuntimeException ignored)
        {
            // One corrupt document cannot leak partial or untrusted state.
            history.clear();
        }
        return history;
    }

    private static List<ProgressSessionSummary> readSessions(JsonElement value)
    {
        List<ProgressSessionSummary> result = new ArrayList<>();
        var array = array(value);
        if (array == null) return result;
        for (JsonElement element : array)
        {
            var object = asObject(element);
            if (object == null) continue;
            var started = naturalLong(object.get("startedAtMillis"), -1L);
            var ended = naturalLong(object.get("endedAtMillis"), -1L);
            var active = naturalLong(object.get(get(1906)), -1L);
            var xp = naturalLong(object.get("totalXpGained"), -1L);
            var levels = integer(object.get("levelsGained"), -1);
            if (started < 0L || ended < started || active < 0L
                    || active > ended - started || xp < 0L
                    || xp > MAX_ACCOUNT_XP || levels < 0
                    || levels > MAX_SESSION_LEVELS)
                continue;
            var skills = readSkills(object.get("xpBySkill"));
            long skillTotal = skills.values().stream()
                    .mapToLong(Integer::longValue).sum();
            if (skillTotal != xp) continue;
            result.add(new ProgressSessionSummary(started, ended, active, xp,
                    levels, skills,
                    readMilestones(object.get("milestones"))));
        }
        return result;
    }

    private static List<ProgressMilestone> readMilestones(JsonElement value)
    {
        List<ProgressMilestone> result = new ArrayList<>();
        var array = array(value);
        if (array == null) return result;
        for (JsonElement element : array)
        {
            var object = asObject(element);
            var id = string(object, "id");
            var type = string(object, "type");
            var title = string(object, "title");
            long at = object == null ? -1L
                    : naturalLong(object.get(get(1907)), -1L);
            if (id == null || type == null || title == null || at < 0L)
                continue;
            try
            {
                result.add(new ProgressMilestone(id,
                        ProgressMilestoneType.valueOf(type), title,
                        string(object, "detail"), string(object, "goalId"), at));
            }
            catch (IllegalArgumentException ignored)
            {
                // Removed/unknown milestone types do not become fake progress.
            }
        }
        return result;
    }

    private static JsonArray milestones(List<ProgressMilestone> values)
    {
        var result = new JsonArray();
        if (values == null) return result;
        for (ProgressMilestone value : values)
        {
            if (value == null) continue;
            var object = new JsonObject();
            object.addProperty("id", value.id);
            object.addProperty("type", value.getType().name());
            object.addProperty("title", value.title);
            addOptional(object, "detail", value.getDetail());
            addOptional(object, "goalId", value.getGoalId());
            object.addProperty(get(1907), value.getOccurredAtMillis());
            result.add(object);
        }
        return result;
    }

    private static List<ProgressTimeBucket> readBuckets(JsonElement value)
    {
        List<ProgressTimeBucket> result = new ArrayList<>();
        var array = array(value);
        if (array == null) return result;
        for (JsonElement element : array)
        {
            var object = asObject(element);
            long at = object == null ? -1L
                    : naturalLong(object.get("startedAtMillis"), -1L);
            Map<Skill, Integer> xp = object == null
                    ? new EnumMap<>(Skill.class)
                    : readSkills(object.get("xpBySkill"));
            if (at >= 0L && !xp.isEmpty())
                result.add(new ProgressTimeBucket(at, xp));
        }
        return result;
    }

    private static JsonObject skills(Map<Skill, Integer> values)
    {
        var result = new JsonObject();
        for (Map.Entry<Skill, Integer> entry : values.entrySet())
            if (!overall(entry.getKey()) && entry.getValue() != null
                    && entry.getValue() > 0)
                result.addProperty(entry.getKey().name(), entry.getValue());
        return result;
    }

    private static Map<Skill, Integer> readSkills(JsonElement value)
    {
        EnumMap<Skill, Integer> result = new EnumMap<>(Skill.class);
        var object = asObject(value);
        if (object == null) return result;
        for (Map.Entry<String, JsonElement> entry : object.entrySet())
        {
            var xp = integer(entry.getValue(), -1);
            if (xp <= 0 || xp > ProgressAnalyticsService.MAX_SKILL_XP)
                continue;
            try
            {
                var skill = Skill.valueOf(entry.getKey());
                if (!overall(skill)) result.put(skill, xp);
            }
            catch (IllegalArgumentException ignored)
            {
                // New/removed skills are ignored by older clients.
            }
        }
        return result;
    }

    private static void addOptional(JsonObject object, String key, String value)
    {
        if (value != null && !value.trim().isEmpty()) object.addProperty(key, value);
    }

    private static JsonObject object(Gson gson, String json)
    {
        try
        {
            return gson == null || json == null ? null
                    : gson.fromJson(json, JsonObject.class);
        }
        catch (RuntimeException ignored)
        {
            return null;
        }
    }

    private static JsonObject asObject(JsonElement value)
    {
        return value != null && value.isJsonObject()
                ? value.getAsJsonObject() : null;
    }

    private static JsonArray array(JsonElement value)
    {
        return value != null && value.isJsonArray()
                ? value.getAsJsonArray() : null;
    }

    private static String string(JsonObject object, String key)
    {
        try
        {
            var value = object == null ? null : object.get(key);
            return value != null && value.isJsonPrimitive()
                    && value.getAsJsonPrimitive().isString()
                    ? value.getAsString() : null;
        }
        catch (RuntimeException ignored)
        {
            return null;
        }
    }

    private static int integer(JsonElement value, int fallback)
    {
        try
        {
            return value != null && value.isJsonPrimitive()
                    && value.getAsJsonPrimitive().isNumber()
                    ? value.getAsInt() : fallback;
        }
        catch (RuntimeException ignored)
        {
            return fallback;
        }
    }

    private static long naturalLong(JsonElement value, long fallback)
    {
        try
        {
            if (value == null || !value.isJsonPrimitive()
                    || !value.getAsJsonPrimitive().isNumber()) return fallback;
            var result = value.getAsLong();
            return result < 0L ? fallback : result;
        }
        catch (RuntimeException ignored)
        {
            return fallback;
        }
    }

    private static boolean overall(Skill skill)
    {
        return skill != null && "OVERALL".equals(skill.name());
    }
}

package compass;
import static java.lang.Math.*;
import static compass.Text.get;

import java.awt.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.List;
import javax.swing.*;

/** Calm secondary progress view; DO NEXT remains outside this component. */
public final class ProgressViewPanel extends JPanel
{
    final JLabel sessionXp = new JLabel("0 XP");
    final JLabel sessionMeta = new JLabel(get(1158));
    final JTextArea target = textArea(get(1159));
    private final JTextArea leadingSkill = textArea("");
    final JTextArea planPath = textArea(get(1160));
    private final JTextArea milestones = textArea("");
    private final JPanel milestoneCard = card();
    final JTextArea lastSession = textArea("");
    private final JPanel lastSessionCard = card();
    final ProgressChartPanel chart = new ProgressChartPanel();

    public ProgressViewPanel()
    {
        this(1.0f);
    }

    public ProgressViewPanel(float textScale)
    {
        var scale = max(1.0f, min(1.6f, textScale));
        setLayout(new BorderLayout());
        setOpaque(true);
        setBackground(StrategistTheme.BACKGROUND);

        var content = new JPanel();
        content.setOpaque(false);
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
        content.add(heading("PROGRESS", 15f * scale));
        content.add(Box.createVerticalStrut(8));

        var summary = card();
        sessionXp.setForeground(StrategistTheme.GOLD);
        sessionXp.setFont(sessionXp.getFont().deriveFont(Font.BOLD, 17f * scale));
        sessionMeta.setForeground(StrategistTheme.MUTED_TEXT);
        sessionMeta.setFont(sessionMeta.getFont().deriveFont(13f * scale));
        summary.add(sessionXp);
        summary.add(Box.createVerticalStrut(4));
        summary.add(sessionMeta);
        content.add(summary);
        content.add(Box.createVerticalStrut(8));

        var current = card();
        current.add(heading("CURRENT TARGET", 12f * scale));
        current.add(Box.createVerticalStrut(5));
        target.setFont(target.getFont().deriveFont(14f * scale));
        current.add(target);
        current.add(Box.createVerticalStrut(5));
        leadingSkill.setFont(leadingSkill.getFont().deriveFont(13f * scale));
        leadingSkill.setForeground(StrategistTheme.MUTED_TEXT);
        current.add(leadingSkill);
        content.add(current);
        content.add(Box.createVerticalStrut(8));

        var plan = card();
        plan.add(heading("CURRENT PLAN", 12f * scale));
        plan.add(Box.createVerticalStrut(5));
        planPath.setFont(planPath.getFont().deriveFont(13f * scale));
        plan.add(planPath);
        content.add(plan);
        content.add(Box.createVerticalStrut(8));

        var chartCard = card();
        chartCard.add(heading("SESSION XP", 12f * scale));
        chartCard.add(Box.createVerticalStrut(5));
        chart.setAlignmentX(LEFT_ALIGNMENT);
        chart.setMaximumSize(new Dimension(Integer.MAX_VALUE, 112));
        chartCard.add(chart);
        content.add(chartCard);
        content.add(Box.createVerticalStrut(8));

        milestoneCard.add(heading("MILESTONES", 12f * scale));
        milestoneCard.add(Box.createVerticalStrut(5));
        milestones.setFont(milestones.getFont().deriveFont(13f * scale));
        milestoneCard.add(milestones);
        milestoneCard.setVisible(false);
        content.add(milestoneCard);

        content.add(Box.createVerticalStrut(8));
        lastSessionCard.add(heading("LAST SESSION", 12f * scale));
        lastSessionCard.add(Box.createVerticalStrut(5));
        lastSession.setFont(lastSession.getFont().deriveFont(13f * scale));
        lastSessionCard.add(lastSession);
        lastSessionCard.setVisible(false);
        content.add(lastSessionCard);
        add(content, BorderLayout.NORTH);
    }

    public void setSnapshot(ProgressSessionSnapshot snapshot)
    {
        if (snapshot == null)
        {
            sessionXp.setText("0 XP");
            sessionMeta.setText(get(1158));
            target.setText(get(1159));
            leadingSkill.setText("");
            chart.setBuckets(null);
            milestones.setText("");
            milestoneCard.setVisible(false);
            return;
        }
        sessionXp.setText(format(snapshot.getTotalXpGained()) + " XP");
        sessionMeta.setText(snapshot.getLevelsGained() + " levels • "
                + duration(snapshot.activeDurationMillis) + " active");
        chart.setBuckets(snapshot.getBuckets());
        updateTarget(snapshot.getTargetProjection());
        snapshot.getSkills().values().stream()
                .filter(value -> value.getXpGained() > 0)
                .max(Comparator.comparingInt(SkillSessionProgress::getXpGained))
                .ifPresentOrElse(value -> leadingSkill.setText(
                        value.getSkill().getName() + " +"
                                + format(value.getXpGained())),
                        () -> leadingSkill.setText(get(1161)));
        updateMilestones(snapshot.milestones);
    }

    public void setPlan(StrategicPlan plan)
    {
        if (plan == null)
        {
            planPath.setText(get(1160));
            return;
        }
        var text = new StringBuilder();
        text.append("NOW  ").append(plan.getCurrentStep().getObjective());
        if (plan.getNextStep() != null)
            text.append("\nNEXT  ").append(plan.getNextStep().getObjective());
        text.append("\nTARGET  ")
                .append(GoalRecommendationContext.displayName(plan.getGoal()));
        var steps = plan.getSteps().size();
        if (steps > 1)
            text.append("\nStep ").append(plan.getCurrentIndex() + 1)
                    .append(" of ").append(steps);
        planPath.setText(text.toString());
    }

    public void setHistory(ProgressHistory history)
    {
        List<ProgressSessionSummary> sessions = history == null
                ? java.util.Collections.emptyList() : history.getSessions();
        if (sessions.isEmpty())
        {
            lastSession.setText("");
            lastSessionCard.setVisible(false);
            return;
        }
        var summary = sessions.get(sessions.size() - 1);
        StringBuilder text = new StringBuilder()
                .append('+').append(format(summary.getTotalXpGained()))
                .append(" XP • ").append(summary.getLevelsGained())
                .append(" levels • ")
                .append(duration(summary.activeDurationMillis))
                .append(" active");
        summary.getXpBySkill().entrySet().stream()
                .max(java.util.Map.Entry.comparingByValue())
                .ifPresent(value -> text.append("\nTop: ")
                        .append(value.getKey().getName()).append(" +")
                        .append(format(value.getValue())));
        if (!summary.milestones.isEmpty())
        {
            var first = max(0, summary.milestones.size() - 2);
            text.append(get(1162));
            for (int index = first; index < summary.milestones.size(); index++)
            {
                if (index > first) text.append("; ");
                text.append(summary.milestones.get(index).title);
            }
        }
        lastSession.setText(text.toString());
        lastSessionCard.setVisible(true);
    }



    private void updateMilestones(List<ProgressMilestone> values)
    {
        if (values == null || values.isEmpty())
        {
            milestones.setText("");
            milestoneCard.setVisible(false);
            return;
        }
        var text = new StringBuilder();
        var first = max(0, values.size() - 3);
        for (int i = first; i < values.size(); i++)
        {
            if (text.length() > 0) text.append('\n');
            text.append("• ").append(values.get(i).title);
        }
        milestones.setText(text.toString());
        milestoneCard.setVisible(true);
    }

    private void updateTarget(TargetProjection projection)
    {
        if (projection == null
                || projection.getState() == TargetProjection.State.NO_TARGET)
        {
            target.setText(get(1159));
            return;
        }
        var value = projection.getTarget();
        String prefix = value.getSkill().getName() + " to "
                + value.targetLevel + "\n"
                + format(projection.getXpRemaining()) + " XP remaining";
        switch (projection.getState())
        {
            case COMPLETE:
                target.setText(value.getSkill().getName() + " "
                        + value.targetLevel + " complete");
                break;
            case READY:
                target.setText(prefix + " • " + duration(projection.getEtaMillis()));
                break;
            default:
                target.setText(prefix + get(1163));
                break;
        }
    }

    private static JPanel card()
    {
        var panel = new JPanel();
        panel.setOpaque(true);
        panel.setBackground(StrategistTheme.CARD);
        panel.setBorder(StrategistTheme.cardBorder());
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setAlignmentX(LEFT_ALIGNMENT);
        return panel;
    }

    private static JLabel heading(String text, float size)
    {
        var label = new JLabel(text);
        label.setForeground(StrategistTheme.GOLD_SOFT);
        label.setFont(label.getFont().deriveFont(Font.BOLD, size));
        label.setAlignmentX(LEFT_ALIGNMENT);
        return label;
    }

    private static JTextArea textArea(String text)
    {
        var area = new JTextArea(text);
        area.setEditable(false);
        area.setOpaque(false);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setForeground(StrategistTheme.TEXT);
        area.setBorder(null);
        area.setFocusable(false);
        area.setAlignmentX(LEFT_ALIGNMENT);
        return area;
    }

    private static String format(long value)
    {
        return NumberFormat.getIntegerInstance(Locale.UK).format(value);
    }

    private static String duration(long millis)
    {
        var minutes = max(0L, round(millis / 60_000.0));
        if (minutes < 60L) return minutes + " min";
        var hours = minutes / 60L;
        var remainder = minutes % 60L;
        return remainder == 0L ? hours + " hr"
                : hours + " hr " + remainder + " min";
    }
}

package compass;
import lombok.*;
import static net.runelite.api.Skill.*;
import static compass.Text.get;

import java.util.*;
import javax.inject.*;
import net.runelite.api.*;

/**
 * Conservative first-pass readiness for every boss identity RuneLite exposes.
 * Exact encounter modules can override these broad floors with better evidence.
 */
@Singleton
@RequiredArgsConstructor(access = AccessLevel.PUBLIC, onConstructor_ = @Inject)
public class PvmReadinessAnalyzer
{
    private final PvmActivityCatalog catalog;
    private final PvmEvidenceProfileCatalog evidenceProfiles;
    private final PvmPreparationProfileCatalog preparationProfiles;
    public PvmSnapshot analyze(
            AccountSnapshot account,
            QuestSnapshot quests,
            ItemsState equipment,
            ItemsState inventory,
            ItemsState bank,
            PvmSnapshot observed)
    {
        return analyze(account, quests, equipment, inventory, null, bank, observed);
    }

    public PvmSnapshot analyze(
            AccountSnapshot account,
            QuestSnapshot quests,
            ItemsState equipment,
            ItemsState inventory,
            StorageSnapshot storage,
            ItemsState bank,
            PvmSnapshot observed)
    {
        if (account == null) return observed;
        var mode = AccountMode.fromTypeCode(account.modeCode());
        Map<String, PvmReadiness> result = new HashMap<>();
        for (PvmActivity activity : catalog.all())
        {
            var prior = priorFor(observed, activity.id);
            if (prior != null
                    && prior.confidence == Confidence.BLOCKED)
            {
                result.put(activity.id, prior);
                continue;
            }
            List<String> missing = new ArrayList<>();
            PvmEvidenceProfile exact = evidenceProfiles == null ? null
                    : evidenceProfiles.forActivity(activity.id);
            PvmPreparationProfile preparation = preparationProfiles == null ? null
                    : preparationProfiles.forActivity(activity.id);
            if (preparation == null)
            {
                result.put(activity.id, new PvmReadiness(activity.id, false,
                        Confidence.CHECK_NEEDED,
                        Collections.singletonList(get(1565))));
                continue;
            }
            // Exact profiles are recomputed from current carried state so a
            // preparation -> ready transition cannot retain stale failures.
            if (exact == null && prior != null)
                missing.addAll(prior.missingRequirements);

            requireLevel(account, ATTACK, preparation.getAttack(), missing);
            requireLevel(account, STRENGTH, preparation.getStrength(), missing);
            requireLevel(account, DEFENCE, preparation.getDefence(), missing);
            requireLevel(account, RANGED, preparation.getRanged(), missing);
            requireLevel(account, MAGIC, preparation.getMagic(), missing);
            requireLevel(account, PRAYER, preparation.getPrayer(), missing);
            requireLevel(account, SLAYER, preparation.getSlayer(), missing);

            if (preparation.requiredQuest != null
                    && !questUsable(quests, preparation.requiredQuest,
                    preparation.isQuestMayBeInProgress()))
            {
                missing.add("Quest/access: " + preparation.requiredQuest);
            }

            String requiredStyle = exact == null ? preparation.getPreferredStyle()
                    : exact.getWeaponStyle();
            if (!hasCombatWeapon(equipment, requiredStyle))
                addMissing(missing, "Equip a usable " + preparation.getPreferredStyle() + get(1566));
            else if (exact == null)
                addMissing(missing, get(443));

            int requiredFood = exact == null ? (preparation.isRequiresSupplies() ? 5 : 0)
                    : exact.getMinimumFood();
            if (carriedFoodQuantity(inventory) < requiredFood)
                addMissing(missing, get(445));
            int requiredRestore = exact == null ? (preparation.getPrayer() >= 43 ? 1 : 0)
                    : exact.getMinimumRestoration();
            if (carriedRestorationQuantity(inventory) < requiredRestore)
                addMissing(missing, get(446));
            if (usesRanged(preparation.getPreferredStyle()))
                addMissing(missing, carriedAmmoQuantity(inventory, equipment) > 0
                        ? get(447)
                        : get(448));
            if (usesMagic(preparation.getPreferredStyle()))
                addMissing(missing, runeEvidence(inventory, storage)
                        ? get(449)
                        : get(450));

            if (exact == null)
                addMissing(missing, get(451));
            else
                for (String accessItem : exact.getAccessItems())
                    if (carriedQuantity(inventory, accessItem.toLowerCase(Locale.ROOT)) < 1)
                        addMissing(missing, "Carry " + accessItem + get(1567));

            if (exact == null && preparation != null)
                for (String check : preparation.getChecks()) addMissing(missing, check);

            if (mode == AccountMode.ULTIMATE_IRONMAN && preparation.isRequiresSupplies())
                addMissing(missing, get(452));

            var fullyVerified = exact != null && missing.isEmpty();
            result.put(activity.id, new PvmReadiness(
                    activity.id,
                    fullyVerified,
                    fullyVerified ? Confidence.VERIFIED
                            : Confidence.CHECK_NEEDED,
                    missing
            ));
        }
        return new PvmSnapshot(result);
    }


    private static PvmReadiness priorFor(PvmSnapshot observed, String activityId)
    {
        if (observed == null || activityId == null) return null;
        var prior = observed.readinessFor(activityId);
        if (prior != null) return prior;
        String shortId = activityId.startsWith("pvm:")
                ? activityId.substring("pvm:".length()) : activityId;
        return observed.readinessFor(shortId);
    }

    private static void requireLevel(AccountSnapshot account, Skill skill,
            int required, List<String> missing)
    {
        if (required > 1 && account.level(skill) < required)
            missing.add(skill.getName() + " " + required);
    }

    private static boolean questUsable(QuestSnapshot quests, String quest,
            boolean inProgressAllowed)
    {
        if (quests == null || quest == null) return false;
        for (Map.Entry<String, QuestStatus> entry : quests.quests().entrySet())
        {
            if (!entry.getKey().equalsIgnoreCase(quest)) continue;
            if (entry.getValue() == QuestStatus.COMPLETE) return true;
            return inProgressAllowed && entry.getValue() == QuestStatus.IN_PROGRESS;
        }
        return false;
    }

    private static boolean hasCombatWeapon(ItemsState equipment, String style)
    {
        List<ItemState> items = new ArrayList<>();
        if (equipment != null) items.addAll(equipment.getEquippedItems());
        boolean melee = false, ranged = false, magic = false;
        for (ItemState item : items)
        {
            // Persisted snapshots without slot provenance cannot prove a readied weapon.
            if (item.slotIndex != EquipmentInventorySlot.WEAPON.getSlotIdx()) continue;
            var name = item.getName() == null ? "" : item.getName().toLowerCase(Locale.ROOT);
            melee |= containsAny(name, "scimitar", "sword", "whip", "mace", "axe",
                    "halberd", "spear", "hasta", "fang", "scythe", "maul", "bludgeon", "lance");
            ranged |= containsAny(name, "bow", "crossbow", "blowpipe", "ballista", "atlatl");
            magic |= containsAny(name, "staff", "wand", "trident", "sceptre", "scepter", "shadow");
        }
        if ("melee".equals(style)) return melee;
        if ("ranged".equals(style)) return ranged;
        if ("magic".equals(style)) return magic;
        if ("ranged or magic".equals(style)) return ranged || magic;
        if ("hybrid".equals(style)) return (melee && ranged) || (ranged && magic) || (melee && magic);
        return melee || ranged || magic;
    }

    private static int carriedFoodQuantity(ItemsState inventory)
    {
        return carriedQuantity(inventory, "shark", "karambwan", "anglerfish",
                "manta ray", get(1568), "lobster", "swordfish", "pizza");
    }

    private static int carriedRestorationQuantity(ItemsState inventory)
    {
        return carriedQuantity(inventory, "prayer potion", "super restore");
    }

    private static int carriedAmmoQuantity(ItemsState inventory,
            ItemsState equipment)
    {
        int quantity = carriedQuantity(inventory, "arrow", "bolt", "dart",
                "javelin", "chinchompa");
        if (equipment != null)
            for (ItemState item : equipment.getEquippedItems())
                if (item.slotIndex == EquipmentInventorySlot.AMMO.getSlotIdx()
                        && containsAny(item.getName() == null ? ""
                        : item.getName().toLowerCase(Locale.ROOT),
                        "arrow", "bolt", "dart", "javelin"))
                    quantity += item.quantity;
        return quantity;
    }

    private static int carriedRuneQuantity(ItemsState inventory)
    {
        return carriedQuantity(inventory, " rune");
    }

    private static boolean runeEvidence(ItemsState inventory,
            StorageSnapshot storage)
    {
        if (carriedRuneQuantity(inventory) > 0) return true;
        return storage != null
                && storage.verified(StorageKind.RUNE_POUCH)
                && storage.hasObservedContents(StorageKind.RUNE_POUCH)
                && !storage.contentsOf(StorageKind.RUNE_POUCH).isEmpty();
    }

    private static void addMissing(List<String> missing, String requirement)
    {
        if (requirement != null && !requirement.trim().isEmpty()
                && !missing.contains(requirement)) missing.add(requirement);
    }

    private static int carriedQuantity(ItemsState inventory, String... terms)
    {
        if (inventory == null) return 0;
        var total = 0;
        for (ItemState item : inventory.getItems())
        {
            var name = item.getName() == null ? "" : item.getName().toLowerCase(Locale.ROOT);
            if (containsAny(name, terms)) total += Math.max(0, item.quantity);
        }
        return total;
    }

    private static boolean usesRanged(String style)
    {
        return style != null && (style.contains("ranged") || "hybrid".equals(style));
    }

    private static boolean usesMagic(String style)
    {
        return style != null && (style.contains("magic") || "hybrid".equals(style));
    }

    private static boolean containsAny(String value, String... terms)
    {
        for (String term : terms) if (value.contains(term)) return true;
        return false;
    }

}

