package compass;
import static java.lang.Math.*;
import lombok.*;


/**
 * One ranked action the player could take next.
 *
 * <p>Current/target levels are structured fields instead of being buried in a
 * paragraph. That lets the sidebar stay compact while Details can still expose
 * the full reasoning.</p>
 */
@Getter
public final class Recommendation
{
    final String id;
    final String title;
    final String reason;
    final double score;
    final TrainingPlan trainingPlan;
    final Confidence confidence;
    final int currentLevel;
    final int targetLevel;
    final Guidance guidance;
    final Safety safetyEvidence;
    final GoalProvenance goalProvenance;
    final StrategicValue strategicValue;

    TrainingPlan plan() { return trainingPlan; }

    public Recommendation(String id, String title, String reason, double score,
            Confidence confidence, Guidance guidance,
            Safety safetyEvidence)
    {
        this(id, title, reason, score, confidence, guidance, safetyEvidence,
                StrategicValue.neutral());
    }

    public Recommendation(String id, String title, String reason, double score,
            Confidence confidence, Guidance guidance,
            Safety safetyEvidence,
            StrategicValue strategicValue)
    {
        this(id, title, reason, score, null, confidence, 0, 0, guidance,
                safetyEvidence, null, strategicValue);
    }

    public Recommendation(
            String id, String title, String reason, double score,
            TrainingPlan trainingPlan, Confidence confidence,
            int currentLevel, int targetLevel, Guidance guidance,
            Safety safetyEvidence)
    {
        this(id, title, reason, score, trainingPlan, confidence, currentLevel,
                targetLevel, guidance, safetyEvidence, null,
                StrategicValue.neutral());
    }

    public Recommendation(String id, String title, String reason, double score,
            TrainingPlan trainingPlan, Confidence confidence,
            int currentLevel, int targetLevel, Guidance guidance)
    {
        this(id, title, reason, score, trainingPlan, confidence, currentLevel,
                targetLevel, guidance, Safety.unknown());
    }

    private Recommendation(
            String id, String title, String reason, double score,
            TrainingPlan trainingPlan, Confidence confidence,
            int currentLevel, int targetLevel, Guidance guidance,
            Safety safetyEvidence,
            GoalProvenance goalProvenance,
            StrategicValue strategicValue)
    {
        this.id = id;
        this.title = title;
        this.reason = reason;
        this.score = score;
        this.trainingPlan = trainingPlan;
        this.confidence = confidence == null
                ? Confidence.CHECK_NEEDED
                : confidence;
        this.currentLevel = max(0, currentLevel);
        this.targetLevel = max(0, targetLevel);
        this.guidance = guidance;
        this.safetyEvidence = safetyEvidence == null
                ? Safety.unknown() : safetyEvidence;
        this.goalProvenance = goalProvenance;
        this.strategicValue = strategicValue == null
                ? StrategicValue.neutral() : strategicValue;
    }


    /** Active execution boundary; the distant strategic objective stays targetLevel. */
    public int getCurrentExecutionTargetLevel()
    {
        int stage = trainingPlan == null
                ? 0 : trainingPlan.getCurrentStageTargetLevel();
        return stage > 0 ? stage : targetLevel;
    }

    public Recommendation withGoalProvenance(GoalProvenance provenance)
    {
        return new Recommendation(id, title, reason, score, trainingPlan,
                confidence, currentLevel, targetLevel, guidance, safetyEvidence,
                provenance, strategicValue);
    }

    public Recommendation withStrategicValue(
            StrategicValue value)
    {
        return new Recommendation(id, title, reason, score, trainingPlan,
                confidence, currentLevel, targetLevel, guidance, safetyEvidence,
                goalProvenance, value);
    }

    public Recommendation withGuidance(Guidance value)
    {
        return new Recommendation(id, title, reason, score, trainingPlan,
                confidence, currentLevel, targetLevel, value, safetyEvidence,
                goalProvenance, strategicValue);
    }

    public Recommendation withSafetyEvidence(Safety value)
    {
        return new Recommendation(id, title, reason, score, trainingPlan,
                confidence, currentLevel, targetLevel, guidance, value,
                goalProvenance, strategicValue);
    }

}

package compass;

import static compass.Text.get;

import java.util.*;
import java.util.regex.*;

/** Stable semantic collapse for equivalent actions emitted by several domains. */
public final class RecommendationDeduplicator
{
    private static final Pattern TRAIN_TO = Pattern.compile(
            get(1898));

    public List<Recommendation> deduplicate(List<Recommendation> candidates)
    {
        Map<String, Recommendation> merged = new LinkedHashMap<>();
        if (candidates == null) return new ArrayList<>();
        for (Recommendation candidate : candidates)
        {
            if (candidate == null) continue;
            // Do not allow weaker evidence to borrow VERIFIED status from an
            // equivalent-looking action emitted by another provider.
            var key = semanticKey(candidate) + "|" + candidate.confidence;
            var previous = merged.get(key);
            merged.put(key, previous == null ? candidate : merge(previous, candidate));
        }
        return new ArrayList<>(merged.values());
    }

    String semanticKey(Recommendation candidate)
    {
        if (candidate == null) return "";
        var plan = candidate.plan();
        var activity = canonicalActivity(candidate, plan);
        if (activity != null) return "activity:" + activity;
        if (plan != null && plan.method() != null
                && candidate.targetLevel > 0)
            return "skill-level:" + Names.words(plan.method().getSkill().getName())
                    + ":" + candidate.targetLevel;

        var training = TRAIN_TO.matcher(safe(candidate.title).trim());
        if (training.matches())
            return "skill-level:" + Names.words(training.group(1))
                    + ":" + training.group(2);

        var id = safe(candidate.id).toLowerCase(Locale.ROOT);
        if (id.startsWith("quest:") || id.startsWith("diary:")
                || id.startsWith("clue:") || id.startsWith("stash:")
                || id.startsWith("gear:") || id.startsWith("upgrade:")
                || id.startsWith("pvm:") || id.startsWith("slayer:"))
            return family(id) + ":" + Names.words(candidate.title);
        return Names.words(candidate.title);
    }

    private static Recommendation merge(Recommendation first,
            Recommendation second)
    {
        var primary = better(first, second);
        var other = primary == first ? second : first;
        var reason = mergeText(primary.reason, other.reason);
        double sharedBenefitBonus = sameText(first.reason, second.reason)
                ? 0.0 : 3.0;
        return new Recommendation(primary.id, primary.title, reason,
                Math.max(first.score, second.score) + sharedBenefitBonus,
                primary.plan(), primary.confidence,
                primary.currentLevel, primary.targetLevel,
                primary.guidance, primary.safetyEvidence)
                .withStrategicValue(first.strategicValue.merge(
                        second.strategicValue));
    }

    private static String canonicalActivity(Recommendation candidate,
            TrainingPlan plan)
    {
        var id = safe(candidate.id).toLowerCase(Locale.ROOT);
        if (id.startsWith("minigame:")) return id.substring("minigame:".length());
        if (plan == null || plan.method() == null) return null;
        var method = safe(plan.method().id).toLowerCase(Locale.ROOT);
        switch (method)
        {
            case "firemaking_wintertodt": return "wintertodt";
            case "fishing_tempoross": return "tempoross";
            case "runecraft_gotr": return get(1899);
            case "smithing_giants_foundry": return "giants-foundry";
            case "construction_mahogany_homes": return "mahogany-homes";
            case "farming_tithe": return "tithe-farm";
            case "mining_mlm": return "motherlode-mine";
            case "mining_volcanic": return "volcanic-mine";
            case "mining_blast_mine": return "blast-mine";
            case "thieving_pyramid": return "pyramid-plunder";
            case "fishing_aerial": return "aerial-fishing";
            case "fishing_drift_net": return get(1900);
            case "thieving_artefacts": return get(1901);
            case "woodcutting_forestry": return "forestry";
            case "mining_stars": return "shooting-stars";
            case "smithing_blast_furnace_gold":
            case "smithing_blast_furnace_bars": return "blast-furnace";
            default: return null;
        }
    }

    private static Recommendation better(Recommendation first,
            Recommendation second)
    {
        if (second.score > first.score) return second;
        if (second.score < first.score) return first;
        return safe(second.id).compareTo(safe(first.id)) < 0
                ? second : first;
    }

    private static String mergeText(String first, String second)
    {
        var left = safe(first).trim();
        var right = safe(second).trim();
        if (right.isEmpty() || sameText(left, right)) return left;
        if (left.isEmpty()) return right;
        return left + get(1902) + right;
    }

    private static boolean sameText(String first, String second)
    {
        return Names.words(first).equals(Names.words(second));
    }

    private static String family(String id)
    {
        var colon = id.indexOf(':');
        return colon < 0 ? id : id.substring(0, colon);
    }


    private static String safe(String value)
    {
        return value == null ? "" : value;
    }
}

package compass;

import static compass.Text.get;

import java.util.*;

/**
 * Separates unresolved knowledge from ordinary preparation work.
 *
 * <p>A recommendation may still be actionable when Compass knows the route
 * but the player needs to obtain consumables or ordinary tools first. That is
 * different from not knowing whether a quest, area, spellbook, activity, or
 * irreversible build requirement is unlocked.</p>
 */
public final class RequirementActionability
{
    private RequirementActionability()
    {
    }

    public static boolean isActionablePreparation(
            TrainingPlan plan,
            Guidance guidance)
    {
        if (plan == null || plan.method() == null
                || guidance == null || !hasText(guidance.getAction()))
        {
            return false;
        }

        var checks = plan.requirementChecks;
        if (checks == null || checks.isEmpty()) return true;

        var hasPreparation = false;
        for (EvidenceCheck check : checks)
        {
            if (check == null) return false;
            if (check.getState() == RequirementState.BLOCKED) return false;
            if (check.getState() == RequirementState.VERIFIED) continue;
            if (!isPreparationRequirement(check)) return false;
            hasPreparation = true;
        }

        // If preparation is outstanding, the recommendation must actually tell
        // the player what supplies/setup to prepare instead of hiding the gap.
        return !hasPreparation || hasText(guidance.supplies);
    }

    public static boolean hasHardUnresolvedRequirement(TrainingPlan plan)
    {
        if (plan == null || plan.requirementChecks == null) return false;
        for (EvidenceCheck check : plan.requirementChecks)
        {
            if (check == null) return true;
            if (check.getState() == RequirementState.BLOCKED) return true;
            if (check.getState() == RequirementState.CHECK_NEEDED
                    && !isPreparationRequirement(check))
            {
                return true;
            }
        }
        return false;
    }

    public static boolean isPreparationRequirement(EvidenceCheck check)
    {
        if (check == null || check.getState() != RequirementState.CHECK_NEEDED)
        {
            return false;
        }

        var id = Names.lower(check.id);
        var label = Names.lower(check.getLabel());

        // Domain evaluators reserve preparation:* for a fully understood,
        // reversible setup such as fitting specified boat parts. Unknown area,
        // quest, risk, and live-assignment gates retain their typed IDs.
        if (id.startsWith("preparation:"))
        {
            var evidence = Names.lower(check.evidence);
            return !evidence.contains("unknown")
                    && !evidence.contains(get(1202))
                    && !evidence.contains(get(1203));
        }

        // ItemIndex uses typed resource:* checks. A known tool
        // or material shortfall is ordinary preparation, not uncertainty about
        // whether a quest, region, spellbook, or activity is available.
        if (id.startsWith("resource:"))
        {
            var evidence = Names.lower(check.evidence);
            // Retrieval-only UIM storage is not ordinary shopping/banking
            // preparation. The route must first model its extra access or
            // death-risk setup explicitly.
            return !evidence.contains(get(1204))
                    && !evidence.contains(get(1805));
        }
        if (!id.startsWith("generic:")) return false;

        // A combined label such as get(1806) is an
        // access check, not ordinary shopping/banking preparation. Check hard
        // gates first so one supply word cannot accidentally make an unknown
        // quest, area, activity, room, assignment, or risk gate actionable.
        if (containsAny(label,
                "access", "unlock", "quest", "completion", "completed",
                "route", "contract", "spellbook", "activity", "minigame",
                "region", "guild", "poh", "room", "course", "team",
                "patch", "reachable",
                "role", "assignment", "task", "location", "habitat",
                "target", "risk accepted"))
        {
            return false;
        }

        // These words describe resources or ordinary setup that can be acquired
        // as part of the recommendation. Access/unlock requirements deliberately
        // do not appear in this list and therefore stay hard CHECK_NEEDED gates.
        return containsAny(label,
                "supply", "supplies", "food", "healing", "rune", "runes",
                "ammo", "ammunition", "arrow", "bolt", "dart", "cannonball",
                "chinchompa", "bone", "bones", "head", "heads",
                "essence", "talisman", "tiara", get(1807),
                "ore", "bars", "metal", "log", "logs", "plank",
                "planks", "herb", "herbs", "secondary", "secondaries",
                "seed", "seeds", "compost", "payment", "payments",
                "potion", "potions", "grape", "grapes", "jug",
                "dynamite", get(1205), "warm clothing",
                "knife", "hammer", "saw", "chisel", "rope", "bucket",
                "pickaxe", "hatchet", "axe", "harpoon", "fishing rod",
                "fly fishing rod", "net", "lobster pot", "cage", "snare",
                "talisman", "tiara",
                "teleport setup", "teleports", "stamina", "repair supplies");
    }

    private static boolean containsAny(String value, String... needles)
    {
        for (String needle : needles)
        {
            if (value.contains(needle)) return true;
        }
        return false;
    }

    private static boolean hasText(String value)
    {
        return value != null && !value.trim().isEmpty();
    }

}

