package compass;
import lombok.*;

import java.awt.image.BufferedImage;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.*;
import javax.swing.*;
import net.runelite.api.Skill;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.util.ImageUtil;

/**
 * Loads RuneScape's own skill sprites through RuneLite instead of bundling
 * replacement artwork. This keeps Compass visually native and means new
 * RuneLite sprite updates can flow through without us maintaining image files.
 *
 * <p>Scaled icons are cached so routine account refreshes do not briefly clear
 * and reload the same sprite. A per-label request key also prevents an older
 * asynchronous sprite callback from replacing a newer recommendation icon.</p>
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SkillIconLoader
{
    private final SpriteManager spriteManager;
    private final Map<String, ImageIcon> iconCache = new ConcurrentHashMap<>();
    private final Map<JLabel, String> latestRequest =
            Collections.synchronizedMap(new WeakHashMap<>());

    public void load(Skill skill, JLabel target, int size)
    {
        if (skill == null || target == null)
        {
            return;
        }

        HiscoreSkill hiscoreSkill;
        try
        {
            hiscoreSkill = HiscoreSkill.valueOf(skill.name());
        }
        catch (IllegalArgumentException ex)
        {
            return;
        }

        var requestKey = skill.name() + ':' + size;
        latestRequest.put(target, requestKey);

        var cached = iconCache.get(requestKey);
        if (cached != null)
        {
            applyIcon(target, requestKey, cached);
            return;
        }

        spriteManager.getSpriteAsync(
                hiscoreSkill.getSpriteId(),
                0,
                sprite -> cacheAndApply(target, requestKey, sprite, size)
        );
    }

    /**
     * Clear a label and invalidate every callback issued for its old icon.
     * This matters when a skill recommendation is replaced by a quest or
     * upgrade before RuneLite finishes loading the skill sprite.
     */
    public void clear(JLabel target)
    {
        if (target == null) return;
        var requestKey = "clear:" + System.nanoTime();
        latestRequest.put(target, requestKey);
        Runnable clear = () ->
        {
            synchronized (latestRequest)
            {
                if (!requestKey.equals(latestRequest.get(target))) return;
            }
            target.setIcon(null);
            target.revalidate();
            target.repaint();
        };
        if (SwingUtilities.isEventDispatchThread()) clear.run();
        else SwingUtilities.invokeLater(clear);
    }

    void cacheAndApply(
            JLabel target,
            String requestKey,
            BufferedImage sprite,
            int size)
    {
        if (sprite == null)
        {
            return;
        }

        BufferedImage scaled = ImageUtil.resizeImage(
                ImageUtil.resizeCanvas(sprite, 25, 25),
                size,
                size
        );
        var icon = new ImageIcon(scaled);
        iconCache.put(requestKey, icon);
        applyIcon(target, requestKey, icon);
    }

    private void applyIcon(JLabel target, String requestKey, ImageIcon icon)
    {
        Runnable apply = () ->
        {
            synchronized (latestRequest)
            {
                if (!requestKey.equals(latestRequest.get(target)))
                {
                    return;
                }
            }

            target.setIcon(icon);
            target.revalidate();
            target.repaint();
        };

        if (SwingUtilities.isEventDispatchThread())
        {
            apply.run();
        }
        else
        {
            SwingUtilities.invokeLater(apply);
        }
    }
}

package compass;
import static net.runelite.api.Skill.*;
import static compass.Text.get;

import java.util.*;
import javax.inject.Singleton;
import net.runelite.api.Skill;

/** Chooses a useful permanent Slayer reward without consuming the skip reserve. */
@Singleton
public class SlayerRewardAdvisor
{
    private static final int SKIP_RESERVE = SlayerPointEconomy.SKIP_COST;

    public SlayerRewardAdvice recommend(StrategyContext context,
            SlayerSnapshot slayer)
    {
        if (context == null || slayer == null || slayer.getRewards() == null)
            return null;
        List<SlayerRewardAdvice> candidates = new ArrayList<>();
        var account = context.data().account();
        var slayerLevel = account.level(SLAYER);
        var crafting = account.level(CRAFTING);
        var fletching = account.level(FLETCHING);

        add(candidates, slayer, SlayerReward.BIGGER_AND_BADDER,
                slayerLevel >= 5, 100.0,
                get(792));
        add(candidates, slayer, SlayerReward.MALEVOLENT_MASQUERADE,
                crafting >= 55, context.accountMode().isIronLike() ? 82.0 : 74.0,
                get(797));
        add(candidates, slayer, SlayerReward.BROADER_FLETCHING,
                context.accountMode().isIronLike() && fletching >= 52,
                78.0,
                get(798));
        add(candidates, slayer, SlayerReward.RING_BLING,
                crafting >= 75 && context.accountMode().isIronLike(),
                context.accountMode() == AccountMode.ULTIMATE_IRONMAN
                        ? 76.0 : 68.0,
                get(799));
        add(candidates, slayer, SlayerReward.TASK_STORAGE,
                context.accountMode() == AccountMode.ULTIMATE_IRONMAN
                        || context.intent() == SessionIntent.QUICK_20_MIN,
                context.accountMode() == AccountMode.ULTIMATE_IRONMAN
                        ? 72.0 : 62.0,
                get(800));
        add(candidates, slayer, SlayerReward.HOT_STUFF,
                context.goal() == GoalType.FIRE_CAPE
                        || context.goal() == GoalType.INFERNAL_CAPE,
                70.0,
                get(801));
        add(candidates, slayer, SlayerReward.LIKE_A_BOSS,
                context.goal() == GoalType.ELITE_COMBAT_ACHIEVEMENTS
                        || context.goal() == GoalType.GEAR_TARGET,
                66.0,
                get(802));

        boolean longXpSession = context.intent()
                == SessionIntent.LONG_SESSION
                && (context.goal() == GoalType.SLAYER_85
                    || context.goal() == GoalType.MAX);
        add(candidates, slayer, SlayerReward.EXTEND_DUST_DEVILS,
                longXpSession && slayerLevel >= 65, 64.0,
                get(803));
        add(candidates, slayer, SlayerReward.EXTEND_NECHRYAELS,
                longXpSession && slayerLevel >= 80, 65.0,
                get(804));
        add(candidates, slayer, SlayerReward.EXTEND_ABYSSAL_DEMONS,
                longXpSession && slayerLevel >= 85, 61.0,
                get(793));
        add(candidates, slayer, SlayerReward.EXTEND_BLOODVELDS,
                context.accountMode().isIronLike()
                        && context.intent() != SessionIntent.QUICK_20_MIN
                        && slayerLevel >= 50,
                58.0,
                get(794));
        add(candidates, slayer, SlayerReward.EXTEND_GARGOYLES,
                context.accountMode().isIronLike()
                        && context.intent() != SessionIntent.QUICK_20_MIN
                        && slayerLevel >= 75,
                57.0,
                get(795));
        add(candidates, slayer, SlayerReward.EXTEND_KRAKEN,
                slayerLevel >= 87
                        && (context.goal() == GoalType.GEAR_TARGET
                            || context.mode() == StrategyMode.RELAXED),
                56.0,
                get(796));

        return candidates.stream().max(Comparator.comparingDouble(
                SlayerRewardAdvice::getScore)).orElse(null);
    }

    private static void add(List<SlayerRewardAdvice> candidates,
            SlayerSnapshot slayer, SlayerReward reward, boolean eligible,
            double score, String reason)
    {
        if (!eligible
                || slayer.getRewards().stateOf(reward) != Capability.BLOCKED
                || slayer.getPoints() < reward.getPointCost() + SKIP_RESERVE)
            return;
        candidates.add(new SlayerRewardAdvice(reward, score, reason));
    }
}

package compass;
import lombok.*;
import static java.lang.Math.*;

import java.util.*;


/** Current Slayer task and point-economy evidence observed from RuneLite. */
@Getter
public final class SlayerSnapshot
{
    final String taskName;
    final int remaining;
    final String masterName;
    final String taskLocation;
    final int points;
    final Integer taskStreak;
    final Integer questPoints;
    final Integer blockSlotCapacity;
    final Integer occupiedBlockSlots;
    final SlayerRewardSnapshot rewards;
    final List<SlayerTaskOffer> taskOffers;
    @Getter(AccessLevel.NONE)
    final Boolean mortimerIntroduced;
    final Confidence confidence;

    public SlayerSnapshot(
            String taskName,
            int remaining,
            String masterName,
            String taskLocation,
            int points,
            Integer taskStreak,
            Integer questPoints,
            Integer blockSlotCapacity,
            Integer occupiedBlockSlots,
            SlayerRewardSnapshot rewards,
            List<SlayerTaskOffer> taskOffers,
            Boolean mortimerIntroduced,
            Confidence confidence)
    {
        this.taskName = taskName;
        this.remaining = max(0, remaining);
        this.masterName = masterName;
        this.taskLocation = taskLocation;
        this.points = max(0, points);
        this.taskStreak = nonNegative(taskStreak);
        this.questPoints = nonNegative(questPoints);
        this.blockSlotCapacity = nonNegative(blockSlotCapacity);
        this.occupiedBlockSlots = nonNegative(occupiedBlockSlots);
        this.rewards = rewards == null ? SlayerRewardSnapshot.unknown() : rewards;
        this.taskOffers = Collections.unmodifiableList(taskOffers == null
                ? new ArrayList<>() : new ArrayList<>(taskOffers));
        this.mortimerIntroduced = mortimerIntroduced;
        this.confidence = confidence == null
                ? Confidence.CHECK_NEEDED
                : confidence;
    }

    public static SlayerSnapshot unknown()
    {
        return new SlayerSnapshot(
                null,
                0,
                null,
                null,
                0,
                null,
                null,
                null,
                null,
                null,
                null,
                null,
                Confidence.CHECK_NEEDED
        );
    }

    public Boolean isMortimerIntroduced() { return mortimerIntroduced; }

    public boolean hasTask()
    {
        return taskName != null && !taskName.trim().isEmpty() && remaining > 0;
    }

    public SlayerState getAssignmentState()
    {
        if (hasTask()) return SlayerState.ASSIGNED;
        if (!taskOffers.isEmpty()) return SlayerState.CHOICE_PENDING;
        if (confidence == Confidence.VERIFIED && remaining == 0)
            return SlayerState.NO_TASK;
        return SlayerState.UNKNOWN;
    }

    /** True only when both capacity and current per-master usage are known. */
    public boolean hasKnownFreeBlockSlot()
    {
        return blockSlotCapacity != null && occupiedBlockSlots != null
                && occupiedBlockSlots < blockSlotCapacity;
    }

    static Integer nonNegative(Integer value)
    {
        return value == null ? null : max(0, value);
    }
}

package compass;
import static net.runelite.api.Skill.*;
import static java.lang.Math.*;
import static compass.Text.get;

import java.util.*;
import javax.inject.*;
import net.runelite.api.*;

/**
 * Property-driven Slayer master and current-task decisions.
 *
 * <p>The service never assigns a task verdict merely because of its ID. IDs
 * select reviewed metadata; XP value, resource value, burden, attention, risk,
 * point economy, readiness and live intent determine the decision.</p>
 */
@Singleton
public class SlayerStrategist
{
    private final SlayerMasterCatalog masters;
    private final SlayerTaskProfileCatalog mechanics;
    private final SlayerTaskStrategicCatalog strategy;
    private final SlayerRewardAdvisor rewardAdvisor;

    @Inject
    public SlayerStrategist(SlayerMasterCatalog masters,
            SlayerTaskProfileCatalog mechanics,
            SlayerTaskStrategicCatalog strategy,
            SlayerRewardAdvisor rewardAdvisor)
    {
        this.masters = masters == null ? new SlayerMasterCatalog() : masters;
        this.mechanics = mechanics == null
                ? new SlayerTaskProfileCatalog() : mechanics;
        this.strategy = strategy == null
                ? new SlayerTaskStrategicCatalog(this.mechanics) : strategy;
        this.rewardAdvisor = rewardAdvisor == null
                ? new SlayerRewardAdvisor() : rewardAdvisor;
    }

    public SlayerStrategist()
    {
        this(new SlayerMasterCatalog(), new SlayerTaskProfileCatalog(),
                null, null);
    }

    public SlayerDecisionResult assess(StrategyContext context)
    {
        if (context == null || context.data() == null
                || context.data().account() == null) return null;
        var account = context.data().account();
        if (account.membership() != Membership.P2P
                || !AccountBuildPolicy.allowsSkill(account, SLAYER))
            return null;

        var slayer = context.data().slayer();
        if (slayer == null
                || slayer.getAssignmentState() == SlayerState.UNKNOWN)
            return unknownAssignment();
        if (slayer.getAssignmentState() == SlayerState.CHOICE_PENDING)
            return chooseMortimerOffer(context, slayer);
        if (slayer.getAssignmentState() == SlayerState.NO_TASK)
            return chooseMaster(context, slayer);
        return evaluateTask(context, slayer);
    }

    private SlayerDecisionResult chooseMortimerOffer(StrategyContext context,
            SlayerSnapshot slayer)
    {
        var master = masters.byId("mortimer");
        for (SlayerTaskOffer offer : slayer.getTaskOffers())
        {
            if (offer.taskName == null || offer.getModifierName() == null
                    || strategy.profileFor(offer.taskName) == null)
                return unresolvedMortimerChoice(master);
        }
        SlayerTaskOffer choice = slayer.getTaskOffers().stream()
                .max(Comparator.comparingDouble(o -> offerValue(o, context)))
                .orElse(null);
        if (choice == null) return unresolvedMortimerChoice(master);
        SlayerStrategy profile = strategy.profileFor(
                choice.taskName);
        var value = offerValue(choice, context);
        var modifier = describeModifier(choice);
        String reason = get(815)
                + get(826);
        Guidance guidance = new Guidance(
                "Select " + choice.taskName + " with " + modifier
                        + get(837),
                get(848),
                get(859),
                reason);
        return new SlayerDecisionResult(SlayerState.CHOICE_PENDING,
                null, master, profile, 62.0 + value,
                Confidence.VERIFIED, reason, guidance, null,
                null, choice);
    }

    private SlayerDecisionResult unresolvedMortimerChoice(
            SlayerMasterProfile master)
    {
        var reason = get(870);
        return new SlayerDecisionResult(SlayerState.CHOICE_PENDING,
                SlayerDecision.PREP_FIRST, master, null, 34.0,
                Confidence.CHECK_NEEDED, reason,
                new Guidance(
                        get(881),
                        get(889),
                        get(890),
                        reason), null, null, null);
    }

    private double offerValue(SlayerTaskOffer offer, StrategyContext context)
    {
        SlayerStrategy profile = strategy.profileFor(
                offer.taskName);
        if (profile == null) return -1000.0;
        var value = taskValue(profile, context);
        var modifier = Names.lower(offer.getModifierName());
        double magnitude = min(3.0, max(.5,
                offer.getModifierValue() / 10.0));
        var direction = offer.isNegativeModifier() ? -1.0 : 1.0;
        if (modifier.contains("xp"))
        {
            double fit = context.mode() == StrategyMode.EFFICIENT
                    || context.goal() == GoalType.SLAYER_85
                    ? 3.0 : 1.8;
            value += direction * magnitude * fit;
        }
        else if (modifier.contains("superior"))
            value += direction * magnitude
                    * (context.accountMode().isIronLike() ? 3.2 : 2.3);
        else if (modifier.contains("point"))
            value += direction * magnitude
                    * (slayerPoints(context) < 150 ? 3.0 : 1.6);
        else if (modifier.contains("clue"))
            value += direction * magnitude
                    * (context.accountMode().isIronLike() ? 2.4 : 1.2);
        else if (modifier.contains("quant"))
        {
            double taskFit = profile.xpQuality + profile.getResourceValue()
                    - profile.completionBurden;
            double sessionFit = context.intent() == SessionIntent.LONG_SESSION
                    ? 1.0 : context.intent() == SessionIntent.QUICK_20_MIN
                            ? -1.0 : 0.0;
            value += direction * magnitude * (taskFit + sessionFit) * .7;
        }
        return value;
    }

    private static int slayerPoints(StrategyContext context)
    {
        var slayer = context.data().slayer();
        return slayer == null ? 0 : slayer.getPoints();
    }

    private static String describeModifier(SlayerTaskOffer offer)
    {
        var prefix = offer.isNegativeModifier() ? "the reduced " : "the ";
        return prefix + offer.getModifierName()
                + (offer.getModifierValue() > 0
                        ? " modifier (" + offer.getModifierValue() + ")"
                        : " modifier");
    }

    private SlayerDecisionResult chooseMaster(StrategyContext context,
            SlayerSnapshot slayer)
    {
        var rewardAdvice = rewardAdvisor.recommend(context, slayer);
        if (rewardAdvice != null) return rewardPurchase(rewardAdvice, slayer);

        var eligible = masters.eligible(context);
        SlayerMasterProfile choice = eligible.stream()
                .max(Comparator.comparingDouble(p -> masterScore(p, context, slayer)))
                .orElse(null);
        if (choice == null) return unknownAssignment();

        var score = masterScore(choice, context, slayer);
        int next = slayer.getTaskStreak() == null
                ? -1 : slayer.getTaskStreak() + 1;
        String milestone = next > 0 && SlayerPointEconomy.isBonusCompletion(next)
                ? " This is task " + next + get(816)
                : "";
        String reason = get(817)
