package compass;
import lombok.*;

import javax.inject.Singleton;
import net.runelite.api.Skill;

/**
 * Lightweight live-session fatigue model.
 *
 * <p>This is intentionally not a permanent dislike. Sustained training of one
 * skill can temporarily reduce that skill's ranking in Balanced/Relaxed modes,
 * while Efficient mode remains focused on account efficiency. Hitpoints is
 * ignored because it passively changes alongside combat and would otherwise
 * break the continuity signal for the combat skill the player actually chose.</p>
 */
@Singleton
public class TrainingFatigueTracker
{
    static final long CONTINUITY_GAP_MILLIS = 10L * 60L * 1000L;
    static final long BALANCED_THRESHOLD_MILLIS = 45L * 60L * 1000L;
    static final long RELAXED_THRESHOLD_MILLIS = 30L * 60L * 1000L;
    static final long PENALTY_DURATION_MILLIS = 35L * 60L * 1000L;

    private Skill activeSkill;
    private int lastXp = -1;
    private long startedAtMillis;
    private long lastGainAtMillis;
    private long gainedXp;

    /** Records a RuneLite stat snapshot and returns a fatigue signal if due. */
    public FatigueSignal record(
            Skill skill,
            int currentXp,
            StrategyMode strategyMode)
    {
        return record(skill, currentXp, strategyMode, System.currentTimeMillis());
    }

    FatigueSignal record(
            Skill skill,
            int currentXp,
            StrategyMode strategyMode,
            long now)
    {
        if (skill == null || skill == Skill.HITPOINTS || currentXp < 0)
        {
            return FatigueSignal.none();
        }

        if (activeSkill != skill
                || lastGainAtMillis <= 0L
                || now - lastGainAtMillis > CONTINUITY_GAP_MILLIS)
        {
            begin(skill, currentXp, now);
            return FatigueSignal.none();
        }

        if (lastXp >= 0 && currentXp > lastXp)
        {
            gainedXp += (long) currentXp - lastXp;
            lastGainAtMillis = now;
        }
        lastXp = currentXp;

        if (strategyMode == null || strategyMode == StrategyMode.EFFICIENT)
        {
            return FatigueSignal.none();
        }

        var duration = Math.max(0L, now - startedAtMillis);
        long threshold = strategyMode == StrategyMode.RELAXED
                ? RELAXED_THRESHOLD_MILLIS
                : BALANCED_THRESHOLD_MILLIS;
        if (duration < threshold || gainedXp <= 0L)
        {
            return FatigueSignal.none();
        }

        // Relaxed rotates sooner and more strongly. Balanced still allows a
        // strategically valuable continuation to overcome the soft penalty.
        var penalty = strategyMode == StrategyMode.RELAXED ? -14.0 : -8.0;
        return new FatigueSignal(
                "skill:" + skill.name().toLowerCase(),
                penalty,
                PENALTY_DURATION_MILLIS,
                duration,
                gainedXp);
    }

    public void clear()
    {
        activeSkill = null;
        lastXp = -1;
        startedAtMillis = 0L;
        lastGainAtMillis = 0L;
        gainedXp = 0L;
    }
    private void begin(Skill skill, int xp, long now)
    {
        activeSkill = skill;
        lastXp = xp;
        startedAtMillis = now;
        lastGainAtMillis = now;
        gainedXp = 0L;
    }

    @Getter
    @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
    public static final class FatigueSignal
    {
        private static final FatigueSignal NONE = new FatigueSignal(
                null, 0.0, 0L, 0L, 0L);

        final String activityId;
        private final double scoreDelta;
        private final long durationMillis;
        private final long activeDurationMillis;
        private final long gainedXp;
        public static FatigueSignal none() { return NONE; }
        public boolean isPresent() { return activityId != null; }
    }
}

package compass;
import lombok.*;

import java.util.*;


import net.runelite.api.Skill;

@AllArgsConstructor(access = AccessLevel.PRIVATE)
@Getter
public final class TrainingMethod
{
    final String id;
    final Skill skill;
    final int minLevel;
    final int maxLevel;
    final String name;
    final String instructions;
    @Getter(AccessLevel.NONE)
    final double efficientScore;
    @Getter(AccessLevel.NONE)
    final double balancedScore;
    @Getter(AccessLevel.NONE)
    final double relaxedScore;
    final AttentionLevel attentionLevel;
    final int minimumSessionMinutes;
    final int setupMinutes;
    final List<String> requirements;
    final Confidence confidence;
    final boolean membersOnly;
    final boolean wilderness;
    final boolean progressionProtected;
    @Getter(AccessLevel.NONE)
    final boolean delegatesMethodChoice;

    public TrainingMethod(
            String id,
            Skill skill,
            int minLevel,
            int maxLevel,
            String name,
            String instructions,
            double efficientScore,
            double balancedScore,
            double relaxedScore,
            AttentionLevel attentionLevel,
            int minimumSessionMinutes,
            int setupMinutes,
            List<String> requirements,
            Confidence confidence)
    {
        this(id, skill, minLevel, maxLevel, name, instructions,
                efficientScore, balancedScore, relaxedScore, attentionLevel,
                minimumSessionMinutes, setupMinutes, requirements, confidence,
                false, false, false);
    }

    public TrainingMethod(
            String id,
            Skill skill,
            int minLevel,
            int maxLevel,
            String name,
            String instructions,
            double efficientScore,
            double balancedScore,
            double relaxedScore,
            AttentionLevel attentionLevel,
            int minimumSessionMinutes,
            int setupMinutes,
            List<String> requirements,
            Confidence confidence,
            boolean membersOnly,
            boolean wilderness,
            boolean progressionProtected)
    {
        this(id, skill, minLevel, maxLevel, name, instructions,
                efficientScore, balancedScore, relaxedScore, attentionLevel,
                minimumSessionMinutes, setupMinutes,
                Collections.unmodifiableList(new ArrayList<>(requirements)),
                confidence, membersOnly, wilderness, progressionProtected,
                false);
    }

    public boolean delegatesMethodChoice() { return delegatesMethodChoice; }

    public boolean supportsLevel(int level)
    {
        return level >= minLevel && level <= maxLevel;
    }

    public double scoreFor(
            StrategyMode strategyMode,
            SessionIntent sessionIntent)
    {
        double score;

        switch (strategyMode)
        {
            case EFFICIENT:
                score = efficientScore;
                break;
            case RELAXED:
                score = relaxedScore;
                break;
            case BALANCED:
            default:
                score = balancedScore;
                break;
        }

        switch (sessionIntent)
        {
            case QUICK_20_MIN:
                if (minimumSessionMinutes <= 20) score += 4.0;
                else score -= 5.0;
                if (setupMinutes <= 5) score += 3.0;
                break;
            case ONE_HOUR:
                if (minimumSessionMinutes <= 60) score += 2.0;
                break;
            case LONG_SESSION:
                score += efficientScore * 0.10;
                break;
            case AFK:
                switch (attentionLevel)
                {
                    case AFK: score += 8.0; break;
                    case LOW: score += 5.0; break;
                    case ACTIVE: score -= 8.0; break;
                    case MODERATE: score -= 2.0; break;
                    default: break;
                }
                break;
            case PICK_FOR_ME:
            default:
                break;
        }

        if (confidence == Confidence.CHECK_NEEDED)
        {
            score -= 1.5;
        }
        else if (confidence == Confidence.BLOCKED)
        {
            score -= 1000.0;
        }

        return score;
    }
}

package compass;
import static java.util.Collections.*;
import lombok.*;

import static compass.Text.get;

import java.util.*;
import javax.inject.*;
import net.runelite.api.Skill;

@Singleton
public class TrainingMethodSelector
{
    private final TrainingMethodCatalog catalog;
    private final RequirementEvidenceEngine requirementEvidenceEngine;
    private final TrainingMethodPolicy methodPolicy;
    private final MethodStrategyKnowledgeCatalog strategyCatalog;
    private final UimInventoryResolutionService inventoryResolution;

    @Inject
    public TrainingMethodSelector(
            TrainingMethodCatalog catalog,
            RequirementEvidenceEngine requirementEvidenceEngine,
            TrainingMethodPolicy methodPolicy,
            MethodStrategyKnowledgeCatalog strategyCatalog,
            UimInventoryResolutionService inventoryResolution)
    {
        this.catalog = catalog;
        this.requirementEvidenceEngine = requirementEvidenceEngine;
        this.methodPolicy = methodPolicy;
        this.strategyCatalog = strategyCatalog == null
                ? new MethodStrategyKnowledgeCatalog() : strategyCatalog;
        this.inventoryResolution = inventoryResolution == null
                ? new UimInventoryResolutionService() : inventoryResolution;
    }

    public TrainingPlan select(GameData data, Skill skill, int currentLevel,
            StrategyMode mode, SessionIntent intent, boolean... options)
    {
        List<TrainingPlan> ranked = rankedCandidates(data, skill, currentLevel,
                mode, intent, options.length > 0 && options[0],
                options.length > 1 && options[1]);
        return ranked.isEmpty() ? null : ranked.get(0);
    }

    /** Ranked legal methods, exposed package-wide for decision-tournament tests. */
    List<TrainingPlan> rankedCandidates(GameData data, Skill skill,
            int currentLevel, StrategyMode strategyMode,
            SessionIntent sessionIntent, boolean allowWildernessMethods,
            boolean useGroupStorage)
    {
        var methods = candidates(data, skill);
        var membershipStatus = membershipStatus(data);
        List<ScoredPlan> ranked = new ArrayList<>();
        AccountMode mode = data == null || data.account() == null
                ? AccountMode.UNKNOWN : AccountMode.fromTypeCode(
                        data.account().modeCode());

        for (CuratedTrainingMethod candidate : methods)
        {
            var method = candidate.method();
            var metadata = candidate.getMetadata();
            MethodStrategyProfile strategyProfile = strategyCatalog.profileFor(
                    method, metadata, mode);
            double strategyAdjustment = strategyAdjustment(data,
                    strategyProfile);
            if (!method.supportsLevel(currentLevel)
                    || !ContentAccessRules.isMethodAvailable(method, membershipStatus)
                    || method.confidence == Confidence.BLOCKED
                    || !methodPolicy.isAllowed(data, method, metadata, allowWildernessMethods)
                    || Double.isNaN(strategyAdjustment))
            {
                continue;
            }

            List<EvidenceCheck> checks = requirementEvidenceEngine == null
                    ? emptyList()
                    : useGroupStorage
                            ? requirementEvidenceEngine.evaluate(
                                    data, method, true)
                            : requirementEvidenceEngine.evaluate(data, method);
            var confidence = assessConfidence(method, checks);
            if (confidence == Confidence.BLOCKED) continue;

            // A skill gets one selected method. Never let a higher-scoring
            // method with unknown access consume that slot and hide a simpler
            // route the player can actually begin. Hard-gated methods can
            // return once their quest/access evidence is observed.
            TrainingPlan assessed = new TrainingPlan(method, "", confidence,
                    checks, strategyProfile);
            boolean hardRequirementUnknown =
                    RequirementActionability.hasHardUnresolvedRequirement(
                            assessed);

            double score = method.scoreFor(strategyMode, sessionIntent)
                    + methodPolicy.scoreAdjustment(data, metadata, strategyMode, sessionIntent)
                    + strategyAdjustment
                    + readinessAdjustment(data, checks, sessionIntent);
            // Retain a hard-gated plan as diagnostic/secondary information when
            // every route is unknown, but it must lose to any executable route
            // regardless of their normal efficiency scores.
            if (hardRequirementUnknown) score -= 10_000.0;
            ranked.add(new ScoredPlan(new TrainingPlan(method,
                    buildExplanation(method, metadata, strategyMode,
                            sessionIntent, data, strategyProfile), confidence,
                    checks, strategyProfile), score));
        }

        ranked.sort(Comparator.comparingDouble(ScoredPlan::getScore).reversed());
        List<TrainingPlan> plans = new ArrayList<>();
        for (ScoredPlan candidate : ranked) plans.add(candidate.plan);
        return unmodifiableList(plans);
    }

    private static double readinessAdjustment(GameData data,
            List<EvidenceCheck> checks, SessionIntent sessionIntent)
    {
        if (checks == null || checks.isEmpty()) return 0.0;
        AccountMode mode = data == null || data.account() == null
                ? AccountMode.UNKNOWN
                : AccountMode.fromTypeCode(data.account().modeCode());
        var fullyReady = true;
        var missingResourcePenalty = 0.0;
        for (EvidenceCheck check : checks)
        {
            if (check == null)
            {
                fullyReady = false;
                continue;
            }
            if (check.getState() != RequirementState.VERIFIED)
                fullyReady = false;
            if (check.getState() == RequirementState.CHECK_NEEDED
                    && RequirementActionability.isPreparationRequirement(check))
            {
                var penalty = mode.isIronLike() ? 14.0 : 10.0;
                if (sessionIntent == SessionIntent.QUICK_20_MIN) penalty += 4.0;
                if (sessionIntent == SessionIntent.LONG_SESSION)
                    penalty -= mode.isIronLike() ? 5.0 : 8.0;
                missingResourcePenalty += penalty;
            }
        }
        // Readiness is plan-level: a requirement-free method and a method with
        // every check verified get the same benefit. The number of evidence
        // rows never adds score, so splitting one fact into several checks
        // cannot change the winner.
        return (fullyReady ? 10.0 : 0.0) - missingResourcePenalty;
    }

    @RequiredArgsConstructor(access = AccessLevel.PRIVATE)

    private static final class ScoredPlan
    {
        private final TrainingPlan plan;
        @Getter
        private final double score;
    }

    private List<CuratedTrainingMethod> candidates(GameData data, Skill skill)
    {
        List<CuratedTrainingMethod> candidates = new ArrayList<>();
        var membership = membershipStatus(data);

        if (catalog.legacyOnly())
        {
            for (TrainingMethod method : catalog.legacyFor(skill))
                candidates.add(new CuratedTrainingMethod(method,
                        TrainingMethodMetadata.legacy(method)));
            return candidates;
        }

        // In production, legacy methods predate route-level F2P metadata. F2P
        // therefore uses only catalogs whose membership compatibility is explicit.
        if (membership == Membership.P2P)
        {
            for (TrainingMethod method : catalog.legacyFor(skill))
            {
                // These legacy catch-alls delegate the meaningful method choice
                // back to the player and can outrank their concrete successors.
                if (method.delegatesMethodChoice()) continue;
                candidates.add(new CuratedTrainingMethod(method,
                        TrainingMethodMetadata.legacy(method)));
            }
        }

        candidates.addAll(catalog.curatedFor(skill));

        // Basic F2P routes are also valid on members worlds. Keep them available
        // to P2P accounts as concrete low-level Runecraft routes and as a safe
        // fallback when a higher-level members method is not currently usable.
        candidates.addAll(catalog.f2pFor(skill));
        // Several routes exist in both the protected legacy catalog and the
        // richer expanded catalog. A duplicate must never masquerade as the
        // runner-up in Other Good Options or method-tournament diagnostics.
        // Prefer the later expanded definition, preserving original order.
        Map<String, CuratedTrainingMethod> unique = new LinkedHashMap<>();
        for (CuratedTrainingMethod candidate : candidates)
        {
            var id = candidate.method().id;
            if (unique.containsKey(id)) unique.remove(id);
            unique.put(id, candidate);
        }
        return new ArrayList<>(unique.values());
    }

    private static Membership membershipStatus(GameData data)
    {
        if (data == null || data.account() == null) return Membership.UNKNOWN;
        return data.account().membership();
    }

    private Confidence assessConfidence(
            TrainingMethod method, List<EvidenceCheck> checks)
    {
        if (method.confidence == Confidence.BLOCKED)
            return Confidence.BLOCKED;
        if (checks != null && !checks.isEmpty())
        {
            var hasUnknown = false;
            for (EvidenceCheck check : checks)
            {
                if (check.getState() == RequirementState.BLOCKED)
                    return Confidence.BLOCKED;
                if (check.getState() == RequirementState.CHECK_NEEDED) hasUnknown = true;
            }
            return hasUnknown ? Confidence.CHECK_NEEDED
                    : Confidence.VERIFIED;
        }
        if (method.requirements.isEmpty()
                && method.confidence == Confidence.VERIFIED)
            return Confidence.VERIFIED;
        return Confidence.CHECK_NEEDED;
    }

    private String buildExplanation(TrainingMethod method,
            TrainingMethodMetadata metadata, StrategyMode strategyMode,
            SessionIntent sessionIntent, GameData data,
            MethodStrategyProfile strategyProfile)
    {
        var reason = new StringBuilder();
        if (strategyProfile != null
                && strategyProfile.getPlayerReason() != null
                && !strategyProfile.getPlayerReason().trim().isEmpty())
        {
            reason.append(strategyProfile.getPlayerReason().trim());
        }
        else
        {
            reason.append(get(1279))
                    .append(pretty(strategyMode.name())).append(" play.");
        }
        if (sessionIntent != SessionIntent.PICK_FOR_ME)
            reason.append(" It also fits ").append(pretty(sessionIntent.name()))
                    .append(" sessions.");
        if (method.wilderness)
            reason.append(get(898));
        return reason.toString();
    }

    /** NaN means the sourced method is not legal for the live account. */
    private double strategyAdjustment(GameData data,
            MethodStrategyProfile profile)
    {
        if (data == null || data.account() == null)
            return profile == null ? Double.NaN : 0.0;
        if (profile == null) return Double.NaN;
        AccountMode mode = AccountMode.fromTypeCode(data.account().modeCode());
        if (!profile.supports(mode)
                || mode == AccountMode.ULTIMATE_IRONMAN
                && profile.bankingBehavior == BankingMode.CONVENTIONAL_BANK_LOOP)
            return Double.NaN;

        InventoryFootprint footprint = profile.inventoryFootprint;
        ItemsState inventory = data.inventory();
        if (mode == AccountMode.ULTIMATE_IRONMAN && footprint != null
                && footprint.minimumPracticalFreeSlots > 0
                && (inventory == null
                || !inventory.hasCompleteSlotObservation()))
            return Double.NaN;
        int occupied = UimSetupCostService.occupiedInventorySlots(inventory);
        int free = Math.max(0, 28 - occupied);
        if (mode == AccountMode.ULTIMATE_IRONMAN && inventory != null
                && inventory.hasCompleteSlotObservation()
                && inventoryResolution.resolve(data, footprint, false, false,
                        emptyList()).getKind() != UimInventoryKind.USE_AS_IS)
            return Double.NaN;

        double score = profile.getAccountValueFit() * 8.0;
        if (mode == AccountMode.ULTIMATE_IRONMAN && inventory != null
                && inventory.hasCompleteSlotObservation())
        {
            if (free - footprint.minimumPracticalFreeSlots <= 1) score -= 5.0;
            if (footprint.tearsDownCurrentSetup()) score -= 8.0;
            if (footprint.getFlow() == InventoryFlow.GROWS_NONSTACKABLE_OUTPUTS)
                score -= 3.0;
        }
        return score;
    }

    private static String pretty(String value)
    {
        if (value == null || value.isEmpty()) return "Unknown";
        var lower = value.toLowerCase().replace('_', ' ');
        return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
    }
}

package compass;
import static compass.Text.get;

import java.util.*;

/** Verified behavior classes for UIM storage; distinct systems never alias. */
public final class UimStorageMechanics
{
    private static final Set<StorageKind> ITEM_RETRIEVAL_SERVICES =
            EnumSet.of(StorageKind.HESPORI_ITEM_RETRIEVAL,
                    StorageKind.ZULRAH_ITEM_RETRIEVAL,
                    StorageKind.VOLCANIC_MINE_ITEM_RETRIEVAL);
    private static final Set<StorageKind> RESTRICTED_RETRIEVAL =
            EnumSet.of(StorageKind.LOOTING_BAG,
                    StorageKind.DEATH_STORAGE,
                    StorageKind.HESPORI_ITEM_RETRIEVAL,
                    StorageKind.ZULRAH_ITEM_RETRIEVAL,
                    StorageKind.VOLCANIC_MINE_ITEM_RETRIEVAL,
                    StorageKind.DEATHPILE);
    private static final Map<StorageKind, UimStorageMechanicProfile>
            PROFILES = profiles();

    private UimStorageMechanics() {}

    public static boolean isExactItemRetrievalService(
            StorageKind capability)
    {
        return capability != null
                && ITEM_RETRIEVAL_SERVICES.contains(capability);
    }

    public static boolean isDangerous(StorageKind capability)
    {
        return isExactItemRetrievalService(capability)
                || capability == StorageKind.DEATHPILE;
    }

    public static boolean isRestrictedRetrieval(StorageKind capability)
    {
        return capability != null && RESTRICTED_RETRIEVAL.contains(capability);
    }

    /** Generic death storage lacks the location-specific rules needed to act. */
    public static boolean isTooGenericToRecommend(StorageKind capability)
    {
        return capability == StorageKind.DEATH_STORAGE;
    }

    public static UimStorageMechanicProfile profile(
            StorageKind capability)
    {
        return capability == null ? null : PROFILES.get(capability);
    }

    public static String displayName(StorageKind capability)
    {
        if (capability == null) return "unknown storage";
        switch (capability)
        {
            case HESPORI_ITEM_RETRIEVAL:
                return get(1189);
            case ZULRAH_ITEM_RETRIEVAL:
                return get(1190);
            case VOLCANIC_MINE_ITEM_RETRIEVAL:
                return get(1021);
            case DEATHPILE:
                return get(1191);
            case LOOTING_BAG:
                return "the looting bag";
            case POH_COSTUME_ROOM:
                return get(1192);
            case POH_STORAGE:
                return get(1193);
            case STASH:
                return get(1194);
            default:
                return capability.name().toLowerCase().replace('_', ' ');
        }
    }

    private static Map<StorageKind, UimStorageMechanicProfile> profiles()
    {
        EnumMap<StorageKind, UimStorageMechanicProfile> values =
                new EnumMap<>(StorageKind.class);
        add(values, StorageKind.LOOTING_BAG,
                get(1195),
                get(1032),
                get(1043),
                get(1051),
                get(1052),
                get(1053),
                get(1054),
                get(1055),
                RiskLevel.MEDIUM, Source.UIM_ITEM_MANAGEMENT, true);
        add(values, StorageKind.HESPORI_ITEM_RETRIEVAL,
                get(1056),
                get(1022),
                get(1023),
                get(1024),
                get(1025),
                "25,000 coins.",
                get(1026),
                get(1027),
                RiskLevel.HIGH, Source.ITEM_RETRIEVAL_SERVICES, true);
        add(values, StorageKind.ZULRAH_ITEM_RETRIEVAL,
                get(1196),
                get(1028),
                get(1029),
                get(1030),
                get(1031),
                get(1033),
                get(1034),
                get(1035),
                RiskLevel.HIGH, Source.ITEM_RETRIEVAL_SERVICES, true);
        add(values, StorageKind.VOLCANIC_MINE_ITEM_RETRIEVAL,
                get(1036),
                get(1037),
                get(1038),
                get(1039),
                get(1040),
                "150 numulite.",
                get(1041),
                get(1042),
                RiskLevel.HIGH, Source.ITEM_RETRIEVAL_SERVICES, true);
        add(values, StorageKind.DEATHPILE,
                get(1044),
                get(1045),
                get(1046),
                get(1047),
                get(1048),
                "No service fee.",
                get(1049),
                get(1050),
                RiskLevel.IRREVERSIBLE, Source.UIM_ITEM_MANAGEMENT,
                true);
        values.put(StorageKind.DEATH_STORAGE,
                new UimStorageMechanicProfile(StorageKind.DEATH_STORAGE,
                        "Unknown", get(1197), "Unknown",
                        "Unknown", "Unknown", "Unknown", "Unknown",
                        "Unknown", RiskLevel.HIGH,
                        Source.ITEM_RETRIEVAL_SERVICES, false));
        return Collections.unmodifiableMap(values);
    }

    private static void add(
            Map<StorageKind, UimStorageMechanicProfile> values,
            StorageKind capability, String location,
            String accessRequirements, String eligibleItems,
            String insertionRules, String retrievalRules, String cost,
            String expiration, String secondDeathBehavior, RiskLevel risk,
            Source source, boolean recommendationEligible)
    {
        values.put(capability, new UimStorageMechanicProfile(capability,
                location, accessRequirements, eligibleItems, insertionRules,
                retrievalRules, cost, expiration, secondDeathBehavior, risk,
                source, recommendationEligible));
    }
}

package compass;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AccountBuildPolicyTest extends CatalogHostTest
{
    @Test
    public void oneDefencePureNeverGetsDefenceTraining()
    {
        AccountSnapshot pure = account(60, 80, 1, 80, 52, 80, 70, 30);
        assertEquals(BuildType.ONE_DEFENCE_PURE,
                AccountBuildPolicy.effectiveBuild(pure));
        assertFalse(AccountBuildPolicy.allowsSkill(pure, Skill.DEFENCE));
        assertTrue(AccountBuildPolicy.allowsSkill(pure, Skill.RANGED));
    }

    @Test
    public void defencePureOnlyAllowsDefenceAndPrayerCombatProgression()
    {
        AccountSnapshot pure = account(1, 1, 75, 1, 43, 1, 63, 30);
        assertEquals(BuildType.DEFENCE_PURE,
                AccountBuildPolicy.effectiveBuild(pure));
        assertTrue(AccountBuildPolicy.allowsSkill(pure, Skill.DEFENCE));
        assertTrue(AccountBuildPolicy.allowsSkill(pure, Skill.PRAYER));
        assertFalse(AccountBuildPolicy.allowsSkill(pure, Skill.ATTACK));
        assertFalse(AccountBuildPolicy.allowsSkill(pure, Skill.STRENGTH));
        assertFalse(AccountBuildPolicy.allowsSkill(pure, Skill.RANGED));
        assertFalse(AccountBuildPolicy.allowsSkill(pure, Skill.MAGIC));
        assertFalse(AccountBuildPolicy.allowsSkill(pure, Skill.SLAYER));
    }

    @Test
    public void establishedLevelThreeSkillerProtectsAllCombatSkills()
    {
        AccountSnapshot skiller = account(1, 1, 1, 1, 1, 1, 10, 70);
        assertEquals(BuildType.SKILLER,
                AccountBuildPolicy.effectiveBuild(skiller));
        assertFalse(AccountBuildPolicy.allowsSkill(skiller, Skill.ATTACK));
        assertFalse(AccountBuildPolicy.allowsSkill(skiller, Skill.PRAYER));
        assertFalse(AccountBuildPolicy.allowsSkill(skiller, Skill.SLAYER));
        assertTrue(AccountBuildPolicy.allowsSkill(skiller, Skill.COOKING));
    }

    @Test
    public void tenHpBuildAllowsNonDamagingMagicButRejectsCombatMagic()
    {
        AccountSnapshot tenHp = account(1, 1, 1, 1, 20, 55, 10, 60);
        assertEquals(BuildType.TEN_HITPOINTS,
                AccountBuildPolicy.effectiveBuild(tenHp));

        TrainingMethod alch = method("magic_high_alch", Skill.MAGIC);
        TrainingMethod combat = method("magic_f2p_combat", Skill.MAGIC);
        assertTrue(AccountBuildPolicy.allowsMethod(tenHp, alch));
        assertFalse(AccountBuildPolicy.allowsMethod(tenHp, combat));
    }

    private static TrainingMethod method(String id, Skill skill)
    {
        return new TrainingMethod(
                id, skill, 1, 99, id, id,
                10, 10, 10, AttentionLevel.MODERATE, 10, 1,
                java.util.Collections.emptyList(),
                Confidence.VERIFIED);
    }

    private static AccountSnapshot account(
            int attack, int strength, int defence, int ranged,
            int prayer, int magic, int hp, int nonCombat)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, nonCombat);
            xp.put(skill, 0);
        }
        levels.put(Skill.ATTACK, attack);
        levels.put(Skill.STRENGTH, strength);
        levels.put(Skill.DEFENCE, defence);
        levels.put(Skill.RANGED, ranged);
        levels.put(Skill.PRAYER, prayer);
        levels.put(Skill.MAGIC, magic);
        levels.put(Skill.HITPOINTS, hp);
        levels.put(Skill.SLAYER, nonCombat);

        return new AccountSnapshot("Build Test", 0L, 0, "Main", Membership.P2P, 1, 1000, 0L, levels, xp);
    }
}

package compass;

import java.util.ArrayList;
