import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/** One-variable account-mode comparisons over real strategy seams. */
public class AccountModePairRedTeamTest extends CatalogHostTest
{
    private static final List<Skill> HIGH_IMPACT_SKILLS = Arrays.asList(
            Skill.SMITHING, Skill.CRAFTING, Skill.HERBLORE,
            Skill.CONSTRUCTION, Skill.RUNECRAFT, Skill.PRAYER,
            Skill.FISHING, Skill.SLAYER);
    private final TrainingMethodSelector selector = new TrainingMethodSelector(
            new TrainingMethodCatalog(),
            new RequirementEvidenceEngine(new FarmingAccessEvaluator(new FarmingAccessCatalog()), new AgilityAccessEvaluator(new AgilityCourseCatalog()), new FarmingSupplyCatalog(), new RunecraftSupplyCatalog()),
            new TrainingMethodPolicy(), new MethodStrategyKnowledgeCatalog(),
            new UimInventoryResolutionService());

    @Test
    public void mainIronAndUimGeneratePracticalSkillFamilies()
    {
        for (AccountMode mode : Arrays.asList(AccountMode.MAIN,
                AccountMode.IRONMAN, AccountMode.ULTIMATE_IRONMAN))
        {
            GameData data = data(mode, Membership.P2P,
                    carriedSetup(), null);
            for (Skill skill : HIGH_IMPACT_SKILLS)
            {
                List<TrainingPlan> plans = selector.rankedCandidates(data,
                        skill, 50, StrategyMode.BALANCED,
                        SessionIntent.ONE_HOUR, false, false);
                assertFalse(mode + " has no " + skill.getName()
                        + " strategy", plans.isEmpty());
                if (mode == AccountMode.ULTIMATE_IRONMAN)
                    for (TrainingPlan plan : plans)
                        assertNotEquals(skill + " leaked a bank loop",
                                BankingMode.CONVENTIONAL_BANK_LOOP,
                                plan.getStrategyProfile().getBankingBehavior());
            }
        }
    }

    @Test
    public void mainVersusUimChangesSmithingAndRunecraftGeneration()
    {
        GameData main = data(AccountMode.MAIN,
                Membership.F2P, carriedSetup(), null);
        GameData uim = data(AccountMode.ULTIMATE_IRONMAN,
                Membership.F2P, carriedSetup(), null);

        TrainingPlan mainSmithing = winner(main, Skill.SMITHING, 1);
        TrainingPlan uimSmithing = winner(uim, Skill.SMITHING, 1);
        assertEquals("smithing_f2p_uim_bronze",
                uimSmithing.getMethod().getId());
        assertNotEquals(mainSmithing.getMethod().getId(),
                uimSmithing.getMethod().getId());

        TrainingPlan mainRunecraft = winner(main, Skill.RUNECRAFT, 1);
        TrainingPlan uimRunecraft = winner(uim, Skill.RUNECRAFT, 1);
        assertEquals("runecraft_f2p_uim_local",
                uimRunecraft.getMethod().getId());
        assertNotEquals(mainRunecraft.getMethod().getId(),
                uimRunecraft.getMethod().getId());
    }

    @Test
    public void sharedFishingStaysSharedWhenThePracticalRouteIsShared()
    {
        TrainingMethod fly = new ExpandedTrainingMethodCatalog()
                .methodsFor(Skill.FISHING).stream()
                .filter(value -> "fishing_f2p_fly".equals(
                        value.getMethod().getId()))
                .map(CuratedTrainingMethod::getMethod)
                .findFirst().orElseThrow(AssertionError::new);
        TrainingMethodMetadata metadata = new ExpandedTrainingMethodCatalog()
                .methodsFor(Skill.FISHING).stream()
                .filter(value -> "fishing_f2p_fly".equals(
                        value.getMethod().getId()))
                .map(CuratedTrainingMethod::getMetadata)
                .findFirst().orElseThrow(AssertionError::new);
        MethodStrategyKnowledgeCatalog catalog =
                new MethodStrategyKnowledgeCatalog();

        assertNotNull(catalog.profileFor(fly, metadata, AccountMode.MAIN));
        assertNotNull(catalog.profileFor(fly, metadata, AccountMode.IRONMAN));
        assertNotNull(catalog.profileFor(fly, metadata,
                AccountMode.ULTIMATE_IRONMAN));
    }

    @Test
    public void sharedActivitiesRemainAvailableBesideAccountSpecificVariants()
    {
        ExpandedTrainingMethodCatalog methods =
                new ExpandedTrainingMethodCatalog();
        MethodStrategyKnowledgeCatalog knowledge =
                new MethodStrategyKnowledgeCatalog();
        for (String id : Arrays.asList("smithing_giants_foundry",
                "construction_mahogany_homes",
                "prayer_bonecrusher_passive"))
        {
            CuratedTrainingMethod method = Arrays.stream(Skill.values())
                    .flatMap(skill -> methods.methodsFor(skill).stream())
                    .filter(value -> id.equals(value.getMethod().getId()))
                    .findFirst().orElseThrow(AssertionError::new);
            MethodStrategyProfile main = knowledge.profileFor(
                    method.getMethod(), method.getMetadata(), AccountMode.MAIN);
            MethodStrategyProfile iron = knowledge.profileFor(
                    method.getMethod(), method.getMetadata(),
                    AccountMode.IRONMAN);
            MethodStrategyProfile uim = knowledge.profileFor(
                    method.getMethod(), method.getMetadata(),
                    AccountMode.ULTIMATE_IRONMAN);
            assertNotNull(id + " Main", main);
            assertNotNull(id + " Iron", iron);
            assertNotNull(id + " UIM", uim);
            assertEquals(id + " Main tier", KnowledgeTier.VERIFIED_SHARED,
                    main.getTier());
            assertEquals(id + " UIM tier",
                    KnowledgeTier.VERIFIED_ACCOUNT_SPECIFIC,
                    uim.getTier());
        }
    }

    @Test
    public void ironVersusHardcoreRiskChangesEligibilityBeforeSelection()
    {
        TrainingMethod wilderness = new TrainingMethod("risky", Skill.PRAYER,
                1, 99, "Risky bones", "Use a Wilderness route.",
                1, 1, 1, AttentionLevel.MODERATE, 10, 2,
                Collections.emptyList(), Confidence.VERIFIED,
                false, true, false);
        TrainingMethodMetadata metadata = new TrainingMethodMetadata(
                TrainingIntensity.EFFICIENT, MethodCostTier.FREE,
                RiskLevel.HIGH, true, true, true, false,
                Collections.emptyList());
        TrainingMethodPolicy policy = new TrainingMethodPolicy();

        assertTrue(policy.isAllowed(data(AccountMode.IRONMAN,
                Membership.P2P, carriedSetup(), null), wilderness,
                metadata, true));
        assertFalse(policy.isAllowed(data(AccountMode.HARDCORE_IRONMAN,
                Membership.P2P, carriedSetup(), null), wilderness,
                metadata, true));
        assertFalse(policy.isAllowed(data(
                AccountMode.HARDCORE_GROUP_IRONMAN,
                Membership.P2P, carriedSetup(), null), wilderness,
                metadata, true));
    }

    @Test
    public void fullInventoryChangesUimQuestGearPvmAndInfrastructureOnlyWhenNeeded()
    {
        ActivityStrategyKnowledgeService knowledge =
                new ActivityStrategyKnowledgeService();
        StrategyContext uim = context(data(AccountMode.ULTIMATE_IRONMAN,
                Membership.P2P, fullInventory(), null), false);
        StrategyContext main = context(data(AccountMode.MAIN,
                Membership.P2P, fullInventory(), null), false);

        for (String id : Arrays.asList("quest:waterfall-quest", "clue:step",
                "minigame:tempoross", "upgrade:fighter-torso", "pvm:tztok_jad",
                "prepare:infrastructure:poh-costume-room"))
        {
            assertNotNull(id, knowledge.attach(candidate(id), main));
            assertEquals(id, null, knowledge.attach(candidate(id), uim));
        }
        assertNotNull(knowledge.attach(candidate("slayer:do-task"), uim));
        assertNotNull(knowledge.attach(candidate("pvm:the_gauntlet"), uim));
    }

    @Test
    public void fullInventoryRejectsEverySkillingFootprintThatDoesNotFit()
    {
        GameData normal = data(AccountMode.ULTIMATE_IRONMAN,
                Membership.P2P, carriedSetup(), null);
        GameData full = data(AccountMode.ULTIMATE_IRONMAN,
                Membership.P2P, fullInventory(), null);
        for (Skill skill : Arrays.asList(Skill.SMITHING, Skill.CRAFTING,
                Skill.HERBLORE, Skill.CONSTRUCTION, Skill.RUNECRAFT,
                Skill.FARMING, Skill.PRAYER, Skill.FISHING))
        {
            assertFalse(skill.getName() + " lacks a normal UIM strategy",
                    selector.rankedCandidates(normal, skill, 50,
                            StrategyMode.BALANCED, SessionIntent.ONE_HOUR,
                            false, false).isEmpty());
            for (TrainingPlan plan : selector.rankedCandidates(full, skill, 50,
                    StrategyMode.BALANCED, SessionIntent.ONE_HOUR,
                    false, false))
            {
                assertEquals(skill.getName() + " plan does not fit zero free slots",
                        0, plan.getStrategyProfile().getInventoryFootprint()
                                .getMinimumPracticalFreeSlots());
                assertNotEquals(BankingMode.CONVENTIONAL_BANK_LOOP,
                        plan.getStrategyProfile().getBankingBehavior());
            }
        }
    }

    private TrainingPlan winner(GameData data, Skill skill, int level)
    {
        TrainingPlan plan = selector.select(data, skill, level,
                StrategyMode.BALANCED, SessionIntent.ONE_HOUR, false, false);
        assertNotNull(skill.getName(), plan);
        return plan;
    }

    private static Recommendation candidate(String id)
    {
        return new Recommendation(id, "Candidate", "Reason", 10.0, null,
                Confidence.VERIFIED, 0, 0,
                new Guidance("Do it.", "Observed setup",
                        "Verified location", "Note"),
                Safety.harmless(false));
    }

    private static StrategyContext context(GameData data,
            boolean groupStorage)
    {
        return new StrategyContext(data, StrategyMode.BALANCED,
                SessionIntent.ONE_HOUR, QuestTolerance.NORMAL,
                GoalType.AUTOMATIC, groupStorage, false, false,
                new PreferenceProfile());
    }

    private static GameData data(AccountMode mode,
            Membership membership, List<ItemState> inventory,
            ItemsState groupStorage)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        int total = 0;
        long totalXp = 0L;
        for (Skill skill : Skill.values())
        {
            int level = skill == Skill.HITPOINTS ? 50 : 50;
            levels.put(skill, level);
            int value = Experience.getXpForLevel(level);
            xp.put(skill, value);
            total += level;
            totalXp += value;
        }
        Map<String, QuestStatus> quests = new HashMap<>();
        quests.put("Temple of the Eye", QuestStatus.COMPLETE);
        quests.put("The Knight's Sword", QuestStatus.COMPLETE);
        AccountSnapshot account = new AccountSnapshot(mode.name(),
                1000L + typeCode(mode), typeCode(mode), mode.name(),
                membership, membership == Membership.P2P ? 1 : 0,
                total, totalXp, levels, xp);
        GameData.Builder builder = GameData.builder(account)
                .inventory(new ItemsState(inventory, true))
                .equipment(new ItemsState(Collections.emptyList()))
                .quests(new QuestSnapshot(quests));
        if (mode != AccountMode.ULTIMATE_IRONMAN)
            builder.bank(new ItemsState(Collections.emptyList(), 1L));
        if (groupStorage != null) builder.groupStorage(groupStorage);
        return builder.build();
    }

    private static List<ItemState> carriedSetup()
    {
        return Arrays.asList(
                item(ItemID.BRONZE_PICKAXE, "Bronze pickaxe", 1, 0),
                item(ItemID.HAMMER, "Hammer", 1, 1),
                item(ItemID.CHISEL, "Chisel", 1, 2),
                item(ItemID.FLY_FISHING_ROD, "Fly fishing rod", 1, 3),
                item(ItemID.FEATHER, "Feather", 1000, 4),
                item(ItemID.COINS, "Coins", 100_000, 5));
    }

    private static List<ItemState> fullInventory()
    {
        List<ItemState> values = new ArrayList<>();
        for (int slot = 0; slot < 28; slot++)
            values.add(item(20_000 + slot, "Persistent item " + slot,
                    1, slot));
        return values;
    }

    private static ItemState item(int id, String name, int quantity,
            int slot)
    {
        return new ItemState(id, name, quantity, slot);
    }

    private static int typeCode(AccountMode mode)
    {
        switch (mode)
        {
            case MAIN: return 0;
            case IRONMAN: return 1;
            case ULTIMATE_IRONMAN: return 2;
            case HARDCORE_IRONMAN: return 3;
            case GROUP_IRONMAN: return 4;
            case HARDCORE_GROUP_IRONMAN: return 5;
            case UNRANKED_GROUP_IRONMAN: return 6;
            default: return -1;
        }
    }
}

package compass;

import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class AccountProgressMilestoneDetectorTest extends CatalogHostTest
{
    @Test
    public void firstSnapshotIsBaselineNotAListOfFakeAchievements()
    {
        AccountProgressMilestoneDetector detector =
                new AccountProgressMilestoneDetector();
        assertTrue(detector.observe(data(1L, QuestStatus.COMPLETE, true),
                GoalType.BARROWS_GLOVES, 1L).isEmpty());
    }

    @Test
    public void successiveLiveStateDetectsQuestTransportAndStorage()
    {
        AccountProgressMilestoneDetector detector =
                new AccountProgressMilestoneDetector();
        detector.observe(data(1L, QuestStatus.NOT_STARTED, false),
                GoalType.BARROWS_GLOVES, 1L);
        java.util.List<ProgressMilestone> milestones = detector.observe(
                data(1L, QuestStatus.COMPLETE, true),
                GoalType.BARROWS_GLOVES, 2L);

        assertEquals(3, milestones.size());
        assertTrue(milestones.stream().anyMatch(value ->
                value.getType() == ProgressMilestoneType.QUEST));
        assertTrue(milestones.stream().anyMatch(value ->
                value.getType() == ProgressMilestoneType.TRANSPORT));
        assertTrue(milestones.stream().anyMatch(value ->
                value.getType() == ProgressMilestoneType.INFRASTRUCTURE));
    }

    @Test
    public void accountSwitchRebaselinesWithoutLeakingMilestones()
    {
        AccountProgressMilestoneDetector detector =
                new AccountProgressMilestoneDetector();
        detector.observe(data(1L, QuestStatus.NOT_STARTED, false),
                GoalType.BARROWS_GLOVES, 1L);
        assertTrue(detector.observe(data(2L, QuestStatus.COMPLETE, true),
                GoalType.BARROWS_GLOVES, 2L).isEmpty());
    }

    @Test
    public void detectsDiaryTierAndSlayerRewardWithoutRepeatingThem()
    {
        AccountProgressMilestoneDetector detector =
                new AccountProgressMilestoneDetector();
        detector.observe(progressData(false), GoalType.AUTOMATIC, 1L);

        java.util.List<ProgressMilestone> first = detector.observe(
                progressData(true), GoalType.AUTOMATIC, 2L);
        java.util.List<ProgressMilestone> duplicate = detector.observe(
                progressData(true), GoalType.AUTOMATIC, 3L);

        assertEquals(2, first.size());
        assertTrue(first.stream().anyMatch(value -> value.getType()
                == ProgressMilestoneType.DIARY));
        assertTrue(first.stream().anyMatch(value -> value.getType()
                == ProgressMilestoneType.SLAYER_UNLOCK));
        assertTrue(duplicate.isEmpty());
    }

    private static GameData data(long hash, QuestStatus quest,
            boolean unlocked)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 70);
            xp.put(skill, 0);
        }
        AccountSnapshot account = new AccountSnapshot("Progress", hash, 0,
                "MAIN", Membership.P2P, 1,
                70 * Skill.values().length, 0L, levels, xp);
        Map<String, QuestStatus> quests = new HashMap<>();
        quests.put("Cook's Assistant", quest);
        Map<StorageKind, Capability> storage =
                new EnumMap<>(StorageKind.class);
        storage.put(StorageKind.POH_COSTUME_ROOM, unlocked
                ? Capability.VERIFIED : Capability.UNKNOWN);
        return GameData.builder(account)
                .quests(new QuestSnapshot(quests))
                .transport(new TransportSnapshot(unlocked
                        ? Collections.singleton("spirit-trees")
                        : Collections.emptySet()))
                .storage(new StorageSnapshot(storage, Collections.emptyMap()))
                .build();
    }

    private static GameData progressData(boolean complete)
    {
        GameData base = data(9L, QuestStatus.NOT_STARTED, false);
        Map<DiaryTier, Boolean> tiers = new EnumMap<>(DiaryTier.class);
        tiers.put(DiaryTier.MEDIUM, complete);
        Map<String, Map<DiaryTier, Boolean>> regions = new HashMap<>();
        regions.put("Varrock", tiers);
        Map<SlayerReward, Capability> rewards =
                new EnumMap<>(SlayerReward.class);
        rewards.put(SlayerReward.BIGGER_AND_BADDER, complete
                ? Capability.VERIFIED : Capability.BLOCKED);
        return GameData.builder(base.account())
                .diaries(new DiarySnapshot(Collections.emptyMap(),
                        Collections.emptyMap(), regions, Collections.emptyMap()))
                .slayer(TestFixtures.slayerSnapshot(null, 0, "Nieve", null, 0,
                        10, 100, 2, 0,
                        new SlayerRewardSnapshot(rewards),
                        Confidence.VERIFIED))
                .build();
    }
}

package compass;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AccountResourcePlannerTest extends CatalogHostTest
{
    private final AccountResourcePlanner planner = TestFixtures.accountResourcePlanner();

    @Test
    public void unopenedMainBankNeverBecomesFakeShortfall()
    {
        GameData data = GameData.builder(account(0))
                .inventory(new ItemsState(Collections.singletonList(
                        item("Yew logs", 100))))
                .build();

        SupplyPlan plan = planner.plan(
                data,
                Collections.singletonList(need("Yew logs", 500)),
                false);

        assertFalse(plan.isPrimaryStorageObserved());
        assertTrue(plan.getGuidance().contains("Open your bank once"));
        assertFalse(plan.getGuidance().contains("Buy 400"));
    }

    @Test
    public void mainDoesNotAssumeAnUnpricedShortfallShouldBeBought()
    {
        GameData data = GameData.builder(account(0))
                .inventory(new ItemsState(Collections.singletonList(
                        item("Yew logs", 25))))
                .equipment(new ItemsState(Collections.emptyList()))
                .bank(new ItemsState(Collections.singletonList(
                        item("Yew logs", 275)), 1L))
                .build();

        SupplyPlan plan = planner.plan(
                data,
                Collections.singletonList(need("Yew logs", 500)),
                false);

        assertTrue(plan.isPrimaryStorageObserved());
        assertEquals(200, plan.getTotalMissingUnits());
        assertTrue(plan.getGuidance().contains("Verified usable: 300 Yew logs"));
        assertTrue(plan.getGuidance().contains("Do not assume the shortfall should be bought"));
        assertTrue(plan.getGuidance().contains("Reviewed self-source route"));
    }

    @Test
    public void ironSelfSourcesInsteadOfUsingGrandExchange()
    {
        GameData data = GameData.builder(account(1))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .bank(new ItemsState(Collections.singletonList(
                        item("Ranarr weed", 40)), 1L))
                .build();

        SupplyPlan plan = planner.plan(
                data,
                Collections.singletonList(need("Ranarr weed", 100)),
                false);

        assertEquals(60, plan.getTotalMissingUnits());
        assertTrue(plan.getGuidance().contains("Self-source 60 Ranarr weed"));
        assertFalse(plan.getGuidance().contains("Grand Exchange"));
    }

    @Test
    public void groupStorageOnlyChangesShortfallWhenEnabledAndObserved()
    {
        GameData data = GameData.builder(account(4))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .bank(new ItemsState(Collections.singletonList(
                        item("Oak plank", 100)), 1L))
                .groupStorage(new ItemsState(true,
                        Collections.singletonList(item("Oak plank", 300))))
                .build();

        List<MethodInput> needs = Collections.singletonList(
                need("Oak plank", 500));
        SupplyPlan disabled = planner.plan(data, needs, false);
        SupplyPlan enabled = planner.plan(data, needs, true);

        assertEquals(400, disabled.getTotalMissingUnits());
        assertEquals(100, enabled.getTotalMissingUnits());
        assertTrue(enabled.getGuidance().contains("Group Storage"));
    }

    @Test
    public void enabledButUnobservedGroupStorageIsNeverAssumedEmpty()
    {
        GameData data = GameData.builder(account(4))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .bank(new ItemsState(Collections.singletonList(
                        item("Oak plank", 100)), 1L))
                .groupStorage(ItemsState.unknown())
                .build();

        SupplyPlan plan = planner.plan(
                data,
                Collections.singletonList(need("Oak plank", 500)),
                true);

        assertEquals(400, plan.getTotalMissingUnits());
        assertTrue(plan.getGuidance().contains(
                "enabled but has not been observed"));
    }

    @Test
    public void uimIgnoresNormalBankAndReportsRetrievalOnlySupplySeparately()
    {
        Map<StorageKind, Capability> states =
                new EnumMap<>(StorageKind.class);
        states.put(StorageKind.LOOTING_BAG, Capability.VERIFIED);
        Map<StorageKind, List<ItemState>> contents =
                new EnumMap<>(StorageKind.class);
        contents.put(StorageKind.LOOTING_BAG,
                Collections.singletonList(item("Mahogany plank", 250)));

        GameData data = GameData.builder(account(2))
                .inventory(new ItemsState(Collections.singletonList(
                        item("Mahogany plank", 20))))
                .equipment(new ItemsState(Collections.emptyList()))
                .bank(new ItemsState(Collections.singletonList(
                        item("Mahogany plank", 5000)), 1L))
                .storage(new StorageSnapshot(states, contents))
                .build();

        SupplyPlan plan = planner.plan(
                data,
                Collections.singletonList(need("Mahogany plank", 100)),
                false);

        assertEquals(80, plan.getTotalMissingUnits());
        assertEquals(80, plan.getMissingInputs().get(0).getQuantity());
        assertTrue(plan.getGuidance().contains("resupply only"));
        assertTrue(plan.getGuidance().contains("retrieval-only UIM storage"));
        assertFalse(plan.getGuidance().contains("5,020"));
    }

    @Test
    public void partialUimSnapshotNeverBecomesAProvenShortfall()
    {
        GameData data = GameData.builder(account(2))
                .inventory(new ItemsState(Collections.emptyList()))
                .build();

        SupplyPlan plan = planner.plan(data,
                Collections.singletonList(need("Oak plank", 100)), false);

        assertFalse(plan.isPrimaryStorageObserved());
        assertTrue(plan.getGuidance().contains("not fully observed"));
        assertFalse(plan.getGuidance().contains("Self-source 100"));
    }

    @Test
    public void equippedElementalStaffWaivesMatchingRuneConsumption()
    {
        GameData data = GameData.builder(account(0))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.singletonList(
                        item("Staff of fire", 1))))
                .bank(new ItemsState(Collections.emptyList(), 1L))
                .build();

        SupplyPlan plan = planner.plan(
                data,
                Arrays.asList(
                        need("Nature rune", 100),
                        need("Fire rune", 500)),
                false);

        assertEquals(100, plan.getTotalMissingUnits());
        assertEquals(1, plan.getMissingInputs().size());
        assertEquals("Nature rune", plan.getMissingInputs().get(0).getName());
        assertTrue(plan.getGuidance().contains("Fire rune supplied by Staff of fire"));
        assertTrue(plan.getGuidance().contains("Do not assume the shortfall should be bought"));
    }

    @Test
    public void lowBurdenExactMainPurchaseUsesLivePriceAndLiquidCash()
    {
        AccountResourcePlanner pricedPlanner = new AccountResourcePlanner(
                new FixedPriceService(20),
                new ResourceSourceCatalog());
        GameData data = GameData.builder(account(0))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .bank(new ItemsState(Collections.emptyList(), 1L))
                .economy(new AccountEconomySnapshot(100_000L, 100_000L,
                        Confidence.VERIFIED))
                .build();

        SupplyPlan plan = pricedPlanner.plan(data,
                Collections.singletonList(need("Yew logs", 100)), false);

        assertTrue(plan.getGuidance().contains("Buy 100 Yew logs"));
        assertTrue(plan.getGuidance().contains("2,000 coins"));
        assertTrue(plan.getGuidance().contains("low-burden"));
    }

    @Test
    public void wealthBurdenCanMakeMainUseReviewedSelfSourceRoute()
    {
        AccountResourcePlanner pricedPlanner = new AccountResourcePlanner(
                new FixedPriceService(500),
                new ResourceSourceCatalog());
        GameData data = GameData.builder(account(0))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .bank(new ItemsState(Collections.emptyList(), 1L))
                .economy(new AccountEconomySnapshot(100_000L, 100_000L,
                        Confidence.VERIFIED))
                .build();

        SupplyPlan plan = pricedPlanner.plan(data,
                Collections.singletonList(need("Yew logs", 100)), false);

        assertTrue(plan.getGuidance().contains("Self-source 100 Yew logs"));
        assertTrue(plan.getGuidance().contains("Reviewed route"));
        assertFalse(plan.getGuidance().contains("Buy 100 Yew logs"));
    }

    @Test
    public void emptyTomeOfFireDoesNotWaiveFireRunes()
    {
        GameData data = GameData.builder(account(0))
                .equipment(new ItemsState(Collections.singletonList(
                        item("Tome of fire (empty)", 1))))
                .bank(new ItemsState(Collections.emptyList(), 1L))
                .build();

        SupplyPlan plan = planner.plan(
                data,
                Collections.singletonList(need("Fire rune", 500)),
                false);

        assertEquals(500, plan.getTotalMissingUnits());
    }

    @Test
    public void duplicateRecipeRowsAreMergedBeforeShortfallMath()
    {
        GameData data = GameData.builder(account(1))
                .bank(new ItemsState(Collections.singletonList(
                        item("Feather", 15)), 1L))
                .build();

        SupplyPlan plan = planner.plan(
                data,
                Arrays.asList(need("Feather", 10), need("feather", 20)),
                false);

        assertEquals(1, plan.getMissingInputs().size());
        assertEquals(15, plan.getMissingInputs().get(0).getQuantity());
        assertTrue(plan.getGuidance().contains("Need 30 Feather"));
    }

    private static MethodInput need(String name, int quantity)
    {
        return new MethodInput(name, -1, quantity);
    }

    private static ItemState item(String name, int quantity)
    {
        return new ItemState(-1, name, quantity);
    }

    private static AccountSnapshot account(int typeCode)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 70);
            xp.put(skill, 0);
        }
        return new AccountSnapshot("Resource Test", 0L, typeCode, AccountMode.fromTypeCode(typeCode).name(), Membership.P2P, 1, 1500, 0L, levels, xp);
    }

    private static final class FixedPriceService extends MarketPriceService
    {
        private final int price;

        private FixedPriceService(int price)
        {
            super(null);
            this.price = price;
        }

        @Override
        public MarketPriceQuote quote(String exactItemName)
        {
            return new MarketPriceQuote(1, exactItemName, price);
        }
    }
}

package compass;

import static org.junit.Assert.assertEquals;

import java.util.*;
import net.runelite.api.Skill;
import org.junit.Test;

/** Covers the focused account policy consumed by infrastructure planning. */
public class AccountStrategicPriorityServiceTest extends CatalogHostTest
{
    private Priority priority(StrategyContext context, InfraBenefit benefit)
    {
        return InfrastructureUnlockValueService.priorityOf(context, benefit);
    }

    @Test
    public void mainAndIronDivergeOnSelfSourcingBenefits()
    {
        assertEquals(Priority.LOW, priority(AccountMode.MAIN,
                InfraBenefit.SELF_SUFFICIENCY, 10));
        assertEquals(Priority.HIGH, priority(AccountMode.IRONMAN,
                InfraBenefit.SELF_SUFFICIENCY, 10));
        assertEquals(Priority.LOW, priority(AccountMode.MAIN,
                InfraBenefit.RESOURCE_SUSTAINABILITY, 10));
        assertEquals(Priority.HIGH, priority(AccountMode.IRONMAN,
                InfraBenefit.RESOURCE_SUSTAINABILITY, 10));
    }

    @Test
    public void uimInventoryStorageAndSetupBenefitsAreCritical()
    {
        StrategyContext context = context(AccountMode.ULTIMATE_IRONMAN, 25);
        assertEquals(Priority.CRITICAL,
                priority(context, InfraBenefit.INVENTORY_RELIEF));
        assertEquals(Priority.CRITICAL,
                priority(context, InfraBenefit.STORAGE));
        assertEquals(Priority.CRITICAL,
                priority(context, InfraBenefit.SETUP_REUSE));
        assertEquals(Priority.CRITICAL,
                priority(context, InfraBenefit.STORABLE_EQUIPMENT));
    }

    @Test
    public void uimInventoryPressureUsesObservedSlots()
    {
        assertEquals(Priority.HIGH, priority(AccountMode.ULTIMATE_IRONMAN,
                InfraBenefit.INVENTORY_RELIEF, 10));
        assertEquals(Priority.CRITICAL, priority(AccountMode.ULTIMATE_IRONMAN,
                InfraBenefit.INVENTORY_RELIEF, 25));
    }

    @Test
    public void hardcoreRiskExceedsOrdinaryIronRisk()
    {
        assertEquals(Priority.MODERATE, priority(AccountMode.IRONMAN,
                InfraBenefit.RISK_REDUCTION, 10));
        assertEquals(Priority.CRITICAL, priority(AccountMode.HARDCORE_IRONMAN,
                InfraBenefit.RISK_REDUCTION, 10));
    }

    @Test
    public void unknownModeFailsClosedForSelfSourcingOnly()
    {
        assertEquals(Priority.CRITICAL,
                priority(null, InfraBenefit.SELF_SUFFICIENCY));
        assertEquals(Priority.NONE,
                priority(null, InfraBenefit.POH_PLATFORM));
    }

    private Priority priority(AccountMode mode, InfraBenefit benefit,
            int occupied)
    {
        return priority(context(mode, occupied), benefit);
    }

    private static StrategyContext context(AccountMode mode, int occupied)
    {
        List<ItemState> items = new ArrayList<>();
        for (int i = 0; i < occupied; i++)
            items.add(new ItemState(10_000 + i, "Item " + i, 1, i));
        GameData data = GameData.builder(account(mode))
                .inventory(new ItemsState(items)).build();
        return new StrategyContext(data, StrategyMode.BALANCED,
                SessionIntent.PICK_FOR_ME, QuestTolerance.NORMAL,
                GoalType.AUTOMATIC, false, false, new PreferenceProfile());
    }

    private static AccountSnapshot account(AccountMode mode)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 70);
            xp.put(skill, 0);
        }
        return new AccountSnapshot("Priority", 1L, mode.ordinal(), mode.name(),
                Membership.P2P, 1, 70 * levels.size(), 0L, levels, xp);
    }
}

