                data,
                StrategyMode.BALANCED,
                SessionIntent.PICK_FOR_ME,
                false,
                false,
                GoalType.AUTOMATIC,
                new PreferenceProfile());

        assertFalse(recommendations.isEmpty());
        for (Recommendation recommendation : recommendations)
        {
