    @Test
    public void broadModeMatrixNeverReturnsBuildOrMembershipIllegalMethod()
    {
        int[] accountTypes = {0, 1, 2, 3, 4, 5, 6};
        StrategyMode[] modes = StrategyMode.values();
        SessionIntent[] sessions = {
                SessionIntent.PICK_FOR_ME,
                SessionIntent.AFK,
                SessionIntent.QUICK_20_MIN,
                SessionIntent.LONG_SESSION
        };

        for (int accountType : accountTypes)
        {
            AccountSnapshot account = account(
                    Membership.P2P,
                    accountType,
                    standardLevels(70));
            GameData data = data(account);
            for (StrategyMode mode : modes)
            {
                for (SessionIntent session : sessions)
                {
                    for (Skill skill : Skill.values())
                    {
                        if (skill == Skill.HITPOINTS) continue;
                        TrainingPlan plan = selector.select(
                                data,
                                skill,
                                account.getSkillLevel(skill),
                                mode,
                                session,
                                false);
                        if (plan == null) continue;
                        TrainingMethod method = plan.getMethod();
                        assertNotNull(method);
                        assertTrue("Build-illegal method " + method.getId(),
                                AccountBuildPolicy.allowsMethod(account, method));
                        assertTrue("Membership-illegal method " + method.getId(),
                                ContentAccessRules.isMethodAvailable(
                                        method, Membership.P2P));
                        assertFalse("Wilderness method leaked with risk disabled: "
                                        + method.getId(),
                                method.isWilderness());
                    }
                }
            }
        }
    }

    @Test
    public void strategyEngineRunsMajorAccountStageMatrixEndToEnd()
    {
        StrategyEngine strategyEngine = TestFixtures.strategyEngine(engine, null, null,
                null, new ActionabilityPolicy(),
                new RecommendationIntelligenceService());
        Membership[] memberships = {
                Membership.F2P, Membership.UNKNOWN,
                Membership.P2P};
        int[] stages = {1, 35, 65, 90, 98, 99};
        for (Membership membership : memberships)
        {
            for (int accountType = 0; accountType <= 6; accountType++)
            {
                for (int stage : stages)
                {
                    GameData data = data(account(membership,
                            accountType, standardLevels(stage)));
                    for (StrategyMode mode : StrategyMode.values())
                    {
                        for (SessionIntent session : new SessionIntent[]{
                                SessionIntent.QUICK_20_MIN, SessionIntent.AFK,
                                SessionIntent.PICK_FOR_ME,
                                SessionIntent.LONG_SESSION})
                        {
                            StrategyResult result = strategyEngine.evaluate(data,
                                    mode, session, new PreferenceProfile());
                            assertFalse("DO NEXT missing for " + membership + "/"
                                    + accountType + "/" + stage + "/" + mode + "/"
                                    + session, result.getRecommendations().isEmpty());
                            for (Recommendation recommendation
                                    : result.getRecommendations())
                            {
                                assertFalse(recommendation.getConfidence()
                                        == Confidence.BLOCKED);
                                if (FallbackRecommendationFactory.isFallback(
                                        recommendation)) continue;
                                TrainingMethod method = requireMethod(recommendation);
                                assertTrue(ContentAccessRules.isMethodAvailable(
                                        method, membership));
                                assertTrue(AccountBuildPolicy.allowsMethod(
                                        data.account(), method));
                            }
                        }
                    }
                }
            }
        }
    }

    private static GameData data(AccountSnapshot account)
    {
        return GameData.builder(account)
                .bank(new ItemsState(Collections.emptyList(), 1L))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .build();
    }

    private static AccountSnapshot account(
            Membership membership,
            int typeCode,
            Map<Skill, Integer> levels)
    {
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        int total = 0;
        long totalXp = 0L;
        for (Skill skill : Skill.values())
        {
            int level = Math.max(1, levels.getOrDefault(skill, 1));
            int skillXp = level <= 1 ? 0 : Experience.getXpForLevel(level);
            xp.put(skill, skillXp);
            total += level;
            totalXp += skillXp;
        }
        return new AccountSnapshot("Simulation", 0L, typeCode, AccountMode.fromTypeCode(typeCode).name(), membership, membership == Membership.P2P ? 1 : 0, total, totalXp, levels, xp);
    }

    private static Map<Skill, Integer> standardLevels(int level)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) levels.put(skill, level);
        // Hitpoints should never be below its real account baseline.
        levels.put(Skill.HITPOINTS, Math.max(10, level));
        return levels;
    }

    private static TrainingMethod requireMethod(Recommendation recommendation)
    {
        assertNotNull(recommendation);
        assertNotNull(recommendation.getTrainingPlan());
        assertNotNull(recommendation.getTrainingPlan().getMethod());
        return recommendation.getTrainingPlan().getMethod();
    }

    private static void assertNullPlan(TrainingPlan plan)
    {
        assertTrue("Expected no legal plan but got "
                        + (plan == null || plan.getMethod() == null
                        ? "unknown" : plan.getMethod().getId()),
                plan == null || plan.getMethod() == null);
    }

    private static String safe(String value)
    {
        return value == null ? "" : value;
    }
}

package compass;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Cross-system regression tests for failures that are unacceptable in beta.
 *
 * <p>These deliberately test boundaries rather than one implementation detail:
 * membership isolation, primary-queue actionability, restricted builds, and
 * account-mode storage semantics.</p>
 */
public class BetaSafetyRegressionTest extends CatalogHostTest
{
    @Test
    public void unknownMembershipFailsClosedToF2pContent()
    {
        assertTrue(ContentAccessRules.isSkillAvailable(
                Skill.DEFENCE, Membership.UNKNOWN));
        assertFalse(ContentAccessRules.isSkillAvailable(
                Skill.SLAYER, Membership.UNKNOWN));
        assertFalse(ContentAccessRules.isSkillAvailable(
                Skill.SAILING, Membership.UNKNOWN));

        TrainingMethod f2p = method(
                "mining_f2p_iron", Skill.MINING, false,
                Confidence.VERIFIED);
        TrainingMethod members = method(
                "mining_mlm", Skill.MINING, true,
                Confidence.VERIFIED);

        assertTrue(ContentAccessRules.isMethodAvailable(
                f2p, Membership.UNKNOWN));
        assertFalse(ContentAccessRules.isMethodAvailable(
                members, Membership.UNKNOWN));
    }

    @Test
    public void f2pNeverGetsCombatAchievementRewardTierCandidate()
    {
        AccountSnapshot account = account(
                Membership.F2P, 0, 60, 1, 1, 1, 1);
        GameData data = GameData.builder(account)
                .combatAchievements(new CombatAchievementSnapshot(18, 27,
                        Collections.emptySet()))
                .build();
        StrategyContext context = new StrategyContext(
                data,
                StrategyMode.BALANCED,
                SessionIntent.PICK_FOR_ME,
                QuestTolerance.NORMAL,
                GoalType.MAX,
                false,
                false,
                false,
                new PreferenceProfile());

        assertTrue(new CombatAchievementCandidateProvider()
                .candidates(context).isEmpty());
    }

    @Test
    public void needsInfoCannotOutrankReadyDoNext()
    {
        Recommendation ready = new Recommendation(
                "skill:defence",
                "Train Defence to 80",
                "Protected Defence-pure progression.",
                40.0,
                null,
                Confidence.VERIFIED,
                75,
                80,
                new Guidance(
                        "Train Defence with the best legal defensive style.",
                        "Use verified food and gear.",
                        "Use a safe F2P combat target.",
                        "Defence is the protected offensive-free combat path for this build."));
        Recommendation unresolvedQuest = new Recommendation(
                "quest:pandemonium",
                "Quest: Pandemonium",
                "Unresolved quest candidate.",
                999.0,
                null,
                Confidence.CHECK_NEEDED,
                0,
                0,
                null);

        ActionabilityPolicy policy =
                new ActionabilityPolicy();
        assertTrue(policy.canLeadQueue(ready));
        assertFalse(policy.canLeadQueue(unresolvedQuest));

        List<Recommendation> queue = queue(
                Arrays.asList(unresolvedQuest, ready), policy);

        assertEquals(1, queue.size());
        assertEquals("skill:defence", queue.get(0).getId());
    }

    @Test
    public void queueReturnsNothingRatherThanInventingPrimaryAction()
    {
        Recommendation unresolved = new Recommendation(
                "quest:unknown",
                "Quest: Unknown",
                "Requirements are not verified.",
                500.0, Confidence.CHECK_NEEDED, null, Safety.unknown());
        List<Recommendation> queue = queue(
                Collections.singletonList(unresolved),
                new ActionabilityPolicy());
        assertTrue(queue.isEmpty());
    }

    @Test
    public void defencePureAllowsDefenceAndPrayerButBlocksOffence()
    {
        AccountSnapshot account = account(
                Membership.F2P, 0, 75, 1, 1, 1, 43);

        assertEquals(BuildType.DEFENCE_PURE,
                AccountBuildPolicy.effectiveBuild(account));
        assertTrue(AccountBuildPolicy.allowsSkill(account, Skill.DEFENCE));
        assertTrue(AccountBuildPolicy.allowsSkill(account, Skill.PRAYER));
        assertFalse(AccountBuildPolicy.allowsSkill(account, Skill.ATTACK));
        assertFalse(AccountBuildPolicy.allowsSkill(account, Skill.STRENGTH));
        assertFalse(AccountBuildPolicy.allowsSkill(account, Skill.RANGED));
        assertFalse(AccountBuildPolicy.allowsSkill(account, Skill.MAGIC));
        assertFalse(AccountBuildPolicy.allowsSkill(account, Skill.SLAYER));
    }

    @Test
    public void uimNeverCountsNormalBankAsImmediatelyUsable()
    {
        AccountSnapshot uim = account(
                Membership.P2P, 2, 70, 1, 1, 1, 43);
        ItemsState bank = new ItemsState(
                Collections.singletonList(
                        new ItemState(383, "Raw shark", 1000)),
                1L);
        GameData data = GameData.builder(uim)
                .bank(bank)
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .build();

        ItemIndex items = new ItemIndex(data, false);
        assertEquals(0, items.quantity("Raw shark"));
        assertFalse(items.bankObserved());
        assertTrue(items.primaryOwnershipObserved());
    }

    @Test
    public void uimModeAloneNeverProvesAnUnobservedInventoryEmpty()
    {
        GameData data = GameData.builder(account(
                Membership.P2P, 2, 70, 1, 1, 1, 43)).build();

        ItemIndex items = new ItemIndex(data, false);
        assertFalse(items.bankObserved());
        assertFalse(items.primaryOwnershipObserved());
        assertFalse(items.usableOwnershipObserved());
    }

    @Test
    public void ordinaryAccountCountsObservedBank()
    {
        AccountSnapshot main = account(
                Membership.P2P, 0, 70, 70, 70, 70, 70);
        ItemsState bank = new ItemsState(
                Collections.singletonList(
                        new ItemState(383, "Raw shark", 1000)),
                1L);
        GameData data = GameData.builder(main)
                .bank(bank)
                .inventory(new ItemsState(Collections.emptyList()))
                .build();

        assertEquals(1000,
                new ItemIndex(data, false).quantity("Raw shark"));
    }

    @Test
    public void groupStorageOnlyCountsWhenEnabledAndObserved()
    {
        AccountSnapshot gim = account(
                Membership.P2P, 4, 70, 70, 70, 70, 70);
        ItemsState group = new ItemsState(
                true,
                Collections.singletonList(
                        new ItemState(1515, "Yew logs", 500)));
        GameData data = GameData.builder(gim)
                .groupStorage(group)
                .inventory(new ItemsState(Collections.emptyList()))
                .build();

        assertEquals(0,
                new ItemIndex(data, false).quantity("Yew logs"));
        assertEquals(500,
                new ItemIndex(data, true).quantity("Yew logs"));
    }

    private static List<Recommendation> queue(
            List<Recommendation> pool,
            ActionabilityPolicy policy)
    {
        StrategyEngine engine = TestFixtures.strategyEngine(
                null, null, null, null, policy);
        return engine.buildPlayerQueue(pool, null);
    }

    private static TrainingMethod method(
            String id,
            Skill skill,
            boolean membersOnly,
            Confidence confidence)
    {
        return new TrainingMethod(
                id,
                skill,
                1,
                99,
                id,
                "test",
                10,
                10,
                10,
                AttentionLevel.MODERATE,
                10,
                1,
                Collections.emptyList(),
                confidence,
                membersOnly,
                false,
                false);
    }

    private static AccountSnapshot account(
            Membership membership,
            int typeCode,
            int defence,
            int attack,
            int strength,
            int ranged,
            int prayer)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 30);
            xp.put(skill, Experience.getXpForLevel(30));
        }
        levels.put(Skill.ATTACK, attack);
        levels.put(Skill.STRENGTH, strength);
        levels.put(Skill.DEFENCE, defence);
        levels.put(Skill.RANGED, ranged);
        levels.put(Skill.MAGIC, 1);
        levels.put(Skill.PRAYER, prayer);
        levels.put(Skill.HITPOINTS, Math.max(10, defence >= 20 ? 63 : 10));
        xp.put(Skill.ATTACK, Experience.getXpForLevel(Math.max(1, attack)));
        xp.put(Skill.STRENGTH, Experience.getXpForLevel(Math.max(1, strength)));
        xp.put(Skill.DEFENCE, Experience.getXpForLevel(Math.max(1, defence)));
        xp.put(Skill.RANGED, Experience.getXpForLevel(Math.max(1, ranged)));
        xp.put(Skill.MAGIC, 0);
        xp.put(Skill.PRAYER, Experience.getXpForLevel(Math.max(1, prayer)));
        xp.put(Skill.HITPOINTS, Experience.getXpForLevel(
                Math.max(10, defence >= 20 ? 63 : 10)));

        return new AccountSnapshot("Beta Safety", 0L, typeCode, AccountMode.fromTypeCode(typeCode).name(), membership, 1, 1200, 0L, levels, xp);
    }
}

package compass;

import java.awt.Component;
import java.awt.Container;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Protects the display rename without invalidating existing local profiles. */
public class BrandingCompatibilityTest extends CatalogHostTest
{
    @Test
    public void pluginAndSidebarUseGielinorCompassBrand() throws Exception
    {
        PluginDescriptor descriptor = OsrsStrategistPlugin.class
                .getAnnotation(PluginDescriptor.class);
        assertEquals("Gielinor Compass", descriptor.name());
        PluginDependency dependency = OsrsStrategistPlugin.class
                .getAnnotation(PluginDependency.class);
        assertEquals(ClueScrollPlugin.class, dependency.value());

        OsrsStrategistPanel panel = new OsrsStrategistPanel(
                (id, action) -> { }, null);
        String text = allText(panel);
        assertTrue(text.contains("GIELINOR COMPASS"));
        assertTrue(text.contains("DO NEXT"));
        assertFalse(text.contains("OSRS STRATEGIST"));

        String metadata = new String(Files.readAllBytes(
                Paths.get("runelite-plugin.properties")), StandardCharsets.UTF_8);
        assertTrue(metadata.contains("displayName=Gielinor Compass"));
        assertFalse(metadata.contains("displayName=OSRS Strategist"));
    }

    @Test
    public void stableConfigurationAndProfileGroupsRemainCompatible()
    {
        assertEquals("osrs-strategist", OsrsStrategistConfig.GROUP);
        assertEquals("osrs-strategist-profile", AccountProfileStore.GROUP);
        assertEquals("osrs-strategist-profile", AccountAccessMemoryStore.GROUP);
        assertEquals("osrs-strategist-profile", FarmingRunStateStore.GROUP);
        assertEquals("osrs-strategist-profile",
                AccountProfileStore.GROUP);
    }

    private static String allText(Component component)
    {
        StringBuilder result = new StringBuilder();
        if (component instanceof javax.swing.JLabel)
            result.append(((javax.swing.JLabel) component).getText()).append('\n');
        if (component instanceof javax.swing.AbstractButton)
            result.append(((javax.swing.AbstractButton) component).getText()).append('\n');
        if (component instanceof Container)
            for (Component child : ((Container) component).getComponents())
                result.append(allText(child));
        return result.toString();
    }
}

package compass;

import com.google.gson.JsonParseException;
import org.junit.Test;

import static org.junit.Assert.*;

public class BundledCatalogLoaderTest extends CatalogHostTest
{
    @Test
    public void catalogUsesTheHostInjectedGsonAdapters()
    {
        com.google.inject.Injector previous = net.runelite.client.RuneLite.getInjector();
        com.google.gson.Gson hostGson = new com.google.gson.GsonBuilder()
                .registerTypeAdapter(String[].class, (com.google.gson.JsonDeserializer<String[]>)
                        (json, type, context) -> new String[] {"host adapter"}).create();
        try
        {
            net.runelite.client.RuneLite.setInjector(com.google.inject.Guice.createInjector(
                    new com.google.inject.AbstractModule()
                    {
                        @Override protected void configure()
                        { bind(com.google.gson.Gson.class).toInstance(hostGson); }
                    }));
            assertArrayEquals(new String[] {"host adapter"},
                    BundledCatalogLoader.array("/content/player-text.json", String[].class));
        }
        finally { net.runelite.client.RuneLite.setInjector(previous); }
    }

    @Test
    public void missingHostCannotSilentlyCreateAPluginOwnedParser()
    {
        com.google.inject.Injector previous = net.runelite.client.RuneLite.getInjector();
        try
        {
            net.runelite.client.RuneLite.setInjector(null);
            IllegalStateException error = assertThrows(IllegalStateException.class,
                    () -> BundledCatalogLoader.array("/content/player-text.json", String[].class));
            assertTrue(error.getMessage().contains("host injector"));
        }
        finally { net.runelite.client.RuneLite.setInjector(previous); }
    }

    @Test
    public void rejectsMissingResource()
    {
        IllegalStateException error = assertThrows(IllegalStateException.class,
                () -> BundledCatalogLoader.array("/missing-catalog.json", String[].class));
        assertEquals("Missing required bundled catalog: /missing-catalog.json", error.getMessage());
    }

    @Test
    public void rejectsNullCatalog()
    {
        IllegalStateException error = assertThrows(IllegalStateException.class,
                () -> BundledCatalogLoader.array("/catalog-tests/null.json", String[].class));
        assertEquals("Empty required bundled catalog: /catalog-tests/null.json", error.getMessage());
    }

    @Test
    public void rejectsNullRecord()
    {
        IllegalStateException error = assertThrows(IllegalStateException.class,
                () -> BundledCatalogLoader.array("/catalog-tests/null-record.json", String[].class));
        assertEquals("Null record 1 in /catalog-tests/null-record.json", error.getMessage());
    }

    @Test
    public void rejectsMalformedCatalogAndPreservesCause()
    {
        IllegalStateException error = assertThrows(IllegalStateException.class,
                () -> BundledCatalogLoader.array("/catalog-tests/malformed.json", String[].class));
        assertEquals("Malformed required bundled catalog: /catalog-tests/malformed.json", error.getMessage());
        assertTrue(error.getCause() instanceof JsonParseException);
    }
}

package compass;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CandidateSafetyPolicyTest extends CatalogHostTest
{
    private final CandidateSafetyPolicy policy = new CandidateSafetyPolicy();

    @Test
    public void protectedBuildsCannotReceiveUnprovenIrreversibleFamilies()
    {
        assertProtected(account(60, 60, 1, 60, 43, 60, 70, 40)); // 1 Defence
        assertProtected(account(1, 1, 60, 1, 43, 1, 70, 40)); // Defence pure
        assertProtected(account(1, 1, 1, 1, 1, 1, 10, 50)); // level 3 skiller
        assertProtected(account(1, 1, 1, 1, 20, 1, 10, 50)); // Prayer skiller
        assertProtected(account(1, 1, 1, 20, 20, 1, 10, 50)); // 10 HP
    }

    @Test
    public void harmlessWorkRemainsAvailableAndStandardMainIsUnrestricted()
    {
        StrategyContext skiller = context(account(1, 1, 1, 1, 1, 1, 10, 50));
        assertTrue(policy.isAllowed(recommendation("money:f2p-iron",
                Safety.skill(true, Skill.MINING)), skiller));
        assertTrue(policy.isAllowed(recommendation("detour:tempoross-planks",
                Safety.skill(false, Skill.FISHING)), skiller));

        StrategyContext main = context(account(70, 70, 70, 70, 70, 70, 70, 70));
        assertTrue(policy.isAllowed(recommendation("pvm:test"), main));
        assertTrue(policy.isAllowed(recommendation("combat-achievements:easy"), main));
    }

    private void assertProtected(AccountSnapshot account)
    {
        StrategyContext context = context(account);
        assertFalse(policy.isAllowed(recommendation("pvm:test"), context));
        assertFalse(policy.isAllowed(recommendation("combat-achievements:easy"), context));
        assertFalse(policy.isAllowed(recommendation("diary:test"), context));
        assertFalse(policy.isAllowed(recommendation("clue:test"), context));
        assertFalse(policy.isAllowed(recommendation("upgrade:test"), context));
        assertFalse(policy.isAllowed(recommendation("minigame:pest-control"), context));
        assertFalse(policy.isAllowed(recommendation("opportunity:tears-of-guthix"), context));
        assertTrue(policy.isAllowed(recommendation("opportunity:herb-run",
                Safety.skill(false, Skill.FARMING)), context));
    }

    private static Recommendation recommendation(String id)
    {
        return recommendation(id, Safety.unknown());
    }

    private static Recommendation recommendation(String id,
            Safety evidence)
    {
        return new Recommendation(id, id, "test", 10, null,
                Confidence.VERIFIED, 0, 0,
                new Guidance("Do it.", "Prepare.", "Safe area.", "Test."),
                evidence);
    }

    private static StrategyContext context(AccountSnapshot account)
    {
        return new StrategyContext(GameData.builder(account).build(),
                StrategyMode.BALANCED, SessionIntent.PICK_FOR_ME,
                QuestTolerance.NORMAL, GoalType.MAX, false, false, false,
                new PreferenceProfile());
    }

    private static AccountSnapshot account(int attack, int strength, int defence,
            int ranged, int prayer, int magic, int hp, int nonCombat)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) { levels.put(skill, nonCombat); xp.put(skill, 0); }
        levels.put(Skill.ATTACK, attack); levels.put(Skill.STRENGTH, strength);
        levels.put(Skill.DEFENCE, defence); levels.put(Skill.RANGED, ranged);
        levels.put(Skill.PRAYER, prayer); levels.put(Skill.MAGIC, magic);
        levels.put(Skill.HITPOINTS, hp); levels.put(Skill.SLAYER, 1);
        return new AccountSnapshot("Safety", 0L, 0, "Main", Membership.P2P, 1, 1000, 0L, levels, xp);
    }
}

