package compass;

import java.util.*;
import net.runelite.api.Skill;

final class ContentCoverageEntry
{
    private final String id, name;
    private final ContentCoverageState state;
    private final String reason, provenance;
    ContentCoverageEntry(String id, String name, ContentCoverageState state,
            String reason, String provenance)
    {
        this.id = id; this.name = name; this.state = state;
        this.reason = reason; this.provenance = provenance;
    }
    String getId() { return id; }
    String getName() { return name; }
    ContentCoverageState getState() { return state; }
    String getReason() { return reason; }
    String getProvenance() { return provenance; }
}

enum ContentCoverageState
{
    STRUCTURED, PARTIAL_PREPARATION, CONSERVATIVE_FAIL_CLOSED,
    NOT_PROGRESSION_RELEVANT
}

enum TransportCategory
{
    FAIRY_RING, SPIRIT_TREE, GNOME, MINECART, BOAT, CHARTER, ITEM_TELEPORT,
    STANDARD_SPELL, ANCIENT_SPELL, LUNAR_SPELL, ARCEUUS_SPELL, JEWELLERY,
    DIARY, MINIGAME, QUEST, AGILITY_SHORTCUT, SLAYER, POH, SAILING
}

final class TransportDefinition
{
    private final String id, name;
    private final TransportCategory category;
    private final boolean membersOnly;
    private final String quest;
    private final boolean questStartSuffices;
    private final Skill skill;
    private final int level;
    private final String itemOrAccessCheck, pohFurniture;
    private final boolean wilderness;
    private final List<String> uses;
    private TransportDefinition()
    {
        id = name = quest = itemOrAccessCheck = pohFurniture = null;
        category = null; skill = null; level = 0;
        membersOnly = questStartSuffices = wilderness = false; uses = null;
    }
    String getId() { return id; }
    String getName() { return name; }
    TransportCategory getCategory() { return category; }
    int getLevel() { return level; }
    String getItemOrAccessCheck() { return itemOrAccessCheck; }
    boolean isQuestStartSufficient() { return questStartSuffices; }
    int getFanOut() { return uses.size(); }
}

final class TransportCatalog
{
    private final Map<String, TransportDefinition> routes = new LinkedHashMap<>();
    TransportCatalog()
    {
        for (TransportDefinition value : BundledCatalogLoader.array(
                "/content/catalogs/transports.json", TransportDefinition[].class))
            if (routes.put(value.getId(), value) != null)
                throw new IllegalStateException("Duplicate transport " + value.getId());
    }
    List<TransportDefinition> all() { return new ArrayList<>(routes.values()); }
    TransportDefinition get(String id) { return routes.get(id); }
}

package compass;

import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Membership regressions for clues and stale recurring observations. */
public class ClueMembershipTest extends CatalogHostTest
{
    @Test
    public void f2pHidesHardClueOpportunity()
    {
        GameData data = GameData.builder(account(Membership.F2P))
                .clue(new ClueSnapshot(true, "hard", System.currentTimeMillis(),
                        Confidence.VERIFIED, null))
                .build();

        assertFalse(new OpportunityEngine().evaluate(data).stream()
                .anyMatch(o -> o.getType() == OpportunityType.CLUE));
    }

    @Test
    public void f2pKeepsBeginnerClueOpportunity()
    {
        GameData data = GameData.builder(account(Membership.F2P))
                .clue(new ClueSnapshot(true, "beginner", System.currentTimeMillis(),
                        Confidence.VERIFIED, null))
                .build();

        assertTrue(new OpportunityEngine().evaluate(data).stream()
                .anyMatch(o -> o.getType() == OpportunityType.CLUE));
    }

    @Test
    public void p2pKeepsHardClueOpportunity()
    {
        GameData data = GameData.builder(account(Membership.P2P))
                .clue(new ClueSnapshot(true, "hard", System.currentTimeMillis(),
                        Confidence.VERIFIED, null))
                .build();

        assertTrue(new OpportunityEngine().evaluate(data).stream()
                .anyMatch(o -> o.getType() == OpportunityType.CLUE));
    }

    @Test
    public void tierObservationAloneIsNotReportedReady()
    {
        GameData data = GameData.builder(
                account(Membership.P2P))
                .clue(new ClueSnapshot(true, "hard", 1L,
                        Confidence.VERIFIED, null)).build();

        Opportunity clue = new OpportunityEngine().evaluate(data).stream()
                .filter(value -> value.getType() == OpportunityType.CLUE)
                .findFirst().get();

        assertFalse(clue.isReady());
        assertEquals(Confidence.CHECK_NEEDED,
                clue.getConfidence());
        assertTrue(clue.getPreparation().get(0)
                .contains("Open the clue scroll"));
    }

    @Test
    public void exactStepReplacesGenericPreparationChecklist()
    {
        ClueStepSnapshot step = new ClueStepSnapshot("emote step",
                "Perform the emote.", "Catherby bank",
                Collections.singletonList("Maple longbow"), false, false,
                null, false, "outside catherby bank");
        GameData data = GameData.builder(
                account(Membership.P2P))
                .clue(new ClueSnapshot(true, "medium", 1L,
                        Confidence.VERIFIED, step)).build();

        Opportunity clue = new OpportunityEngine().evaluate(data).stream()
                .filter(value -> value.getType() == OpportunityType.CLUE)
                .findFirst().get();

        assertTrue(clue.getTitle().contains("emote step"));
        assertTrue(clue.getPreparation().contains("Maple longbow"));
        assertTrue(clue.getPreparation().stream()
                .anyMatch(value -> value.contains("STASH")));
        assertFalse(clue.getPreparation().stream()
                .anyMatch(value -> value.contains("when needed")));
    }

    @Test
    public void f2pDoesNotLeakPreviouslyObservedMembersTimers()
    {
        Map<String, Long> timers = new HashMap<>();
        timers.put("opportunity:birdhouse", 0L);
        timers.put("opportunity:herb-run", 0L);

        GameData data = GameData.builder(account(Membership.F2P))
                .recurringOpportunities(new RecurringOpportunitySnapshot(timers))
                .build();

        List<Opportunity> opportunities = new OpportunityEngine().evaluate(data);
        assertTrue(opportunities.isEmpty());
    }

    @Test
    public void clueTierMembershipRuleIsCentralized()
    {
        assertTrue(ClueTier.BEGINNER.isAvailableFor(Membership.F2P));
        assertFalse(ClueTier.EASY.isAvailableFor(Membership.F2P));
        assertFalse(ClueTier.MEDIUM.isAvailableFor(Membership.F2P));
        assertFalse(ClueTier.HARD.isAvailableFor(Membership.F2P));
        assertFalse(ClueTier.ELITE.isAvailableFor(Membership.F2P));
        assertFalse(ClueTier.MASTER.isAvailableFor(Membership.F2P));
        assertTrue(ClueTier.HARD.isAvailableFor(Membership.P2P));
    }

    private static AccountSnapshot account(Membership membership)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 1);
            xp.put(skill, 0);
        }
        return new AccountSnapshot("Membership Test", 0L, 0, "Main", membership, 1, 1, 0L, levels, xp);
    }
}

package compass;

import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class CombatGuidanceServiceTest extends CatalogHostTest
{
    private final CombatGuidanceService service = new CombatGuidanceService();

    @Test
    public void defencePureUsesObservedNoAttackWeaponAndDefensiveStyle()
    {
        AccountSnapshot account = defencePure();
        GameData data = GameData.builder(account)
                .bank(new ItemsState(Collections.singletonList(
                        new ItemState(24219, "Swift blade", 1)), 1L))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .build();

        Guidance guidance = service.build(
                data,
                Skill.DEFENCE,
                75,
                80,
                plan("defence_crabs", Skill.DEFENCE),
                SessionIntent.PICK_FOR_ME,
                true);

        assertNotNull(guidance);
        assertTrue(guidance.getAction().contains("Defensive / Defence XP"));
        assertTrue(guidance.getAction().contains("Swift blade"));
        assertTrue(Presentation.compactSentence(
                guidance.getAction(), 150).contains("Fight sand crabs"));
        assertTrue(guidance.getAction().contains("successful damage dealt"));
        assertTrue(guidance.getLocation().toLowerCase().contains("sand crab"));
        assertTrue(guidance.getAction().toLowerCase().contains("fight sand crabs"));
        assertTrue(guidance.getNote().contains("Defence pure"));
    }

    @Test
    public void strengthPlannerDoesNotRecommendWhipForDedicatedStrengthXp()
    {
        AccountSnapshot account = standard(70);
        GameData data = GameData.builder(account)
                .bank(new ItemsState(Collections.singletonList(
                        new ItemState(4151, "Abyssal whip", 1)), 1L))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .build();

        Guidance guidance = service.build(
                data,
                Skill.STRENGTH,
                70,
                80,
                plan("strength_crabs", Skill.STRENGTH),
                SessionIntent.PICK_FOR_ME,
                true);

        assertNull("A whip-only setup cannot execute dedicated Strength XP",
                guidance);
    }

    @Test
    public void afkGemstoneCrabUsesItsReducedXpPerDamage()
    {
        AccountSnapshot account = standard(70);
        Map<String, QuestStatus> quests = new HashMap<>();
        quests.put("Children of the Sun", QuestStatus.COMPLETE);
        GameData data = GameData.builder(account)
                .bank(new ItemsState(Collections.singletonList(
                        new ItemState(4151, "Abyssal whip", 1)), 1L))
                .quests(new QuestSnapshot(quests))
                .build();

        Guidance guidance = service.build(
                data,
                Skill.ATTACK,
                70,
                80,
                plan("attack_crabs", Skill.ATTACK),
                SessionIntent.AFK,
                true);

        assertNotNull(guidance);
        assertTrue(guidance.getLocation().contains("Gemstone Crab"));
        assertTrue(guidance.getAction().contains("follow it through the cave"));
        assertTrue(guidance.getAction().contains("3.5 XP per damage"));
    }

    @Test
    public void unknownMembershipCannotReceiveCombatRouteGuidanceDirectly()
    {
        AccountSnapshot p2p = standard(70);
        AccountSnapshot unknown = new AccountSnapshot(p2p.getPlayerName(), 0L, p2p.getAccountTypeCode(), p2p.getAccountTypeName(), Membership.UNKNOWN, 0, p2p.getTotalLevel(), p2p.getTotalExperience(), p2p.getSkillLevels(), p2p.getSkillExperience());
        Guidance guidance = service.build(
                GameData.builder(unknown).build(), Skill.ATTACK,
                70, 80, plan("attack_crabs", Skill.ATTACK),
                SessionIntent.AFK, true);
        assertTrue(guidance == null);
    }

    @Test
    public void scurriusNamesObservedFoodInsteadOfDelegatingSupplies()
    {
        AccountSnapshot account = standard(70);
        GameData data = GameData.builder(account)
                .bank(new ItemsState(java.util.Arrays.asList(
                        new ItemState(4151, "Abyssal whip", 1),
                        new ItemState(385, "Shark", 20)), 1L))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .build();

        Guidance guidance = service.build(data, Skill.ATTACK,
                70, 71, plan("attack_scurrius", Skill.ATTACK),
                SessionIntent.ONE_HOUR, true);

        assertNotNull(guidance);
        assertTrue(guidance.getSupplies().contains("observed Shark"));
        assertFalse(guidance.getSupplies().contains("appropriate"));
    }

    @Test
    public void scurriusWithoutObservedHealingStaysHidden()
    {
        AccountSnapshot account = standard(70);
        GameData data = GameData.builder(account)
                .bank(new ItemsState(Collections.singletonList(
                        new ItemState(4151, "Abyssal whip", 1)), 1L))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .build();

        assertNull(service.build(data, Skill.ATTACK, 70, 71,
                plan("attack_scurrius", Skill.ATTACK),
                SessionIntent.ONE_HOUR, true));
    }

    private static TrainingPlan plan(String id, Skill skill)
    {
        TrainingMethod method = new TrainingMethod(
                id, skill, 1, 99, id, "test",
                10, 10, 10, AttentionLevel.LOW,
                10, 1, Collections.emptyList(),
                Confidence.VERIFIED);
        return new TrainingPlan(method, "test",
                Confidence.VERIFIED,
                Collections.emptyList());
    }

    private static AccountSnapshot defencePure()
    {
        Map<Skill, Integer> levels = baseLevels(60);
        Map<Skill, Integer> xp = baseXp(60);
        levels.put(Skill.ATTACK, 1);
        levels.put(Skill.STRENGTH, 1);
        levels.put(Skill.DEFENCE, 75);
        levels.put(Skill.RANGED, 1);
        levels.put(Skill.MAGIC, 1);
        levels.put(Skill.PRAYER, 43);
        levels.put(Skill.HITPOINTS, 63);
        xp.put(Skill.DEFENCE, Experience.getXpForLevel(75));
        return new AccountSnapshot("Def pure", 0L, 0, "Main", Membership.P2P, 1, 1000, 0L, levels, xp);
    }

    private static AccountSnapshot standard(int combatLevel)
    {
        Map<Skill, Integer> levels = baseLevels(60);
        Map<Skill, Integer> xp = baseXp(60);
        levels.put(Skill.ATTACK, combatLevel);
        levels.put(Skill.STRENGTH, combatLevel);
        levels.put(Skill.DEFENCE, combatLevel);
        levels.put(Skill.RANGED, combatLevel);
        levels.put(Skill.MAGIC, combatLevel);
        levels.put(Skill.PRAYER, 70);
        levels.put(Skill.HITPOINTS, 80);
        xp.put(Skill.ATTACK, Experience.getXpForLevel(combatLevel));
        xp.put(Skill.STRENGTH, Experience.getXpForLevel(combatLevel));
        xp.put(Skill.DEFENCE, Experience.getXpForLevel(combatLevel));
        return new AccountSnapshot("Main", 0L, 0, "Main", Membership.P2P, 1, 1600, 0L, levels, xp);
    }

    private static Map<Skill, Integer> baseLevels(int value)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) levels.put(skill, value);
        return levels;
    }

    private static Map<Skill, Integer> baseXp(int level)
    {
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
            xp.put(skill, Experience.getXpForLevel(level));
        return xp;
    }
}

package compass;

import com.google.gson.Gson;
import java.lang.reflect.Modifier;
import java.lang.reflect.Proxy;
import java.util.concurrent.Executors;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigItem;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.*;

public class ConfigProxyTest extends CatalogHostTest
{
    @Rule public TemporaryFolder temporary = new TemporaryFolder();

    @Test
    public void allPublicConfigSignatureTypesAreAccessible()
    {
        for (var method : OsrsStrategistConfig.class.getMethods())
        {
            assertAccessible(method.getReturnType());
            for (Class<?> parameter : method.getParameterTypes()) assertAccessible(parameter);
            for (Class<?> exception : method.getExceptionTypes()) assertAccessible(exception);
        }
    }

    private static void assertAccessible(Class<?> type)
    {
        if (type.isArray()) { assertAccessible(type.getComponentType()); return; }
        if (type.isPrimitive()) return;
        for (Class<?> owner = type; owner != null; owner = owner.getEnclosingClass())
            assertTrue("Config proxy cannot access " + owner.getName(),
                    Modifier.isPublic(owner.getModifiers()));
    }

    @Test
    public void runeLiteProxyReadsEveryEnumDefaultAndRoundTripsStoredNames() throws Exception
    {
        var executor = Executors.newSingleThreadScheduledExecutor();
        try
        {
            // Use the real RuneLite proxy and codecs, without loading a user profile
            // or supplying any network/account services. Reflection is test-only.
            var constructor = ConfigManager.class.getDeclaredConstructors()[0];
            constructor.setAccessible(true);
            ConfigManager manager = (ConfigManager) constructor.newInstance(
                    null, executor, null, null, new Gson(), null, null, null);
            var dataField = ConfigManager.class.getDeclaredField("configProfile");
            dataField.setAccessible(true);
            var dataConstructor = dataField.getType().getDeclaredConstructor(java.io.File.class);
            dataConstructor.setAccessible(true);
            Object data = dataConstructor.newInstance(temporary.newFile("config.properties"));
            dataField.set(manager, data);
            var setProperty = dataField.getType().getDeclaredMethod("setProperty", String.class, String.class);
            setProperty.setAccessible(true);
            OsrsStrategistConfig proxy = manager.getConfig(OsrsStrategistConfig.class);
            assertTrue(Proxy.isProxyClass(proxy.getClass()));
            OsrsStrategistConfig defaults = new OsrsStrategistConfig() { };
            var encode = ConfigManager.class.getDeclaredMethod("objectToString", Object.class);
            encode.setAccessible(true);
            var handler = Proxy.getInvocationHandler(proxy);
            var invalidate = handler.getClass().getDeclaredMethod("invalidate");
            invalidate.setAccessible(true);
            int enumMethods = 0;
            for (var method : OsrsStrategistConfig.class.getMethods())
            {
                if (!method.getReturnType().isEnum()) continue;
                enumMethods++;
                assertEquals(method.getName(), method.invoke(defaults), method.invoke(proxy));
                for (Object value : method.getReturnType().getEnumConstants())
                {
                    String stored = (String) encode.invoke(manager, value);
                    assertEquals(((Enum<?>) value).name(), stored);
                    setProperty.invoke(data, OsrsStrategistConfig.GROUP + "."
                            + method.getAnnotation(ConfigItem.class).keyName(), stored);
                    invalidate.invoke(handler);
                    assertSame(value, method.invoke(proxy));
                }
            }
            assertEquals(5, enumMethods);
        }
        finally
        {
            executor.shutdownNow();
        }
    }
}

package compass;

import java.util.Collections;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ContentAccessRulesTest extends CatalogHostTest
{
    @Test
    public void f2pAllowsCoreFreeSkillsAndBlocksMembersSkills()
    {
        assertTrue(ContentAccessRules.isSkillAvailable(
                Skill.MINING,
                Membership.F2P
        ));
        assertTrue(ContentAccessRules.isSkillAvailable(
                Skill.RUNECRAFT,
                Membership.F2P
        ));

        assertFalse(ContentAccessRules.isSkillAvailable(
                Skill.FARMING,
                Membership.F2P
        ));
        assertFalse(ContentAccessRules.isSkillAvailable(
                Skill.HERBLORE,
                Membership.F2P
        ));
        assertFalse(ContentAccessRules.isSkillAvailable(
                Skill.SAILING,
                Membership.F2P
        ));
    }

    @Test
    public void p2pAllowsMembersSkills()
    {
        assertTrue(ContentAccessRules.isSkillAvailable(
                Skill.FARMING,
                Membership.P2P
        ));
        assertTrue(ContentAccessRules.isSkillAvailable(
                Skill.SAILING,
                Membership.P2P
        ));
    }

    @Test
    public void f2pBlocksMembersActivityInsideFreeSkill()
    {
        TrainingMethod motherlode = method(
                "mining_mlm",
                Skill.MINING,
                false
        );
        TrainingMethod normalOre = method(
                "mining_ore",
                Skill.MINING,
                false
        );

        assertFalse(ContentAccessRules.isMethodAvailable(
                motherlode,
                Membership.F2P
        ));
        assertTrue(ContentAccessRules.isMethodAvailable(
                normalOre,
                Membership.F2P
        ));
        assertTrue(ContentAccessRules.isMethodAvailable(
                motherlode,
                Membership.P2P
        ));
    }

    @Test
    public void explicitMembersOnlyFlagIsFutureProof()
    {
        TrainingMethod futureMembersMethod = method(
                "future_members_method",
                Skill.MINING,
                true
        );

        assertFalse(ContentAccessRules.isMethodAvailable(
                futureMembersMethod,
                Membership.F2P
        ));
        assertTrue(ContentAccessRules.isMethodAvailable(
                futureMembersMethod,
                Membership.P2P
        ));
    }

    private static TrainingMethod method(
            String id,
            Skill skill,
            boolean membersOnly)
    {
        return new TrainingMethod(
                id,
                skill,
                1,
                99,
                id,
                "test",
                1,
                1,
                1,
                AttentionLevel.MODERATE,
                10,
                1,
                Collections.emptyList(),
                Confidence.VERIFIED,
                membersOnly, false, false
        );
    }
}

package compass;

import java.util.Map;
import net.runelite.api.Skill;

/** Development-time machine-readable census entry point. */
public final class ContentCensusReporter extends CatalogHostTest
{
    private ContentCensusReporter() { }

    public static void main(String[] args)
    {
        QuestRequirementCensus quests = new QuestRequirementCensus();
        TrainingMethodCensus training = new TrainingMethodCensus();
        StashUnitCensus stash = new StashUnitCensus();
        DiaryTaskCatalog diaries = new DiaryTaskCatalog();
        TransportCatalog transports = new TransportCatalog();
        StringBuilder output = new StringBuilder();
        boolean includeUnresolved = args.length == 0
                || !"--summary".equals(args[0]);
        output.append("{\n  \"quests\": {")
                .append("\n    \"total\": ").append(quests.getTotalQuests())
                .append(",\n    \"withItemRequirements\": ").append(quests.getQuestsWithItemRequirements())
                .append(",\n    \"fullyExecutableOrVerifiedNone\": ").append(quests.getFullyExecutable())
                .append(",\n    \"partiallyExecutable\": ").append(quests.getPartiallyExecutable())
                .append(",\n    \"rawOnly\": ").append(quests.getRawOnly())
                .append(",\n    \"unsupportedExpressions\": ").append(quests.getUnsupportedExpressions())
                .append(",\n    \"explicitCheckExpressions\": ").append(quests.getExplicitCheckExpressions())
                .append(",\n    \"parseFailures\": ").append(quests.getParseFailures())
                .append(",\n    \"sourceMissingFields\": ").append(quests.getSourceMissingFields());
        if (!quests.getRawOnlyQuests().isEmpty())
        {
            output.append(",\n    \"rawOnlyQuests\": [");
            for (int index = 0; index < quests.getRawOnlyQuests().size(); index++)
            {
                if (index > 0) output.append(',');
                output.append('\"').append(json(quests.getRawOnlyQuests().get(index)))
                        .append('\"');
            }
            output.append(']');
        }
        if (!includeUnresolved)
        {
            output.append("\n  },");
            appendTraining(output, training);
            output.append(',');
            appendStash(output, stash);
            output.append(',');
            appendDiaries(output, diaries);
            output.append(',');
            appendTransports(output, transports);
            output.append(',');
            appendCombatAndAcquisition(output);
            output.append("\n}");
            System.out.println(output);
            return;
        }
        output.append(",\n    \"unresolved\": [");
        boolean first = true;
        for (QuestRequirementCensus.Unresolved entry : quests.getUnresolved())
        {
            if (!first) output.append(',');
            first = false;
            output.append("\n      {\"quest\":\"").append(json(entry.getQuest()))
                    .append("\",\"field\":\"").append(json(entry.getField()))
                    .append("\",\"rawEvidence\":\"").append(json(entry.getRawEvidence()))
                    .append("\",\"reason\":\"").append(json(entry.getReason()))
                    .append("\"}");
        }
        if (!first) output.append('\n');
        output.append("    ]\n  },");
        appendTraining(output, training);
        output.append(',');
        appendStash(output, stash);
        output.append(',');
        appendDiaries(output, diaries);
        output.append(',');
        appendTransports(output, transports);
        output.append(',');
        appendCombatAndAcquisition(output);
        output.append("\n}");
        System.out.println(output);
    }

    private static void appendDiaries(StringBuilder output,
            DiaryTaskCatalog diaries)
    {
        int requirements = 0;
        int alternativeChecks = 0;
        int transportTasks = 0;
        for (DiaryTaskDefinition task : diaries.all())
        {
            requirements += task.getRequirements().size();
            if (DiaryTaskCensusSupport.transportRelevant(task)) transportTasks++;
            for (DiaryTaskRequirement requirement : task.getRequirements())
                if (requirement.getKind()
                        == DiaryTaskRequirement.Kind.ALTERNATIVE_CHECK)
                    alternativeChecks++;
        }
        output.append("\n  \"diaryTasks\": {")
                .append("\n    \"regions\": ").append(DiaryTaskCensusSupport.census(diaries).size())
                .append(",\n    \"tiers\": 48")
                .append(",\n    \"tasks\": ").append(diaries.all().size())
                .append(",\n    \"structuredRequirements\": ")
                .append(requirements - alternativeChecks)
                .append(",\n    \"alternativeChecks\": ")
                .append(alternativeChecks)
                .append(",\n    \"transportRelevantTasks\": ")
                .append(transportTasks)
                .append("\n  }");
    }

    private static void appendTransports(StringBuilder output,
            TransportCatalog transports)
    {
        output.append("\n  \"transportSystems\": {")
                .append("\n    \"systems\": ").append(transports.all().size())
                .append(",\n    \"categories\": ")
                .append(TransportCategory.values().length)
                .append(",\n    \"reusableFanOutUses\": ")
                .append(transports.all().stream()
                        .mapToInt(TransportDefinition::getFanOut).sum())
                .append("\n  }");
    }

    private static void appendCombatAndAcquisition(StringBuilder output)
    {
        SlayerTaskIdentityCatalog slayerIdentities =
                new SlayerTaskIdentityCatalog();
        SlayerTaskProfileCatalog slayerProfiles =
                new SlayerTaskProfileCatalog();
        int mapped = 0;
        for (SlayerTaskIdentity identity : slayerIdentities.all())
            if (slayerProfiles.profileFor(identity.getAssignment()) != null)
                mapped++;
        int aliases = slayerProfiles.all().stream()
                .mapToInt(profile -> profile.getAliases().size()).sum();
        PvmActivityCatalog activities = new PvmActivityCatalog();
        PvmPreparationProfileCatalog preparation =
                new PvmPreparationProfileCatalog();
        output.append("\n  \"combatAndAcquisition\": {")
                .append("\n    \"pvmIdentities\": ")
                .append(activities.all().size())
                .append(",\n    \"pvmPreparationProfiles\": ")
                .append(preparation.all().size())
                .append(",\n    \"pvmLocallyVerifiedProfiles\": ")
                .append(new PvmEvidenceProfileCatalog().size())
                .append(",\n    \"slayerCanonicalIdentities\": ")
                .append(slayerIdentities.all().size())
                .append(",\n    \"slayerMappedIdentities\": ")
                .append(mapped)
                .append(",\n    \"slayerProfiles\": ")
                .append(slayerProfiles.all().size())
                .append(",\n    \"slayerAliases\": ").append(aliases)
                .append(",\n    \"gearAcquisitionTargets\": ")
                .append(new GearAcquisitionCatalog().all().size())
                .append(",\n    \"gearContextLadders\": ")
                .append(new GearProgressionCatalog().all().size())
                .append(",\n    \"deterministicResourceDefinitions\": ")
                .append(new ResourceDependencyCatalog().size())
                .append(",\n    \"accountAwareResourceSourceFamilies\": ")
                .append(new ResourceSourceCatalog().all().size())
                .append("\n  }");
    }

    private static void appendStash(StringBuilder output,
            StashUnitCensus stash)
    {
        output.append("\n  \"stashUnits\": {")
                .append("\n    \"total\": ").append(stash.getTotal())
                .append(",\n    \"missingEvidence\": ")
                .append(stash.getMissingEvidence())
                .append(",\n    \"wilderness\": ")
                .append(stash.getWildernessUnits())
                .append(",\n    \"byTier\": {");
        boolean first = true;
        for (Map.Entry<ClueTier, Integer> entry : stash.getByTier().entrySet())
        {
            if (!first) output.append(',');
            first = false;
            output.append("\n      \"")
                    .append(entry.getKey().name().toLowerCase())
                    .append("\": ").append(entry.getValue());
        }
        if (!first) output.append('\n');
        output.append("    }\n  }");
    }

    private static void appendTraining(StringBuilder output,
            TrainingMethodCensus training)
    {
        output.append("\n  \"trainingMethods\": {")
                .append("\n    \"skills\": ").append(training.getSkillCount())
                .append(",\n    \"curatedMethods\": ")
                .append(training.getCuratedMethodCount())
                .append(",\n    \"runeLiteActions\": ")
                .append(training.getRuneLiteActionCount())
                .append(",\n    \"skillsWithRuneLiteActions\": ")
                .append(training.getSkillsWithRuneLiteActions())
                .append(",\n    \"duplicateIds\": ")
                .append(training.getDuplicateIds())
                .append(",\n    \"invalidMethods\": ")
                .append(training.getInvalidMethods().size())
                .append(",\n    \"perSkill\": {");
        boolean first = true;
        for (Map.Entry<Skill, TrainingMethodCensus.SkillCoverage> entry
                : training.getBySkill().entrySet())
        {
            if (!first) output.append(',');
            first = false;
            TrainingMethodCensus.SkillCoverage value = entry.getValue();
            output.append("\n      \"").append(entry.getKey().getName())
                    .append("\": {\"curated\":")
                    .append(value.getCuratedMethods())
                    .append(",\"runeLiteActions\":")
                    .append(value.getRuneLiteActions()).append('}');
        }
        if (!first) output.append('\n');
        output.append("    }\n  }");
    }

    private static String json(String value)
    {
        return value == null ? "" : value.replace("\\", "\\\\")
                .replace("\"", "\\\"").replace("\n", "\\n")
                .replace("\r", "\\r");
    }
}

package compass;

import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class ContentCoverageManifestTest extends CatalogHostTest
{
    @Test
    public void everyRuneLiteQuestIdentityHasAnExplicitDisposition()
    {
        QuestKnowledgeCatalog knowledge = new QuestKnowledgeCatalog();
        assertEquals(Quest.values().length, knowledge.all().size());
        assertEquals(211, knowledge.all().size());
        assertEquals(0, knowledge.all().values().stream()
                .filter(QuestDefinition::hasFieldUncertainty).count());
        assertNotNull(knowledge.definitionFor("Watchtower"));
        assertNotNull(knowledge.definitionFor("Enter the Abyss"));
    }

    @Test
    public void minigameCensusHasNoSilentOrDuplicateEntries()
    {
        MinigameCoverageManifest manifest = new MinigameCoverageManifest();
        assertEquals(43, manifest.all().size());
        assertUniqueAndExplained(manifest.all());
        assertTrue(manifest.all().stream().anyMatch(entry ->
                entry.getName().equals("Burthorpe Games Room")
                        && entry.getState() == ContentCoverageState.NOT_PROGRESSION_RELEVANT));
        assertEquals(42, count(manifest.all(), ContentCoverageState.STRUCTURED));
        assertEquals(0, count(manifest.all(), ContentCoverageState.CONSERVATIVE_FAIL_CLOSED));
        assertEquals(1, count(manifest.all(), ContentCoverageState.NOT_PROGRESSION_RELEVANT));
    }

    @Test
    public void everyRuneLiteHiscoreBossHasAnExplicitCoverageState()
    {
        PvmCoverageManifest manifest = new PvmCoverageManifest();
        assertEquals(new PvmActivityCatalog().all().size(), manifest.all().size());
        assertEquals(71, manifest.all().size());
        assertUniqueAndExplained(manifest.all());
        assertEquals(4, count(manifest.all(), ContentCoverageState.STRUCTURED));
        assertEquals(67, count(manifest.all(), ContentCoverageState.PARTIAL_PREPARATION));
        assertEquals(0, count(manifest.all(), ContentCoverageState.CONSERVATIVE_FAIL_CLOSED));
        assertEquals(71, new PvmPreparationProfileCatalog().all().size());
    }

    @Test
    public void diaryAndTransportCensusesHaveNoSilentCoverageGaps()
    {
        DiaryTaskCatalog diaries = new DiaryTaskCatalog();
        assertEquals(378, diaries.all().size());
        assertEquals(12, DiaryTaskCensusSupport.census(diaries).size());
        assertEquals(48, DiaryTaskCensusSupport.census(diaries).values().stream()
                .mapToInt(Map::size).sum());

        TransportCatalog transports = new TransportCatalog();
        assertEquals(41, transports.all().size());
        assertEquals(TransportCategory.values().length,
                transports.all().stream().map(TransportDefinition::getCategory)
                        .collect(java.util.stream.Collectors.toSet()).size());
        assertEquals(41, ids(transports.all().stream()
                .map(TransportDefinition::getId).toArray(String[]::new)).size());
    }

    @Test
    public void catalogIdentitiesAreUnique()
    {
        Set<String> questNames = new HashSet<>();
        for (Quest quest : Quest.values()) questNames.add(quest.getName());
        for (QuestDefinition definition : new QuestKnowledgeCatalog().all().values())
            assertTrue("quest definition is not a RuneLite identity: "
                    + definition.getName(), questNames.contains(definition.getName()));

        Set<String> minigameCensusIds = new HashSet<>();
        for (ContentCoverageEntry entry : new MinigameCoverageManifest().all())
            minigameCensusIds.add(entry.getId());
        for (MinigameDefinition definition : new MinigameCatalog().all())
            assertTrue("minigame definition is absent from census: "
                    + definition.getId(), minigameCensusIds.contains(definition.getId()));

        assertEquals(new MinigameCatalog().all().size(),
                ids(new MinigameCatalog().all().stream()
                        .map(MinigameDefinition::getId).toArray(String[]::new)).size());
        assertEquals(new SlayerTaskProfileCatalog().all().size(),
                ids(new SlayerTaskProfileCatalog().all().stream()
                        .map(SlayerTaskProfile::getId).toArray(String[]::new)).size());
        // RuneLite's DB-backed Slayer task rows can lead its older plugin Task
        // enum when newly released assignments arrive (currently Venators).
        assertEquals(147, new SlayerTaskProfileCatalog().all().size());

        SlayerTaskIdentityCatalog canonical = new SlayerTaskIdentityCatalog();
        assertEquals(151, canonical.all().size());
        for (SlayerTaskIdentity identity : canonical.all())
            assertNotNull(identity.getAssignment(),
                    new SlayerTaskProfileCatalog().profileFor(
                            identity.getAssignment()));

        Set<String> aliases = new HashSet<>();
        for (SlayerTaskProfile profile : new SlayerTaskProfileCatalog().all())
            for (String alias : profile.getAliases())
                assertTrue("duplicate Slayer alias: " + alias,
                        aliases.add(alias.toLowerCase(java.util.Locale.ROOT).trim()));
        assertEquals(230, aliases.size());
    }

    private static void assertUniqueAndExplained(List<ContentCoverageEntry> entries)
    {
        Set<String> ids = new HashSet<>();
        for (ContentCoverageEntry entry : entries)
        {
            assertTrue(ids.add(entry.getId()));
            assertNotNull(entry.getState());
            assertFalse(entry.getReason().trim().isEmpty());
            assertFalse(entry.getProvenance().trim().isEmpty());
        }
    }

    private static long count(List<ContentCoverageEntry> entries,
            ContentCoverageState state)
    {
        return entries.stream().filter(entry -> entry.getState() == state).count();
    }

    private static Set<String> ids(String... values)
    {
        Set<String> result = new HashSet<>();
        java.util.Collections.addAll(result, values);
        return result;
    }
}

