package compass;

import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DiaryTaskCatalogTest extends CatalogHostTest
{
    @Test
    public void allTwelveRegionsAndFortyEightTiersHaveTaskEvidence()
    {
        DiaryTaskCatalog catalog = new DiaryTaskCatalog();
        assertEquals(378, catalog.all().size());
        assertEquals(12, DiaryTaskCensusSupport.census(catalog).size());
        int tiers = 0;
        int requirements = 0;
        int transports = 0;
        for (Map<DiaryTier, Integer> region : DiaryTaskCensusSupport.census(catalog).values())
        {
            assertEquals(4, region.size());
            tiers += region.size();
            for (Integer count : region.values()) assertTrue(count > 0);
        }
        for (DiaryTaskDefinition task : catalog.all())
        {
            assertFalse(task.getTask().trim().isEmpty());
            requirements += task.getRequirements().size();
            if (DiaryTaskCensusSupport.transportRelevant(task)) transports++;
        }
        assertEquals(48, tiers);
        assertTrue(requirements > 250);
        assertTrue(transports > 20);
    }

    @Test
    public void directSkillAndQuestEvidenceRemainStructured()
    {
        DiaryTaskCatalog catalog = new DiaryTaskCatalog();
        DiaryTaskDefinition teleport = catalog.forTier("Ardougne",
                DiaryTier.MEDIUM).stream()
                .filter(task -> task.getTask().contains("Ardougne Teleport"))
                .findFirst().orElseThrow(AssertionError::new);
        assertTrue(teleport.getRequirements().stream().anyMatch(requirement ->
                requirement.getKind() == DiaryTaskRequirement.Kind.SKILL
                        && requirement.getLevel() == 51));
        assertTrue(teleport.getRequirements().stream().anyMatch(requirement ->
                requirement.getKind() == DiaryTaskRequirement.Kind.QUEST
                        && "Plague City".equals(requirement.getQuest())));
        assertTrue(DiaryTaskCensusSupport.transportRelevant(teleport));
    }

}

package compass;

import java.util.LinkedHashMap;
import java.util.Map;

final class DiaryTaskCensusSupport
{
    private DiaryTaskCensusSupport() { }

    static Map<String, Map<DiaryTier, Integer>> census(DiaryTaskCatalog catalog)
    {
        Map<String, Map<DiaryTier, Integer>> result = new LinkedHashMap<>();
        for (DiaryTaskDefinition task : catalog.all())
        {
            Map<DiaryTier, Integer> tiers = result.computeIfAbsent(
                    task.getRegion(), key -> new LinkedHashMap<>());
            tiers.put(task.getTier(), tiers.getOrDefault(task.getTier(), 0) + 1);
        }
        return result;
    }

    static boolean transportRelevant(DiaryTaskDefinition task)
    {
        String value = task.getTask().toLowerCase(java.util.Locale.ROOT);
        return value.contains("teleport") || value.contains("travel")
                || value.contains("fairy ring") || value.contains("glider")
                || value.contains("balloon") || value.contains("boat")
                || value.contains("minecart");
    }
}

