import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FeedbackRecoveryTest extends CatalogHostTest
{
    @Test
    public void resetActionIsSecondaryExplainedAndConfirmed() throws Exception
    {
        Method method = OsrsStrategistConfig.class.getMethod(
                "resetLearnedFeedback");
        ConfigItem item = method.getAnnotation(ConfigItem.class);
        assertEquals("Reset learned feedback", item.name());
        assertEquals(OsrsStrategistConfig.advancedSection, item.section());
        assertTrue(item.description().contains("current character only"));
        assertTrue(item.description().contains("bank observations"));
        assertFalse(item.warning().trim().isEmpty());

        Field sectionField = OsrsStrategistConfig.class.getField(
                "advancedSection");
        ConfigSection section = sectionField.getAnnotation(ConfigSection.class);
        assertTrue(section.closedByDefault());
    }

    @Test
    public void resetClearsOnlyCurrentCharacterLearningAndForcesRefresh()
            throws Exception
    {
        OsrsStrategistPlugin plugin = new OsrsStrategistPlugin();
        RecordingPreferenceStore store = new RecordingPreferenceStore(
                "character-a");
        set(plugin, "accountProfileStore", store);
        set(plugin, "loadedProfileKey", "character-a");
        set(plugin, "latestRecommendations", Collections.singletonList(
                recommendation()));

        PreferenceProfile preferences = (PreferenceProfile) get(
                plugin, "preferenceProfile");
        preferences.apply("skill:mining", FeedbackAction.DISLIKE);
        RecommendationHistory history = (RecommendationHistory) get(
                plugin, "recommendationHistory");
        history.add("skill:mining", "Train Mining",
                RecommendationHistoryAction.COMPLETED);

        assertTrue(plugin.resetLearnedFeedbackForActiveCharacter());

        assertEquals(1, store.clearCount);
        assertEquals("character-a", store.clearedProfile);
        assertTrue(preferences.snapshot().isEmpty());
        assertTrue(preferences.cooldownSnapshot().isEmpty());
        assertEquals(1, history.snapshot().size());
        assertTrue(((java.util.List<?>) get(plugin,
                "latestRecommendations")).isEmpty());
        assertTrue(plugin.consumeStrategyRefreshPending(10_000L));
    }

    @Test
    public void resetWithoutACharacterDoesNothing() throws Exception
    {
        OsrsStrategistPlugin plugin = new OsrsStrategistPlugin();
        RecordingPreferenceStore store = new RecordingPreferenceStore(null);
        set(plugin, "accountProfileStore", store);

        assertFalse(plugin.resetLearnedFeedbackForActiveCharacter());
        assertEquals(0, store.clearCount);
    }

    private static Recommendation recommendation()
    {
        return new Recommendation("skill:mining", "Mine copper to level 2",
                "Safe start.", 1.0, null,
                Confidence.VERIFIED, 1, 2,
                new Guidance("Mine copper and drop it when full.",
                        "Bronze pickaxe.",
                        "East Lumbridge Swamp mine.", null),
                Safety.harmless(true));
    }

    private static Object get(Object target, String name) throws Exception
    {
        Field field = OsrsStrategistPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }

    private static void set(Object target, String name, Object value)
            throws Exception
    {
        Field field = OsrsStrategistPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static final class RecordingPreferenceStore
            extends AccountProfileStore
    {
        private final String profile;
        private int clearCount;
        private String clearedProfile;

        private RecordingPreferenceStore(String profile)
        {
            super((net.runelite.client.config.ConfigManager) null, new Gson());
            this.profile = profile;
        }

        @Override
        public String activeProfileKey()
        {
            return profile;
        }

        @Override
        public void loadPreferences(PreferenceProfile preferenceProfile)
        {
            // Tests seed the active in-memory profile directly.
        }

        @Override
        public void clearPreferences()
        {
            clearCount++;
            clearedProfile = profile;
        }
    }
}

package compass;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

public class FeedbackTortureTest extends CatalogHostTest
{
    private final RecommendationDeduplicator deduplicator =
            new RecommendationDeduplicator();

    @Test
    public void laterNotTodayAndDislikeSuppressEverySemanticAliasImmediately()
    {
        for (FeedbackAction action : Arrays.asList(FeedbackAction.LATER,
                FeedbackAction.NOT_TODAY, FeedbackAction.DISLIKE))
        {
            Recommendation displayed = ready("quest-prereq:agility-70",
                    "Train Agility to 70", 50);
            Recommendation alias = ready("diary-prereq:agility-70",
                    "Train Agility to 70", 50);
            Recommendation unrelated = ready("skill:mining",
                    "Train Mining to 71", 30);
            PreferenceProfile profile = new PreferenceProfile();
            String semantic = deduplicator.semanticKey(displayed);
            profile.applySemantic(semantic, action);

            List<Recommendation> queue = engine().buildPlayerQueue(
                    Arrays.asList(alias, unrelated), context(profile));
            assertEquals(action.name(), "skill:mining", queue.get(0).getId());
            assertFalse(action.name(), queue.stream().anyMatch(value ->
                    value.getTitle().equals("Train Agility to 70")));
            if (action == FeedbackAction.DISLIKE)
                assertTrue(profile.semanticWeightFor(semantic) < 0.0);
            else
                assertEquals(0.0, profile.semanticWeightFor(semantic), 0.0);
        }
    }

    @Test
    public void accountSwitchAndReturnRestoresOnlyTheCorrectFeedbackState()
    {
        Recommendation action = ready("skill:fishing",
                "Train Fishing to 71", 40);
        String semantic = deduplicator.semanticKey(action);

        PreferenceProfile accountA = new PreferenceProfile();
        accountA.applySemantic(semantic, FeedbackAction.DISLIKE);
        Map<String, Double> aWeights = accountA.snapshot();
        Map<String, Long> aCooldowns = accountA.cooldownSnapshot();

        PreferenceProfile accountB = new PreferenceProfile();
        assertEquals(0.0, accountB.semanticWeightFor(semantic), 0.0);
        assertFalse(accountB.isSemanticOnCooldown(semantic));
        accountB.applySemantic(deduplicator.semanticKey(ready("skill:mining",
                "Train Mining to 71", 40)), FeedbackAction.DISLIKE);
        assertEquals(0.0, accountB.semanticWeightFor(semantic), 0.0);

        PreferenceProfile returnedA = new PreferenceProfile();
        returnedA.replaceAll(aWeights);
        returnedA.replaceCooldowns(aCooldowns);
        assertEquals(accountA.semanticWeightFor(semantic),
                returnedA.semanticWeightFor(semantic), 0.0);
        assertTrue(returnedA.isSemanticOnCooldown(semantic));
    }

    private static StrategyEngine engine()
    {
        return TestFixtures.strategyEngine(null, null, null, null,
                new ActionabilityPolicy(),
                new RecommendationIntelligenceService());
    }

    private static StrategyContext context(PreferenceProfile profile)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 70);
            xp.put(skill, 0);
        }
        AccountSnapshot account = new AccountSnapshot("Feedback", 700L, 0,
                "MAIN", Membership.P2P, 1,
                70 * Skill.values().length, 0L, levels, xp);
        return new StrategyContext(GameData.builder(account).build(),
                StrategyMode.BALANCED, SessionIntent.PICK_FOR_ME,
                QuestTolerance.NORMAL, GoalType.MAX, false, false, profile);
    }

    private static Recommendation ready(String id, String title, double score)
    {
        Skill skill = title.contains("Agility") ? Skill.AGILITY
                : title.contains("Fishing") ? Skill.FISHING : Skill.MINING;
        TrainingMethod method = new TrainingMethod(id + ":method", skill,
                1, 99, title, "Use the method.", 1, 1, 1,
                AttentionLevel.LOW, 20, 2, Collections.emptyList(),
                Confidence.VERIFIED);
        return new Recommendation(id, title, "Useful account progress.", score,
                new TrainingPlan(method, "Useful account progress.",
                        Confidence.VERIFIED, Collections.emptyList()),
                Confidence.VERIFIED, 70, 71,
                new Guidance("Do it now.",
                        "Setup verified.", "Safe location.", "Useful."),
                Safety.skill(false, skill));
    }
}

