                70, 70, 70, 70, 70, 70, 80, 1);
        assertOnlyFallback(evaluate(combatOnly, candidate("future:farming",
                Safety.skill(false, Skill.FARMING))));

        for (AccountSnapshot restricted : java.util.Arrays.asList(
                account(Membership.P2P, 1, 1, 60, 1, 1, 1, 70, 50),
                account(Membership.P2P, 1, 1, 1, 1, 1, 1, 10, 50),
                account(Membership.P2P, 1, 1, 1, 1, 20, 1, 10, 50),
                account(Membership.P2P, 1, 1, 1, 20, 1, 20, 10, 50)))
        {
