    }

    @Test
    public void completesWithoutAnyButtonPressAtTarget()
    {
        TrackedMilestone tracked = new TrackedMilestone(
                "skill:farming",
                "Train Farming to 10",
                Skill.FARMING.name(),
                1,
                10,
                false
        );

        MilestoneCompletion completion = tracker.detectCompletion(
                tracked,
                accountWithFarming(10)
