import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ProgressAnalyticsServiceTest extends CatalogHostTest
{
    @Test
    public void absoluteXpEventsNeedABaselineAndNeverCreateNegativeProgress()
    {
        ProgressAnalyticsService service = new ProgressAnalyticsService();
        service.reset(1_000L);

        assertFalse(service.record(new StatChanged(
                Skill.MINING, 1_000, 10, 10), 2_000L));
        assertTrue(service.record(new StatChanged(
                Skill.MINING, 1_125, 11, 11), 3_000L));
        assertFalse(service.record(Skill.MINING, 1_000, 10, 4_000L));
        assertFalse(service.record(Skill.MINING, -1, 10, 5_000L));
        assertFalse(service.record(Skill.MINING, 200_000_001, 10, 5_000L));

        SkillSessionProgress progress = service.snapshot(6_000L)
                .getSkills().get(Skill.MINING);
        assertEquals(0, progress.getXpGained());
        assertEquals(10, progress.getCurrentLevel());
    }

    @Test
    public void tracksSessionTotalsLevelsActiveTimeAndMeasuredRate()
    {
        ProgressAnalyticsService service = new ProgressAnalyticsService();
        service.beginSession(account(Skill.FISHING, 10, 1_000), 1_000L);

        service.record(Skill.FISHING, 1_050, 10, 11_000L);
        service.record(Skill.FISHING, 1_150, 11, 26_000L);
        ProgressSessionSnapshot calculating = service.snapshot(26_000L);
        assertFalse(calculating.getSkills().get(Skill.FISHING)
                .getRate().isReady());

        service.record(Skill.FISHING, 1_250, 12, 46_000L);
        ProgressSessionSnapshot ready = service.snapshot(46_000L);

        assertEquals(250L, ready.getTotalXpGained());
        assertEquals(2, ready.getLevelsGained());
        assertEquals(35_000L, ready.getActiveDurationMillis());
        XpRateEstimate rate = ready.getSkills().get(Skill.FISHING).getRate();
        assertTrue(rate.isReady());
        assertEquals(20_571L, rate.getXpPerHour());
    }

    @Test
    public void idleGapIsNotActiveTrainingAndForcesRateToRecalculate()
    {
        ProgressAnalyticsService service = readyService();
        long before = service.snapshot(46_000L).getActiveDurationMillis();

        service.record(Skill.FISHING, 1_300, 12,
                46_000L + ProgressAnalyticsService.IDLE_GAP_MILLIS + 1L);
        ProgressSessionSnapshot after = service.snapshot(
                46_000L + ProgressAnalyticsService.IDLE_GAP_MILLIS + 1L);

        assertEquals(before, after.getActiveDurationMillis());
        assertFalse(after.getSkills().get(Skill.FISHING)
                .getRate().isReady());
    }

    @Test
    public void crossSkillOutOfOrderEventsCannotInflateTimeOrReorderBuckets()
    {
        ProgressAnalyticsService service = new ProgressAnalyticsService();
        service.beginSession(account(Skill.FISHING, 10, 1_000), 1_000L);
        assertTrue(service.record(Skill.FISHING, 1_100, 10, 61_000L));
        assertFalse(service.record(Skill.MINING, 100, 2, 60_000L));
        assertTrue(service.record(Skill.FISHING, 1_200, 10, 62_000L));

        ProgressSessionSnapshot snapshot = service.snapshot(62_000L);
        assertEquals(1_000L, snapshot.getActiveDurationMillis());
        assertEquals(1, snapshot.getBuckets().size());
    }

    @Test
    public void lowerAbsoluteXpClearsPriorAccountSessionEvidence()
    {
        ProgressAnalyticsService service = readyService();
        service.setTarget(new ProgressTarget("skill:fishing", "fly-fishing",
                Skill.FISHING, 20));
        service.recordMilestone(new ProgressMilestone("quest:test",
                ProgressMilestoneType.QUEST, "Test complete", null, null,
                46_000L));

        assertFalse(service.record(Skill.FISHING, 500, 5, 47_000L));
        ProgressSessionSnapshot snapshot = service.snapshot(47_000L);

        assertEquals(0L, snapshot.getTotalXpGained());
        assertEquals(0L, snapshot.getActiveDurationMillis());
        assertTrue(snapshot.getBuckets().isEmpty());
        assertTrue(snapshot.getMilestones().isEmpty());
        assertEquals(TargetProjection.State.NO_TARGET,
                snapshot.getTargetProjection().getState());
    }

    @Test
    public void logoutPauseRetainsGainsButNeverCountsOfflineGap()
    {
        ProgressAnalyticsService service = readyService();
        long activeBefore = service.snapshot(46_000L).getActiveDurationMillis();

        service.pause(47_000L);
        service.record(Skill.FISHING, 1_350, 12, 107_000L);
        ProgressSessionSnapshot snapshot = service.snapshot(107_000L);

        assertEquals(350L, snapshot.getTotalXpGained());
        assertEquals(activeBefore, snapshot.getActiveDurationMillis());
        assertFalse(snapshot.getSkills().get(Skill.FISHING).getRate().isReady());
    }

    @Test
    public void targetEtaIsSafeAndMethodChangeRebasesMeasuredRate()
    {
        ProgressAnalyticsService service = readyService();
        service.setTarget(new ProgressTarget("skill:fishing", "fly-fishing",
                Skill.FISHING, 11));

        TargetProjection projection = service.snapshot(46_000L)
                .getTargetProjection();
        assertEquals(TargetProjection.State.READY,
                projection.getState());
        assertEquals(Math.max(0, Experience.getXpForLevel(11) - 1_250),
                projection.getXpRemaining());
        assertTrue(projection.getEtaMillis() > 0L);

        service.setTarget(new ProgressTarget("skill:fishing", "lobsters",
                Skill.FISHING, 12));
        assertEquals(TargetProjection.State.CALCULATING,
                service.snapshot(46_000L).getTargetProjection().getState());
    }

    @Test
    public void switchingToAnotherSkillCannotReuseAnUnrelatedOldRate()
    {
        ProgressAnalyticsService service = readyService();
        service.setTarget(new ProgressTarget("skill:fishing", "fly-fishing",
                Skill.FISHING, 11));
        service.record(Skill.MINING, 1_000, 10, 47_000L);
        service.record(Skill.MINING, 1_100, 10, 62_000L);
        service.record(Skill.MINING, 1_200, 10, 82_000L);
        service.setTarget(new ProgressTarget("skill:mining", "iron-ore",
                Skill.MINING, 11));

        assertEquals(TargetProjection.State.CALCULATING,
                service.snapshot(82_000L).getTargetProjection().getState());
    }

    @Test
    public void completedTargetHasZeroEtaEvenWithoutRateEvidence()
    {
        ProgressAnalyticsService service = new ProgressAnalyticsService();
        int levelTwoXp = Experience.getXpForLevel(2);
        service.beginSession(account(Skill.COOKING, 2, levelTwoXp), 1_000L);
        service.setTarget(new ProgressTarget("skill:cooking", "fish",
                Skill.COOKING, 2));

        TargetProjection projection = service.snapshot(1_000L)
                .getTargetProjection();
        assertEquals(TargetProjection.State.COMPLETE,
                projection.getState());
        assertEquals(0L, projection.getEtaMillis());
    }

    @Test
    public void bucketsAndMilestonesRemainBoundedAndDeduplicated()
    {
        ProgressAnalyticsService service = new ProgressAnalyticsService();
        service.beginSession(account(Skill.WOODCUTTING, 1, 0), 0L);
        int xp = 0;
        for (int index = 0; index < 400; index++)
        {
            xp++;
            service.record(Skill.WOODCUTTING, xp, 1,
                    1L + index * ProgressAnalyticsService.BUCKET_MILLIS);
        }
        ProgressMilestone same = new ProgressMilestone("quest:test",
                ProgressMilestoneType.QUEST, "Test quest", null, null, 1L);
        assertTrue(service.recordMilestone(same));
        assertFalse(service.recordMilestone(same));

        ProgressSessionSnapshot snapshot = service.snapshot(
                400L * ProgressAnalyticsService.BUCKET_MILLIS);
        assertEquals(ProgressAnalyticsService.MAX_BUCKETS,
                snapshot.getBuckets().size());
        assertEquals(1, snapshot.getMilestones().size());
    }

    private static ProgressAnalyticsService readyService()
    {
        ProgressAnalyticsService service = new ProgressAnalyticsService();
        service.beginSession(account(Skill.FISHING, 10, 1_000), 1_000L);
        service.record(Skill.FISHING, 1_050, 10, 11_000L);
        service.record(Skill.FISHING, 1_150, 11, 26_000L);
        service.record(Skill.FISHING, 1_250, 12, 46_000L);
        return service;
    }

    private static AccountSnapshot account(
            Skill changed, int level, int xp)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 1);
            experience.put(skill, 0);
        }
        levels.put(changed, level);
        experience.put(changed, xp);
        return new AccountSnapshot("Tester", 0L, 0, "Main", Membership.UNKNOWN, 0, 1, xp, levels, experience);
    }
}

package compass;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ProgressHistoryTest extends CatalogHostTest
{
    private final Gson gson = new Gson();

    @Test
    public void codecRoundTripsCompactProgressWithoutRawEvents()
    {
        ProgressHistory history = populatedHistory();
        String json = ProgressHistoryCodec.encode(gson, history);
        ProgressHistory decoded = ProgressHistoryCodec.decode(gson, json);

        assertEquals(1, decoded.getSessions().size());
        assertEquals(250L,
                decoded.getSessions().get(0).getTotalXpGained());
        assertEquals(Integer.valueOf(250), decoded.getSessions().get(0)
                .getXpBySkill().get(Skill.FISHING));
        assertEquals(1, decoded.getMilestones().size());
        assertEquals(1, decoded.getBuckets().size());
        assertEquals(1, decoded.getSessions().get(0).getMilestones().size());
        assertFalse(json.contains("rateIntervals"));
    }

    @Test
    public void versionOneHistoryStillLoadsWithoutInventedSessionMilestones()
    {
        ProgressHistory decoded = ProgressHistoryCodec.decode(gson,
                "{\"schemaVersion\":1,\"sessions\":[{"
                        + "\"startedAtMillis\":1,\"endedAtMillis\":2,"
                        + "\"activeDurationMillis\":1,\"totalXpGained\":1,"
                        + "\"levelsGained\":0,\"xpBySkill\":{\"MINING\":1}}],"
                        + "\"milestones\":[],\"buckets\":[]}");

        assertEquals(1, decoded.getSessions().size());
        assertTrue(decoded.getSessions().get(0).getMilestones().isEmpty());
    }

    @Test
    public void persistenceSortsAndMergesDuplicateTimelineEntries()
    {
        ProgressHistory history = new ProgressHistory();
        ProgressSessionSummary duplicate = new ProgressSessionSummary(
                20, 30, 10, 5, 0,
                Collections.singletonMap(Skill.MINING, 5));
        List<ProgressTimeBucket> buckets = new ArrayList<>();
        buckets.add(new ProgressTimeBucket(20,
                Collections.singletonMap(Skill.MINING, 3)));
        buckets.add(new ProgressTimeBucket(10,
                Collections.singletonMap(Skill.FISHING, 2)));
        buckets.add(new ProgressTimeBucket(20,
                Collections.singletonMap(Skill.MINING, 4)));
        ProgressMilestone milestone = new ProgressMilestone("quest:test",
                ProgressMilestoneType.QUEST, "Test complete", null, null, 20);

        history.replaceAll(java.util.Arrays.asList(duplicate, duplicate),
                java.util.Arrays.asList(milestone, milestone), buckets);

        assertEquals(1, history.getSessions().size());
        assertEquals(1, history.getMilestones().size());
        assertEquals(2, history.getBuckets().size());
        assertEquals(10L, history.getBuckets().get(0).getStartedAtMillis());
        assertEquals(7, history.getBuckets().get(1).getTotalXp());
    }

    @Test
    public void checkpointDoesNotCloseOrMutateLiveHistory()
    {
        ProgressAnalyticsService service = new ProgressAnalyticsService();
        service.reset(1L);
        service.record(Skill.MINING, 100, 2, 1L);
        service.record(Skill.MINING, 200, 3, 2L);
        ProgressHistory live = new ProgressHistory();

        ProgressHistory checkpoint = live.checkpoint(service.snapshot(2L));

        assertTrue(live.getSessions().isEmpty());
        assertEquals(1, checkpoint.getSessions().size());
        assertEquals(100L,
                checkpoint.getSessions().get(0).getTotalXpGained());
    }

    @Test
    public void corruptOrUnknownPersistenceFailsClosed()
    {
        assertTrue(ProgressHistoryCodec.decode(gson, "not json")
                .getSessions().isEmpty());
        assertTrue(ProgressHistoryCodec.decode(gson,
                "{\"schemaVersion\":99,\"sessions\":[{}]}")
                .getSessions().isEmpty());
        assertTrue(ProgressHistoryCodec.decode(gson,
                "{\"schemaVersion\":1,\"sessions\":[{"
                        + "\"startedAtMillis\":10,\"endedAtMillis\":1,"
                        + "\"activeDurationMillis\":99,"
                        + "\"totalXpGained\":-5,\"levelsGained\":-1}],"
                        + "\"milestones\":[],\"buckets\":[]}")
                .getSessions().isEmpty());
    }

    @Test
    public void archiveBoundsAllPersistentCollections()
    {
        ProgressHistory history = new ProgressHistory();
        List<ProgressSessionSummary> sessions = new ArrayList<>();
        List<ProgressMilestone> milestones = new ArrayList<>();
        List<ProgressTimeBucket> buckets = new ArrayList<>();
        for (int index = 0; index < 400; index++)
        {
            sessions.add(new ProgressSessionSummary(index, index + 1,
                    1, 1, 0, Collections.singletonMap(Skill.MINING, 1)));
            milestones.add(new ProgressMilestone("m:" + index,
                    ProgressMilestoneType.PLAN_STEP, "Step " + index,
                    null, null, index));
            buckets.add(new ProgressTimeBucket(index,
                    Collections.singletonMap(Skill.MINING, 1)));
        }
        history.replaceAll(sessions, milestones, buckets);

        assertEquals(ProgressHistory.MAX_SESSIONS,
                history.getSessions().size());
        assertEquals(ProgressHistory.MAX_MILESTONES,
                history.getMilestones().size());
        assertEquals(ProgressHistory.MAX_BUCKETS,
                history.getBuckets().size());
        assertEquals(370L, history.getSessions().get(0).getStartedAtMillis());
    }

    @Test
    public void storeUsesActiveRuneLiteProfileAndNeverLeaksAcrossCharacters()
    {
        FakeProfileConfiguration config = new FakeProfileConfiguration();
        AccountProfileStore store = new AccountProfileStore(config, gson);

        config.active = "alice";
        store.saveProgress(populatedHistory());
        config.active = "bob";
        assertTrue(store.loadProgress().getSessions().isEmpty());
        store.saveProgress(new ProgressHistory());
        config.active = "alice";
        assertEquals(1, store.loadProgress().getSessions().size());

        config.active = null;
        store.saveProgress(populatedHistory());
        assertEquals(2, config.values.size());
    }

    private ProgressHistory populatedHistory()
    {
        ProgressAnalyticsService service = new ProgressAnalyticsService();
        service.reset(1_000L);
        service.record(Skill.FISHING, 1_000, 10, 1_000L);
        service.record(Skill.FISHING, 1_250, 12, 2_000L);
        service.recordMilestone(new ProgressMilestone("quest:test",
                ProgressMilestoneType.QUEST, "Test quest complete", null,
                "goal:test", 2_000L));
        ProgressHistory history = new ProgressHistory();
        history.archive(service.snapshot(2_000L));
        return history;
    }

    private static final class FakeProfileConfiguration
            implements AccountProfileStore.ProfileConfiguration
    {
        private final Map<String, String> values = new HashMap<>();
        private String active;

        public String activeProfileKey() { return active; }
        public String get(String group, String key)
        {
            return values.get(active + ":" + group + ":" + key);
        }
        public void set(String group, String key, String value)
        {
            values.put(active + ":" + group + ":" + key, value);
        }
        public void unset(String group, String key)
        {
            values.remove(active + ":" + group + ":" + key);
        }
    }
}

