    @Test
    public void emptyStateRendersWithoutFakeRateOrEta()
    {
        ProgressViewPanel panel = new ProgressViewPanel();
        panel.setSnapshot(null);
        paint(panel, 220, 420);

        assertEquals("0 XP", panel.sessionXp.getText());
        assertEquals("No progress this session", panel.sessionMeta.getText());
        assertEquals("No active skill target", panel.target.getText());
    }

    @Test
    public void lastSessionRecapUsesBoundedCharacterHistory()
    {
        ProgressHistory history = new ProgressHistory();
        history.replaceAll(Collections.singletonList(
                new ProgressSessionSummary(0L, 3_600_000L, 2_400_000L,
                        87_420L, 3,
                        Collections.singletonMap(Skill.FISHING, 87_420))),
                Collections.emptyList(), Collections.emptyList());
        ProgressViewPanel panel = new ProgressViewPanel();
        panel.setHistory(history);
        paint(panel, 220, 520);

        assertTrue(panel.lastSession.getText().contains("+87,420 XP"));
        assertTrue(panel.lastSession.getText().contains("3 levels"));
        assertTrue(panel.lastSession.getText().contains("Fishing +87,420"));
    }

    @Test
    public void milestoneOnlySessionRecapShowsAccountProgress()
    {
        ProgressMilestone milestone = new ProgressMilestone(
                "infrastructure:poh-fairy-ring",
                ProgressMilestoneType.INFRASTRUCTURE,
                "POH upgrade: fairy ring", null, GoalType.AUTOMATIC.name(),
                10L);
        ProgressSessionSummary summary = new ProgressSessionSummary(
                0L, 10L, 0L, 0L, 0, Collections.emptyMap(),
                Collections.singletonList(milestone));
        ProgressHistory history = new ProgressHistory();
        history.replaceAll(Collections.singletonList(summary),
                Collections.singletonList(milestone), Collections.emptyList());
        ProgressViewPanel panel = new ProgressViewPanel();

        panel.setHistory(history);

        assertTrue(panel.lastSession.getText().contains("+0 XP"));
        assertTrue(panel.lastSession.getText().contains(
                "Account progress: POH upgrade: fairy ring"));
    }

    @Test
    public void planProgressCountIncludesCurrentAndTargetSteps()
    {
        StrategicPlan plan = new StrategicPlan(GoalType.BARROWS_GLOVES,
                account(), Arrays.asList(
                        step("skill", "Fishing 49 → 53"),
                        step("quest", "Heroes' Quest"),
                        step("goal", "Barrows gloves")), 2, 1L);
        ProgressViewPanel panel = new ProgressViewPanel();

        panel.setPlan(plan);

        assertTrue(panel.planPath.getText().contains("Step 3 of 3"));
    }

    private static StrategicPlanStep step(String id, String objective)
    {
        return new StrategicPlanStep(id, GoalNodeKind.ACTIVITY, objective,
                "Proven path", CompletionRule.none(), null);
    }

    private static AccountSnapshot account()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 70);
            xp.put(skill, 0);
        }
        return new AccountSnapshot("Progress", 7L, 0, "MAIN",
                Membership.P2P, 1, 70 * Skill.values().length,
                0L, levels, xp);
    }

    private static void paint(ProgressViewPanel panel, int width, int height)
    {
        panel.setSize(width, height);
        panel.doLayout();
        BufferedImage image = new BufferedImage(width, height,
                BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            panel.paint(graphics);
        }
        finally
        {
            graphics.dispose();
        }
    }
}

package compass;

import java.util.Collections;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ProgressionObjectiveServiceTest extends CatalogHostTest
{
    private final MilestoneTracker service =
            new MilestoneTracker(new ProgressionObjectiveCatalog());

    @Test
    public void unknownCollectionStateConservativelyProtectsGracefulGrind()
    {
        TrainingPlan plan = new TrainingPlan(method("agility_rooftop"), "test",
                Confidence.VERIFIED, Collections.emptyList());
        assertTrue(service.protect(plan.method(), null));
    }

    @Test
    public void explicitlyCompletedObjectiveStopsProtection()
    {
        TrainingPlan plan = new TrainingPlan(method("agility_rooftop"), "test",
                Confidence.VERIFIED, Collections.emptyList());
        CollectionLogSnapshot log = new CollectionLogSnapshot(
                Collections.emptySet(),
                Collections.singleton("objective:graceful"),
                Collections.emptyMap(), Collections.emptyMap()
        );
        assertFalse(service.protect(plan.method(), log));
    }

    private static TrainingMethod method(String id)
    {
        for (Skill skill : Skill.values())
        {
            for (TrainingMethod method : new TrainingMethodDatabase().methodsFor(skill))
            {
                if (id.equals(method.getId())) return method;
            }
        }
        throw new AssertionError("Missing method " + id);
    }
}

