    /**
     * The no-ItemManager test adapter keeps RuneLite's maintained names, levels,
     * XP, and icons while supplying the already route-gated account membership.
     * Membership leakage is covered independently by the production policy
     * matrices; this census measures whether concrete rendering survives the
     * final quality boundary.
     */
    private static final class CensusSkillActionCatalog
            extends RuneLiteSkillActionCatalog
    {
        private final Membership membership;

        private CensusSkillActionCatalog(Membership membership)
        {
            this.membership = membership;
        }

        @Override
        public List<ActionDef> actionsFor(Skill skill)
        {
            List<ActionDef> result = new ArrayList<>();
            for (ActionDef action : super.actionsFor(skill))
            {
                result.add(new ActionDef(
                        action.getSkill(), action.getId(), action.getName(),
                        action.getLevel(), action.getXp(), action.getCategory(),
                        membership, action.getItemId()));
            }
            return result;
        }
    }

    private static GameData data(Scenario scenario, int level)
    {
        return data(scenario, level, false);
    }

    private static GameData data(Scenario scenario, int level,
            boolean prepared)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        int totalLevel = 0;
        long totalXp = 0;
        for (Skill skill : Skill.values())
        {
            int value = skill == Skill.HITPOINTS ? Math.max(10, level) : level;
            int valueXp = value <= 1 ? 0 : Experience.getXpForLevel(value);
            levels.put(skill, value);
            xp.put(skill, valueXp);
            totalLevel += value;
            totalXp += valueXp;
        }
        AccountSnapshot account = new AccountSnapshot(
                scenario.name, 10_000L + scenario.type, scenario.type,
                AccountMode.fromTypeCode(scenario.type).name(),
                scenario.membership,
                scenario.membership == Membership.P2P ? 1 : 0,
                totalLevel, totalXp, levels, xp);
        List<ItemState> items = prepared
                ? AccountMode.fromTypeCode(scenario.type)
                        == AccountMode.ULTIMATE_IRONMAN
                        ? uimPreparedItems() : preparedItems()
                : Collections.emptyList();
        GameData.Builder builder = GameData.builder(account)
                // Census scenarios model a complete live container, including
                // the observed-empty case. UIM generation must not confuse it
                // with a persisted list whose slot completeness is unknown.
                .inventory(new ItemsState(items, true))
                .equipment(new ItemsState(Collections.emptyList()));
        if (prepared)
        {
            builder.combatEvidence(new CombatEvidenceSnapshot(0,
                    Collections.emptySet(), false, false, false));
        }
        if (scenario.membership == Membership.P2P)
        {
            Map<String, Capability> tools = new HashMap<>();
            if (prepared)
            {
                tools.put("rake", Capability.VERIFIED);
                tools.put("dibber", Capability.VERIFIED);
                tools.put("spade", Capability.VERIFIED);
            }
            builder.farming(new FarmingSnapshot(
                    new HashSet<>(Collections.singletonList("falador")),
                    tools, Collections.emptyMap()));
            if (prepared)
            {
                Map<String, QuestStatus> quests = new HashMap<>();
                quests.put("Pandemonium", QuestStatus.COMPLETE);
                builder.quests(new QuestSnapshot(quests));
                builder.sailing(new SailingSnapshot(
                        new HashSet<>(java.util.Arrays.asList(
                                SailingSnapshot.PORT_SARIM,
                                SailingSnapshot.PORT_PANDEMONIUM)),
                        new HashSet<>(java.util.Arrays.asList(
                                SailingSnapshot.ACTIVITY_COURIER,
                                SailingSnapshot.ACTIVITY_SEA_CHARTING,
                                SailingSnapshot.ACTIVITY_BOAT_OWNED)),
                        Confidence.VERIFIED));
                Map<String, Capability> poh = new HashMap<>();
                poh.put("room:parlour", Capability.VERIFIED);
                poh.put("room:kitchen", Capability.VERIFIED);
                builder.poh(new PohSnapshot(Capability.VERIFIED, poh));
            }
        }
        if (scenario.type != 2)
        {
            builder.bank(new ItemsState(Collections.emptyList(), 1L));
        }
        return builder.build();
    }

