package compass;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class RecommendationDeduplicatorTest extends CatalogHostTest
{
    @Test
    public void sharedSkillPrerequisiteBecomesOneActionWithMultipleReasons()
    {
        Recommendation quest = skill("quest-prereq:agility-70",
                "Train Agility to 70", "Required by a quest.", 40);
        Recommendation diary = skill("diary-prereq:agility-70",
                "Train Agility to 70", "Also completes a diary requirement.", 42);
        Recommendation clue = skill("clue-prereq:agility-70",
                "Train Agility to 70", "Unlocks the active clue route.", 41);

        List<Recommendation> result = new RecommendationDeduplicator()
                .deduplicate(Arrays.asList(quest, diary, clue));
        assertEquals(1, result.size());
        assertTrue(result.get(0).getReason().contains("quest"));
        assertTrue(result.get(0).getReason().contains("diary"));
        assertTrue(result.get(0).getReason().contains("clue"));
        assertEquals(48.0, result.get(0).getScore(), 0.001);
    }

    @Test
    public void evidenceLevelsNeverMergeAcrossSafetyBoundary()
    {
        Recommendation verified = skill("skill:agility", "Train Agility to 70",
                "Verified route.", 30);
        Recommendation check = new Recommendation("diary:agility",
                "Train Agility to 70", "Access unknown.", 100, null,
                Confidence.CHECK_NEEDED, 60, 70,
                guidance(), Safety.harmless(false));
        assertEquals(2, new RecommendationDeduplicator()
                .deduplicate(Arrays.asList(verified, check)).size());
    }

    @Test
    public void orderingDoesNotChangeTieWinner()
    {
        Recommendation alpha = skill("skill:alpha", "Train Mining to 70",
                "One route.", 40);
        Recommendation beta = skill("skill:beta", "Train Fishing to 70",
                "Another route.", 40);
        StrategyEngine engine = TestFixtures.strategyEngine(null, null, null, null,
                new ActionabilityPolicy(),
                new RecommendationIntelligenceService());
        List<Recommendation> first = engine.buildPlayerQueue(
                Arrays.asList(beta, alpha), null);
        List<Recommendation> second = engine.buildPlayerQueue(
                Arrays.asList(alpha, beta), null);
        assertEquals(first.get(0).getId(), second.get(0).getId());
    }

    @Test
    public void skillAndMinigameVersionsOfSameLoopBecomeOneAction()
    {
        Recommendation skill = skillMethod("skill:firemaking",
                "Train Firemaking to 70", "firemaking_wintertodt", 40,
                "skill-breakpoint");
        Recommendation minigame = new Recommendation("minigame:wintertodt",
                "Wintertodt", "Pyromancer progression.", 42, null,
                Confidence.VERIFIED, 0, 0, guidance(),
                Safety.skill(false, Skill.FIREMAKING))
                .withStrategicValue(StrategicValue.builder()
                        .resourceFit(0.6).evidence("wintertodt-rewards").build());

        List<Recommendation> result = new RecommendationDeduplicator()
                .deduplicate(Arrays.asList(skill, minigame));

        assertEquals(1, result.size());
        assertTrue(result.get(0).getReason().contains("Pyromancer"));
        assertTrue(result.get(0).getStrategicValue().getEvidenceIds()
                .contains("skill-breakpoint"));
        assertTrue(result.get(0).getStrategicValue().getEvidenceIds()
                .contains("wintertodt-rewards"));
    }

    private static Recommendation skill(String id, String title,
            String reason, double score)
    {
        Skill skill = title.contains("Fishing") ? Skill.FISHING
                : title.contains("Mining") ? Skill.MINING : Skill.AGILITY;
        TrainingMethod method = new TrainingMethod(id + ":method", skill,
                1, 99, title, "Do the method.", 1, 1, 1,
                AttentionLevel.LOW, 20, 2, Collections.emptyList(),
                Confidence.VERIFIED);
        return new Recommendation(id, title, reason, score,
                new TrainingPlan(method, reason,
                        Confidence.VERIFIED, Collections.emptyList()),
                Confidence.VERIFIED, 60, 70, guidance(),
                Safety.skill(false, skill));
    }

    private static Recommendation skillMethod(String id, String title,
            String methodId, double score, String evidence)
    {
        TrainingMethod method = new TrainingMethod(methodId, Skill.FIREMAKING,
                1, 99, title, "Do the method.", 1, 1, 1,
                AttentionLevel.LOW, 20, 2, Collections.emptyList(),
                Confidence.VERIFIED);
        return new Recommendation(id, title, "Firemaking breakpoint.", score,
                new TrainingPlan(method, "route",
                        Confidence.VERIFIED, Collections.emptyList()),
                Confidence.VERIFIED, 60, 70, guidance(),
                Safety.skill(false, Skill.FIREMAKING))
                .withStrategicValue(StrategicValue.builder()
                        .unlockValue(0.5).evidence(evidence).build());
    }

    private static Guidance guidance()
    {
        return new Guidance("Do the action.",
                "Verified: setup available.", "Safe location.", "Useful.");
    }
}

package compass;

import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

/**
 * Guards the distinction between milestone variety and explicit snoozing.
 */
public class RecommendationEngineMilestoneTest extends CatalogHostTest
{
    @Test
    public void completedSkillRemainsEligibleDespiteLargeSoftPenalty()
    {
        TrainingMethodSelector selector = new TrainingMethodSelector(new TrainingMethodDatabase(), null, new TrainingMethodPolicy(), new MethodStrategyKnowledgeCatalog(), new UimInventoryResolutionService());
        RecommendationEngine engine = TestFixtures.recommendationEngine(selector);
        PreferenceProfile profile = new PreferenceProfile();

        profile.addTemporaryScoreAdjustment(
                "skill:farming",
                -1000.0,
                60_000L
        );

        // A completion adjustment is deliberately not a cooldown.
        assertFalse(profile.isOnCooldown("skill:farming"));

        List<Recommendation> recommendations = engine.recommendAll(
                GameData.builder(farmingOnlyAccount()).build(),
                StrategyMode.BALANCED,
                SessionIntent.PICK_FOR_ME,
                true, false,
                GoalType.AUTOMATIC,
                profile
        );

        assertEquals(1, recommendations.size());
        assertEquals(
                "skill:farming",
                recommendations.get(0).getId()
        );
    }

    private static AccountSnapshot farmingOnlyAccount()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> experience = new EnumMap<>(Skill.class);

        for (Skill skill : Skill.values())
        {
            levels.put(skill, 99);
            experience.put(skill, 0);
        }

        // Hitpoints is skipped by the recommendation engine either way.
        levels.put(Skill.FARMING, 10);

        return new AccountSnapshot("Test", 0L, 0, "Main", Membership.P2P, 1, 2200, 0L, levels, experience);
    }
}

package compass;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RecommendationGuidanceServiceTest extends CatalogHostTest
{
    private final RecommendationGuidanceService service =
            TestFixtures.recommendationGuidanceService();

    @Test
    public void mainAccountGetsExactGrandExchangeShortfall()
    {
        GameData data = GameData.builder(
                        account(0, 17, Experience.getXpForLevel(17)))
                .bank(bank(new ItemState(335, "Raw trout", 20)))
                .inventory(inventory(new ItemState(335, "Raw trout", 5)))
                .quests(completedCooksAssistant())
                .build();

        Guidance guidance = service.build(
                data,
                Skill.COOKING,
                17,
                20,
                fishPlan(), true
        );

        assertTrue(guidance.getAction().contains("20 successful cooks"));
        assertTrue(guidance.getSupplies().contains("about 50 raw trout"));
        assertTrue(guidance.getSupplies().contains("Verified: 25 raw trout"));
        assertTrue(guidance.getSupplies().contains("Buy 25 raw trout"));
        assertTrue(guidance.getSupplies().contains("Grand Exchange"));
        assertTrue(guidance.getLocation().contains("Lumbridge Castle range"));
    }

    @Test
    public void enoughVerifiedTroutDoesNotTellPlayerToBuyMore()
    {
        GameData data = GameData.builder(
                        account(0, 17, Experience.getXpForLevel(17)))
                .bank(bank(new ItemState(335, "Raw trout", 60)))
                .inventory(inventory())
                .build();

        Guidance guidance = service.build(
                data,
                Skill.COOKING,
                17,
                20,
                fishPlan(), true
        );

        assertTrue(guidance.getSupplies().contains("already have enough"));
        assertFalse(guidance.getSupplies().contains(" Buy "));
    }

    @Test
    public void unopenedBankIsUnknownNotEmpty()
    {
        GameData data = GameData.builder(
                        account(0, 17, Experience.getXpForLevel(17)))
                .inventory(inventory(new ItemState(335, "Raw trout", 4)))
                .build();

        Guidance guidance = service.build(
                data,
                Skill.COOKING,
                17,
                20,
                fishPlan(), true
        );

        assertTrue(guidance.getSupplies().contains("Open your bank once"));
        assertFalse(guidance.getSupplies().contains("Buy 50"));
    }

    @Test
    public void ironAccountSourcesMissingFishInsteadOfUsingGrandExchange()
    {
        GameData data = GameData.builder(
                        account(1, 17, Experience.getXpForLevel(17)))
                .bank(bank(new ItemState(335, "Raw trout", 20)))
                .inventory(inventory())
                .build();

        Guidance guidance = service.build(
                data,
                Skill.COOKING,
                17,
                20,
                fishPlan(), true
        );

        assertTrue(guidance.getSupplies().toLowerCase()
                .contains("source 30 raw trout"));
        assertTrue(guidance.getSupplies().contains("Barbarian Village"));
        assertFalse(guidance.getSupplies().contains("Grand Exchange"));
    }

    @Test
    public void partialLevelProgressUsesExactCurrentExperience()
    {
        GameData data = GameData.builder(
                        account(0, 19, 4000))
                .bank(bank())
                .inventory(inventory())
                .build();

        Guidance guidance = service.build(
                data,
                Skill.COOKING,
                19,
                20,
                fishPlan(), true
        );

        assertTrue(guidance.getAction().contains("7 successful cooks"));
        assertTrue(guidance.getSupplies().contains("about 18 raw trout"));
        assertTrue(guidance.getSupplies().contains("Buy 18 raw trout"));
    }

    @Test
    public void levelTwentyPlanStagesPikeThenSalmonToThirty()
    {
        GameData data = GameData.builder(
                        account(0, 20, Experience.getXpForLevel(20)))
                .bank(bank(
                        new ItemState(349, "Raw pike", 8),
                        new ItemState(331, "Raw salmon", 5)
                ))
                .inventory(inventory())
                .build();

        Guidance guidance = service.build(
                data,
                Skill.COOKING,
                20,
                30,
                fishPlan(), true
        );

        assertTrue(guidance.getAction().contains("pike to level 25"));
        assertTrue(guidance.getAction().contains("43 successful cooks"));
        assertTrue(guidance.getAction().contains("salmon to level 30"));
        assertTrue(guidance.getAction().contains("62 successful cooks"));
        assertTrue(guidance.getSupplies().contains("about 108 raw pike"));
        assertTrue(guidance.getSupplies().contains("about 155 raw salmon"));
        assertTrue(guidance.getSupplies().contains("Buy 100 raw pike and 150 raw salmon"));
    }

    private static TrainingPlan fishPlan()
    {
        TrainingMethod method = new TrainingMethod(
                "cooking_f2p_fish",
                Skill.COOKING,
                1,
                99,
                "Cook fish",
                "Generic catalog text should be replaced by account guidance.",
                10,
                10,
                10,
                AttentionLevel.LOW,
                20,
                2,
                Collections.emptyList(),
                Confidence.VERIFIED
        );
        return new TrainingPlan(
                method,
                "test",
                Confidence.VERIFIED,
                Collections.emptyList()
        );
    }

    private static AccountSnapshot account(
            int typeCode,
            int cookingLevel,
            int cookingXp)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 99);
            xp.put(skill, 0);
        }
        levels.put(Skill.COOKING, cookingLevel);
        xp.put(Skill.COOKING, cookingXp);

        return new AccountSnapshot("Guidance Test", 0L, typeCode, typeCode == 0 ? "Main" : "Ironman", Membership.F2P, 1, 2200, cookingXp, levels, xp);
    }

    private static ItemsState bank(ItemState... items)
    {
        return new ItemsState(
                items == null || items.length == 0
                        ? Collections.emptyList()
                        : Arrays.asList(items),
                System.currentTimeMillis()
        );
    }

    private static ItemsState inventory(ItemState... items)
    {
        return new ItemsState(
                items == null || items.length == 0
                        ? Collections.emptyList()
                        : Arrays.asList(items)
        );
    }

    private static QuestSnapshot completedCooksAssistant()
    {
        Map<String, QuestStatus> quests = new HashMap<>();
        quests.put("Cook's Assistant", QuestStatus.COMPLETE);
        return new QuestSnapshot(quests);
    }
}

