package compass;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class RecommendationIntelligenceServiceTest extends CatalogHostTest
{
    private final RecommendationIntelligenceService service =
            new RecommendationIntelligenceService();

    @Test
    public void gearGoalCanBeatHigherRawSkillingScore()
    {
        StrategyContext context = context(
                account(Membership.P2P, 0, 80),
                GoalType.GEAR_TARGET,
                SessionIntent.PICK_FOR_ME);

        Recommendation skill = recommendation(
                "skill:mining", "Train Mining to 90", 60.0,
                Skill.MINING, 80, 90, 2, 30, AttentionLevel.MODERATE);
        Recommendation gear = new Recommendation(
                "upgrade:dragon-defender",
                "Get a Dragon defender",
                "Permanent melee upgrade.",
                40.0,
                null,
                Confidence.VERIFIED,
                0,
                0,
                guidance("Enter the Warriors' Guild and obtain the defender."));

        gear = gear.withGoalProvenance(GoalProvenance.direct(
                GoalType.GEAR_TARGET, gear.getId(), java.util.Arrays.asList(
                        "Gear target", "Dragon defender")));
        assertTrue(service.rankScore(gear, context)
                > service.rankScore(skill, context));
    }

    @Test
    public void quickSessionPrefersLowSetupMethod()
    {
        StrategyContext context = context(
                account(Membership.P2P, 0, 70),
                GoalType.MAX,
                SessionIntent.QUICK_20_MIN);

        Recommendation quick = recommendation(
                "skill:fishing", "Train Fishing", 40.0,
                Skill.FISHING, 70, 80, 2, 15, AttentionLevel.LOW);
        Recommendation setupHeavy = recommendation(
                "skill:construction", "Train Construction", 45.0,
                Skill.CONSTRUCTION, 70, 80, 15, 60, AttentionLevel.ACTIVE);

        assertTrue(service.rankScore(quick, context)
                > service.rankScore(setupHeavy, context));
    }

    @Test
    public void uimStronglyPenalizesHighSetupTraining()
    {
        StrategyContext context = context(
                account(Membership.P2P, 2, 70),
                GoalType.MAX,
                SessionIntent.PICK_FOR_ME);

        Recommendation light = recommendation(
                "skill:fishing", "Train Fishing", 40.0,
                Skill.FISHING, 70, 80, 2, 20, AttentionLevel.LOW);
        Recommendation heavy = recommendation(
                "skill:construction", "Train Construction", 46.0,
                Skill.CONSTRUCTION, 70, 80, 15, 20, AttentionLevel.ACTIVE);

        assertTrue(service.rankScore(light, context)
                > service.rankScore(heavy, context));
    }

    @Test
    public void slayer85GoalDominatesGenericSkillProgress()
    {
        StrategyContext context = context(
                account(Membership.P2P, 1, 75),
                GoalType.SLAYER_85,
                SessionIntent.LONG_SESSION);

        Recommendation slayer = recommendation(
                "skill:slayer", "Train Slayer to 80", 35.0,
                Skill.SLAYER, 75, 80, 4, 60, AttentionLevel.MODERATE);
        Recommendation mining = recommendation(
                "skill:mining", "Train Mining to 80", 58.0,
                Skill.MINING, 75, 80, 1, 60, AttentionLevel.LOW);

        slayer = new GoalDependencyProvenanceService().attach(slayer, context);
        mining = new GoalDependencyProvenanceService().attach(mining, context);
        assertTrue(service.rankScore(slayer, context)
                > service.rankScore(mining, context));
    }

    @Test
    public void typedRiskChangesRankButWildernessWordingDoesNot()
    {
        StrategyContext context = context(
                account(Membership.P2P, 0, 85),
                GoalType.GEAR_TARGET,
                SessionIntent.LONG_SESSION);
        Recommendation wildernessWording = new Recommendation(
                "pvm:revenants",
                "Kill revenants",
                "Fast Wilderness money and drops.",
                999.0,
                null,
                Confidence.VERIFIED,
                0,
                0,
                guidance("Enter the Wilderness revenant caves."));
        Recommendation neutralWording = new Recommendation(
                "upgrade:fighter-torso",
                "Get a Fighter torso",
                "Safe account upgrade.",
                999.0,
                null,
                Confidence.VERIFIED,
                0,
                0,
                guidance("Play Barbarian Assault."));

        assertEquals(service.rankScore(neutralWording, context),
                service.rankScore(wildernessWording, context), 0.001);

        Recommendation typedRisk = wildernessWording.withStrategicValue(
                StrategicValue.builder()
                        .riskBurden(1.0)
                        .evidence("risk:wilderness")
                        .build());
        assertTrue(service.rankScore(neutralWording, context)
                > service.rankScore(typedRisk, context));
    }

    @Test
    public void relaxedModePricesAttentionAndSetupReuseNotNames()
    {
        StrategyContext context = context(
                account(Membership.P2P, 0, 85),
                GoalType.AUTOMATIC,
                SessionIntent.PICK_FOR_ME,
                StrategyMode.RELAXED);
        Recommendation lowAttention = recommendation(
                "opaque:a", "Intense-sounding route", 40.0,
                Skill.FISHING, 85, 90, 3, 30, AttentionLevel.LOW)
                .withStrategicValue(StrategicValue.builder()
                        .setupReuse(0.75)
                        .evidence("test:setup-reuse")
                        .build());
        Recommendation active = recommendation(
                "opaque:b", "Relaxed AFK best method", 44.0,
                Skill.FISHING, 85, 90, 3, 30, AttentionLevel.ACTIVE);

        assertTrue(service.rankScore(lowAttention, context)
                > service.rankScore(active, context));
    }

    @Test
    public void efficientModePricesTypedUnlockAndSharedDependencyValue()
    {
        StrategyContext context = context(
                account(Membership.P2P, 0, 70),
                GoalType.AUTOMATIC,
                SessionIntent.PICK_FOR_ME,
                StrategyMode.EFFICIENT);
        Recommendation useful = recommendation(
                "opaque:a", "Ordinary route", 40.0,
                Skill.AGILITY, 70, 72, 4, 30, AttentionLevel.MODERATE)
                .withStrategicValue(StrategicValue.builder()
                        .unlockValue(0.8)
                        .sharedDependencyValue(0.7)
                        .evidence("test:typed-account-value")
                        .build());
        Recommendation proseOnly = recommendation(
                "opaque:b", "Best efficient unlock for many goals", 45.0,
                Skill.AGILITY, 70, 72, 4, 30, AttentionLevel.MODERATE);

        assertTrue(service.rankScore(useful, context)
                > service.rankScore(proseOnly, context));
    }

    private static Recommendation recommendation(
            String id,
            String title,
            double score,
            Skill skill,
            int current,
            int target,
            int setupMinutes,
            int minimumMinutes,
            AttentionLevel attention)
    {
        TrainingMethod method = new TrainingMethod(
                id + ":method",
                skill,
                1,
                99,
                title,
                "Use the method.",
                10,
                10,
                10,
                attention,
                minimumMinutes,
                setupMinutes,
                Collections.emptyList(),
                Confidence.VERIFIED,
                true,
                false,
                false);
        return new Recommendation(
                id,
                title,
                "Account progression.",
                score,
                new TrainingPlan(method, "test",
                        Confidence.VERIFIED,
                        Collections.emptyList()),
                Confidence.VERIFIED,
                current,
                target,
                guidance("Do the selected training method."));
    }

    private static Guidance guidance(String action)
    {
        return new Guidance(
                action,
                "Verified: required setup is available.",
                "Safe reachable location.",
                "Account-safe route.");
    }

    private static StrategyContext context(
            AccountSnapshot account,
            GoalType goal,
            SessionIntent intent)
    {
        return context(account, goal, intent, StrategyMode.BALANCED);
    }

    private static StrategyContext context(
            AccountSnapshot account,
            GoalType goal,
            SessionIntent intent,
            StrategyMode mode)
    {
        GameData data = GameData.builder(account)
                .bank(new ItemsState(Collections.emptyList(), 1L))
                .inventory(new ItemsState(Collections.emptyList()))
                .equipment(new ItemsState(Collections.emptyList()))
                .build();
        return new StrategyContext(
                data,
                mode,
                intent,
                QuestTolerance.NORMAL,
                goal,
                true,
                false,
                false,
                new PreferenceProfile());
    }

    private static AccountSnapshot account(
            Membership membership,
            int typeCode,
            int level)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        int total = 0;
        long totalXp = 0L;
        for (Skill skill : Skill.values())
        {
            int effective = skill == Skill.HITPOINTS ? Math.max(10, level) : level;
            levels.put(skill, effective);
            int skillXp = effective <= 1 ? 0 : Experience.getXpForLevel(effective);
            xp.put(skill, skillXp);
            total += effective;
            totalXp += skillXp;
        }
        return new AccountSnapshot("Intelligence Test", 0L, typeCode, AccountMode.fromTypeCode(typeCode).name(), membership, membership == Membership.P2P ? 1 : 0, total, totalXp, levels, xp);
    }
}

package compass;

import java.util.Collections;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RecommendationPresentationCompactTest extends CatalogHostTest
{
    @Test
    public void sidebarUsesRequestedMethodAndNeededHierarchy()
    {
        Recommendation recommendation = recommendationWithMethodAndMissingRequirement();
        String text = Presentation.compactText(recommendation);
        assertTrue(text.contains("METHOD"));
        assertTrue(text.contains("NEEDED"));
        assertFalse(text.contains("NEXT UNLOCK"));
        assertFalse(text.contains("BEST METHOD"));
        assertFalse(text.contains("NEEDS INFO"));
    }

    @Test
    public void nonSkillCardsUseActivityHierarchyAndNeverExposeDebugCopy()
    {
        Recommendation recommendation = new Recommendation(
                "stash:master:very-long", "Build the current Master STASH unit",
                "Avoid repeated clue inventory setup after the unit is observed built.",
                40, null, Confidence.CHECK_NEEDED, 0, 0,
                new Guidance(
                        "Open the Construction interface at the exact STASH location and verify built state.",
                        "Bring the verified flatpack materials only after the live built-state check.",
                        "The active clue location.",
                        "Built state remains unknown."));
        String compact = Presentation.compactText(recommendation);
        assertTrue(compact.contains("ACTIVITY"));
        assertTrue(compact.contains("BRING"));
        assertTrue(compact.contains("WHERE"));
        assertTrue(compact.contains("DO"));
        assertFalse(compact.contains("NEXT UNLOCK"));
        assertFalse(compact.contains("Strategist will verify"));
        assertFalse(compact.contains("policy class"));
    }
    @Test
    public void compactCardDoesNotDumpFullPlannerParagraphs()
    {
        String longAction = "Cook 1,234 sharks at the range after withdrawing them in batches. "
                + "This second sentence contains intentionally detailed execution notes that belong in Details instead of the narrow sidebar.";
        String longSupplies = "Verified: you own 900 raw sharks in the bank, 100 in inventory, and need 234 more. "
                + "Buy the remaining fish and keep several other detailed accounting notes in the full overlay.";
        Recommendation recommendation = recommendation(longAction, longSupplies);

        String compact = Presentation.compactText(recommendation);
        String details = Presentation.detailedText(recommendation);

        assertTrue(compact.contains("Verified: you own 900 raw sharks"));
        assertFalse(compact.contains("intentionally detailed execution notes"));
        assertFalse(compact.contains("several other detailed accounting notes"));
        assertFalse(details.contains("intentionally detailed execution notes"));
        assertFalse(details.contains("several other detailed accounting notes"));
        assertTrue(details.contains("CURRENT STEP"));
        assertTrue(details.length() < 500);
    }

    @Test
    public void verifiedDetailsDoNotMislabelCarriedSetupAsMissing()
    {
        Recommendation verified = recommendation(
                "Cook the carried fish and bank the output.",
                "Carry the observed raw salmon.");
        String details = Presentation.detailedText(verified);

        assertTrue(details.contains("WHERE"));
        assertFalse(details.contains("NEEDED"));
        assertTrue(details.contains("CURRENT STEP"));
    }

    @Test
    public void compactSentenceNeverCutsIntoHugeWordWallBeyondBudget()
    {
        String value = "This is useful compact text followed by a very long explanation that should be shortened without destroying the full details presentation.";
        String compact = Presentation.compactSentence(value, 60);
        assertTrue(compact.length() <= 61);
        assertTrue(compact.endsWith("…") || compact.endsWith("."));
    }

    @Test
    public void longPlayerFacingContentStaysCompactAndKeepsHierarchy()
    {
        String longName = "Complete The Fremennik Isles using the verified Neitiznot travel and equipment preparation route";
        Recommendation recommendation = recommendation(
                longName + ". Bring the required quest items and follow the marked route.",
                "A very long required item name, food, teleport, and quest prerequisite list that must wrap inside the RuneLite sidebar.");

        String compact = Presentation.compactText(recommendation);
        assertTrue(compact.contains("METHOD"));
        assertTrue(compact.contains("BRING"));
        assertTrue(compact.contains("WHERE"));
        assertTrue(compact.contains("DO"));
        assertFalse(compact.contains("Compass will verify"));
        assertFalse(compact.contains("policy class"));
    }

    private static Recommendation recommendation(String action, String supplies)
    {
        TrainingMethod method = new TrainingMethod(
                "cooking_test", Skill.COOKING, 1, 99,
                "Cook banked food", "Cook the selected food.",
                10, 10, 10, AttentionLevel.MODERATE,
                20, 2, Collections.emptyList(),
                Confidence.VERIFIED);
        TrainingPlan plan = new TrainingPlan(
                method, "test", Confidence.VERIFIED,
                Collections.emptyList());
        return new Recommendation(
                "skill:cooking", "Train Cooking to 80", "Useful progression.",
                50.0, plan, Confidence.VERIFIED,
                70, 80,
                new Guidance(
                        action, supplies,
                        "Use the best verified range.",
                        "Detailed note that belongs in Details."));
    }

    private static Recommendation recommendationWithMethodAndMissingRequirement()
    {
        TrainingMethod method = new TrainingMethod(
                "cooking_test", Skill.COOKING, 1, 99,
                "Cook banked food", "Cook the selected food.",
                10, 10, 10, AttentionLevel.MODERATE,
                20, 2, Collections.emptyList(),
                Confidence.CHECK_NEEDED);
        EvidenceCheck check = new EvidenceCheck(
                "access:range", "Verify range access",
                RequirementState.CHECK_NEEDED, "No range access observation yet.");
        TrainingPlan plan = new TrainingPlan(method, "test",
                Confidence.CHECK_NEEDED,
                Collections.singletonList(check));
        return new Recommendation(
                "skill:cooking", "Train Cooking", "Useful progression.",
                50.0, plan, Confidence.CHECK_NEEDED,
                70, 80, null);
    }
}

package compass;

import java.util.Arrays;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Protects the compact-sidebar UX from accidentally becoming a wall of text
 * while also ensuring Needs Info always tells the player what is unresolved.
 */
public class RecommendationPresentationTest extends CatalogHostTest
{
    @Test
    public void compactViewHidesDeepExplanation()
    {
        Recommendation recommendation = recommendation();

        String compact = Presentation.compactHtml(
                recommendation
        );

        assertTrue(compact.contains("METHOD"));
        assertTrue(compact.contains("NEEDED"));
        assertTrue(compact.contains("Planks/materials"));
        assertFalse(compact.contains("WHY IT MATTERS"));
        assertFalse(compact.contains("HOW"));
        assertFalse(compact.contains("Current:"));
        assertFalse(compact.contains("Verified POH access"));
        assertTrue("Compact copy should stay short", compact.length() < 450);
    }

    @Test
    public void detailedViewKeepsOnlyDecisionCriticalSections()
    {
        String detailed = Presentation.detailedHtml(
                recommendation()
        );

        assertTrue(detailed.contains("WHY"));
        assertTrue(detailed.contains("NEEDED"));
        assertTrue(detailed.contains("CURRENT STEP"));
        assertTrue(detailed.contains("Planks/materials"));
        assertFalse(detailed.contains("Need to confirm materials"));
        assertFalse(detailed.contains("Verified POH access"));
        assertTrue(detailed.length() < 500);
    }

    private static Recommendation recommendation()
    {
        TrainingMethod method = new TrainingMethod(
                "test-construction",
                Skill.CONSTRUCTION,
                1,
                99,
                "Practical furniture",
                "Build the best verified furniture route for the account.",
                10.0,
                10.0,
                10.0,
                AttentionLevel.MODERATE,
                10,
                2,
                Arrays.asList(
                        "POH access",
                        "Planks/materials",
                        "Transport"
                ),
                Confidence.CHECK_NEEDED
        );

        TrainingPlan plan = new TrainingPlan(
                method,
                "Selected for the current strategy style.",
                Confidence.CHECK_NEEDED,
                Arrays.asList(
                        new EvidenceCheck(
                                "poh",
                                "POH access",
                                RequirementState.VERIFIED,
                                "Verified POH access"
                        ),
                        new EvidenceCheck(
                                "planks",
                                "Planks/materials",
                                RequirementState.CHECK_NEEDED,
                                "Need to confirm materials"
                        ),
                        new EvidenceCheck(
                                "transport",
                                "Transport",
                                RequirementState.CHECK_NEEDED,
                                "Need to confirm transport"
                        )
                )
        );

        return new Recommendation(
                "skill:construction",
                "Train Construction to 10",
                "Builds useful POH progression.",
                50.0,
                plan,
                Confidence.CHECK_NEEDED,
                1,
                10,
                null
        );
    }
}

package compass;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class RecommendationStabilizerTest extends CatalogHostTest
{
    @Test
    public void minorRerankKeepsTheCurrentCheckpointSteady()
    {
        Recommendation oldTop = ready("skill:mining", "Train Mining to 50", 50);
        StrategyResult fresh = result(
                ready("skill:fishing", "Train Fishing to 50", 51),
                ready("skill:mining", "Train Mining to 50", 50));
        StrategyResult stable = new RecommendationStabilizer().stabilize(
                Collections.singletonList(oldTop), fresh);
        assertEquals("skill:mining", stable.getRecommendations().get(0).getId());
    }

    @Test
    public void incidentalXpInventoryBankAndUiRefreshesKeepCheckpointSteady()
    {
        String[] refreshes = {"XP tick", "inventory", "bank", "UI"};
        for (int i = 0; i < refreshes.length; i++)
        {
            Recommendation oldTop = ready(
                    "skill:mining", "Train Mining to 50", 50);
            Recommendation refreshed = ready(
                    "skill:mining", "Train Mining to 50", 49 - i);
            StrategyResult stable = new RecommendationStabilizer().stabilize(
                    Collections.singletonList(oldTop), result(
                            ready("skill:fishing", "Train Fishing to 50", 51),
                            refreshed));
            assertEquals(refreshes[i], "skill:mining",
                    stable.getRecommendations().get(0).getId());
            assertSame(refreshes[i], refreshed,
                    stable.getRecommendations().get(0));
        }
    }

    @Test
    public void completedCheckpointAdvancesInsteadOfBeingPinned()
    {
        Recommendation oldTop = ready("skill:mining", "Train Mining to 50", 50);
        StrategyResult fresh = result(
                ready("skill:fishing", "Train Fishing to 50", 51),
                ready("skill:mining", "Train Mining to 60", 50));
        StrategyResult stable = new RecommendationStabilizer().stabilize(
                Collections.singletonList(oldTop), fresh);
        assertEquals("skill:fishing", stable.getRecommendations().get(0).getId());
    }

    @Test
    public void dismissedRecommendationCannotBeResurrected()
    {
        Recommendation oldTop = ready("skill:mining", "Train Mining to 50", 50);
        StrategyResult fresh = result(
                ready("skill:fishing", "Train Fishing to 50", 51));
        StrategyResult stable = new RecommendationStabilizer().stabilize(
                Collections.singletonList(oldTop), fresh);
        assertEquals("skill:fishing", stable.getRecommendations().get(0).getId());
    }

    @Test
    public void materialInvalidationsCannotBeResurrected()
    {
        String[] causes = {"quest completed", "membership changed",
                "account changed", "method invalid", "Later", "Not Today",
                "Dislike", "required resource unavailable",
                "completion condition true"};
        for (String cause : causes)
        {
            Recommendation oldTop = ready(
                    "skill:mining", "Train Mining to 50", 50);
            StrategyResult stable = new RecommendationStabilizer().stabilize(
                    Collections.singletonList(oldTop), result(
                            ready("skill:fishing", "Train Fishing to 50", 51)));
            assertEquals(cause, "skill:fishing",
                    stable.getRecommendations().get(0).getId());
        }
    }

    @Test
    public void changedMethodGuidanceIsAppliedEvenWhenSkillStaysPinned()
    {
        Recommendation oldTop = skillPlan("skill:mining",
                "Train Mining to 50", 50, "mining_stars",
                "Mine the observed star.");
        Recommendation replacementMethod = skillPlan("skill:mining",
                "Train Mining to 50", 49, "mining_f2p_iron",
                "Mine iron and drop it when full.");

        StrategyResult stable = new RecommendationStabilizer().stabilize(
                Collections.singletonList(oldTop), result(
                        ready("skill:fishing", "Train Fishing to 50", 51),
                        replacementMethod));

        Recommendation top = stable.getRecommendations().get(0);
        assertSame(replacementMethod, top);
        assertEquals("mining_f2p_iron",
                top.getTrainingPlan().getMethod().getId());
        assertEquals("Mine iron and drop it when full.",
                top.getGuidance().getAction());
    }

    @Test
    public void resourceLossReplacesExecutionGuidanceImmediately()
    {
        Recommendation oldTop = skillPlan("skill:mining",
                "Train Mining to 50", 50, "mining_f2p_iron",
                "Mine iron and drop it when full.");
        Recommendation acquireTool = skillPlan("skill:mining",
                "Train Mining to 50", 49, "mining_f2p_iron",
                "Get a bronze pickaxe from the Mining tutor, then mine iron.");

        StrategyResult stable = new RecommendationStabilizer().stabilize(
                Collections.singletonList(oldTop), result(
                        ready("skill:fishing", "Train Fishing to 50", 51),
                        acquireTool));

        assertSame(acquireTool, stable.getRecommendations().get(0));
        assertTrue(stable.getRecommendations().get(0).getGuidance().getAction()
                .contains("Get a bronze pickaxe"));
    }

    @Test
    public void deliberateGoalAndAccountChangesBypassHysteresis()
    {
        for (String cause : new String[] {"goal changed", "account changed"})
        {
            StrategyResult changed = new RecommendationStabilizer().stabilize(
                    Collections.emptyList(), result(
                            ready("skill:fishing", "Train Fishing to 50", 40)));
            assertEquals(cause, "skill:fishing",
                    changed.getRecommendations().get(0).getId());
        }
    }

    @Test
    public void materiallyBetterNewPlanReplacesTheOldOne()
    {
        Recommendation oldTop = ready("skill:mining", "Train Mining to 50", 50);
        StrategyResult fresh = result(
                ready("opportunity:birdhouse", "Run birdhouses", 70),
                ready("skill:mining", "Train Mining to 50", 50));

        StrategyResult stable = new RecommendationStabilizer().stabilize(
                Collections.singletonList(oldTop), fresh);

        assertEquals("opportunity:birdhouse",
                stable.getRecommendations().get(0).getId());
    }

    private static StrategyResult result(Recommendation... recommendations)
    {
        return new StrategyResult(Arrays.asList(recommendations),
                Collections.emptyList(), null);
    }

    private static Recommendation ready(String id, String title, double score)
    {
        return new Recommendation(id, title, "Reason.", score, null,
                Confidence.VERIFIED, 49, 50,
                new Guidance("Follow the named route.",
                        "Required setup.", "Named location.", null),
                Safety.harmless(true));
    }

    private static Recommendation skillPlan(String id, String title,
            double score, String methodId, String action)
    {
        TrainingMethod method = new TrainingMethod(
                methodId, net.runelite.api.Skill.MINING, 1, 99,
                "Concrete mining route", "Varrock East mine.",
                10, 10, 10, AttentionLevel.MODERATE,
                20, 1, Collections.emptyList(),
                Confidence.VERIFIED);
        TrainingPlan plan = new TrainingPlan(method, "Concrete route.",
                Confidence.VERIFIED, Collections.emptyList());
        return new Recommendation(id, title, "Reason.", score, plan,
                Confidence.VERIFIED, 49, 50,
                new Guidance(action, "Bronze pickaxe.",
                        "Varrock East mine, southeast of Varrock.", null),
                Safety.harmless(true));
    }
}

package compass;

import java.util.Collections;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ReleaseUxControlsTest extends CatalogHostTest
{
    @Test
    public void supportIsHiddenWhenUnconfiguredAndNeverBrowses()
    {
        AtomicInteger opened = new AtomicInteger();
        OsrsStrategistPanel panel = panel("", value -> opened.incrementAndGet(),
                () -> { });
        assertFalse(panel.supportButton.isVisible());
        panel.supportButton.doClick();
        assertEquals(0, opened.get());
    }

    @Test
    public void configuredSupportUsesOnlyExplicitClick()
    {
        AtomicReference<String> opened = new AtomicReference<>();
        OsrsStrategistPanel panel = panel("https://example.test/support",
                opened::set, () -> { });
        assertTrue(panel.supportButton.isVisible());
        assertNull(opened.get());
        panel.supportButton.doClick();
        assertEquals("https://example.test/support", opened.get());
    }

    @Test
    public void negativeFeedbackIsTheOnlyPrimaryFeedback()
    {
        OsrsStrategistPanel panel = panel("", value -> { },
                () -> { });
        assertEquals(java.util.Arrays.asList("Later", "Not Today", "Dislike"),
                java.util.Arrays.asList(panel.laterButton.getText(), panel.notTodayButton.getText(), panel.dislikeButton.getText()));
        assertFalse(java.util.Arrays.asList(panel.laterButton.getText(), panel.notTodayButton.getText(), panel.dislikeButton.getText()).contains("Do This"));
    }

    @Test
    public void selectedGoalFallbackIsVisibleWithoutBlankingDoNext()
    {
        OsrsStrategistPanel panel = panel("", value -> { }, () -> { });
        panel.updateAccount("Player", "Main", Membership.F2P, 500);
        panel.updateGoal(GoalType.BOWFA);
        panel.updateRecommendations(Collections.singletonList(recommendation()));
        assertFalse(panel.recommendationBody.getText().contains("GOAL"));
        assertFalse(panel.recommendationBody.getText().trim().isEmpty());
    }

    @Test
    public void detailsControlDoesNotAffectSidebarRecommendation()
    {
        OsrsStrategistPanel panel = panel("", value -> { }, () -> { });
        panel.updateRecommendations(Collections.singletonList(recommendation()));
        String before = panel.recommendationBody.getText();
        panel.setDetailsOverlayEnabled(false);
        assertFalse(panel.detailsButton.isEnabled());
        assertFalse(panel.detailsButton.isVisible());
        assertEquals(before, panel.recommendationBody.getText());
        panel.setDetailsOverlayEnabled(true);
        assertTrue(panel.detailsButton.isEnabled());
        assertTrue(panel.detailsButton.isVisible());
    }

    @Test
    public void dangerousStorageUsesAnExplicitRiskStepControl()
    {
        AtomicReference<Recommendation> shown = new AtomicReference<>();
        OsrsStrategistPanel panel = new OsrsStrategistPanel(
                (id, feedback) -> { }, null, shown::set,
                () -> { }, () -> { }, "", value -> { });
        Guidance guidance = new Guidance(
                "Follow only the verified retrieval sequence.",
                "Exact observed setup", "Hespori cave", "Second deaths can delete stored items.",
                BankingMode.UNKNOWN, new UimStorageDecision(
                        StorageKind.HESPORI_ITEM_RETRIEVAL, true,
                        Confidence.VERIFIED, RiskLevel.HIGH,
                        "Verified exact service"),
                RecommendationRiskDisclosure.deathStorage());
        Recommendation dangerous = new Recommendation(
                "uim:hespori-transition", "Death-storage transition",
                "A major transition is otherwise blocked.", 1.0, null,
                Confidence.CHECK_NEEDED, 0, 0, guidance,
                Safety.harmless(false));

        panel.updateRecommendations(Collections.singletonList(dangerous));
        assertEquals("View Risk Steps", panel.detailsButton.getText());
        assertNull(shown.get());
        panel.detailsButton.doClick();
        assertEquals(dangerous, shown.get());
        assertEquals("Hide Risk Steps", panel.detailsButton.getText());
    }

    @Test
    public void emptySecondarySectionsDoNotOccupyTheSidebar()
    {
        OsrsStrategistPanel panel = panel("", value -> { }, () -> { });
        panel.updateRecommendations(Collections.singletonList(recommendation()));
        panel.updateOpportunities(Collections.emptyList());
        assertFalse(panel.alternativesCard.isVisible());
        assertFalse(panel.opportunitiesCard.isVisible());
    }

    @Test
    public void alternativesUseCompactLevelAndMethodLines()
    {
        OsrsStrategistPanel panel = panel("", value -> { }, () -> { });
        Recommendation first = recommendation("skill:mining", "Train Mining to 40");
        Recommendation second = recommendation("skill:fishing", "Train Fishing to 40");
        panel.updateRecommendations(java.util.Arrays.asList(first, second));

        String text = panel.alternativeOne.getText();
        assertTrue(text.contains("Concrete method"));
        assertTrue(text.contains("30 → 40"));
        assertFalse(text.contains("Named location"));
    }

    @Test
    public void fallbackHidesControlsThatCannotDoAnything()
    {
        OsrsStrategistPanel panel = panel("", value -> { }, () -> { });
        panel.updateRecommendations(Collections.emptyList());

        assertFalse(panel.detailsButton.isVisible());
        assertFalse(panel.feedbackPanel.isVisible());
        assertFalse(panel.progressBar.isVisible());
    }

    @Test
    public void opportunityCardExplainsFirstPreparationInsteadOfDebugConfidence()
    {
        OsrsStrategistPanel panel = panel("", value -> { }, () -> { });
        Opportunity herb = new Opportunity("opportunity:herb-run",
                OpportunityType.HERB_RUN, "Herb run", true,
                Confidence.VERIFIED,
                Collections.singletonList("Carry a spade"), false,
                Safety.skill(false,
                        net.runelite.api.Skill.FARMING));

        panel.updateOpportunities(Collections.singletonList(herb));

        assertTrue(panel.opportunityOne.getText()
                .contains("Prep: Carry a spade"));
        assertFalse(panel.opportunityOne.getText()
                .contains("Check Needed"));
    }

    private static OsrsStrategistPanel panel(String support,
            java.util.function.Consumer<String> browser, Runnable reset)
    {
        return new OsrsStrategistPanel((id, feedback) -> { }, null,
                recommendation -> { }, () -> { }, () -> { },
                support, browser);
    }

    private static Recommendation recommendation()
    {
        return new Recommendation("quest:test", "Complete a useful quest",
                "Unlocks useful progression.", 1.0, null,
                Confidence.VERIFIED, 0, 0,
                new Guidance("Start the quest.", null,
                        "Quest start", null));
    }

    private static Recommendation recommendation(String id, String title)
    {
        net.runelite.api.Skill skill = id.contains("fishing")
                ? net.runelite.api.Skill.FISHING : net.runelite.api.Skill.MINING;
        TrainingMethod method = new TrainingMethod(id + ":method", skill,
                1, 99, "Concrete method", "Named location", 1, 1, 1,
                AttentionLevel.MODERATE, 10, 1, Collections.emptyList(),
                Confidence.VERIFIED);
        return new Recommendation(id, title, "Reason", 1,
                new TrainingPlan(method, "Reason",
                        Confidence.VERIFIED, Collections.emptyList()),
                Confidence.VERIFIED, 30, 40,
                new Guidance("Repeat the exact loop.",
                        "Required tool.", "Named location.", null));
    }
}

package compass;

import java.util.Collections;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RequirementActionabilityTest extends CatalogHostTest
{
    @Test
    public void knownSupplyShortfallCanStillBeDoNext()
    {
        TrainingMethod method = method("smithing_test", Skill.SMITHING);
        TrainingPlan plan = new TrainingPlan(
                method,
                "test",
                Confidence.CHECK_NEEDED,
                Collections.singletonList(new EvidenceCheck(
                        "generic:Steel bar supply",
                        "Steel bar supply",
                        RequirementState.CHECK_NEEDED,
                        "Acquire the missing bars.")));
        Recommendation recommendation = new Recommendation(
                "skill:smithing",
                "Train Smithing to 50",
                "test",
                10.0,
                plan,
                Confidence.CHECK_NEEDED,
                40,
                50,
                new Guidance(
                        "Smith steel platebodies until the milestone.",
                        "Need 500 steel bars. Buy or self-source the missing amount.",
                        "Varrock West anvils, directly south of the bank.",
                        "The route is known; only supplies remain."));

        ActionabilityPolicy policy =
                new ActionabilityPolicy();
        assertTrue(RequirementActionability.isActionablePreparation(
                plan, recommendation.getGuidance()));
        assertTrue(policy.canLeadQueue(recommendation));
        assertTrue(Presentation.compactText(recommendation)
                .contains("Need 500 steel bars"));
        assertTrue(Presentation.compactText(recommendation)
                .contains("BRING"));
    }

    @Test
    public void unknownAccessCanNeverBeDoNext()
    {
        TrainingMethod method = method("minigame_test", Skill.MINING);
        TrainingPlan plan = new TrainingPlan(
                method,
                "test",
                Confidence.CHECK_NEEDED,
                Collections.singletonList(new EvidenceCheck(
                        "generic:Volcanic Mine access",
                        "Volcanic Mine access",
                        RequirementState.CHECK_NEEDED,
                        "Access has not been proven.")));
        Recommendation recommendation = new Recommendation(
                "skill:mining",
                "Train Mining",
                "test",
                1000.0,
                plan,
                Confidence.CHECK_NEEDED,
                70,
                80,
                new Guidance(
                        "Run Volcanic Mine.",
                        "Bring your best pickaxe.",
                        "Volcanic Mine.",
                        "Access must be verified."));

        assertFalse(RequirementActionability.isActionablePreparation(
                plan, recommendation.getGuidance()));
        assertTrue(RequirementActionability.hasHardUnresolvedRequirement(plan));
        assertFalse(new ActionabilityPolicy()
                .canLeadQueue(recommendation));
        assertFalse(new ActionabilityPolicy()
                .mayAppearAsAlternative(recommendation));
        assertTrue(Presentation.compactText(recommendation)
                .contains("NEEDED"));
    }

    @Test
    public void accessAndSupplyInOneLabelRemainsAHardGate()
    {
        TrainingPlan plan = new TrainingPlan(
                method("runecraft_zmi", Skill.RUNECRAFT),
                "test",
                Confidence.CHECK_NEEDED,
                Collections.singletonList(new EvidenceCheck(
                        "generic:Ourania Altar route and essence supply",
                        "Ourania Altar route and essence supply",
                        RequirementState.CHECK_NEEDED,
                        "Route not observed.")));

        assertTrue(RequirementActionability.hasHardUnresolvedRequirement(plan));
        assertFalse(RequirementActionability.isActionablePreparation(plan,
                new Guidance(
                        "Run essence to the altar.",
                        "Bring pure essence.",
                        "Ourania Altar.",
                        "Route access is unknown.")));
    }

    @Test
    public void typedResourceShortfallIsPreparationNotUnknownAccess()
    {
        TrainingPlan plan = new TrainingPlan(
                method("runecraft_f2p_earth", Skill.RUNECRAFT),
                "test", Confidence.CHECK_NEEDED,
                java.util.Arrays.asList(
                        new EvidenceCheck("resource:runecraft_essence",
                                "Rune or pure essence",
                                RequirementState.CHECK_NEEDED,
                                "No essence is currently observed."),
                        new EvidenceCheck("resource:runecraft_earth_entry",
                                "Earth talisman or earth tiara",
                                RequirementState.CHECK_NEEDED,
                                "No entry item is currently observed.")));
        Guidance guidance = new Guidance(
                "Bank at Varrock East, craft earth runes, and repeat.",
                "Acquire essence and an earth talisman before starting.",
                "Earth Altar northeast of Varrock.", null);

        assertFalse(RequirementActionability.hasHardUnresolvedRequirement(plan));
        assertTrue(RequirementActionability.isActionablePreparation(
                plan, guidance));
    }

    @Test
    public void knownTypedBoatSetupCanLeadPreparation()
    {
        EvidenceCheck check = new EvidenceCheck(
                "preparation:sailing-trial-boat", "Trial-ready boat",
                RequirementState.CHECK_NEEDED,
                "Fit an iron helm, oak mast, and linen sails.");
        TrainingPlan plan = new TrainingPlan(
                method("sailing_barracuda_tantrum", Skill.SAILING),
                "test", Confidence.CHECK_NEEDED,
                Collections.singletonList(check));

        assertFalse(RequirementActionability.hasHardUnresolvedRequirement(plan));
        assertTrue(RequirementActionability.isActionablePreparation(plan,
                new Guidance("Run Tempor Tantrum.",
                        "Fit an iron helm, oak mast, and linen sails.",
                        "Rum-dashed Ralph north-west of The Storm Tempor.", null)));
    }

    @Test
    public void locationDoesNotMasqueradeAsALogSupply()
    {
        EvidenceCheck check = new EvidenceCheck(
                "generic:Forestry-enabled tree location",
                "Forestry-enabled tree location",
                RequirementState.CHECK_NEEDED,
                "No location is proven.");
        TrainingPlan plan = new TrainingPlan(
                method("woodcutting_forestry", Skill.WOODCUTTING),
                "test", Confidence.CHECK_NEEDED,
                Collections.singletonList(check));

        assertTrue(RequirementActionability.hasHardUnresolvedRequirement(plan));
    }

    @Test
    public void barbarianFishingDoesNotMasqueradeAsAMetalBarShortfall()
    {
        TrainingPlan plan = new TrainingPlan(
                method("fishing_barbarian", Skill.FISHING),
                "test", Confidence.CHECK_NEEDED,
                Collections.singletonList(new EvidenceCheck(
                        "generic:Barbarian Fishing training",
                        "Barbarian Fishing training",
                        RequirementState.CHECK_NEEDED,
                        "Training unlock has not been observed.")));

        assertTrue(RequirementActionability.hasHardUnresolvedRequirement(plan));
        assertFalse(RequirementActionability.isActionablePreparation(plan,
                new Guidance("Catch leaping fish.",
                        "Bring feathers.", "Otto's Grotto.", null)));
    }

    @Test
    public void unknownFarmingPatchIsNotJustASeedShortfall()
    {
        TrainingPlan plan = new TrainingPlan(
                method("farming_allotments_expanded", Skill.FARMING),
                "test", Confidence.CHECK_NEEDED,
                Collections.singletonList(new EvidenceCheck(
                        "generic:Reachable allotment patches and supplies",
                        "Reachable allotment patches and supplies",
                        RequirementState.CHECK_NEEDED,
                        "No patch has been proven.")));

        assertTrue(RequirementActionability.hasHardUnresolvedRequirement(plan));
    }

    @Test
    public void retrievalOnlyUimResourceStillRequiresExplicitRoute()
    {
        EvidenceCheck check = new EvidenceCheck(
                "resource:runecraft_essence", "Rune or pure essence",
                RequirementState.CHECK_NEEDED,
                "Enough is observed only after counting UIM storage with additional access/risk preconditions; verify that route before using the resource.");
        TrainingPlan plan = new TrainingPlan(
                method("runecraft_f2p_earth", Skill.RUNECRAFT),
                "test", Confidence.CHECK_NEEDED,
                Collections.singletonList(check));

        assertTrue(RequirementActionability.hasHardUnresolvedRequirement(plan));
    }

    @Test
    public void blockedRequirementCanNeverBePrep()
    {
        TrainingMethod method = method("blocked_test", Skill.PRAYER);
        TrainingPlan plan = new TrainingPlan(
                method,
                "test",
                Confidence.BLOCKED,
                Collections.singletonList(new EvidenceCheck(
                        "build:restriction",
                        "Build restriction",
                        RequirementState.BLOCKED,
                        "This action would violate the protected account build.")));
        Recommendation recommendation = new Recommendation(
                "skill:prayer",
                "Train Prayer",
                "test",
                1000.0,
                plan,
                Confidence.BLOCKED,
                1,
                43,
                new Guidance(
                        "Do the blocked action.",
                        "None.",
                        "Nowhere.",
                        "Blocked."));

        assertFalse(new ActionabilityPolicy()
                .canLeadQueue(recommendation));
    }

    private static TrainingMethod method(String id, Skill skill)
    {
        return new TrainingMethod(
                id,
                skill,
                1,
                99,
                id,
                "test",
                10,
                10,
                10,
                AttentionLevel.MODERATE,
                10,
                1,
                Collections.emptyList(),
                Confidence.CHECK_NEEDED);
    }
}

package compass;

import java.util.Collections;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class RequirementEvidenceEngineTest extends CatalogHostTest
{
    @Test
    public void earlyFarmingExplainsKnownAccessAndUnfinishedSeedCatalog()
    {
        FarmingAccessEvaluator accessEvaluator =
                new FarmingAccessEvaluator(new FarmingAccessCatalog());
        RequirementEvidenceEngine engine =
                new RequirementEvidenceEngine(accessEvaluator, null, new FarmingSupplyCatalog(), new RunecraftSupplyCatalog());

        FarmingSnapshot farming = new FarmingSnapshot(
                Collections.singleton("falador"),
                Collections.emptyMap(),
                Collections.emptyMap()
        );

        GameData data = GameData
                .builder(account(9))
                .farming(farming)
                .build();

        TrainingMethod method = method("farming_early");
        java.util.List<EvidenceCheck> checks =
                engine.evaluate(data, method);

        assertEquals(2, checks.size());
        assertEquals(RequirementState.VERIFIED, checks.get(0).getState());
        assertTrue(checks.get(0).getEvidence().contains("Falador"));
        assertEquals(RequirementState.CHECK_NEEDED, checks.get(1).getState());
        assertTrue(checks.get(1).getEvidence().contains("source is not verified"));
    }

    @Test
    public void herbRunUsesObservedBankAndLeprechaunResources()
    {
        FarmingAccessEvaluator accessEvaluator =
                new FarmingAccessEvaluator(new FarmingAccessCatalog());
        RequirementEvidenceEngine engine =
                new RequirementEvidenceEngine(accessEvaluator, null, new FarmingSupplyCatalog(), new RunecraftSupplyCatalog());

        Map<String, Capability> tools = new HashMap<>();
        tools.put("rake", Capability.VERIFIED);
        tools.put("dibber", Capability.VERIFIED);
        tools.put("spade", Capability.VERIFIED);
        FarmingSnapshot farming = new FarmingSnapshot(
                Collections.singleton("falador"),
                tools,
                Collections.emptyMap()
        );

        GameData data = GameData
