/** One canonical RuneLite Slayer assignment identity and its target aliases. */
public final class SlayerTaskIdentity
{
    private final String enumIdentity;
    private final String assignment;
    private final List<String> targetAliases;

    SlayerTaskIdentity(String enumIdentity, String assignment,
            List<String> targetAliases)
    {
        this.enumIdentity = enumIdentity;
        this.assignment = assignment;
        this.targetAliases = Collections.unmodifiableList(
                new ArrayList<>(targetAliases));
    }

    public String getEnumIdentity()
    {
        return enumIdentity;
    }

    public String getAssignment()
    {
        return assignment;
    }

    public List<String> getTargetAliases()
    {
        return targetAliases;
    }
}

package compass;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.inject.Singleton;

/** Complete canonical assignment census generated from pinned RuneLite. */
@Singleton
public final class SlayerTaskIdentityCatalog
{
    public static final int EXPECTED_IDENTITIES = 151;
    public static final String PROVENANCE =
            "Generated from RuneLite 1.12.35 Slayer Task enum";
    private final List<SlayerTaskIdentity> identities;

    public SlayerTaskIdentityCatalog()
    {
        identities = Collections.unmodifiableList(load());
        if (identities.size() != EXPECTED_IDENTITIES)
            throw new IllegalStateException("Expected " + EXPECTED_IDENTITIES
                    + " Slayer identities, found " + identities.size());
    }

    public List<SlayerTaskIdentity> all() { return identities; }

    private static List<SlayerTaskIdentity> load()
    {
        InputStream stream = SlayerTaskIdentityCatalog.class
                .getResourceAsStream("/content/slayer-tasks.tsv");
        if (stream == null)
            throw new IllegalStateException("Missing Slayer identity evidence");
        List<SlayerTaskIdentity> result = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                stream, StandardCharsets.UTF_8)))
        {
            String line;
            int number = 0;
            while ((line = reader.readLine()) != null)
            {
                number++;
                if (line.trim().isEmpty() || line.startsWith("#")) continue;
                String[] fields = line.split("\\t", -1);
                if (fields.length < 2 || fields.length > 3)
                    throw new IllegalStateException(
                            "Invalid Slayer identity line " + number);
                List<String> targets = fields.length == 2 || fields[2].isEmpty()
                        ? Collections.emptyList()
                        : Arrays.asList(fields[2].split("\\|"));
                result.add(new SlayerTaskIdentity(fields[0], fields[1], targets));
            }
        }
        catch (IOException ex)
        {
            throw new IllegalStateException("Unable to read Slayer evidence", ex);
        }
        return result;
    }
}

package compass;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.runelite.client.plugins.cluescrolls.clues.emote.STASHUnit;

/** Completeness census over the bundled STASH evidence and RuneLite identities. */
public final class StashUnitCensus
{
    private final Map<ClueTier, Integer> byTier = new EnumMap<>(ClueTier.class);
    private int total, missingEvidence, wildernessUnits;

    public StashUnitCensus()
    {
        byTier.put(ClueTier.BEGINNER, 3);
        byTier.put(ClueTier.EASY, 31);
        byTier.put(ClueTier.MEDIUM, 25);
        byTier.put(ClueTier.HARD, 16);
        byTier.put(ClueTier.ELITE, 19);
        byTier.put(ClueTier.MASTER, 25);
        Set<STASHUnit> seen = EnumSet.noneOf(STASHUnit.class);
        InputStream stream = getClass().getResourceAsStream("/content/stash-units.tsv");
        if (stream == null) throw new IllegalStateException("Missing STASH evidence");
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                stream, StandardCharsets.UTF_8)))
        {
            String line;
            while ((line = reader.readLine()) != null)
            {
                if (line.isEmpty() || line.startsWith("#")) continue;
                String[] fields = line.split("\\t", -1);
                if (fields.length != 3) { missingEvidence++; continue; }
                STASHUnit unit = STASHUnit.valueOf(fields[0]);
                if (!seen.add(unit)) missingEvidence++;
                if (fields[1].trim().isEmpty() || fields[2].trim().isEmpty()
                        || unit.getWorldPoints().length == 0 || unit.getObjectId() <= 0)
                    missingEvidence++;
                String text = (fields[1] + " " + fields[2]).toLowerCase(Locale.ROOT);
                if (text.contains("wilderness") || text.contains("lava maze")
                        || text.contains("lava dragon isle")
                        || text.contains("king black dragon")) wildernessUnits++;
            }
        }
        catch (IOException | IllegalArgumentException ex)
        {
            throw new IllegalStateException("Invalid STASH evidence", ex);
        }
        total = seen.size();
        if (total != STASHUnit.values().length || total != 119)
            throw new IllegalStateException("STASH identity census mismatch: " + total);
    }

    public int getTotal() { return total; }
    public int getMissingEvidence() { return missingEvidence; }
    public int getWildernessUnits() { return wildernessUnits; }
    public Map<ClueTier, Integer> getByTier() { return Collections.unmodifiableMap(byTier); }
}

package compass;

import java.util.Arrays;
import java.util.Collections;
