package compass;

import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TrainingFatigueTrackerTest extends CatalogHostTest
{
    @Test
    public void balancedOnlyPenalizesSustainedTraining()
    {
        TrainingFatigueTracker tracker = new TrainingFatigueTracker();
        long start = 1_000_000L;
        assertFalse(tracker.record(Skill.MINING, 1000,
                StrategyMode.BALANCED, start).isPresent());
        for (int minute = 8; minute <= 40; minute += 8)
        {
            assertFalse(tracker.record(
                    Skill.MINING,
                    1000 + minute * 100,
                    StrategyMode.BALANCED,
                    start + minutes(minute)).isPresent());
        }

        TrainingFatigueTracker.FatigueSignal signal = tracker.record(
                Skill.MINING, 6000, StrategyMode.BALANCED,
                start + minutes(46));
        assertTrue(signal.isPresent());
        assertEquals("skill:mining", signal.getActivityId());
        assertEquals(-8.0, signal.getScoreDelta(), 0.001);
    }

    @Test
    public void relaxedRotatesEarlierAndMoreStrongly()
    {
        TrainingFatigueTracker tracker = new TrainingFatigueTracker();
        long start = 5_000_000L;
        tracker.record(Skill.WOODCUTTING, 1000, StrategyMode.RELAXED, start);
        tracker.record(Skill.WOODCUTTING, 1800, StrategyMode.RELAXED,
                start + minutes(8));
        tracker.record(Skill.WOODCUTTING, 2600, StrategyMode.RELAXED,
                start + minutes(16));
        tracker.record(Skill.WOODCUTTING, 3400, StrategyMode.RELAXED,
                start + minutes(24));

        TrainingFatigueTracker.FatigueSignal signal = tracker.record(
                Skill.WOODCUTTING, 4100, StrategyMode.RELAXED,
                start + minutes(31));

        assertTrue(signal.isPresent());
        assertEquals(-14.0, signal.getScoreDelta(), 0.001);
    }

    @Test
    public void efficientNeverAppliesPsychologicalVarietyPenalty()
    {
        TrainingFatigueTracker tracker = new TrainingFatigueTracker();
        long start = 10_000_000L;
        tracker.record(Skill.AGILITY, 1000, StrategyMode.EFFICIENT, start);
        for (int minute = 8; minute <= 120; minute += 8)
        {
            assertFalse(tracker.record(
                    Skill.AGILITY,
                    1000 + minute * 100,
                    StrategyMode.EFFICIENT,
                    start + minutes(minute)).isPresent());
        }
    }

    @Test
    public void switchingSkillsResetsContinuity()
    {
        TrainingFatigueTracker tracker = new TrainingFatigueTracker();
        long start = 20_000_000L;
        tracker.record(Skill.FISHING, 1000, StrategyMode.RELAXED, start);
        tracker.record(Skill.FISHING, 1800, StrategyMode.RELAXED,
                start + minutes(8));
        tracker.record(Skill.FISHING, 2600, StrategyMode.RELAXED,
                start + minutes(16));

        assertFalse(tracker.record(Skill.COOKING, 1000,
                StrategyMode.RELAXED,
                start + minutes(17)).isPresent());
        assertFalse(tracker.record(Skill.COOKING, 1800,
                StrategyMode.RELAXED,
                start + minutes(25)).isPresent());
        assertFalse(tracker.record(Skill.COOKING, 2600,
                StrategyMode.RELAXED,
                start + minutes(33)).isPresent());
        assertFalse(tracker.record(Skill.COOKING, 3400,
                StrategyMode.RELAXED,
                start + minutes(41)).isPresent());
    }

    @Test
    public void hitpointsDoesNotBreakChosenCombatSkillContinuity()
    {
        TrainingFatigueTracker tracker = new TrainingFatigueTracker();
        long start = 30_000_000L;
        tracker.record(Skill.DEFENCE, 1000, StrategyMode.RELAXED, start);
        tracker.record(Skill.HITPOINTS, 5000, StrategyMode.RELAXED,
                start + minutes(4));
        tracker.record(Skill.DEFENCE, 1800, StrategyMode.RELAXED,
                start + minutes(8));
        tracker.record(Skill.HITPOINTS, 5600, StrategyMode.RELAXED,
                start + minutes(12));
        tracker.record(Skill.DEFENCE, 2600, StrategyMode.RELAXED,
                start + minutes(16));
        tracker.record(Skill.DEFENCE, 3400, StrategyMode.RELAXED,
                start + minutes(24));

        TrainingFatigueTracker.FatigueSignal signal = tracker.record(
                Skill.DEFENCE, 4100, StrategyMode.RELAXED,
                start + minutes(31));
        assertTrue(signal.isPresent());
        assertEquals("skill:defence", signal.getActivityId());
    }

    @Test
    public void longBreakStartsFreshSession()
    {
        TrainingFatigueTracker tracker = new TrainingFatigueTracker();
        long start = 40_000_000L;
        tracker.record(Skill.CRAFTING, 1000, StrategyMode.RELAXED, start);
        assertFalse(tracker.record(Skill.CRAFTING, 3000,
                StrategyMode.RELAXED,
                start + minutes(11)).isPresent());
        assertFalse(tracker.record(Skill.CRAFTING, 4000,
                StrategyMode.RELAXED,
                start + minutes(20)).isPresent());
    }

    private static long minutes(int value)
    {
        return value * 60L * 1000L;
    }
}

package compass;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;

/** Development-time census for strategic methods and RuneLite action evidence. */
public final class TrainingMethodCensus
{
    public static final class SkillCoverage
    {
        private final int curatedMethods;
        private final int runeLiteActions;
        private final Set<TrainingIntensity> intensities;
        private final Set<MethodCostTier> costTiers;
        private final boolean hasF2p;
        private final boolean hasSelfSource;
        private final boolean hasUim;
        private final boolean hasHardcoreSafe;

        private SkillCoverage(int curatedMethods, int runeLiteActions,
                Set<TrainingIntensity> intensities,
                Set<MethodCostTier> costTiers, boolean hasF2p,
                boolean hasSelfSource, boolean hasUim,
                boolean hasHardcoreSafe)
        {
            this.curatedMethods = curatedMethods;
            this.runeLiteActions = runeLiteActions;
            this.intensities = Collections.unmodifiableSet(intensities);
            this.costTiers = Collections.unmodifiableSet(costTiers);
            this.hasF2p = hasF2p;
            this.hasSelfSource = hasSelfSource;
            this.hasUim = hasUim;
            this.hasHardcoreSafe = hasHardcoreSafe;
        }

        public int getCuratedMethods() { return curatedMethods; }
        public int getRuneLiteActions() { return runeLiteActions; }
        public Set<TrainingIntensity> getIntensities() { return intensities; }
        public Set<MethodCostTier> getCostTiers() { return costTiers; }
        public boolean hasF2p() { return hasF2p; }
        public boolean hasSelfSource() { return hasSelfSource; }
        public boolean hasUim() { return hasUim; }
        public boolean hasHardcoreSafe() { return hasHardcoreSafe; }
    }

    private final Map<Skill, SkillCoverage> bySkill;
    private final int curatedMethodCount;
    private final int runeLiteActionCount;
    private final int duplicateIds;
    private final List<String> invalidMethods;

    public TrainingMethodCensus()
    {
        ExpandedTrainingMethodCatalog curated = new ExpandedTrainingMethodCatalog();
        RuneLiteSkillActionCatalog actions = new RuneLiteSkillActionCatalog();
        EnumMap<Skill, SkillCoverage> coverage = new EnumMap<>(Skill.class);
        Set<String> ids = new HashSet<>();
        List<String> invalid = new ArrayList<>();
        int curatedCount = 0;
        int actionCount = 0;
        int duplicates = 0;

        for (Skill skill : Skill.values())
        {
            List<CuratedTrainingMethod> methods = curated.methodsFor(skill);
            Set<TrainingIntensity> intensities = new HashSet<>();
            Set<MethodCostTier> costs = new HashSet<>();
            boolean f2p = false;
            boolean selfSource = false;
            boolean uim = false;
            boolean hardcore = false;
            for (CuratedTrainingMethod candidate : methods)
            {
                curatedCount++;
                TrainingMethod method = candidate.getMethod();
                TrainingMethodMetadata metadata = candidate.getMetadata();
                if (method == null || metadata == null)
                {
                    invalid.add(skill + ": null method or metadata");
                    continue;
                }
                if (!ids.add(method.getId())) duplicates++;
                if (method.getSkill() != skill || method.getName() == null
                        || method.getName().trim().isEmpty()
                        || method.getInstructions() == null
                        || method.getInstructions().trim().isEmpty()
                        || method.getMinLevel() < 1
                        || method.getMaxLevel() < method.getMinLevel()
                        || metadata.isFreeToPlayAllowed() && method.isMembersOnly())
                    invalid.add(method.getId());
                intensities.add(metadata.getIntensity());
                costs.add(metadata.getCostTier());
                f2p |= metadata.isFreeToPlayAllowed();
                selfSource |= metadata.isSelfSourceFriendly();
                uim |= metadata.isUimFriendly();
                hardcore |= metadata.isHardcoreSafe();
            }
            int actionSize = actions.actionsFor(skill).size();
            actionCount += actionSize;
            coverage.put(skill, new SkillCoverage(methods.size(), actionSize,
                    intensities, costs, f2p, selfSource, uim, hardcore));
        }
        bySkill = Collections.unmodifiableMap(coverage);
        curatedMethodCount = curatedCount;
        runeLiteActionCount = actionCount;
        duplicateIds = duplicates;
        invalidMethods = Collections.unmodifiableList(invalid);
    }

    public Map<Skill, SkillCoverage> getBySkill() { return bySkill; }
    public int getSkillCount() { return bySkill.size(); }
    public int getCuratedMethodCount() { return curatedMethodCount; }
    public int getRuneLiteActionCount() { return runeLiteActionCount; }
    public int getDuplicateIds() { return duplicateIds; }
    public List<String> getInvalidMethods() { return invalidMethods; }
    public int getSkillsWithRuneLiteActions()
    {
        int count = 0;
        for (SkillCoverage value : bySkill.values())
            if (value.getRuneLiteActions() > 0) count++;
        return count;
    }
}

package compass;

import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TrainingMethodCensusTest extends CatalogHostTest
{
    @Test
    public void everyCurrentSkillHasValidStrategicMethods()
    {
        TrainingMethodCensus census = new TrainingMethodCensus();
        assertEquals(Skill.values().length, census.getSkillCount());
        assertTrue(census.getCuratedMethodCount() >= 125);
        assertEquals(0, census.getDuplicateIds());
        assertTrue(census.getInvalidMethods().toString(),
                census.getInvalidMethods().isEmpty());
        for (Skill skill : Skill.values())
        {
            TrainingMethodCensus.SkillCoverage coverage =
                    census.getBySkill().get(skill);
            assertTrue("too few strategic methods for " + skill,
                    coverage.getCuratedMethods() >= 2);
            assertTrue("no self-source route for " + skill,
                    coverage.hasSelfSource());
            assertTrue("no Hardcore-safe route for " + skill,
                    coverage.hasHardcoreSafe());
        }
    }

    @Test
    public void runeLiteActionsSupplementButDoNotReplaceStrategyMethods()
    {
        TrainingMethodCensus census = new TrainingMethodCensus();
        assertEquals(17, census.getSkillsWithRuneLiteActions());
        assertTrue(census.getRuneLiteActionCount() > 500);
        assertTrue(census.getBySkill().get(Skill.HUNTER)
                .getRuneLiteActions() > 60);
        assertEquals(0, census.getBySkill().get(Skill.SAILING)
                .getRuneLiteActions());
    }

    @Test
    public void currentLiveSepulchreLevelsOverridePinnedRuneLiteData()
    {
        RuneLiteSkillActionCatalog catalog = new RuneLiteSkillActionCatalog();
        assertEquals(77, level(catalog,
                "runelite:agility:hallowed_sepulchre_floor_4"));
        assertEquals(87, level(catalog,
                "runelite:agility:hallowed_sepulchre_floor_5"));
        assertEquals(112.0f, xp(catalog,
                "runelite:hunter:regular_bird_house"), 0.0f);
        assertEquals(969.0f, xp(catalog,
                "runelite:hunter:magic_bird_house"), 0.0f);
        assertEquals(0.0f, xp(catalog,
                "runelite:hunter:pyre_fox"), 0.0f);
        assertEquals(0.0f, xp(catalog,
                "runelite:agility:colossal_wyrm_basic_course"), 0.0f);
    }

    private static int level(RuneLiteSkillActionCatalog catalog, String id)
    {
        for (ActionDef action
                : catalog.actionsFor(Skill.AGILITY))
            if (id.equals(action.getId())) return action.getLevel();
        throw new AssertionError("Missing action " + id);
    }

    private static float xp(RuneLiteSkillActionCatalog catalog, String id)
    {
        for (Skill skill : Skill.values())
            for (ActionDef action
                    : catalog.actionsFor(skill))
                if (id.equals(action.getId())) return action.getXp();
        throw new AssertionError("Missing action " + id);
    }
}

package compass;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TrainingMethodPolicyAccountModeTest extends CatalogHostTest
{
    private final TrainingMethodPolicy policy = new TrainingMethodPolicy();

    @Test
    public void hardcoreRejectsWildernessEvenWhenGloballyEnabled()
    {
        TrainingMethod method = method(true);
        TrainingMethodMetadata metadata = metadata(true, true, RiskLevel.HIGH, false,
                TrainingIntensity.BALANCED);
        assertFalse(policy.isAllowed(data(AccountMode.HARDCORE_IRONMAN,
                Membership.P2P), method, metadata, true));
    }

    @Test
    public void uimRejectsMethodNotMarkedUimFriendly()
    {
        TrainingMethod method = method(false);
        TrainingMethodMetadata metadata = metadata(false, true, RiskLevel.NONE, false,
                TrainingIntensity.BALANCED);
        assertFalse(policy.isAllowed(data(AccountMode.ULTIMATE_IRONMAN,
                Membership.P2P), method, metadata, false));
    }

    @Test
    public void f2pRejectsMembersOnlyMetadata()
    {
        TrainingMethod method = method(false);
        TrainingMethodMetadata metadata = metadata(true, true, RiskLevel.NONE, false,
                TrainingIntensity.BALANCED);
        assertFalse(policy.isAllowed(data(AccountMode.MAIN,
                Membership.F2P), method, metadata, false));
    }

    @Test
    public void unknownMembershipAlsoRejectsMembersOnlyMetadata()
    {
        TrainingMethod method = method(false);
        TrainingMethodMetadata metadata = metadata(true, true, RiskLevel.NONE, false,
                TrainingIntensity.BALANCED);
        assertFalse(policy.isAllowed(data(AccountMode.MAIN,
                Membership.UNKNOWN), method, metadata, false));
    }

    @Test
    public void safeSelfSourceMethodIsAllowedForIron()
    {
        TrainingMethod method = method(false);
        TrainingMethodMetadata metadata = metadata(true, true, RiskLevel.NONE, false,
                TrainingIntensity.BALANCED);
        assertTrue(policy.isAllowed(data(AccountMode.IRONMAN,
                Membership.P2P), method, metadata, false));
    }

    @Test
    public void balancedUimPrefersSustainableRelaxedMethodOverSweatySwitching()
    {
        GameData uim = data(AccountMode.ULTIMATE_IRONMAN,
                Membership.P2P);
        TrainingMethodMetadata relaxed = metadata(true, true, RiskLevel.NONE, false,
                TrainingIntensity.RELAXED);
        TrainingMethodMetadata sweaty = metadata(true, true, RiskLevel.NONE, false,
                TrainingIntensity.SWEATY);

        double relaxedScore = policy.scoreAdjustment(
                uim, relaxed, StrategyMode.BALANCED, SessionIntent.PICK_FOR_ME);
        double sweatyScore = policy.scoreAdjustment(
                uim, sweaty, StrategyMode.BALANCED, SessionIntent.PICK_FOR_ME);

        assertTrue(relaxedScore > sweatyScore);
    }

    @Test
    public void efficientUimDoesNotApplyExtraSustainabilityPenalty()
    {
        GameData uim = data(AccountMode.ULTIMATE_IRONMAN,
                Membership.P2P);
        TrainingMethodMetadata sweaty = metadata(true, true, RiskLevel.NONE, false,
                TrainingIntensity.SWEATY);
        double balanced = policy.scoreAdjustment(
                uim, sweaty, StrategyMode.BALANCED, SessionIntent.PICK_FOR_ME);
        double efficient = policy.scoreAdjustment(
                uim, sweaty, StrategyMode.EFFICIENT, SessionIntent.PICK_FOR_ME);

        assertTrue(efficient > balanced);
    }

    private static TrainingMethod method(boolean wilderness)
    {
        return new TrainingMethod("test", Skill.MINING, 1, 99, "Test", "Test",
                1, 1, 1, AttentionLevel.LOW, 10, 1,
                Collections.emptyList(), Confidence.VERIFIED,
                false, wilderness, false);
    }

    private static TrainingMethodMetadata metadata(boolean uim, boolean hardcore,
            RiskLevel risk, boolean f2p, TrainingIntensity intensity)
    {
        return new TrainingMethodMetadata(intensity,
                MethodCostTier.FREE, risk, f2p, true, uim, hardcore,
                Collections.emptyList());
    }

    private static GameData data(AccountMode mode, Membership membership)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) { levels.put(skill, 1); xp.put(skill, 0); }
        AccountSnapshot account = new AccountSnapshot("Test", 0L, code(mode), mode.name(), membership, 0, 1, 0L, levels, xp);
        return GameData.builder(account).build();
    }

    private static int code(AccountMode mode)
    {
        switch (mode)
        {
            case MAIN: return 0;
            case IRONMAN: return 1;
            case ULTIMATE_IRONMAN: return 2;
            case HARDCORE_IRONMAN: return 3;
            case GROUP_IRONMAN: return 4;
            case HARDCORE_GROUP_IRONMAN: return 5;
            case UNRANKED_GROUP_IRONMAN: return 6;
            default: return -1;
        }
    }
}

package compass;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class TrainingMethodSelectorEvidenceTest extends CatalogHostTest
{
    @Test
    public void blockedHighScoreMethodFallsBackToUsableAlternative()
    {
        TrainingMethod blockedFast = method("fast", 20.0);
        TrainingMethod usableSlower = method("safe", 10.0);

        TrainingMethodDatabase database = new TrainingMethodDatabase()
        {
            @Override
            public List<TrainingMethod> methodsFor(Skill skill)
            {
                return Arrays.asList(blockedFast, usableSlower);
            }
        };

        RequirementEvidenceEngine evidence = new RequirementEvidenceEngine(new FarmingAccessEvaluator(new FarmingAccessCatalog()), null, new FarmingSupplyCatalog(), new RunecraftSupplyCatalog())
        {
            @Override
            public List<EvidenceCheck> evaluate(
                    GameData data,
                    TrainingMethod method)
            {
                if ("fast".equals(method.getId()))
                {
                    return Collections.singletonList(
                            new EvidenceCheck(
                                    "locked",
                                    "Required unlock",
                                    RequirementState.BLOCKED,
                                    "Known locked"
                            )
                    );
                }

                return Collections.singletonList(
                        new EvidenceCheck(
                                "ready",
                                "Required unlock",
                                RequirementState.VERIFIED,
                                "Verified"
                        )
                );
            }
        };

        TrainingMethodSelector selector =
                new TrainingMethodSelector(database, evidence, new TrainingMethodPolicy(), new MethodStrategyKnowledgeCatalog(), new UimInventoryResolutionService());

        TrainingPlan plan = selector.select(
                null,
                Skill.MINING,
                50,
                StrategyMode.BALANCED,
                SessionIntent.PICK_FOR_ME
        );

        assertEquals("safe", plan.getMethod().getId());
        assertEquals(
                Confidence.VERIFIED,
                plan.getConfidence()
        );
    }

    @Test
    public void unknownAccessHighScoreMethodFallsBackToActionableAlternative()
    {
        TrainingMethod unknownFast = method("unknown-fast", 20.0);
        TrainingMethod usableSlower = method("safe", 10.0);
        TrainingMethodDatabase database = new TrainingMethodDatabase()
        {
            @Override
            public List<TrainingMethod> methodsFor(Skill skill)
            {
                return Arrays.asList(unknownFast, usableSlower);
            }
        };
        RequirementEvidenceEngine evidence = new RequirementEvidenceEngine(new FarmingAccessEvaluator(new FarmingAccessCatalog()), null, new FarmingSupplyCatalog(), new RunecraftSupplyCatalog())
        {
            @Override
            public List<EvidenceCheck> evaluate(
                    GameData data, TrainingMethod method)
            {
                if ("unknown-fast".equals(method.getId()))
                {
                    return Collections.singletonList(new EvidenceCheck(
                            "generic:Minigame access and food supply",
                            "Minigame access and food supply",
                            RequirementState.CHECK_NEEDED,
                            "Access has not been observed."));
                }
                return Collections.singletonList(new EvidenceCheck(
                        "ready", "Ready", RequirementState.VERIFIED,
                        "Verified."));
            }
        };

        TrainingPlan plan = new TrainingMethodSelector(database, evidence, new TrainingMethodPolicy(), new MethodStrategyKnowledgeCatalog(), new UimInventoryResolutionService())
                .select(null, Skill.MINING, 50, StrategyMode.BALANCED,
                        SessionIntent.PICK_FOR_ME);

        assertEquals("safe", plan.getMethod().getId());
    }

    @Test
    public void extraVerifiedRowsDoNotCreateASelectionAdvantage()
    {
        TrainingMethod oneCheck = method("one-check", 10.0);
        TrainingMethod threeChecks = method("three-checks", 10.0);
        TrainingMethodDatabase database = new TrainingMethodDatabase()
        {
            @Override
            public List<TrainingMethod> methodsFor(Skill skill)
            {
                return Arrays.asList(oneCheck, threeChecks);
            }
        };
        RequirementEvidenceEngine evidence = new RequirementEvidenceEngine(new FarmingAccessEvaluator(new FarmingAccessCatalog()), null, new FarmingSupplyCatalog(), new RunecraftSupplyCatalog())
        {
            @Override
            public List<EvidenceCheck> evaluate(
                    GameData data, TrainingMethod method)
            {
                EvidenceCheck ready = new EvidenceCheck(
                        "access:ready", "Ready", RequirementState.VERIFIED,
                        "Verified.");
                return "one-check".equals(method.getId())
                        ? Collections.singletonList(ready)
                        : Arrays.asList(ready, ready, ready);
            }
        };

        TrainingPlan plan = new TrainingMethodSelector(database, evidence, new TrainingMethodPolicy(), new MethodStrategyKnowledgeCatalog(), new UimInventoryResolutionService())
                .select(null, Skill.MINING, 50, StrategyMode.BALANCED,
                        SessionIntent.PICK_FOR_ME);

        assertEquals("one-check", plan.getMethod().getId());
    }

    private static TrainingMethod method(String id, double score)
    {
        return new TrainingMethod(
                id,
                Skill.MINING,
                1,
                99,
                id,
                "test",
                score,
                score,
                score,
                AttentionLevel.MODERATE,
                10,
                1,
                Collections.singletonList("Required unlock"),
                Confidence.CHECK_NEEDED
        );
    }
}

