package compass;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class UiGenerationGuardTest extends CatalogHostTest
{
    @Test
    public void rapidRefreshAndShutdownRejectQueuedStaleWork()
    {
        UiGenerationGuard guard = new UiGenerationGuard();
        long login = guard.next();
        long accountSwitch = guard.next();
        assertFalse(guard.isCurrent(login));
        assertTrue(guard.isCurrent(accountSwitch));

        guard.invalidate();
        assertFalse(guard.isCurrent(accountSwitch));
    }

    @Test
    public void onlyNewestOfManyQueuedAccountEventsMayRender()
    {
        UiGenerationGuard guard = new UiGenerationGuard();
        long[] events = new long[250];
        for (int i = 0; i < events.length; i++) events[i] = guard.next();
        for (int i = 0; i < events.length - 1; i++)
            assertFalse("stale event " + i, guard.isCurrent(events[i]));
        assertTrue(guard.isCurrent(events[events.length - 1]));
    }

    @Test
    public void shutdownInvalidatesLoadingAndFallbackUpdates()
    {
        UiGenerationGuard guard = new UiGenerationGuard();
        long login = guard.next();
        long loadingFallback = guard.next();
        assertFalse(guard.isCurrent(login));
        guard.invalidate();
        assertFalse(guard.isCurrent(loadingFallback));
    }

    @Test
    public void thousandsOfBenignRefreshesRetainOnlyOneCurrentGeneration()
    {
        UiGenerationGuard guard = new UiGenerationGuard();
        long previous = 0;
        for (int i = 0; i < 2_000; i++)
        {
            long current = guard.next();
            if (previous != 0) assertFalse(guard.isCurrent(previous));
            previous = current;
        }
        assertTrue(guard.isCurrent(previous));
    }
}

package compass;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class UiTextStressTest extends CatalogHostTest
{
    @Test
    public void detailsAndGuidanceWrapLongNamesQuantitiesAndUnbrokenTokens()
    {
        BufferedImage image = new BufferedImage(800, 600,
                BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            Font font = new Font(Font.SANS_SERIF, Font.PLAIN, 14);
            graphics.setFont(font);
            FontMetrics metrics = graphics.getFontMetrics(font);
            String text = "Recipe for Disaster - Another Cook's Quest "
                    + "requires 2,147,483,647 carefully-accounted supplies "
                    + "and SupercalifragilisticexpialidociousWithoutBreaks";
            assertWrapped(RecommendationDetailsOverlay.wrap(text, metrics, 310),
                    metrics, 310);
            assertWrapped(MethodGuidanceOverlay.wrap(text, metrics, 230),
                    metrics, 230);
        }
        finally
        {
            graphics.dispose();
        }
    }

    @Test
    public void wrappingNeverDropsContentOrReturnsBlankForContent()
    {
        BufferedImage image = new BufferedImage(300, 200,
                BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            FontMetrics metrics = graphics.getFontMetrics();
            List<String> lines = RecommendationDetailsOverlay.wrap(
                    "CHECK_NEEDED UIM retrieval-only death-storage setup", metrics,
                    90);
            assertFalse(lines.isEmpty());
            assertFalse(String.join("", lines).trim().isEmpty());
            // A narrow renderer may split CHECK_NEEDED itself depending on the
            // runner's installed font. Rejoining without inserted whitespace
            // verifies that wrapping preserved the token rather than dropping it.
            assertTrue(String.join("", lines).contains("CHECK_NEEDED"));
        }
        finally
        {
            graphics.dispose();
        }
    }

    private static void assertWrapped(List<String> lines, FontMetrics metrics,
            int width)
    {
        assertFalse(lines.isEmpty());
        for (String line : lines)
            assertTrue("overflow: " + line,
                    metrics.stringWidth(line) <= width);
    }
}

package compass;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class UimCapabilityServiceTest extends CatalogHostTest
{
    private final UimCapabilityService service = new UimCapabilityService();

    @Test
    public void refusesUnknownUimStorageCapability()
    {
        GameData data = GameData.builder(account(2))
                .storage(StorageSnapshot.unknown())
                .build();

        UimStorageDecision decision = service.evaluateStorage(
                data,
                StorageKind.STASH,
                Capability.VERIFIED,
                Capability.VERIFIED
        );

        assertFalse(decision.isAllowed());
        assertTrue(decision.getConfidence()
                == Confidence.CHECK_NEEDED);
    }

    @Test
    public void requiresCapabilityCompatibilityAndCapacityTogether()
    {
        Map<StorageKind, Capability> states =
                new EnumMap<>(StorageKind.class);
        states.put(StorageKind.POH_STORAGE, Capability.VERIFIED);
        GameData data = GameData.builder(account(2))
                .storage(new StorageSnapshot(states, Collections.emptyMap()))
                .build();

        assertFalse(service.evaluateStorage(
                data,
                StorageKind.POH_STORAGE,
                Capability.UNKNOWN,
                Capability.VERIFIED
        ).isAllowed());

        assertTrue(service.evaluateStorage(
                data,
                StorageKind.POH_STORAGE,
                Capability.VERIFIED,
                Capability.VERIFIED
        ).isAllowed());
    }

    @Test
    public void deathpileAlwaysCarriesIrreversibleRisk()
    {
        assertTrue(service.shouldRequireExplicitWarning(
                StorageKind.DEATHPILE));
    }

    @Test
    public void genericDeathStorageCanNeverAuthorizeAPlan()
    {
        Map<StorageKind, Capability> states =
                new EnumMap<>(StorageKind.class);
        states.put(StorageKind.DEATH_STORAGE,
                Capability.VERIFIED);
        GameData data = GameData.builder(account(2))
                .storage(new StorageSnapshot(states, Collections.emptyMap()))
                .build();

        UimStorageDecision decision = service.evaluateStorage(data,
                StorageKind.DEATH_STORAGE,
                Capability.VERIFIED, Capability.VERIFIED);
        assertFalse(decision.isAllowed());
        assertTrue(decision.getExplanation().contains("exact service"));
    }

    @Test
    public void exactRetrievalServiceStillRequiresAllEvidence()
    {
        Map<StorageKind, Capability> states =
                new EnumMap<>(StorageKind.class);
        states.put(StorageKind.HESPORI_ITEM_RETRIEVAL,
                Capability.VERIFIED);
        GameData data = GameData.builder(account(2))
                .storage(new StorageSnapshot(states, Collections.emptyMap()))
                .build();

        assertFalse(service.evaluateStorage(data,
                StorageKind.HESPORI_ITEM_RETRIEVAL,
                Capability.UNKNOWN, Capability.VERIFIED)
                .isAllowed());
        assertTrue(service.evaluateStorage(data,
                StorageKind.HESPORI_ITEM_RETRIEVAL,
                Capability.VERIFIED, Capability.VERIFIED)
                .isAllowed());
        assertTrue(service.shouldRequireExplicitWarning(
                StorageKind.HESPORI_ITEM_RETRIEVAL));
    }

    @Test
    public void everyDangerousSystemHasCompleteDistinctReviewedMechanics()
    {
        StorageKind[] exact = {
                StorageKind.HESPORI_ITEM_RETRIEVAL,
                StorageKind.ZULRAH_ITEM_RETRIEVAL,
                StorageKind.VOLCANIC_MINE_ITEM_RETRIEVAL,
                StorageKind.DEATHPILE
        };
        for (StorageKind capability : exact)
        {
            UimStorageMechanicProfile profile =
                    UimStorageMechanics.profile(capability);
            assertTrue(capability.name(), profile != null);
            assertTrue(capability.name(),
                    profile.hasCompleteRecommendationRules());
            assertTrue(capability.name(),
                    profile.getSource() == Source.ITEM_RETRIEVAL_SERVICES
                    || profile.getSource()
                            == Source.UIM_ITEM_MANAGEMENT);
        }
        assertTrue(UimStorageMechanics.profile(
                StorageKind.ZULRAH_ITEM_RETRIEVAL).getCost()
                .contains("Free for Ultimate Ironmen"));
        assertTrue(UimStorageMechanics.profile(
                StorageKind.VOLCANIC_MINE_ITEM_RETRIEVAL).getCost()
                .contains("150 numulite"));
        assertTrue(UimStorageMechanics.profile(
                StorageKind.HESPORI_ITEM_RETRIEVAL).getCost()
                .contains("25,000 coins"));
        assertTrue(UimStorageMechanics.profile(StorageKind.DEATHPILE)
                .getExpiration().contains("60 minutes"));
        assertFalse(UimStorageMechanics.profile(
                StorageKind.DEATH_STORAGE)
                .hasCompleteRecommendationRules());
    }

    private static AccountSnapshot account(int typeCode)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 1);
            xp.put(skill, 0);
        }
        return new AccountSnapshot("Tester", 0L, typeCode, "UIM", Membership.P2P, 1, 1, 0L, levels, xp);
    }
}

package compass;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class UimInventoryResolutionServiceTest extends CatalogHostTest
{
    private final UimInventoryResolutionService service =
            new UimInventoryResolutionService();
    private final InventoryFootprint needsFour =
            new InventoryFootprint(4, 2, 3,
                    InventoryFlow.GROWS_NONSTACKABLE_OUTPUTS, true);

    @Test
    public void asIsAndComparableMethodComeBeforeStorage()
    {
        assertEquals(UimInventoryKind.USE_AS_IS,
                service.resolve(data(20), needsFour, false, false,
                        Collections.emptyList()).getKind());
        assertEquals(UimInventoryKind.USE_LOW_FOOTPRINT_ALTERNATIVE,
                service.resolve(data(28), needsFour, true, true,
                        Arrays.asList(option(StorageKind.DEATHPILE,
                                true, Priority.CRITICAL)))
                        .getKind());
    }

    @Test
    public void productiveUseAndVerifiedSafeStorageOutrankDanger()
    {
        assertEquals(UimInventoryKind.PRODUCTIVELY_CONSUME_RESOURCES,
                service.resolve(data(28), needsFour, false, true,
                        Collections.emptyList()).getKind());

        GameData data = data(28,
                StorageKind.POH_COSTUME_ROOM,
                StorageKind.HESPORI_ITEM_RETRIEVAL);
        UimInventoryResolution result = service.resolve(data, needsFour,
                false, false, Arrays.asList(
                        option(StorageKind.HESPORI_ITEM_RETRIEVAL,
                                true, Priority.NONE),
                        option(StorageKind.POH_COSTUME_ROOM,
                                false, Priority.HIGH)));
        assertEquals(UimInventoryKind.USE_VERIFIED_SAFE_STORAGE,
                result.getKind());
        assertEquals(StorageKind.POH_COSTUME_ROOM,
                result.getStorageDecision().getCapability());
    }

    @Test
    public void worthwhileSafeInfrastructureAndLootingBagPrecedeDeathStorage()
    {
        GameData data = data(28, StorageKind.LOOTING_BAG,
                StorageKind.HESPORI_ITEM_RETRIEVAL);
        UimInventoryResolution build = service.resolve(data, needsFour,
                false, false, Arrays.asList(
                        option(StorageKind.POH_STORAGE, true,
                                Priority.HIGH),
                        option(StorageKind.HESPORI_ITEM_RETRIEVAL,
                                true, Priority.NONE)));
        assertEquals(UimInventoryKind.BUILD_HIGH_VALUE_SAFE_STORAGE,
                build.getKind());

        UimInventoryResolution bag = service.resolve(data, needsFour,
                false, false, Arrays.asList(
                        option(StorageKind.LOOTING_BAG, false,
                                Priority.NONE),
                        option(StorageKind.HESPORI_ITEM_RETRIEVAL,
                                true, Priority.NONE)));
        assertEquals(UimInventoryKind.USE_RESTRICTED_RETRIEVAL,
                bag.getKind());
    }

    @Test
    public void dangerousStorageRequiresExactVerifiedMajorTransition()
    {
        GameData data = data(28,
                StorageKind.HESPORI_ITEM_RETRIEVAL,
                StorageKind.DEATH_STORAGE);
        UimInventoryResolution ordinary = service.resolve(data, needsFour,
                false, false, Collections.singletonList(
                        option(StorageKind.HESPORI_ITEM_RETRIEVAL,
                                false, Priority.NONE)));
        assertEquals(UimInventoryKind.UNRESOLVED,
                ordinary.getKind());
        assertTrue(ordinary.getReason().contains("will not recommend banking"));

        UimInventoryResolution major = service.resolve(data, needsFour,
                false, false, Collections.singletonList(
                        option(StorageKind.HESPORI_ITEM_RETRIEVAL,
                                true, Priority.NONE)));
        assertEquals(UimInventoryKind.USE_DANGEROUS_DEATH_STORAGE,
                major.getKind());
        assertEquals(Confidence.CHECK_NEEDED,
                major.getConfidence());
        assertNotNull(major.getRiskDisclosure());
        assertTrue(major.getRiskDisclosure().isAcknowledgementRequired());

        UimInventoryResolution generic = service.resolve(data, needsFour,
                false, false, Collections.singletonList(
                        option(StorageKind.DEATH_STORAGE,
                                true, Priority.NONE)));
        assertEquals(UimInventoryKind.UNRESOLVED,
                generic.getKind());
    }

    private static UimStorageOption option(StorageKind capability,
            boolean major, Priority value)
    {
        boolean build = capability == StorageKind.POH_STORAGE;
        return new UimStorageOption(capability, Capability.VERIFIED,
                Capability.VERIFIED, build, value, major);
    }

    private static GameData data(int occupied,
            StorageKind... verified)
    {
        List<ItemState> items = new ArrayList<>();
        for (int slot = 0; slot < occupied; slot++)
            items.add(new ItemState(30_000 + slot,
                    "Persistent item " + slot, 1, slot));
        Map<StorageKind, Capability> states =
                new EnumMap<>(StorageKind.class);
        for (StorageKind capability : verified)
            states.put(capability, Capability.VERIFIED);
        return GameData.builder(uim())
                .inventory(new ItemsState(items, true))
                .storage(new StorageSnapshot(states, Collections.emptyMap()))
                .build();
    }

    private static AccountSnapshot uim()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            levels.put(skill, 70);
            xp.put(skill, 0);
        }
        return new AccountSnapshot("Uim", 0L, 2, "Ultimate Ironman", Membership.P2P, 1, 70 * Skill.values().length, 0L, levels, xp);
    }
}

